begin;
alter table public.exams disable trigger trg_exams_sync_bank;
do $do$ declare r jsonb; e jsonb; h text; begin
  for r in select * from jsonb_array_elements($j$[{"id":321571,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"270","question":"<p class=\"text-base leading-relaxed my-2\">Một ấm đun nước có công suất 500 W chứa 300 g nước. Cho nhiệt hóa hơi riêng của nước là 2.10<sup>6</sup> J/kg. Sau khi đun nước trong ấm đến nhiệt độ sôi, người ta để ấm tiếp tục đun nước sôi trong 2 phút. Bỏ qua sự mất mát nhiệt. Khối lượng nước còn lại trong ấm bằng bao nhiêu g? Nhiệt lượng ấm cung cấp trong 2 phút là $Q=Pt=500.2.60=60000J$</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Khi nước đang sôi, toàn bộ nhiệt lượng do ấm cung cấp dùng để làm hóa hơi một phần nước ở nhiệt độ sôi không đổi. Bỏ qua mất mát nhiệt, nhiệt lượng hóa hơi bằng nhiệt lượng ấm cung cấp.</p><p class=\"text-base leading-relaxed my-2\">Nhiệt lượng ấm cung cấp trong 2 phút: $Q=Pt=500.2.60=60000\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Công thức nhiệt hóa hơi: $Q=Lm_{hh}$, suy ra khối lượng nước hóa hơi:</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow m_{hh}=\\dfrac{Q}{L}=\\dfrac{60000}{2.10^6}=0{,}03\\ \\text{kg}=30\\ \\text{g}$.</p><p class=\"text-base leading-relaxed my-2\">Khối lượng nước còn lại trong ấm:</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow m_{conlai}=m-m_{hh}=300-30=270\\ \\text{g}$.</p><p class=\"text-base leading-relaxed my-2\">Vậy khối lượng nước còn lại trong ấm là 270 g.</p>","difficultySource":"ai"},"ex":[{"exam":98,"idx":67,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"270","question":"<p class=\"text-base leading-relaxed my-2\">Một ấm đun nước có công suất 500 W chứa 300 g nước. Cho nhiệt hóa hơi riêng của nước là 2.10<sup>6</sup> J/kg. Sau khi đun nước trong ấm đến nhiệt độ sôi, người ta để ấm tiếp tục đun nước sôi trong 2 phút. Bỏ qua sự mất mát nhiệt. Khối lượng nước còn lại trong ấm bằng bao nhiêu g? Nhiệt lượng ấm cung cấp trong 2 phút là $Q=Pt=500.2.60=60000J$</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Khi nước đang sôi, toàn bộ nhiệt lượng do ấm cung cấp dùng để làm hóa hơi một phần nước ở nhiệt độ sôi không đổi. Bỏ qua mất mát nhiệt, nhiệt lượng hóa hơi bằng nhiệt lượng ấm cung cấp.</p><p class=\"text-base leading-relaxed my-2\">Nhiệt lượng ấm cung cấp trong 2 phút: $Q=Pt=500.2.60=60000\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Công thức nhiệt hóa hơi: $Q=Lm_{hh}$, suy ra khối lượng nước hóa hơi:</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow m_{hh}=\\dfrac{Q}{L}=\\dfrac{60000}{2.10^6}=0{,}03\\ \\text{kg}=30\\ \\text{g}$.</p><p class=\"text-base leading-relaxed my-2\">Khối lượng nước còn lại trong ấm:</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow m_{conlai}=m-m_{hh}=300-30=270\\ \\text{g}$.</p><p class=\"text-base leading-relaxed my-2\">Vậy khối lượng nước còn lại trong ấm là 270 g.</p>","difficultySource":"ai"}}]},{"id":324539,"nq":{"form":"ly_thuyet","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"<p class=\"text-base leading-relaxed my-2\">Một chậu đựng hỗn hợp nước và nước đá có khối lượng là 10 kg. Chậu để trong phòng và người ta theo dõi nhiệt độ của hỗn hợp. Đồ thị biểu thị sự phụ thuộc nhiệt độ theo thời gian cho ở hình vẽ. Nhiệt dung riêng của nước là c = 4200 J/kg.K và nhiệt nóng chảy riêng của nước là <em class=\"italic\">$\\lambda$</em> = 3, 4.10<sup>5</sup> <em class=\"italic\">J</em> / <em class=\"italic\">kg</em>. Bỏ qua nhiệt dung của chậu.</p><p class=\"text-base leading-relaxed my-2\">Theo đồ thị, thời gian 50 phút đầu hỗn hợp ở 0$^\\circ$C. Quá trình này nhiệt thu được từ môi</p>","difficulty":"trung-binh","statements":[{"text":"trường dùng để làm nóng chảy nước đá. Trong 10 phút tiếp theo, toàn bộ nước trong chậu nóng dần lên nhờ thu nhiệt của môi trường.","answer":true},{"text":"Nhiệt lượng nhận được từ môi trường trong 10 phút sau bằng 8, 4.$10^{4}$ J.","answer":true},{"text":"Trong 50 phút trước đó, hỗn hợp đã nhận được của môi trường một nhiệt lượng bằng 4,2. $10^{4}$ J.","answer":false},{"text":"Khối lượng nước đá có trong hỗn hợp đầu là 1,23 kg.","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\"><strong class=\"font-bold\">a) Đúng</strong> Từ 50 phút đến 60 phút thì nhiệt độ tỉ lệ với thời gian nên nhiệt lượng cung cấp tỉ lệ với thời gian $Q=mc\\Delta t=10.4200.2=8,4.10^{4} J$ ứng với 10 phút $⟹$</p><p class=\"text-base leading-relaxed my-2\"><strong class=\"font-bold\">b) Đúng</strong> $⟹$ Trong 50 phút đầu thì $Q_{nd}=5Q=5.8,4.10^{4}=42.10^{4} J⟹$</p><p class=\"text-base leading-relaxed my-2\"><strong class=\"font-bold\">c) Sai</strong> Khối lượng nước đá $m=\\frac{Q_{nd}}{\\lambda }=\\frac{42.10^{4}}{3,4.10^{5}}\\approx 1,2353kg\\approx 1,24kg⟹$</p><p class=\"text-base leading-relaxed my-2\"><strong class=\"font-bold\">d) Sai</strong></p>","difficultySource":"ai"},"ex":[{"exam":98,"idx":95,"el":{"form":"ly_thuyet","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"<p class=\"text-base leading-relaxed my-2\">Một chậu đựng hỗn hợp nước và nước đá có khối lượng là 10 kg. Chậu để trong phòng và người ta theo dõi nhiệt độ của hỗn hợp. Đồ thị biểu thị sự phụ thuộc nhiệt độ theo thời gian cho ở hình vẽ. Nhiệt dung riêng của nước là c = 4200 J/kg.K và nhiệt nóng chảy riêng của nước là <em class=\"italic\">$\\lambda$</em> = 3, 4.10<sup>5</sup> <em class=\"italic\">J</em> / <em class=\"italic\">kg</em>. Bỏ qua nhiệt dung của chậu.</p><p class=\"text-base leading-relaxed my-2\">Theo đồ thị, thời gian 50 phút đầu hỗn hợp ở 0$^\\circ$C. Quá trình này nhiệt thu được từ môi</p>","difficulty":"trung-binh","statements":[{"text":"trường dùng để làm nóng chảy nước đá. Trong 10 phút tiếp theo, toàn bộ nước trong chậu nóng dần lên nhờ thu nhiệt của môi trường.","answer":true},{"text":"Nhiệt lượng nhận được từ môi trường trong 10 phút sau bằng 8, 4.$10^{4}$ J.","answer":true},{"text":"Trong 50 phút trước đó, hỗn hợp đã nhận được của môi trường một nhiệt lượng bằng 4,2. $10^{4}$ J.","answer":false},{"text":"Khối lượng nước đá có trong hỗn hợp đầu là 1,23 kg.","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\"><strong class=\"font-bold\">a) Đúng</strong> Từ 50 phút đến 60 phút thì nhiệt độ tỉ lệ với thời gian nên nhiệt lượng cung cấp tỉ lệ với thời gian $Q=mc\\Delta t=10.4200.2=8,4.10^{4} J$ ứng với 10 phút $⟹$</p><p class=\"text-base leading-relaxed my-2\"><strong class=\"font-bold\">b) Đúng</strong> $⟹$ Trong 50 phút đầu thì $Q_{nd}=5Q=5.8,4.10^{4}=42.10^{4} J⟹$</p><p class=\"text-base leading-relaxed my-2\"><strong class=\"font-bold\">c) Sai</strong> Khối lượng nước đá $m=\\frac{Q_{nd}}{\\lambda }=\\frac{42.10^{4}}{3,4.10^{5}}\\approx 1,2353kg\\approx 1,24kg⟹$</p><p class=\"text-base leading-relaxed my-2\"><strong class=\"font-bold\">d) Sai</strong></p>","difficultySource":"ai"}}]},{"id":380993,"nq":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng ΔU = A + Q","answer":"1,5","question":"Khi truyền nhiệt lượng Q cho khối khí trong một xilanh hình trụ thì khí dãn nở đẩy pit-tông làm thể tích khí tăng thêm 5 lít. Biết áp suất của khối khí là 5.10<sup>5</sup> Pa và không đổi trong quá trình khí dãn nở. Nếu trong quá trình này nội năng của khối khí giảm đi 1 kJ thì Q có giá trị bằng bao nhiêu kJ?","difficulty":"trung-binh","explanation":"$A=−p\\Delta V=−5.10^5.5.10^{−3}=−2500J=−2,5kJ$<br>$\\Delta U=Q+A\\Rightarrow −1=Q−2,5\\Rightarrow Q=1,5kJ$","difficultySource":"ai"},"ex":[{"exam":118,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng ΔU = A + Q","answer":"1,5","question":"Khi truyền nhiệt lượng Q cho khối khí trong một xilanh hình trụ thì khí dãn nở đẩy pit-tông làm thể tích khí tăng thêm 5 lít. Biết áp suất của khối khí là 5.10<sup>5</sup> Pa và không đổi trong quá trình khí dãn nở. Nếu trong quá trình này nội năng của khối khí giảm đi 1 kJ thì Q có giá trị bằng bao nhiêu kJ?","difficulty":"trung-binh","explanation":"$A=−p\\Delta V=−5.10^5.5.10^{−3}=−2500J=−2,5kJ$<br>$\\Delta U=Q+A\\Rightarrow −1=Q−2,5\\Rightarrow Q=1,5kJ$","difficultySource":"ai"}}]},{"id":381634,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"${}_{53}^{131}I$ là một hạt nhân phóng xạ phổ biến được tìm thấy trong chất thải phóng xạ từ nhà máy phát điện hạt nhân. Nó trải qua quá trình phân rã β‒ và trở thành một hạt nhân con X với chu kì bán rã 8,02 ngày. Cho khối lượng mol của  ${}_{53}^{131}I$ là 131 g/mol. Giả sử ban đầu có một mẫu  ${}_{53}^{131}I$ nguyên chất có khối lượng 1,0 kg. Một phản ứng phân rã của  ${}_{53}^{131}I$ tỏa năng lượng 0,466 MeV và giả sử toàn bộ năng lượng phân rã này trở thành nhiệt.","difficulty":"kho","statements":[{"text":"Số proton của hạt nhân X là 52.","answer":false},{"text":"Hằng số phóng xạ của  ${}_{53}^{131}I$ là 1,00.10‒6 s‒1.","answer":true},{"text":"Độ phóng xạ ban đầu của mẫu  ${}_{53}^{131}I$ là 1,42.10<sup>8</sup> Ci.","answer":false},{"text":"Công suất phát nhiệt của mẫu  ${}_{53}^{131}I$ sau 30,00 ngày là 26 kW.","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\"><strong>a)</strong> Phương trình phân rã: ${}_{53}^{131}I$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow {}_{Z}^{131}X + {}_{-1}^{0}e + \\bar{\\nu}$. Bảo toàn số hiệu nguyên tử: $53 = Z - 1$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow Z = 54$. Hạt nhân X (Xe) có 54 proton, nên ý này <strong>Sai</strong>.</p><p class=\"text-base leading-relaxed my-2\"><strong>b)</strong> Hằng số phóng xạ: $\\lambda = \\dfrac{\\ln 2}{T} = \\dfrac{0{,}693}{8{,}02 \\cdot 86400\\ \\text{s}} \\approx 1{,}00.10^{-6}\\ \\text{s}^{-1}$. Ý này <strong>Đúng</strong>.</p><p class=\"text-base leading-relaxed my-2\"><strong>c)</strong> Số hạt nhân ban đầu: $N_0 = \\dfrac{m}{A}N_A = \\dfrac{1000}{131}\\cdot 6{,}022.10^{23} \\approx 4{,}60.10^{24}$ hạt.</p><p class=\"text-base leading-relaxed my-2\">Độ phóng xạ ban đầu: $H_0 = \\lambda N_0 = 1{,}00.10^{-6}\\cdot 4{,}60.10^{24} \\approx 4{,}60.10^{18}\\ \\text{Bq}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi sang Ci ($1\\ \\text{Ci} = 3{,}7.10^{10}\\ \\text{Bq}$): $H_0 \\approx \\dfrac{4{,}60.10^{18}}{3{,}7.10^{10}} \\approx 1{,}24.10^{8}\\ \\text{Ci}$, không phải $1{,}42.10^{8}$ Ci. Ý này <strong>Sai</strong>.</p><p class=\"text-base leading-relaxed my-2\"><strong>d)</strong> Công suất phát nhiệt ban đầu: $P_0 = H_0 \\cdot E = 4{,}60.10^{18}\\cdot 0{,}466\\cdot 1{,}6.10^{-13}\\ \\text{J} \\approx 3{,}43.10^{5}\\ \\text{W}$.</p><p class=\"text-base leading-relaxed my-2\">Sau $t = 30{,}00$ ngày, số chu kì: $\\dfrac{t}{T} = \\dfrac{30}{8{,}02} \\approx 3{,}74$. Vậy $P = P_0\\cdot 2^{-t/T} \\approx 3{,}43.10^{5}\\cdot 2^{-3{,}74} \\approx 3{,}43.10^{5}\\cdot 0{,}0748 \\approx 2{,}57.10^{4}\\ \\text{W} \\approx 26\\ \\text{kW}$. Ý này <strong>Đúng</strong>.</p>","difficultySource":"ai"},"ex":[{"exam":119,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"${}_{53}^{131}I$ là một hạt nhân phóng xạ phổ biến được tìm thấy trong chất thải phóng xạ từ nhà máy phát điện hạt nhân. Nó trải qua quá trình phân rã β‒ và trở thành một hạt nhân con X với chu kì bán rã 8,02 ngày. Cho khối lượng mol của  ${}_{53}^{131}I$ là 131 g/mol. Giả sử ban đầu có một mẫu  ${}_{53}^{131}I$ nguyên chất có khối lượng 1,0 kg. Một phản ứng phân rã của  ${}_{53}^{131}I$ tỏa năng lượng 0,466 MeV và giả sử toàn bộ năng lượng phân rã này trở thành nhiệt.","difficulty":"kho","statements":[{"text":"Số proton của hạt nhân X là 52.","answer":false},{"text":"Hằng số phóng xạ của  ${}_{53}^{131}I$ là 1,00.10‒6 s‒1.","answer":true},{"text":"Độ phóng xạ ban đầu của mẫu  ${}_{53}^{131}I$ là 1,42.10<sup>8</sup> Ci.","answer":false},{"text":"Công suất phát nhiệt của mẫu  ${}_{53}^{131}I$ sau 30,00 ngày là 26 kW.","answer":true}],"explanation":"","difficultySource":"ai"}}]},{"id":382307,"nq":{"form":"bai_tap","type":"true_false","topic":"Tính độ hụt khối và năng lượng liên kết","question":"Cho hạt nhân ${}_{26}^{56}{Fe}$ . Biết khối lượng của  ${}_{26}^{56}{Fe}$ , proton và neutron lần lượt là mFe = 55,84522 amu; mp = 1,00728 amu; mn =1,00866 amu. 1 amu = 931,5 MeV/c2","difficulty":"kho","statements":[{"text":"Hạt nhân có 26 proton và 56 neutron.","answer":false},{"text":"${}_{26}^{54}{Fe};_{26}^{57}Fe;_{26}^{58}Fe$ được gọi là những đồng vị của  ${}_{26}^{56}{Fe}$ .","answer":true},{"text":"Độ hụt khối của  ${}_{26}^{56}{Fe}$ là 1,00273.10<sup>−27</sup> kg.","answer":true},{"text":"Năng lượng liên kết riêng của  ${}_{26}^{56}{Fe}$ là 11,045 MeV.","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\"><b>Xác định số proton và số neutron:</b> Với hạt nhân ${}_{26}^{56}\\text{Fe}$, số proton $Z=26$, số khối $A=56$ nên số neutron $N=A-Z=56-26=30$.</p><p class=\"text-base leading-relaxed my-2\">Ý a) <b>Sai</b>, vì hạt nhân có 26 proton và 30 neutron (56 là số khối, không phải số neutron).</p><p class=\"text-base leading-relaxed my-2\"><b>Đồng vị:</b> Đồng vị là các hạt nhân có cùng số proton $Z$ nhưng khác số neutron (khác số khối $A$). Các hạt nhân ${}_{26}^{54}\\text{Fe}$, ${}_{26}^{57}\\text{Fe}$, ${}_{26}^{58}\\text{Fe}$ đều có $Z=26$.</p><p class=\"text-base leading-relaxed my-2\">Ý b) <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>Độ hụt khối:</b> Công thức: $\\Delta m = Z m_p + N m_n - m_{Fe}$</p><p class=\"text-base leading-relaxed my-2\">Thay số: $\\Delta m = 26\\cdot 1{,}00728 + 30\\cdot 1{,}00866 - 55{,}84522 = 0{,}60386\\ \\text{amu}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\Delta m = 0{,}60386\\cdot 1{,}66055\\cdot 10^{-27}\\ \\text{kg} \\approx 1{,}00273\\cdot 10^{-27}\\ \\text{kg}$</p><p class=\"text-base leading-relaxed my-2\">Ý c) <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>Năng lượng liên kết riêng:</b> Năng lượng liên kết $W_{lk} = \\Delta m\\cdot c^2 = 0{,}60386\\cdot 931{,}5\\ \\text{MeV} \\approx 562{,}50\\ \\text{MeV}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\varepsilon = \\dfrac{W_{lk}}{A} = \\dfrac{562{,}50}{56} \\approx 10{,}045\\ \\text{MeV/nuclêôn}$</p><p class=\"text-base leading-relaxed my-2\">Ý d) <b>Sai</b>, vì năng lượng liên kết riêng là khoảng 10,045 MeV/nuclôn, không phải 11,045 MeV.</p>","difficultySource":"ai"},"ex":[{"exam":120,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Tính độ hụt khối và năng lượng liên kết","question":"Cho hạt nhân ${}_{26}^{56}{Fe}$ . Biết khối lượng của  ${}_{26}^{56}{Fe}$ , proton và neutron lần lượt là mFe = 55,84522 amu; mp = 1,00728 amu; mn =1,00866 amu. 1 amu = 931,5 MeV/c2","difficulty":"kho","statements":[{"text":"Hạt nhân có 26 proton và 56 neutron.","answer":false},{"text":"${}_{26}^{54}{Fe};_{26}^{57}Fe;_{26}^{58}Fe$ được gọi là những đồng vị của  ${}_{26}^{56}{Fe}$ .","answer":true},{"text":"Độ hụt khối của  ${}_{26}^{56}{Fe}$ là 1,00273.10<sup>−27</sup> kg.","answer":true},{"text":"Năng lượng liên kết riêng của  ${}_{26}^{56}{Fe}$ là 11,045 MeV.","answer":false}],"explanation":"","difficultySource":"ai"}}]},{"id":382336,"nq":{"form":"bai_tap","type":"short_answer","topic":"Tính lực từ F = BIl·sinθ","answer":"130","question":"Xét một đoạn dây dẫn thẳng có chiều dài L = 1 m, có dòng điện I  = 3 A chạy qua được đặt trong từ trường đều có cảm ứng từ B = 5.10<sup>−2</sup> T. Độ lớn của lực từ tác dụng lên đoạn dây dẫn mang dòng điện nếu phương của dây dẫn hợp với vectơ cảm ứng từ một góc 60  là bao nhiêu mN (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"trung-binh","explanation":"Đáp số 130<br>Độ lớn của lực từ tác dụng lên đoạn dây dẫn mang dòng điện là:<br>$F=BILsin\\alpha =5.10^{−2}.3.1.sin60^0\\approx 0,13N$","difficultySource":"ai"},"ex":[{"exam":120,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Tính lực từ F = BIl·sinθ","answer":"130","question":"Xét một đoạn dây dẫn thẳng có chiều dài L = 1 m, có dòng điện I  = 3 A chạy qua được đặt trong từ trường đều có cảm ứng từ B = 5.10<sup>−2</sup> T. Độ lớn của lực từ tác dụng lên đoạn dây dẫn mang dòng điện nếu phương của dây dẫn hợp với vectơ cảm ứng từ một góc 60  là bao nhiêu mN (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"trung-binh","explanation":"Đáp số 130<br>Độ lớn của lực từ tác dụng lên đoạn dây dẫn mang dòng điện là:<br>$F=BILsin\\alpha =5.10^{−2}.3.1.sin60^0\\approx 0,13N$","difficultySource":"ai"}}]},{"id":382394,"nq":{"form":"bai_tap","type":"short_answer","topic":"Động năng trung bình phân tử và nhiệt độ","answer":"113","question":"Khảo sát chuyển động của các phân tử của một khối khí được xem gần đúng là khí lí tưởng thì thấy động năng tịnh tiến trung bình của chúng vào khoảng 0,05 eV. Biết 1 eV = 1,6.10<sup>−19</sup>J và hằng số Boltzmann k = 1,38.10<sup>−23</sup> J/K. Nhiệt độ của khối khí trên là bao nhiêu độ Celsius ( C) (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"trung-binh","explanation":"Đáp số 113<br>$E=0,05eV=0,05.1,6.10^{−19}=8.10^{−21}J$<br>$E=\\frac{3}{2}kT\\Rightarrow T=\\frac{2E}{3k}=\\frac{2.8.10^{−21}}{3.1,38.10^{−23}}\\approx \\frac{16.10^{−21}}{4,14.10^{−23}}\\approx 386K$<br>$t=T−273\\approx 386−273=113^0C$","difficultySource":"ai"},"ex":[{"exam":120,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Động năng trung bình phân tử và nhiệt độ","answer":"113","question":"Khảo sát chuyển động của các phân tử của một khối khí được xem gần đúng là khí lí tưởng thì thấy động năng tịnh tiến trung bình của chúng vào khoảng 0,05 eV. Biết 1 eV = 1,6.10<sup>−19</sup>J và hằng số Boltzmann k = 1,38.10<sup>−23</sup> J/K. Nhiệt độ của khối khí trên là bao nhiêu độ Celsius ( C) (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"trung-binh","explanation":"Đáp số 113<br>$E=0,05eV=0,05.1,6.10^{−19}=8.10^{−21}J$<br>$E=\\frac{3}{2}kT\\Rightarrow T=\\frac{2E}{3k}=\\frac{2.8.10^{−21}}{3.1,38.10^{−23}}\\approx \\frac{16.10^{−21}}{4,14.10^{−23}}\\approx 386K$<br>$t=T−273\\approx 386−273=113^0C$","difficultySource":"ai"}}]},{"id":382975,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Kích thước, khối lượng hạt nhân và đơn vị u","answer":3,"options":["1,72.10<sup>−30</sup> m3.","7,23.10<sup>−15</sup> m3.","1,23.10<sup>−30</sup> m3.","7,23.10<sup>−45</sup> m3."],"question":"Thể tích nhỏ nhất có thể có của các hạt nhân là","difficulty":"kho","explanation":"<p class=\"text-base leading-relaxed my-2\">Hạt nhân có bán kính $R=1{,}2.10^{-15}A^{1/3}\\ \\text{m}$ nên thể tích (coi hình cầu) $V=\\dfrac43\\pi R^3=\\dfrac43\\pi\\cdot1{,}2^3.10^{-45}A$ tỉ lệ với số khối $A$; nhỏ nhất khi $A=1$ (hạt nhân hiđrô là một proton).</p><p class=\"text-base leading-relaxed my-2\">$V_{\\min}=\\dfrac43\\pi\\cdot(1{,}2.10^{-15})^3\\approx7{,}24.10^{-45}\\ \\text{m}^3$.</p><p class=\"text-base leading-relaxed my-2\">Sai vì: A ($1{,}72.10^{-30}$ m³) có chữ số $1{,}72$ giống $1{,}2^3=1{,}728$ nhưng bỏ hệ số $\\dfrac43\\pi$ và sai mũ ($(10^{-15})^3=10^{-45}$, không phải $10^{-30}$). C ($1{,}23.10^{-30}$ m³) cũng sai mũ. B ($7{,}23.10^{-15}$ m³) có hệ số đúng nhưng mũ không đúng với $(10^{-15})^3$.</p><p class=\"text-base leading-relaxed my-2\">Chọn D.</p>","difficultySource":"ai"},"ex":[{"exam":121,"idx":17,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Kích thước, khối lượng hạt nhân và đơn vị u","answer":3,"options":["1,72.10<sup>−30</sup> m3.","7,23.10<sup>−15</sup> m3.","1,23.10<sup>−30</sup> m3.","7,23.10<sup>−45</sup> m3."],"question":"Thể tích nhỏ nhất có thể có của các hạt nhân là","difficulty":"kho","explanation":"Chọn đáp án D<br>Hạt nhân của đồng vị hydrogen  ${}_1^1A$  chính là 1 proton có số khối A = 1 là hạt nhân có thể tích nhỏ nhất. Bán kính của nó là: R=1,2.10<sup>−15</sup>.A1/3 m.<br>- Coi hạt nhân có dạng hình cầu thì thể tích của nó là:<br>$V=\\frac{4}{3}\\pi R^3=\\frac{4}{3}.\\pi .{\\left(1,2.10^{−15}.A^{\\frac{1}{3}}\\right)}^3=\\frac{4}{3}.\\pi .1,2^3.10^{−45}.A\\approx 7,23.10^{−45}m^3$","difficultySource":"ai"}}]},{"id":383091,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Chất phóng xạ 25Na có chu kì bán rã T = 62 s. Khối lượng 25Na ban đầu là 0,248 mg. Cho số Avogadro NA = 6,02.10<sup>23</sup> mol−1.","difficulty":"kho","statements":[{"text":"Độ phóng xạ ban đầu của 0,248 mg 25Na là 7,259.10<sup>16</sup> Bq.","answer":false},{"text":"Độ phóng xạ của 25Na sau 10 phút là 7,134.10<sup>16</sup> Bq","answer":false},{"text":"Độ phóng xạ của 25Na sau 30 phút là 3,05.10<sup>12</sup> Bq","answer":false},{"text":"Sau 120,45 s chất phóng xạ chỉ còn  $1/5$  độ phóng xạ ban đầu.","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Số hạt ban đầu: $N_0=\\dfrac{m N_A}{A}=\\dfrac{0{,}248\\cdot10^{-3}\\cdot 6{,}02\\cdot10^{23}}{25}\\approx 5{,}97\\cdot10^{18}$ hạt.</p><p class=\"text-base leading-relaxed my-2\">Hằng số phóng xạ: $\\lambda=\\dfrac{\\ln2}{T}=\\dfrac{\\ln 2}{62}\\approx 1{,}118\\cdot10^{-2}\\ \\text{s}^{-1}$.</p><p class=\"text-base leading-relaxed my-2\">Độ phóng xạ ban đầu: $H_0=\\lambda N_0\\approx 6{,}68\\cdot10^{16}$ Bq.</p><p class=\"text-base leading-relaxed my-2\">a) $H_0\\approx 6{,}68\\cdot10^{16}$ Bq, khác $7{,}259\\cdot10^{16}$ Bq. Vậy ý a <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\">b) $H=H_0\\cdot2^{-t/T}$ với $t=600$ s: $H=6{,}68\\cdot10^{16}\\cdot 2^{-600/62}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow H\\approx 8{,}2\\cdot10^{13}$ Bq, khác $7{,}134\\cdot10^{16}$ Bq. Vậy ý b <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\">c) $t=1800$ s: $H=6{,}68\\cdot10^{16}\\cdot 2^{-1800/62}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow H\\approx 1{,}2\\cdot10^{8}$ Bq, khác $3{,}05\\cdot10^{12}$ Bq. Vậy ý c <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\">d) $\\dfrac{H}{H_0}=\\dfrac15=2^{-t/T}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow t=T\\log_2 5=62\\cdot 2{,}32\\approx 144$ s, khác $120{,}45$ s. Vậy ý d <b>Sai</b>.</p>","difficultySource":"ai"},"ex":[{"exam":121,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Chất phóng xạ 25Na có chu kì bán rã T = 62 s. Khối lượng 25Na ban đầu là 0,248 mg. Cho số Avogadro NA = 6,02.10<sup>23</sup> mol−1.","difficulty":"kho","statements":[{"text":"Độ phóng xạ ban đầu của 0,248 mg 25Na là 7,259.10<sup>16</sup> Bq.","answer":false},{"text":"Độ phóng xạ của 25Na sau 10 phút là 7,134.10<sup>16</sup> Bq","answer":false},{"text":"Độ phóng xạ của 25Na sau 30 phút là 3,05.10<sup>12</sup> Bq","answer":false},{"text":"Sau 120,45 s chất phóng xạ chỉ còn  $1/5$  độ phóng xạ ban đầu.","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Số hạt ban đầu: $N_0=\\dfrac{m N_A}{A}=\\dfrac{0{,}248\\cdot10^{-3}\\cdot 6{,}02\\cdot10^{23}}{25}\\approx 5{,}97\\cdot10^{18}$ hạt.</p><p class=\"text-base leading-relaxed my-2\">Hằng số phóng xạ: $\\lambda=\\dfrac{\\ln2}{T}=\\dfrac{\\ln 2}{62}\\approx 1{,}118\\cdot10^{-2}\\ \\text{s}^{-1}$.</p><p class=\"text-base leading-relaxed my-2\">Độ phóng xạ ban đầu: $H_0=\\lambda N_0\\approx 6{,}68\\cdot10^{16}$ Bq.</p><p class=\"text-base leading-relaxed my-2\">a) $H_0\\approx 6{,}68\\cdot10^{16}$ Bq, khác $7{,}259\\cdot10^{16}$ Bq. Vậy ý a <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\">b) $H=H_0\\cdot2^{-t/T}$ với $t=600$ s: $H=6{,}68\\cdot10^{16}\\cdot 2^{-600/62}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow H\\approx 8{,}2\\cdot10^{13}$ Bq, khác $7{,}134\\cdot10^{16}$ Bq. Vậy ý b <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\">c) $t=1800$ s: $H=6{,}68\\cdot10^{16}\\cdot 2^{-1800/62}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow H\\approx 1{,}2\\cdot10^{8}$ Bq, khác $3{,}05\\cdot10^{12}$ Bq. Vậy ý c <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\">d) $\\dfrac{H}{H_0}=\\dfrac15=2^{-t/T}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow t=T\\log_2 5=62\\cdot 2{,}32\\approx 144$ s, khác $120{,}45$ s. Vậy ý d <b>Sai</b>.</p>","difficultySource":"ai"}}]},{"id":383120,"nq":{"form":"bai_tap","type":"short_answer","topic":"Tính lực từ F = BIl·sinθ","answer":"0,8","question":"Một đoạn dây dẫn dài 5 cm đặt trong từ trường đều và vuông góc với vectơ cảm ứng từ. Dòng điện chạy qua dây có cường độ 0,75 A. Lực từ tác dụng lên đoạn dây đó là 3.10<sup>−2</sup> N. Độ lớn cảm ứng từ là bao nhiêu tesla?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Đoạn dây dẫn mang dòng điện đặt vuông góc với vectơ cảm ứng từ, nên lực từ có độ lớn: $F = B\\,I\\,\\ell$ (với $\\sin 90^\\circ = 1$).</p><p class=\"text-base leading-relaxed my-2\">Suy ra cảm ứng từ: $B = \\dfrac{F}{I\\,\\ell}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $\\ell = 5\\ \\text{cm} = 0{,}05\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $B = \\dfrac{3\\cdot 10^{-2}}{0{,}75 \\cdot 0{,}05} = \\dfrac{0{,}03}{0{,}0375} = 0{,}8\\ \\text{T}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: độ lớn cảm ứng từ là $B = 0{,}8\\ \\text{T}$.</p>","difficultySource":"ai"},"ex":[{"exam":121,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Tính lực từ F = BIl·sinθ","answer":"0,8","question":"Một đoạn dây dẫn dài 5 cm đặt trong từ trường đều và vuông góc với vectơ cảm ứng từ. Dòng điện chạy qua dây có cường độ 0,75 A. Lực từ tác dụng lên đoạn dây đó là 3.10<sup>−2</sup> N. Độ lớn cảm ứng từ là bao nhiêu tesla?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Đoạn dây dẫn mang dòng điện đặt vuông góc với vectơ cảm ứng từ, nên lực từ có độ lớn: $F = B\\,I\\,\\ell$ (với $\\sin 90^\\circ = 1$).</p><p class=\"text-base leading-relaxed my-2\">Suy ra cảm ứng từ: $B = \\dfrac{F}{I\\,\\ell}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $\\ell = 5\\ \\text{cm} = 0{,}05\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $B = \\dfrac{3\\cdot 10^{-2}}{0{,}75 \\cdot 0{,}05} = \\dfrac{0{,}03}{0{,}0375} = 0{,}8\\ \\text{T}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: độ lớn cảm ứng từ là $B = 0{,}8\\ \\text{T}$.</p>","difficultySource":"ai"}}]},{"id":383207,"nq":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"36,2","question":"Tại các bệnh viện, oxygen được nén và lưu trữ trong các bình thép. Mỗi bình có thể tích 10 lít và chứa khí oxygen ở áp suất 15 MPa, ở nhiệt độ phòng 27°C. Giả sử khí oxygen trong bình tuân theo định luật khí lí tưởng. Số phân tử khí oxygen chứa trong bình là x.10<sup>24</sup> phân tử. Tìm x (làm tròn kết quả đến chữ số hàng phần mười).","difficulty":"trung-binh","explanation":"Đáp số 36,2<br>Áp dụng phương trình trạng thái khí lí tưởng: pV = nRT\t.<br>Tính số mol n:  $n=\\frac{pV}{RT}=\\frac{15.10^6.10.10^{−3}}{8,31.300}\\approx 60,168 mol$<br>Số phân tử khí oxygen N:   $N=n.N_A=$  = 60,168.6,02.10<sup>23</sup> = 36,219.10<sup>24</sup> phân tử","difficultySource":"ai"},"ex":[{"exam":121,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"36,2","question":"Tại các bệnh viện, oxygen được nén và lưu trữ trong các bình thép. Mỗi bình có thể tích 10 lít và chứa khí oxygen ở áp suất 15 MPa, ở nhiệt độ phòng 27°C. Giả sử khí oxygen trong bình tuân theo định luật khí lí tưởng. Số phân tử khí oxygen chứa trong bình là x.10<sup>24</sup> phân tử. Tìm x (làm tròn kết quả đến chữ số hàng phần mười).","difficulty":"trung-binh","explanation":"Đáp số 36,2<br>Áp dụng phương trình trạng thái khí lí tưởng: pV = nRT\t.<br>Tính số mol n:  $n=\\frac{pV}{RT}=\\frac{15.10^6.10.10^{−3}}{8,31.300}\\approx 60,168 mol$<br>Số phân tử khí oxygen N:   $N=n.N_A=$  = 60,168.6,02.10<sup>23</sup> = 36,219.10<sup>24</sup> phân tử","difficultySource":"ai"}}]},{"id":387011,"nq":{"form":"bai_tap","type":"true_false","topic":"Vận dụng phương trình trạng thái","question":"Một lốp ô tô được bơm căng không khí ở 27°C. Áp suất ban đầu của khí ở áp suất khí quyển bình thường là 1,013.10<sup>5</sup> Pa. Trong quá trình bơm, không khí vào trong lốp bị nén lại và giảm 80% thể tích ban đầu (khi không khí còn ở bên ngoài lốp), nhiệt độ khí trong lốp tăng lên đến 40°C.","difficulty":"kho","statements":[{"text":"Tỉ số giữa thể tích khí sau khi đưa vào trong lốp và thể tích khí khi ở ngoài là 0,2.","answer":true},{"text":"Áp suất khí trong lốp là 2,11.10<sup>3</sup> Pa.","answer":false},{"text":"Biết phần lốp tiếp xúc với mặt đường có dạng hình chữ nhật, diện tích 205 cm2. Áp lực lốp xe lên mặt đường cỡ 1000 N.","answer":false},{"text":"Sau khi ô tô chạy ở tốc độ cao, nhiệt độ không khí trong lốp tăng lên đến 75°C và thể tích khí bên trong lốp tăng bằng 102% thể tích khi lốp ở 40°C. Áp suất mới của khí trong lốp là xấp xỉ 5,76.10<sup>5</sup> Pa.","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\"><b>Tóm tắt:</b> Trạng thái 1 (không khí ngoài lốp): $p_1 = 1{,}013.10^5$ Pa, $V_1$, $T_1 = 27 + 273 = 300$ K. Trạng thái 2 (trong lốp, sau khi nén): $V_2 = 0{,}2V_1$, $T_2 = 40 + 273 = 313$ K.</p><p class=\"text-base leading-relaxed my-2\"><b>Ý a):</b> Thể tích khí sau khi nén bằng 20% thể tích ban đầu (giảm 80%), nên $\\dfrac{V_2}{V_1} = 0{,}2$. Ý a) <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>Ý b):</b> Áp dụng định luật Boyle–Mariotte kết hợp Charles (khối lượng khí không đổi):</p><p class=\"text-base leading-relaxed my-2\">$\\dfrac{p_1V_1}{T_1} = \\dfrac{p_2V_2}{T_2}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow p_2 = p_1\\cdot\\dfrac{V_1}{V_2}\\cdot\\dfrac{T_2}{T_1}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow p_2 = 1{,}013.10^5 \\cdot \\dfrac{1}{0{,}2}\\cdot\\dfrac{313}{300} \\approx 5{,}28.10^5$ Pa.</p><p class=\"text-base leading-relaxed my-2\">Giá trị $2{,}11.10^3$ Pa không phù hợp. Ý b) <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>Ý c):</b> Áp suất dư (chênh với khí quyển) trong lốp là $\\Delta p = p_2 - p_0 \\approx 5{,}28.10^5 - 1{,}013.10^5 = 4{,}27.10^5$ Pa.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F = \\Delta p\\cdot S = 4{,}27.10^5 \\cdot 205.10^{-4} \\approx 8{,}8.10^3$ N.</p><p class=\"text-base leading-relaxed my-2\">Lấy áp suất tuyệt đối thì $F \\approx 1{,}1.10^4$ N. Cả hai đều không ra cỡ 1000 N. Ý c) <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>Ý d):</b> Trạng thái 3: $T_3 = 75 + 273 = 348$ K, $V_3 = 1{,}02V_2$. Áp dụng phương trình trạng thái giữa trạng thái 2 và 3:</p><p class=\"text-base leading-relaxed my-2\">$\\dfrac{p_2V_2}{T_2} = \\dfrac{p_3V_3}{T_3}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow p_3 = p_2\\cdot\\dfrac{T_3}{T_2}\\cdot\\dfrac{V_2}{V_3}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow p_3 = 5{,}28.10^5\\cdot\\dfrac{348}{313}\\cdot\\dfrac{1}{1{,}02} \\approx 5{,}76.10^5$ Pa.</p><p class=\"text-base leading-relaxed my-2\">Ý d) <b>Đúng</b>.</p>","difficultySource":"ai"},"ex":[{"exam":126,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Vận dụng phương trình trạng thái","question":"Một lốp ô tô được bơm căng không khí ở 27°C. Áp suất ban đầu của khí ở áp suất khí quyển bình thường là 1,013.10<sup>5</sup> Pa. Trong quá trình bơm, không khí vào trong lốp bị nén lại và giảm 80% thể tích ban đầu (khi không khí còn ở bên ngoài lốp), nhiệt độ khí trong lốp tăng lên đến 40°C.","difficulty":"kho","statements":[{"text":"Tỉ số giữa thể tích khí sau khi đưa vào trong lốp và thể tích khí khi ở ngoài là 0,2.","answer":true},{"text":"Áp suất khí trong lốp là 2,11.10<sup>3</sup> Pa.","answer":false},{"text":"Biết phần lốp tiếp xúc với mặt đường có dạng hình chữ nhật, diện tích 205 cm2. Áp lực lốp xe lên mặt đường cỡ 1000 N.","answer":false},{"text":"Sau khi ô tô chạy ở tốc độ cao, nhiệt độ không khí trong lốp tăng lên đến 75°C và thể tích khí bên trong lốp tăng bằng 102% thể tích khi lốp ở 40°C. Áp suất mới của khí trong lốp là xấp xỉ 5,76.10<sup>5</sup> Pa.","answer":true}],"explanation":"","difficultySource":"ai"}}]},{"id":389336,"nq":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"3,1","question":"Một cái bơm chứa 120 cm3 không khí ở nhiệt độ 27°C và áp suất 105 Pa. Áp suất của không khí trong bơm khi nó bị nén xuống còn 40 cm3 và tăng nhiệt độ lên tới 37°C là x.10<sup>5</sup> Pa. Giá trị của x bằng bao nhiêu (Làm tròn kết quả đến một chữ số thập phân)?","difficulty":"trung-binh","explanation":"$\\frac{pV}{T}=hs\\Rightarrow \\frac{10^5.120}{27+273}=\\frac{x.10^5.40}{37+273}\\Rightarrow x=3,1$","difficultySource":"ai"},"ex":[{"exam":129,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"3,1","question":"Một cái bơm chứa 120 cm3 không khí ở nhiệt độ 27°C và áp suất 105 Pa. Áp suất của không khí trong bơm khi nó bị nén xuống còn 40 cm3 và tăng nhiệt độ lên tới 37°C là x.10<sup>5</sup> Pa. Giá trị của x bằng bao nhiêu (Làm tròn kết quả đến một chữ số thập phân)?","difficulty":"trung-binh","explanation":"$\\frac{pV}{T}=hs\\Rightarrow \\frac{10^5.120}{27+273}=\\frac{x.10^5.40}{37+273}\\Rightarrow x=3,1$","difficultySource":"ai"}}]},{"id":390149,"nq":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"1,5","question":"Một bình có dung tích 10 lít chứa một lượng khí hydrogen có khối lượng mol là 2 g/mol bị nén ở áp suất 5.10<sup>6</sup> Pa và nhiệt độ 7°C. Khi nung nóng bình, do bình hở nên có một phần khí thoát ra; phần khí còn lại có nhiệt độ 17°C và vẫn dưới áp suất như cũ. Khối lượng khí đã thoát ra khỏi bình là bao nhiêu gam (kết quả làm tròn đến chữ số hàng phần chục)?","difficulty":"trung-binh","explanation":"$pV=nRT=\\frac{m}{M}.R.T\\Rightarrow m=\\frac{pV.M}{RT}$<br>$m_d−m_s=\\frac{pVM}{R}\\left(\\frac{1}{T_d}−\\frac{1}{T_s}\\right)$<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259656309-hinh-9.png\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"},"ex":[{"exam":130,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"1,5","question":"Một bình có dung tích 10 lít chứa một lượng khí hydrogen có khối lượng mol là 2 g/mol bị nén ở áp suất 5.10<sup>6</sup> Pa và nhiệt độ 7°C. Khi nung nóng bình, do bình hở nên có một phần khí thoát ra; phần khí còn lại có nhiệt độ 17°C và vẫn dưới áp suất như cũ. Khối lượng khí đã thoát ra khỏi bình là bao nhiêu gam (kết quả làm tròn đến chữ số hàng phần chục)?","difficulty":"trung-binh","explanation":"$pV=nRT=\\frac{m}{M}.R.T\\Rightarrow m=\\frac{pV.M}{RT}$<br>$m_d−m_s=\\frac{pVM}{R}\\left(\\frac{1}{T_d}−\\frac{1}{T_s}\\right)$<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259656309-hinh-9.png\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"}}]},{"id":390236,"nq":{"form":"bai_tap","type":"short_answer","topic":"Quá trình đẳng nhiệt và định luật Boyle","answer":"2,42","question":"Khi thở ra, dung tích của phổi là 2,40 lít và áp suất của không khí trong phổi là 101,70.10<sup>3</sup> Pa. Cho biết khi hít vào, áp suất này có giá trị 101,01.10<sup>3</sup> Pa. Nhiệt độ của cơ thể người không thay đổi. Dung tích của phổi khi hít vào là bao nhiêu lít (kết quả làm tròn đến chữ số hàng phần trăm)?","difficulty":"trung-binh","explanation":"Nhiệt độ không đổi  $\\Rightarrow$  Quá trình đẳng nhiệt  $\\Rightarrow Boyle$   $p_1V_1=p_2V_2$<br>Khí thở ra:  $p_1=101,70.10^3Pa; V_1=2,40ℓ$<br>Khí hít vào:  $p_2=101,01.10^3Pa$<br>$\\Rightarrow V_2=\\frac{p_1V_1}{p_2}=\\frac{101,70.2,40}{101,01}\\approx 2,42 lit$","difficultySource":"ai"},"ex":[{"exam":130,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Quá trình đẳng nhiệt và định luật Boyle","answer":"2,42","question":"Khi thở ra, dung tích của phổi là 2,40 lít và áp suất của không khí trong phổi là 101,70.10<sup>3</sup> Pa. Cho biết khi hít vào, áp suất này có giá trị 101,01.10<sup>3</sup> Pa. Nhiệt độ của cơ thể người không thay đổi. Dung tích của phổi khi hít vào là bao nhiêu lít (kết quả làm tròn đến chữ số hàng phần trăm)?","difficulty":"trung-binh","explanation":"Nhiệt độ không đổi  $\\Rightarrow$  Quá trình đẳng nhiệt  $\\Rightarrow Boyle$   $p_1V_1=p_2V_2$<br>Khí thở ra:  $p_1=101,70.10^3Pa; V_1=2,40ℓ$<br>Khí hít vào:  $p_2=101,01.10^3Pa$<br>$\\Rightarrow V_2=\\frac{p_1V_1}{p_2}=\\frac{101,70.2,40}{101,01}\\approx 2,42 lit$","difficultySource":"ai"}}]},{"id":391951,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật phóng xạ và chu kì bán rã","answer":2,"options":["0,11MBq .","1,1MBq .","13,1Bq .","131Bq ."],"question":"Potassium (Kali) là nguyên tố dinh dưỡng khoáng thiết yếu đối với cây trồng. Trong potassium tự nhiên có khoảng 0,0117% là đồng vị phóng xạ  ${}_{19}^{40}K$  với chu kì bán rã là 1,251.10<sup>9</sup> năm; lấy 1 năm bằng 365 ngày, khối lượng mol của  ${}_{19}^{40}K$  là 40g/mol . Chuối, khoai tây, khoai lang, cà chua, các loại đậu (đậu nành, đậu đen, đậu lăng), và rau xanh như cải bó xôi... là những thực phẩm có hàm lượng potassium cao. Một quả chuối trung bình nặng 118g chứa khoảng 422mg potassium. Độ phóng xạ của lượng potassium trong 1 quả chuối gần nhất với giá trị nào sau đây?","difficulty":"kho","explanation":"Chọn đáp án C<br>Khối lượng potassium trong một quả chuối là  $422,mg=0,422,g$ . Tỉ lệ đồng vị phóng xạ  ${}_{}^{40}{19}K$  là  $0,0117%=1,17\\cdot 10^{−4}$ , nên khối lượng  ${}_{}^{40}{19}K$  là  $m=0,422\\cdot 1,17\\cdot 10^{−4}\\approx 4,94\\cdot 10^{−5},g$ .<br>Số hạt nhân  ${}_{19}^{40}K$  là  $N=\\frac{m}{M}N_A=\\frac{4,94\\cdot 10^{−5}}{40}\\cdot 6,02\\cdot 10^{23}\\approx 7,43\\cdot 10^{17}$  hạt.<br>Chu kì bán rã là  $T=1,251\\cdot 10^9$  năm  $=1,251\\cdot 10^9\\cdot 365\\cdot 24\\cdot 3600\\approx 3,95\\cdot 10^{16},s$ .<br>Độ phóng xạ  $H=\\lambda N=\\frac{ln2}{T}N\\approx \\frac{0,693}{3,95\\cdot 10^{16}}\\cdot 7,43\\cdot 10^{17}\\approx 13,1,Bq$ . Vậy giá trị gần nhất là  $13,1,Bq$ .","difficultySource":"ai"},"ex":[{"exam":133,"idx":5,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật phóng xạ và chu kì bán rã","answer":2,"options":["0,11MBq .","1,1MBq .","13,1Bq .","131Bq ."],"question":"Potassium (Kali) là nguyên tố dinh dưỡng khoáng thiết yếu đối với cây trồng. Trong potassium tự nhiên có khoảng 0,0117% là đồng vị phóng xạ  ${}_{19}^{40}K$  với chu kì bán rã là 1,251.10<sup>9</sup> năm; lấy 1 năm bằng 365 ngày, khối lượng mol của  ${}_{19}^{40}K$  là 40g/mol . Chuối, khoai tây, khoai lang, cà chua, các loại đậu (đậu nành, đậu đen, đậu lăng), và rau xanh như cải bó xôi... là những thực phẩm có hàm lượng potassium cao. Một quả chuối trung bình nặng 118g chứa khoảng 422mg potassium. Độ phóng xạ của lượng potassium trong 1 quả chuối gần nhất với giá trị nào sau đây?","difficulty":"kho","explanation":"Chọn đáp án C<br>Khối lượng potassium trong một quả chuối là  $422,mg=0,422,g$ . Tỉ lệ đồng vị phóng xạ  ${}_{}^{40}{19}K$  là  $0,0117%=1,17\\cdot 10^{−4}$ , nên khối lượng  ${}_{}^{40}{19}K$  là  $m=0,422\\cdot 1,17\\cdot 10^{−4}\\approx 4,94\\cdot 10^{−5},g$ .<br>Số hạt nhân  ${}_{19}^{40}K$  là  $N=\\frac{m}{M}N_A=\\frac{4,94\\cdot 10^{−5}}{40}\\cdot 6,02\\cdot 10^{23}\\approx 7,43\\cdot 10^{17}$  hạt.<br>Chu kì bán rã là  $T=1,251\\cdot 10^9$  năm  $=1,251\\cdot 10^9\\cdot 365\\cdot 24\\cdot 3600\\approx 3,95\\cdot 10^{16},s$ .<br>Độ phóng xạ  $H=\\lambda N=\\frac{ln2}{T}N\\approx \\frac{0,693}{3,95\\cdot 10^{16}}\\cdot 7,43\\cdot 10^{17}\\approx 13,1,Bq$ . Vậy giá trị gần nhất là  $13,1,Bq$ .","difficultySource":"ai"}}]},{"id":395348,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Động năng trung bình phân tử và nhiệt độ","answer":2,"options":["4,28.10<sup>−21</sup> J.","7,66.10<sup>−22</sup> J.","6,42.10<sup>−21</sup> J.","2,07.10<sup>−23</sup> J."],"question":"Một bình kín chứa khí Helium ở nhiệt độ 37°C. Động năng trung bình của chuyển động tịnh tiến mỗi phân tử khí Helium xấp xỉ là","difficulty":"trung-binh","explanation":"Chọn đáp án C<br>$E_d=\\frac{3}{2}kT=\\frac{3}{2}.1,38.10^{−23}.\\left(37+273\\right)=6,417.10^{−21}\\left(J\\right)$","difficultySource":"ai"},"ex":[{"exam":137,"idx":14,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Động năng trung bình phân tử và nhiệt độ","answer":2,"options":["4,28.10<sup>−21</sup> J.","7,66.10<sup>−22</sup> J.","6,42.10<sup>−21</sup> J.","2,07.10<sup>−23</sup> J."],"question":"Một bình kín chứa khí Helium ở nhiệt độ 37°C. Động năng trung bình của chuyển động tịnh tiến mỗi phân tử khí Helium xấp xỉ là","difficulty":"trung-binh","explanation":"Chọn đáp án C<br>$E_d=\\frac{3}{2}kT=\\frac{3}{2}.1,38.10^{−23}.\\left(37+273\\right)=6,417.10^{−21}\\left(J\\right)$","difficultySource":"ai"}}]},{"id":395522,"nq":{"form":"bai_tap","type":"true_false","topic":"Vận dụng phương trình trạng thái","question":"Một người đi biển tìm thấy một cái chai kín có nút. Nút chai có mặt cắt ngang diện tích 2,3 cm2. Không khí trong chai có áp suất bằng áp suất khí quyển, nhiệt độ 30°C và thể tích là 0,5 lít. Người đi biển đặt cái chai lên trên một nguồn nhiệt, ở nhiệt độ 99°C nút chai được đẩy ra ngoài. Cho biết áp suất khí quyển là 1,01.10<sup>5</sup> Pa. Bỏ qua mọi thay đổi về thể tích của chai và trọng lượng của nút chai.","difficulty":"kho","statements":[{"text":"Số mol khí trong chai là 0,02 mol.","answer":true},{"text":"Nhiệt độ của khí lúc nút chai được đẩy ra là 372 K.","answer":true},{"text":"Áp suất trong chai ngay trước khi nút chai là 1,14.10<sup>5</sup> Pa.","answer":false},{"text":"Lực ma sát nghỉ cực đại giữ nút chai đứng yên có độ lớn bằng 2,59 N.","answer":false}],"explanation":"a) đúng<br>$n=\\frac{pV}{RT}=\\frac{1,01.10^5.0,5.10^{−3}}{8,31.\\left(30+273\\right)}=0,02\\left(mol\\right)$<br>b) đúng<br>$T\\left(K\\right)=99+273=372\\left(K\\right)$<br>c) sai<br>Nút chai làm cho chai ban đầu có thể tích không đổi<br>Trước khi bật ra thể tích khí bên trong chai $V=const$<br>$\\Rightarrow \\frac{p_S}{p}=\\frac{T_S}{T}\\Rightarrow \\frac{p_S}{1,01.10^5}=\\frac{99+273}{30+273}\\Rightarrow p_s=124000\\left(Pa\\right)$<br>d) sai<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259716917-hinh-5.png\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>$pS\\ge p_0S+F_{msN}$<br>$\\Rightarrow F_{msN}=S.\\left(p_s−p_0\\right)$<br>$\\Rightarrow F_{msN}=2,3.10^{−4}.\\left(124000−1,01.10^5\\right)=5,29\\left(N\\right)$","difficultySource":"ai"},"ex":[{"exam":137,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Vận dụng phương trình trạng thái","question":"Một người đi biển tìm thấy một cái chai kín có nút. Nút chai có mặt cắt ngang diện tích 2,3 cm2. Không khí trong chai có áp suất bằng áp suất khí quyển, nhiệt độ 30°C và thể tích là 0,5 lít. Người đi biển đặt cái chai lên trên một nguồn nhiệt, ở nhiệt độ 99°C nút chai được đẩy ra ngoài. Cho biết áp suất khí quyển là 1,01.10<sup>5</sup> Pa. Bỏ qua mọi thay đổi về thể tích của chai và trọng lượng của nút chai.","difficulty":"kho","statements":[{"text":"Số mol khí trong chai là 0,02 mol.","answer":true},{"text":"Nhiệt độ của khí lúc nút chai được đẩy ra là 372 K.","answer":true},{"text":"Áp suất trong chai ngay trước khi nút chai là 1,14.10<sup>5</sup> Pa.","answer":false},{"text":"Lực ma sát nghỉ cực đại giữ nút chai đứng yên có độ lớn bằng 2,59 N.","answer":false}],"explanation":"a) đúng<br>$n=\\frac{pV}{RT}=\\frac{1,01.10^5.0,5.10^{−3}}{8,31.\\left(30+273\\right)}=0,02\\left(mol\\right)$<br>b) đúng<br>$T\\left(K\\right)=99+273=372\\left(K\\right)$<br>c) sai<br>Nút chai làm cho chai ban đầu có thể tích không đổi<br>Trước khi bật ra thể tích khí bên trong chai $V=const$<br>$\\Rightarrow \\frac{p_S}{p}=\\frac{T_S}{T}\\Rightarrow \\frac{p_S}{1,01.10^5}=\\frac{99+273}{30+273}\\Rightarrow p_s=124000\\left(Pa\\right)$<br>d) sai<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259716917-hinh-5.png\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>$pS\\ge p_0S+F_{msN}$<br>$\\Rightarrow F_{msN}=S.\\left(p_s−p_0\\right)$<br>$\\Rightarrow F_{msN}=2,3.10^{−4}.\\left(124000−1,01.10^5\\right)=5,29\\left(N\\right)$","difficultySource":"ai"}}]},{"id":396626,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Liên hệ áp suất với động năng phân tử","answer":2,"options":["94 500 kPa.","21 000 Pa.","94 500 Pa.","210 000 Pa."],"question":"Một bình kín chứa khí neon (xem là khí lí tưởng) có khối lượng riêng là 1,4 kg/m3. Biết căn bậc hai giá trị trung bình của các bình phương tốc độ của các phân tử khí neon ( $\\sqrt{\\overline{v^2}}$ ) là 450 m/s. Áp suất khí trong bình là Sử dụng các thông tin sau cho câu 6 và câu 7: Trong một cylinder kín có chứa một khối khí lí tưởng có áp suất 1,5.10<sup>5</sup> N/m2, thể tích 4 dm3 và nhiệt độ 27 °C được nung nóng đẳng áp đến nhiệt độ 57 °C. Khí dãn nở, đẩy piston dịch chuyển đều và không ma sát. Biết nội năng của khối khí tăng thêm 100 J.","difficulty":"de","explanation":"Chọn đáp án C<br>Ta có:  $\\overline{v^2}=\\frac{3RT}{M}$    $\\frac{RT}{M}=\\frac{ \\overline{v^2}}{3}$<br>Áp dụng phương trình Clapeyron:  $pV=nRT$    $p=D.\\frac{RT}{M}$<br>Suy ra:  $p=D.\\frac{ \\overline{v^2}}{3}=1,4.\\frac{{450}^2}{3}=94500$  Pa.","difficultySource":"ai"},"ex":[{"exam":139,"idx":4,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Liên hệ áp suất với động năng phân tử","answer":2,"options":["94 500 kPa.","21 000 Pa.","94 500 Pa.","210 000 Pa."],"question":"Một bình kín chứa khí neon (xem là khí lí tưởng) có khối lượng riêng là 1,4 kg/m3. Biết căn bậc hai giá trị trung bình của các bình phương tốc độ của các phân tử khí neon ( $\\sqrt{\\overline{v^2}}$ ) là 450 m/s. Áp suất khí trong bình là Sử dụng các thông tin sau cho câu 6 và câu 7: Trong một cylinder kín có chứa một khối khí lí tưởng có áp suất 1,5.10<sup>5</sup> N/m2, thể tích 4 dm3 và nhiệt độ 27 °C được nung nóng đẳng áp đến nhiệt độ 57 °C. Khí dãn nở, đẩy piston dịch chuyển đều và không ma sát. Biết nội năng của khối khí tăng thêm 100 J.","difficulty":"de","explanation":"Chọn đáp án C<br>Ta có:  $\\overline{v^2}=\\frac{3RT}{M}$    $\\frac{RT}{M}=\\frac{ \\overline{v^2}}{3}$<br>Áp dụng phương trình Clapeyron:  $pV=nRT$    $p=D.\\frac{RT}{M}$<br>Suy ra:  $p=D.\\frac{ \\overline{v^2}}{3}=1,4.\\frac{{450}^2}{3}=94500$  Pa.","difficultySource":"ai"}}]},{"id":396916,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng liên kết riêng và độ bền hạt nhân","answer":0,"options":["1,1178 MeV/nucleon.","2,2356 MeV.","1,2.10<sup>3</sup> MeV/nucleon.","2,4.10<sup>3</sup> MeV/nucleon."],"question":"Hạt nhân  ${}_1^2H$  có khối lượng 2,0136 u. Biết khối lượng của hạt proton và neutron lần lượt là 1,0073 u và 1,0087 u. Lấy 1 uc2 = 931,5 MeV. Năng lượng liên kết riêng của hạt nhân  ${}_1^2H$  bằng","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Năng lượng liên kết riêng là năng lượng liên kết chia cho số nuclôn: $\\varepsilon=\\dfrac{E_{lk}}{A}$, với $E_{lk}=\\Delta m\\,c^2$.</p><p class=\"text-base leading-relaxed my-2\">Hạt nhân ${}_1^2H$ có $Z=1$ proton, $N=1$ neutron: $\\Delta m=1{,}0073+1{,}0087-2{,}0136=0{,}0024$ u.</p><p class=\"text-base leading-relaxed my-2\">$E_{lk}=0{,}0024\\cdot931{,}5=2{,}2356$ MeV.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\varepsilon=\\dfrac{2{,}2356}{2}=1{,}1178$ MeV/nuclôn.</p><p class=\"text-base leading-relaxed my-2\">Sai vì: B (2,2356 MeV) là năng lượng liên kết cả hạt nhân, chưa chia cho $A=2$ và sai đơn vị. C và D cỡ $10^3$ MeV/nuclôn, không đúng vì cả hạt nhân chỉ có $E_{lk}=2{,}2356$ MeV nên năng lượng riêng không thể lớn hơn thế.</p><p class=\"text-base leading-relaxed my-2\">Chọn A.</p>","difficultySource":"ai"},"ex":[{"exam":139,"idx":14,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng liên kết riêng và độ bền hạt nhân","answer":0,"options":["1,1178 MeV/nucleon.","2,2356 MeV.","1,2.10<sup>3</sup> MeV/nucleon.","2,4.10<sup>3</sup> MeV/nucleon."],"question":"Hạt nhân  ${}_1^2H$  có khối lượng 2,0136 u. Biết khối lượng của hạt proton và neutron lần lượt là 1,0073 u và 1,0087 u. Lấy 1 uc2 = 931,5 MeV. Năng lượng liên kết riêng của hạt nhân  ${}_1^2H$  bằng","difficulty":"trung-binh","explanation":"Chọn đáp án A<br>Năng lượng liên kết riêng của hạt nhân  ${}_1^2H$  bằng<br>$E_{lkr}=\\frac{E_{lk}}{A}=\\frac{\\left[Z.m_p+\\left(A-Z\\right).m_n-m_H\\right]}{A}=\\frac{\\left[1.1,0073+\\left(2-1\\right).1,0087-2,0136\\right].931,5}{2}=1,1178$  MeV/nucleon.","difficultySource":"ai"}}]},{"id":397265,"nq":{"form":"bai_tap","type":"short_answer","topic":"Định luật phóng xạ và chu kì bán rã","answer":"0,03","question":"Potassium (kali) là một khoáng chất chiếm tỉ lệ nhiều thứ ba trong cơ thể người. Kali có vai trò quan trọng trong việc điều chỉnh cân bằng chất lỏng, truyền tín hiệu đến hệ thần kinh và điều chỉnh sự co cơ. Kali tự nhiên có chứa đồng vị phóng xạ 40K với chu kì bán rã bằng 1,277.10<sup>9</sup> năm. Trong cơ thể một người, độ phóng xạ của 40K là 8280 Bq. Lấy 1 năm có 365 ngày. Khối lượng của 40K có trong cơ thể người này bằng bao nhiêu gram (g)? (Làm tròn kết quả đến chữ số hàng phần trăm)","difficulty":"trung-binh","explanation":"Ta có:  $H_t=.N_t=\\frac{\\ln\\left(2\\right)}{T}.\\frac{m}{M}.N_A$    $m=\\frac{H_t.T.M}{N_A.\\ln\\left(2\\right)}=\\frac{8280.1,277.{10}^9.365.24.3600.40}{6,02.{10}^{23}.\\ln\\left(2\\right)}\\approx 0,03$  g.<br>Vậy, khối lượng của 40K có trong cơ thể người này xấp xỉ bằng 0,03 g.","difficultySource":"ai"},"ex":[{"exam":139,"idx":27,"el":{"form":"bai_tap","type":"short_answer","topic":"Định luật phóng xạ và chu kì bán rã","answer":"0,03","question":"Potassium (kali) là một khoáng chất chiếm tỉ lệ nhiều thứ ba trong cơ thể người. Kali có vai trò quan trọng trong việc điều chỉnh cân bằng chất lỏng, truyền tín hiệu đến hệ thần kinh và điều chỉnh sự co cơ. Kali tự nhiên có chứa đồng vị phóng xạ 40K với chu kì bán rã bằng 1,277.10<sup>9</sup> năm. Trong cơ thể một người, độ phóng xạ của 40K là 8280 Bq. Lấy 1 năm có 365 ngày. Khối lượng của 40K có trong cơ thể người này bằng bao nhiêu gram (g)? (Làm tròn kết quả đến chữ số hàng phần trăm)","difficulty":"trung-binh","explanation":"Ta có:  $H_t=.N_t=\\frac{\\ln\\left(2\\right)}{T}.\\frac{m}{M}.N_A$    $m=\\frac{H_t.T.M}{N_A.\\ln\\left(2\\right)}=\\frac{8280.1,277.{10}^9.365.24.3600.40}{6,02.{10}^{23}.\\ln\\left(2\\right)}\\approx 0,03$  g.<br>Vậy, khối lượng của 40K có trong cơ thể người này xấp xỉ bằng 0,03 g.","difficultySource":"ai"}}]},{"id":398354,"nq":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"2,16","question":"Khi xe đứng yên, khối không khí trong lốp xe ô tô con có nhiệt độ 28°C, áp suất 2,0685.10<sup>5</sup> Pa. Khi lốp lăn trên đường thì khối không khí trong lốp có thể tích tăng thêm 2% so với khi đứng yên, nhiệt độ bằng 48°C và áp suất là x.10<sup>5</sup> Pa. Coi không khí trong lốp là lí tưởng. Giá trị của x là bao nhiêu (làm tròn kết quả đến hàng phần trăm)?","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Khối không khí trong lốp được coi là khí lí tưởng với lượng khí không đổi, nên áp dụng định luật Bôi-lơ – Ma-ri-ốt kết hợp định luật Sác-lơ dưới dạng phương trình trạng thái:</p><p class=\"text-base leading-relaxed my-2\">$\\dfrac{p_1V_1}{T_1}=\\dfrac{p_2V_2}{T_2}$</p><p class=\"text-base leading-relaxed my-2\">Chọn trạng thái 1 là khi xe đứng yên, trạng thái 2 là khi lốp lăn.</p><p class=\"text-base leading-relaxed my-2\">Đổi nhiệt độ sang kelvin: $T_1=28+273=301\\ \\text{K}$, $T_2=48+273=321\\ \\text{K}$.</p><p class=\"text-base leading-relaxed my-2\">Thể tích tăng 2%: $V_2=1,02V_1$.</p><p class=\"text-base leading-relaxed my-2\">Suy ra: $p_2=p_1\\cdot\\dfrac{V_1}{V_2}\\cdot\\dfrac{T_2}{T_1}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow p_2=2,0685\\cdot10^5\\cdot\\dfrac{1}{1,02}\\cdot\\dfrac{321}{301}\\approx 2,1626\\cdot10^5\\ \\text{Pa}$</p><p class=\"text-base leading-relaxed my-2\">Vậy $x\\approx 2,16$ (làm tròn đến hàng phần trăm).</p>","difficultySource":"ai"},"ex":[{"exam":140,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"2,16","question":"Khi xe đứng yên, khối không khí trong lốp xe ô tô con có nhiệt độ 28°C, áp suất 2,0685.10<sup>5</sup> Pa. Khi lốp lăn trên đường thì khối không khí trong lốp có thể tích tăng thêm 2% so với khi đứng yên, nhiệt độ bằng 48°C và áp suất là x.10<sup>5</sup> Pa. Coi không khí trong lốp là lí tưởng. Giá trị của x là bao nhiêu (làm tròn kết quả đến hàng phần trăm)?","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Khối không khí trong lốp được coi là khí lí tưởng với lượng khí không đổi, nên áp dụng định luật Bôi-lơ – Ma-ri-ốt kết hợp định luật Sác-lơ dưới dạng phương trình trạng thái:</p><p class=\"text-base leading-relaxed my-2\">$\\dfrac{p_1V_1}{T_1}=\\dfrac{p_2V_2}{T_2}$</p><p class=\"text-base leading-relaxed my-2\">Chọn trạng thái 1 là khi xe đứng yên, trạng thái 2 là khi lốp lăn.</p><p class=\"text-base leading-relaxed my-2\">Đổi nhiệt độ sang kelvin: $T_1=28+273=301\\ \\text{K}$, $T_2=48+273=321\\ \\text{K}$.</p><p class=\"text-base leading-relaxed my-2\">Thể tích tăng 2%: $V_2=1,02V_1$.</p><p class=\"text-base leading-relaxed my-2\">Suy ra: $p_2=p_1\\cdot\\dfrac{V_1}{V_2}\\cdot\\dfrac{T_2}{T_1}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow p_2=2,0685\\cdot10^5\\cdot\\dfrac{1}{1,02}\\cdot\\dfrac{321}{301}\\approx 2,1626\\cdot10^5\\ \\text{Pa}$</p><p class=\"text-base leading-relaxed my-2\">Vậy $x\\approx 2,16$ (làm tròn đến hàng phần trăm).</p>","difficultySource":"ai"}},{"exam":182,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"2,16","question":"Khi xe đứng yên, khối không khí trong lốp xe ô tô con có nhiệt độ 28°C, áp suất 2,0685.10<sup>5</sup> Pa. Khi lốp lăn trên đường thì khối không khí trong lốp có thể tích tăng thêm 2% so với khi đứng yên, nhiệt độ bằng 48°C và áp suất là x.10<sup>5</sup> Pa. Coi không khí trong lốp là lí tưởng. Giá trị của x là bao nhiêu (làm tròn kết quả đến hàng phần trăm)?","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Khối không khí trong lốp được coi là khí lí tưởng với lượng khí không đổi, nên áp dụng định luật Bôi-lơ – Ma-ri-ốt kết hợp định luật Sác-lơ dưới dạng phương trình trạng thái:</p><p class=\"text-base leading-relaxed my-2\">$\\dfrac{p_1V_1}{T_1}=\\dfrac{p_2V_2}{T_2}$</p><p class=\"text-base leading-relaxed my-2\">Chọn trạng thái 1 là khi xe đứng yên, trạng thái 2 là khi lốp lăn.</p><p class=\"text-base leading-relaxed my-2\">Đổi nhiệt độ sang kelvin: $T_1=28+273=301\\ \\text{K}$, $T_2=48+273=321\\ \\text{K}$.</p><p class=\"text-base leading-relaxed my-2\">Thể tích tăng 2%: $V_2=1,02V_1$.</p><p class=\"text-base leading-relaxed my-2\">Suy ra: $p_2=p_1\\cdot\\dfrac{V_1}{V_2}\\cdot\\dfrac{T_2}{T_1}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow p_2=2,0685\\cdot10^5\\cdot\\dfrac{1}{1,02}\\cdot\\dfrac{321}{301}\\approx 2,1626\\cdot10^5\\ \\text{Pa}$</p><p class=\"text-base leading-relaxed my-2\">Vậy $x\\approx 2,16$ (làm tròn đến hàng phần trăm).</p>","difficultySource":"ai"}}]},{"id":398468,"nq":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"85,8","question":"Một nút chai bị kẹt ở cổ một chai thủy tinh chứa không khí có áp suất bằng áp suất khí quyển 105 Pa và nhiệt độ 26°C. Người ta hơ nóng khí trong chai, nút bật ra nếu áp suất của khí trong chai lớn hơn hoặc bằng 1,2.10<sup>5</sup> Pa. Coi khí trong chai là khí lí tưởng và không bị thoát ra ngoài khi hơ nóng, sự dãn nở vì nhiệt của chai không đáng kể. Nhiệt độ tối thiểu của khí để nút chai bật ra là bao nhiêu °C (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"$V=const\\Rightarrow \\frac{10^5}{26+273}=\\frac{1,2.10^5}{t+273}\\Rightarrow t=85,8\\left({}_{}^0C\\right)$","difficultySource":"ai"},"ex":[{"exam":140,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"85,8","question":"Một nút chai bị kẹt ở cổ một chai thủy tinh chứa không khí có áp suất bằng áp suất khí quyển 105 Pa và nhiệt độ 26°C. Người ta hơ nóng khí trong chai, nút bật ra nếu áp suất của khí trong chai lớn hơn hoặc bằng 1,2.10<sup>5</sup> Pa. Coi khí trong chai là khí lí tưởng và không bị thoát ra ngoài khi hơ nóng, sự dãn nở vì nhiệt của chai không đáng kể. Nhiệt độ tối thiểu của khí để nút chai bật ra là bao nhiêu °C (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"$V=const\\Rightarrow \\frac{10^5}{26+273}=\\frac{1,2.10^5}{t+273}\\Rightarrow t=85,8\\left({}_{}^0C\\right)$","difficultySource":"ai"}},{"exam":182,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"85,8","question":"Một nút chai bị kẹt ở cổ một chai thủy tinh chứa không khí có áp suất bằng áp suất khí quyển 105 Pa và nhiệt độ 26°C. Người ta hơ nóng khí trong chai, nút bật ra nếu áp suất của khí trong chai lớn hơn hoặc bằng 1,2.10<sup>5</sup> Pa. Coi khí trong chai là khí lí tưởng và không bị thoát ra ngoài khi hơ nóng, sự dãn nở vì nhiệt của chai không đáng kể. Nhiệt độ tối thiểu của khí để nút chai bật ra là bao nhiêu °C (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"$V=const\\Rightarrow \\frac{10^5}{26+273}=\\frac{1,2.10^5}{t+273}\\Rightarrow t=85,8\\left({}_{}^0C\\right)$","difficultySource":"ai"}}]},{"id":398525,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"1,33","question":"Dẫn 0,5 kg hơi nước ở nhiệt độ 100°C từ một lò hơi vào một bình chứa 1 kg nước đá ở 0°C. Cho biết nhiệt dung riêng của nước là c = 4200 J/kg. K, nhiệt hoá hơi riêng của nước là L = 2,3.10<sup>6</sup> J/kg và nhiệt nóng chảy riêng của nước đá là λ = 3,4.10<sup>5</sup> J/kg, bỏ qua sự hấp thụ nhiệt của bình chứa. Khi có cân bằng nhiệt, khối lượng nước ở trong bình khi đó là bao nhiêu kg (làm tròn đến 2 chữ số sau dấu phẩy thập phân).","difficulty":"kho","explanation":"Nước  = Đá tan chảy + Hơi nước ngưng tụ<br>$Q_{toa}=0,5.2,3.10^6=1150000\\left(J\\right)$<br>$Q_{thu}=1.3,4.10^5340000+1.4200.100=760000\\left(J\\right)$<br>$m_{ngung tu}=\\frac{760000}{2,3.10^6}=0,33\\left(kg\\right)$<br>$\\Rightarrow$  Nước = 1kg + 0,33 = 1,33 kg","difficultySource":"ai"},"ex":[{"exam":140,"idx":27,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"1,33","question":"Dẫn 0,5 kg hơi nước ở nhiệt độ 100°C từ một lò hơi vào một bình chứa 1 kg nước đá ở 0°C. Cho biết nhiệt dung riêng của nước là c = 4200 J/kg. K, nhiệt hoá hơi riêng của nước là L = 2,3.10<sup>6</sup> J/kg và nhiệt nóng chảy riêng của nước đá là λ = 3,4.10<sup>5</sup> J/kg, bỏ qua sự hấp thụ nhiệt của bình chứa. Khi có cân bằng nhiệt, khối lượng nước ở trong bình khi đó là bao nhiêu kg (làm tròn đến 2 chữ số sau dấu phẩy thập phân).","difficulty":"kho","explanation":"Nước  = Đá tan chảy + Hơi nước ngưng tụ<br>$Q_{toa}=0,5.2,3.10^6=1150000\\left(J\\right)$<br>$Q_{thu}=1.3,4.10^5340000+1.4200.100=760000\\left(J\\right)$<br>$m_{ngung tu}=\\frac{760000}{2,3.10^6}=0,33\\left(kg\\right)$<br>$\\Rightarrow$  Nước = 1kg + 0,33 = 1,33 kg","difficultySource":"ai"}},{"exam":182,"idx":27,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"1,33","question":"Dẫn 0,5 kg hơi nước ở nhiệt độ 100°C từ một lò hơi vào một bình chứa 1 kg nước đá ở 0°C. Cho biết nhiệt dung riêng của nước là c = 4200 J/kg. K, nhiệt hoá hơi riêng của nước là L = 2,3.10<sup>6</sup> J/kg và nhiệt nóng chảy riêng của nước đá là λ = 3,4.10<sup>5</sup> J/kg, bỏ qua sự hấp thụ nhiệt của bình chứa. Khi có cân bằng nhiệt, khối lượng nước ở trong bình khi đó là bao nhiêu kg (làm tròn đến 2 chữ số sau dấu phẩy thập phân).","difficulty":"kho","explanation":"Nước  = Đá tan chảy + Hơi nước ngưng tụ<br>$Q_{toa}=0,5.2,3.10^6=1150000\\left(J\\right)$<br>$Q_{thu}=1.3,4.10^5340000+1.4200.100=760000\\left(J\\right)$<br>$m_{ngung tu}=\\frac{760000}{2,3.10^6}=0,33\\left(kg\\right)$<br>$\\Rightarrow$  Nước = 1kg + 0,33 = 1,33 kg","difficultySource":"ai"}}]},{"id":398844,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":3,"options":["Q = 668 kJ.","Q = 6,68 kJ.","Q = 6,68 J.","Q = 66,8 kJ."],"question":"Tính nhiệt lượng Q cần cung cấp để làm nóng chảy hoàn toàn 200g nước đá ở 0°C. Biết nhiệt nóng chảy riêng của nước đá bằng 3,34.10<sup>5</sup>J/kg.","difficulty":"de","explanation":"Chọn đáp án D<br>$Q=m\\lambda =0,2.3,34.10^5=6,68.10^3\\left(J\\right)=66,8\\left(kJ\\right)$","difficultySource":"ai"},"ex":[{"exam":141,"idx":10,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":3,"options":["Q = 668 kJ.","Q = 6,68 kJ.","Q = 6,68 J.","Q = 66,8 kJ."],"question":"Tính nhiệt lượng Q cần cung cấp để làm nóng chảy hoàn toàn 200g nước đá ở 0°C. Biết nhiệt nóng chảy riêng của nước đá bằng 3,34.10<sup>5</sup>J/kg.","difficulty":"de","explanation":"Chọn đáp án D<br>$Q=m\\lambda =0,2.3,34.10^5=6,68.10^3\\left(J\\right)=66,8\\left(kJ\\right)$","difficultySource":"ai"}}]},{"id":399134,"nq":{"form":"bai_tap","type":"true_false","topic":"Đọc đồ thị các đẳng quá trình","question":"Một xi lanh kín chứa 2g khí Helium (He), khối khí thực hiện chu trình biến đổi trạng thái từ (1) → (2) → (3) → (4) → (1) được biểu diễn trên đồ thị (p – T) như hình vẽ. Cho p0 = 1,5.10<sup>5</sup> Pa, T0 = 300 K. Biết khối lượng mol của Helium là 4 g/mol; R =8,31 J/(mol.K). ⟦ảnh WMF⟧","difficulty":"kho","statements":[{"text":"Quá trình biến đổi từ trạng thái (4) đến trạng thái (1) là quá trình đẳng tích.","answer":true},{"text":"Thể tích khí ở trạng thái (2) lớn hơn thể tích khí ở trạng thái (1).","answer":false},{"text":"Thể tích của khối khí khi ở trạng thái (1) là V1 = 2,77 lít.","answer":true},{"text":"Trong quá trình biến đổi từ trạng thái (1) đến trạng thái (2), chất khí đã thực hiện công có độ lớn 1246,5 J","answer":false}],"explanation":"a) đúng<br>Đồ thị pOT: Quá trình (4) → (1) là một đường thẳng kéo dài cắt qua gốc toạ độ → Đẳng tích.<br>b) sai<br>Quá trình từ (1) sang (2): Đường  $\\left(1\\right)\\rightarrow \\left(2\\right)$  vuông góc Op, áp suất không đổi  $\\Rightarrow$  $\\left(1\\right)\\rightarrow \\left(2\\right)$  đẳng áp<br>Từ  $\\left(1\\right)\\rightarrow \\left(2\\right):T_0↑$<br>Nhiệt độ ở trạng thái (2): 3T0 gấp 3 lần nhiệt độ ở trạng thái (1): T0<br>$\\Rightarrow$  Thể tích ở trạng thái (2) gấp 3 lần thể tích ở trạng thái (1)<br>$\\Rightarrow \\left\\{\\begin{aligned}p_1=p_2 <br>T_2=3T_1\\end{aligned}\\right.\\Rightarrow V_2=3V_1$<br>c) đúng<br>$n=\\frac{m}{M}=\\frac{2}{2}=0,5\\left(mol\\right)$<br>$pV=nRT\\Rightarrow p_1V_1=nRT_1$<br>Trạng thái 1:  $3p_0$<br>$\\Rightarrow 3.1,5.10^5.V_1=0,5.8,31.8,31$<br>$\\Rightarrow V_1=2,77.10^{−3}m^3=2,77\\left(lit\\right)$<br>d) sai<br>Từ  $\\left(1\\right)\\rightarrow \\left(2\\right)$  là quá trình dãn nở đẳng áp  $\\Rightarrow$  Công khối khí thực hiện:  $p.\\Delta V$<br>Áp suất ở trạng thái (1) và (2) bằng nhau<br>$\\Rightarrow p_1.\\left(V_2−V_1\\right)=p_1\\left(3V_1−V_1\\right)=2p_1V_1=2.3.1,5.10^5.2,77.10^{−3}=2493\\left(J\\right)$","difficultySource":"ai"},"ex":[{"exam":141,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Đọc đồ thị các đẳng quá trình","question":"Một xi lanh kín chứa 2g khí Helium (He), khối khí thực hiện chu trình biến đổi trạng thái từ (1) → (2) → (3) → (4) → (1) được biểu diễn trên đồ thị (p – T) như hình vẽ. Cho p0 = 1,5.10<sup>5</sup> Pa, T0 = 300 K. Biết khối lượng mol của Helium là 4 g/mol; R =8,31 J/(mol.K). ⟦ảnh WMF⟧","difficulty":"kho","statements":[{"text":"Quá trình biến đổi từ trạng thái (4) đến trạng thái (1) là quá trình đẳng tích.","answer":true},{"text":"Thể tích khí ở trạng thái (2) lớn hơn thể tích khí ở trạng thái (1).","answer":false},{"text":"Thể tích của khối khí khi ở trạng thái (1) là V1 = 2,77 lít.","answer":true},{"text":"Trong quá trình biến đổi từ trạng thái (1) đến trạng thái (2), chất khí đã thực hiện công có độ lớn 1246,5 J","answer":false}],"explanation":"a) đúng<br>Đồ thị pOT: Quá trình (4) → (1) là một đường thẳng kéo dài cắt qua gốc toạ độ → Đẳng tích.<br>b) sai<br>Quá trình từ (1) sang (2): Đường  $\\left(1\\right)\\rightarrow \\left(2\\right)$  vuông góc Op, áp suất không đổi  $\\Rightarrow$  $\\left(1\\right)\\rightarrow \\left(2\\right)$  đẳng áp<br>Từ  $\\left(1\\right)\\rightarrow \\left(2\\right):T_0↑$<br>Nhiệt độ ở trạng thái (2): 3T0 gấp 3 lần nhiệt độ ở trạng thái (1): T0<br>$\\Rightarrow$  Thể tích ở trạng thái (2) gấp 3 lần thể tích ở trạng thái (1)<br>$\\Rightarrow \\left\\{\\begin{aligned}p_1=p_2 <br>T_2=3T_1\\end{aligned}\\right.\\Rightarrow V_2=3V_1$<br>c) đúng<br>$n=\\frac{m}{M}=\\frac{2}{2}=0,5\\left(mol\\right)$<br>$pV=nRT\\Rightarrow p_1V_1=nRT_1$<br>Trạng thái 1:  $3p_0$<br>$\\Rightarrow 3.1,5.10^5.V_1=0,5.8,31.8,31$<br>$\\Rightarrow V_1=2,77.10^{−3}m^3=2,77\\left(lit\\right)$<br>d) sai<br>Từ  $\\left(1\\right)\\rightarrow \\left(2\\right)$  là quá trình dãn nở đẳng áp  $\\Rightarrow$  Công khối khí thực hiện:  $p.\\Delta V$<br>Áp suất ở trạng thái (1) và (2) bằng nhau<br>$\\Rightarrow p_1.\\left(V_2−V_1\\right)=p_1\\left(3V_1−V_1\\right)=2p_1V_1=2.3.1,5.10^5.2,77.10^{−3}=2493\\left(J\\right)$","difficultySource":"ai"}}]},{"id":399250,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"962","question":"Một thỏi nhôm có khối lượng l,0 kg ở nhiệt độ 8°C . Biết nhôm nóng chảy ở 658°C, nhiệt nóng chảy riêng của nhôm là 3,9.10<sup>5</sup> J/Kg và nhiệt dung riêng của nhôm là 880 J/(kg.K). Cần cung cấp nhiệt lượng Q bằng bao nhiêu kJ để làm nóng chảy hoàn toàn thỏi nhôm này?(làm tròn kết quả đến chữ số hàng đơn vị)","difficulty":"trung-binh","explanation":"$Q=mc\\Delta t+m\\lambda$<br>$\\Rightarrow Q=1.880.\\left(658−8\\right)+1.3,9.10^5$<br>$\\Rightarrow Q=962.10^3\\left(J\\right)=962\\left(kJ\\right)$","difficultySource":"ai"},"ex":[{"exam":141,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"962","question":"Một thỏi nhôm có khối lượng l,0 kg ở nhiệt độ 8°C . Biết nhôm nóng chảy ở 658°C, nhiệt nóng chảy riêng của nhôm là 3,9.10<sup>5</sup> J/Kg và nhiệt dung riêng của nhôm là 880 J/(kg.K). Cần cung cấp nhiệt lượng Q bằng bao nhiêu kJ để làm nóng chảy hoàn toàn thỏi nhôm này?(làm tròn kết quả đến chữ số hàng đơn vị)","difficulty":"trung-binh","explanation":"$Q=mc\\Delta t+m\\lambda$<br>$\\Rightarrow Q=1.880.\\left(658−8\\right)+1.3,9.10^5$<br>$\\Rightarrow Q=962.10^3\\left(J\\right)=962\\left(kJ\\right)$","difficultySource":"ai"}}]},{"id":400180,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Tính lực từ F = BIl·sinθ","answer":0,"options":["1,8.10<sup>−4</sup> N .","2,8.10<sup>−4</sup> N .","3,1.10<sup>−4</sup> N .","2,1.10<sup>−4</sup> N ."],"question":"Một đoạn dây dẫn thẳng có chiều dài 2,0m mang dòng điện 6,0A được đặt nằm ngang, hướng của dòng điện tạo với hướng Tây một góc 600 lệch về phía Nam. Trong vùng này, từ trường của trái đất coi là đều, cảm ứng từ có độ lớn là 3.10<sup>−5</sup> T và hướng về phía Bắc. Lực từ tác dụng lên đoạn dây dẫn trên có độ lớn bằng","difficulty":"trung-binh","explanation":"Chọn đáp án A<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259768108-hinh-1.png\" alt=\"Hình 1\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>$F=BIℓsin\\left(\\vec{B};\\vec{I}\\right)=3.10^{−5}.6.2.sin\\left(90+60\\right)\\approx 1,8.10^{−4}N$","difficultySource":"ai"},"ex":[{"exam":143,"idx":2,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Tính lực từ F = BIl·sinθ","answer":0,"options":["1,8.10<sup>−4</sup> N .","2,8.10<sup>−4</sup> N .","3,1.10<sup>−4</sup> N .","2,1.10<sup>−4</sup> N ."],"question":"Một đoạn dây dẫn thẳng có chiều dài 2,0m mang dòng điện 6,0A được đặt nằm ngang, hướng của dòng điện tạo với hướng Tây một góc 600 lệch về phía Nam. Trong vùng này, từ trường của trái đất coi là đều, cảm ứng từ có độ lớn là 3.10<sup>−5</sup> T và hướng về phía Bắc. Lực từ tác dụng lên đoạn dây dẫn trên có độ lớn bằng","difficulty":"trung-binh","explanation":"Chọn đáp án A<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259768108-hinh-1.png\" alt=\"Hình 1\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>$F=BIℓsin\\left(\\vec{B};\\vec{I}\\right)=3.10^{−5}.6.2.sin\\left(90+60\\right)\\approx 1,8.10^{−4}N$","difficultySource":"ai"}}]},{"id":401283,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Liên hệ áp suất với động năng phân tử","answer":0,"options":["31,25.10<sup>22</sup>.","42,23.10<sup>24</sup>.","31,25.10<sup>24</sup>.","16,52.10<sup>22</sup>."],"question":"Một bình chứa khí lí tưởng có áp suất bằng 2,2.10<sup>5</sup> Pa, thể tích 0,5 m3 và khối lượng mỗi phân tử khí chứa trong bình bằng 6,6.10<sup>−24</sup> kg. Trung bình của bình phương tốc độ phân tử khí  $v^2$ = 4002(v tính bằng m/s). Số phân tử khí N chứa trong bình bằng bao nhiêu?","difficulty":"trung-binh","explanation":"Chọn đáp án A<br>$p=\\frac{1}{3}\\frac{N}{V}.m.v^2$<br>$\\Rightarrow 2,2.10^5=\\frac{1}{3}\\frac{N}{0,5}.6,6.10^{−24}.400^2$<br>$\\Rightarrow N=31,25.10^{22}$  (phân tử)","difficultySource":"ai"},"ex":[{"exam":144,"idx":13,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Liên hệ áp suất với động năng phân tử","answer":0,"options":["31,25.10<sup>22</sup>.","42,23.10<sup>24</sup>.","31,25.10<sup>24</sup>.","16,52.10<sup>22</sup>."],"question":"Một bình chứa khí lí tưởng có áp suất bằng 2,2.10<sup>5</sup> Pa, thể tích 0,5 m3 và khối lượng mỗi phân tử khí chứa trong bình bằng 6,6.10<sup>−24</sup> kg. Trung bình của bình phương tốc độ phân tử khí  $v^2$ = 4002(v tính bằng m/s). Số phân tử khí N chứa trong bình bằng bao nhiêu?","difficulty":"trung-binh","explanation":"Chọn đáp án A<br>$p=\\frac{1}{3}\\frac{N}{V}.m.v^2$<br>$\\Rightarrow 2,2.10^5=\\frac{1}{3}\\frac{N}{0,5}.6,6.10^{−24}.400^2$<br>$\\Rightarrow N=31,25.10^{22}$  (phân tử)","difficultySource":"ai"}}]},{"id":401573,"nq":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"64","question":"Một khinh khí cầu có tổng khối lượng (gồm khinh khí cầu và hành khách) là 450 kg. Phần khí cầu chứa 3,00.10<sup>3</sup> m3 không khí. Biết khí quyển bên ngoài có nhiệt độ là 25°C và áp suất là 1,03.10<sup>5</sup> Pa. Khi không khí trong khí cầu bị đốt nóng, nó bị giãn nở và một phần bị đẩy ra ngoài thông qua lỗ thoát khí phía trên khí cầu. Biết ở 25°C khối lượng riêng của không khí là 1,29 kg/m3, coi vỏ khí cầu mỏng, không giãn và nhẹ. Để khí cầu rời khỏi mặt đất, nhiệt độ khí trong khí cầu phải đạt tối thiểu là bao nhiêu °C (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"kho","explanation":"Đáp số 64<br>Coi như áp suất không đổi  $p=const$ ;<br>$pV=nRT=\\frac{m}{M}.RT\\Rightarrow D=\\frac{m}{V}=\\frac{pM}{RT}$  (p, M, R là hằng số, Cùng trong khí quyển M không đổi)<br>$\\Rightarrow D\\sim \\frac{1}{T}$<br>Để khí cầu bay lên được:  $F_{ASM}\\ge P_{KC}\\Rightarrow V.D_{kk}.g\\ge m_0g+V.D_{KC}g$<br>$\\Rightarrow 3000.1,29\\ge 450+3000.D_{KC}$<br>$\\Rightarrow D_{KC}\\le 1,14\\left(kg/m^3\\right)$<br>$\\Rightarrow \\frac{D_{KC}}{D_{KK}}=\\frac{T_{KK}}{T_{KC}}\\le \\frac{1,14}{1,29}$<br>$\\Rightarrow \\frac{25+273}{t+273}\\le \\frac{1,14}{1,29}$<br>$\\Rightarrow t\\ge 6,4^0C$","difficultySource":"ai"},"ex":[{"exam":144,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"64","question":"Một khinh khí cầu có tổng khối lượng (gồm khinh khí cầu và hành khách) là 450 kg. Phần khí cầu chứa 3,00.10<sup>3</sup> m3 không khí. Biết khí quyển bên ngoài có nhiệt độ là 25°C và áp suất là 1,03.10<sup>5</sup> Pa. Khi không khí trong khí cầu bị đốt nóng, nó bị giãn nở và một phần bị đẩy ra ngoài thông qua lỗ thoát khí phía trên khí cầu. Biết ở 25°C khối lượng riêng của không khí là 1,29 kg/m3, coi vỏ khí cầu mỏng, không giãn và nhẹ. Để khí cầu rời khỏi mặt đất, nhiệt độ khí trong khí cầu phải đạt tối thiểu là bao nhiêu °C (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"kho","explanation":"Đáp số 64<br>Coi như áp suất không đổi  $p=const$ ;<br>$pV=nRT=\\frac{m}{M}.RT\\Rightarrow D=\\frac{m}{V}=\\frac{pM}{RT}$  (p, M, R là hằng số, Cùng trong khí quyển M không đổi)<br>$\\Rightarrow D\\sim \\frac{1}{T}$<br>Để khí cầu bay lên được:  $F_{ASM}\\ge P_{KC}\\Rightarrow V.D_{kk}.g\\ge m_0g+V.D_{KC}g$<br>$\\Rightarrow 3000.1,29\\ge 450+3000.D_{KC}$<br>$\\Rightarrow D_{KC}\\le 1,14\\left(kg/m^3\\right)$<br>$\\Rightarrow \\frac{D_{KC}}{D_{KK}}=\\frac{T_{KK}}{T_{KC}}\\le \\frac{1,14}{1,29}$<br>$\\Rightarrow \\frac{25+273}{t+273}\\le \\frac{1,14}{1,29}$<br>$\\Rightarrow t\\ge 6,4^0C$","difficultySource":"ai"}}]},{"id":401689,"nq":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng ΔU = A + Q","answer":"5286","question":"Một lượng khí trong một xilanh hình trụ bị nung nóng, khí nở ra đẩy pit-tông lên làm thể tích tăng thêm 0,02 m3 và nội năng tăng thêm 1268 J. Biết áp suất của khối khí là 2.10<sup>5</sup> Pa và không đổi trong quá trình giãn nở. Nhiệt lượng đã truyền cho khí bằng bao nhiêu J (viết kết quả đến chữ số hàng đơn vị)?","difficulty":"trung-binh","explanation":"Đáp số 5286<br>Khối khí thực hiện công:  $p\\Delta V=2.10^5.0,02=4000\\left(J\\right)$<br>$\\Rightarrow$  Khối khí nhận công  $A=−4000\\left(J\\right)$<br>$\\Delta U=A+Q=1268\\left(J\\right)$<br>$\\Rightarrow Q=5268\\left(J\\right)$","difficultySource":"ai"},"ex":[{"exam":144,"idx":27,"el":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng ΔU = A + Q","answer":"5286","question":"Một lượng khí trong một xilanh hình trụ bị nung nóng, khí nở ra đẩy pit-tông lên làm thể tích tăng thêm 0,02 m3 và nội năng tăng thêm 1268 J. Biết áp suất của khối khí là 2.10<sup>5</sup> Pa và không đổi trong quá trình giãn nở. Nhiệt lượng đã truyền cho khí bằng bao nhiêu J (viết kết quả đến chữ số hàng đơn vị)?","difficulty":"trung-binh","explanation":"Đáp số 5286<br>Khối khí thực hiện công:  $p\\Delta V=2.10^5.0,02=4000\\left(J\\right)$<br>$\\Rightarrow$  Khối khí nhận công  $A=−4000\\left(J\\right)$<br>$\\Delta U=A+Q=1268\\left(J\\right)$<br>$\\Rightarrow Q=5268\\left(J\\right)$","difficultySource":"ai"}}]},{"id":401746,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":2,"options":["230 kJ.","230 J.","263,6 kJ.","263,6 J."],"question":"Biết nhiệt dung riêng và nhiệt hóa hơi riêng của nước lần lượt là 4200 J/(kg.K) và 2,3.10<sup>6</sup> J/kg. Nhiệt độ sôi của nước là 100 °C. Nhiệt lượng cần cung cấp để làm hóa hơi hoàn toàn 100 g nước ở 20°C là","difficulty":"trung-binh","explanation":"Chọn đáp án C<br>Nhiệt lượng cần cung cấp để làm hóa hơi hoàn toàn 100 g nước ở 20°C là<br>$Q=mc\\Delta T+Lm=0,1.4200.\\left(100-20\\right)+2,3.{10}^6.0,1=263,6$  kJ.","difficultySource":"ai"},"ex":[{"exam":145,"idx":2,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":2,"options":["230 kJ.","230 J.","263,6 kJ.","263,6 J."],"question":"Biết nhiệt dung riêng và nhiệt hóa hơi riêng của nước lần lượt là 4200 J/(kg.K) và 2,3.10<sup>6</sup> J/kg. Nhiệt độ sôi của nước là 100 °C. Nhiệt lượng cần cung cấp để làm hóa hơi hoàn toàn 100 g nước ở 20 C là","difficulty":"trung-binh","explanation":"Chọn đáp án C<br>Nhiệt lượng cần cung cấp để làm hóa hơi hoàn toàn 100 g nước ở 20 C là<br>$Q=mc\\Delta T+Lm=0,1.4200.\\left(100-20\\right)+2,3.{10}^6.0,1=263,6$  kJ.","difficultySource":"ai"}}]},{"id":402082,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Tính độ hụt khối và năng lượng liên kết","answer":2,"options":["1,98.10<sup>14</sup> u.","1,91 u.","1,98.10<sup>14</sup> kg.","1,91 g."],"question":"Hạt nhân uranium  ${}_{92}^{235}U$  có năng lượng liên kết riêng là 7,59 MeV/nucleon. Lấy 1 uc2 = 931,5 MeV. Độ hụt khối của hạt nhân  ${}_{92}^{235}U$  xấp xỉ bằng","difficulty":"trung-binh","explanation":"Chọn đáp án C<br>Năng lượng liên kết của một hạt nhân được xác định bằng năng lượng cần thiết để tách rời tất cả các nucleon trong hạt nhân.","difficultySource":"ai"},"ex":[{"exam":145,"idx":14,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Tính độ hụt khối và năng lượng liên kết","answer":2,"options":["1,98.10<sup>14</sup> u.","1,91 u.","1,98.10<sup>14</sup> kg.","1,91 g."],"question":"Hạt nhân uranium  ${}_{92}^{235}U$  có năng lượng liên kết riêng là 7,59 MeV/nucleon. Lấy 1 uc2 = 931,5 MeV. Độ hụt khối của hạt nhân  ${}_{92}^{235}U$  xấp xỉ bằng","difficulty":"trung-binh","explanation":"Chọn đáp án C<br>Năng lượng liên kết của một hạt nhân được xác định bằng năng lượng cần thiết để tách rời tất cả các nucleon trong hạt nhân.","difficultySource":"ai"}}]},{"id":402138,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":0,"options":["7,34 MeV.","7,34.10<sup>25</sup> MeV.","14,7 MeV.","1,47.10<sup>26</sup> MeV."],"question":"Xét phản ứng nhiệt hạch:  ${}_1^2H$  +  ${}_1^2H$    ${}_2^4{He}$  có năng lượng tỏa ra là 3,25 MeV. Nếu quá trình nhiệt hạch sử dụng hết 150 g  ${}_1^2H$  thì tổng năng lượng thu được xấp xỉ bằng","difficulty":"trung-binh","explanation":"Chọn đáp án A<br>Ta có:  $N_t=25%N_0=N_0.2^{-\\frac{t}{T}}$    $0,25=2^{-\\frac{3}{T}}$    $T=1,5$  giờ.","difficultySource":"ai"},"ex":[{"exam":145,"idx":16,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":0,"options":["7,34 MeV.","7,34.10<sup>25</sup> MeV.","14,7 MeV.","1,47.10<sup>26</sup> MeV."],"question":"Xét phản ứng nhiệt hạch:  ${}_1^2H$  +  ${}_1^2H$    ${}_2^4{He}$  có năng lượng tỏa ra là 3,25 MeV. Nếu quá trình nhiệt hạch sử dụng hết 150 g  ${}_1^2H$  thì tổng năng lượng thu được xấp xỉ bằng","difficulty":"trung-binh","explanation":"Chọn đáp án A<br>Ta có:  $N_t=25%N_0=N_0.2^{-\\frac{t}{T}}$    $0,25=2^{-\\frac{3}{T}}$    $T=1,5$  giờ.","difficultySource":"ai"}}]},{"id":402306,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"16","question":"Biết nhiệt nóng chảy riêng của aluminium (Al) là 4.10<sup>5</sup> J/kg, của lead (Pb) là 0,25.105 J/kg. Nhiệt lượng cần thiết để làm nóng chảy hoàn toàn 1 kg aluminium ở nhiệt độ nóng chảy có thể làm nóng chảy hoàn toàn bao nhiêu kilogram (kg) lead?","difficulty":"de","explanation":"Đáp số 16<br>Ta có:  $Q_{Al}=Q_{Pb}$    ${}_{Al}.m_{Al}={}_{Pb}.m_{Pb}$    $4.{10}^5.1=0,25.{10}^5.m_{Pb}$    $m_{Pb}=16$  kg.","difficultySource":"ai"},"ex":[{"exam":145,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"16","question":"Biết nhiệt nóng chảy riêng của aluminium (Al) là 4.10<sup>5</sup> J/kg, của lead (Pb) là 0,25.105 J/kg. Nhiệt lượng cần thiết để làm nóng chảy hoàn toàn 1 kg aluminium ở nhiệt độ nóng chảy có thể làm nóng chảy hoàn toàn bao nhiêu kilogram (kg) lead?","difficulty":"de","explanation":"Đáp số 16<br>Ta có:  $Q_{Al}=Q_{Pb}$    ${}_{Al}.m_{Al}={}_{Pb}.m_{Pb}$    $4.{10}^5.1=0,25.{10}^5.m_{Pb}$    $m_{Pb}=16$  kg.","difficultySource":"ai"}}]},{"id":402970,"nq":{"form":"bai_tap","type":"true_false","topic":"Quá trình đẳng nhiệt và định luật Boyle","question":"Vào thế kỷ XIX, Lord Kelvin đã đưa ra phương pháp \"ống đo độ sâu\" để đo độ sâu dưới mặt nước biển. Với phương pháp này, người ta sử dụng một ống chứa không khí có một đầu bịt kín, một đầu để hở. Thành trong của ống được phủ một lớp bột. Trong quá trình ống được đưa xuống nước tới độ sâu h (tính từ mặt nước), lượng không khí trong ống luôn không đổi. Khi ống được đưa ra lại trên mặt nước, bằng cách đo chiều dài đoạn ống đã bị rửa trôi bột, người ta có thể xác định được độ sâu h. Cho biết áp suất khí quyển trên mặt nước p0 =1,013.10<sup>5</sup> Pa , khối lượng riêng của nước  $\\rho =$ 1030 kg/m3 , gia tốc trọng trường g = 9,80 $m/s^2$ . Coi không khí trong ống là khí lí tưởng và nhiệt độ của nó không đổi.","difficulty":"kho","statements":[{"text":"Quá trình biến đổi trạng thái của lượng khí trong ống tuân theo định luật Charles.","answer":false},{"text":"Càng xuống sâu, thể tích khối khí trong ống càng tăng lên.","answer":false},{"text":"Áp suất không khí trong ống p phụ thuộc vào độ sâu h theo công thức  $p=p_0+\\rho gh$ .","answer":true},{"text":"Một nhà khoa học sử dụng phương pháp \"ống đo độ sâu\" để nghiên cứu tập tính lặn của một loài chim biển. Nhà khoa học gắn các ống có chiều dài 6,5 cm vào các con chim. Khi chúng trở lại mặt nước, nhà khoa học thu hồi các ống và đo chiều dài đoạn ống đã bị rửa trôi bột. Kết quả cho thấy nước đã rửa trôi bột một đoạn dài lớn nhất 1,5 cm tính từ đầu hở của ống. Nhà khoa học tính toán và đưa ra kết luận độ sâu lớn nhất mà loài chim biển này lặn xuống là 5 m.","answer":false}],"explanation":"a) S  b) S  c) Đ  d) S<br>a) sai<br>Nhiệt độ không đổi ⇒ đẳng nhiệt.<br>b) sai<br>Đẳng nhiệt: pV = hs , càng xuống sâu thì áp suất p tăng theo h với  $p=p_0+\\rho gh$   $\\Rightarrow$ thể tích V giảm.<br>c) đúng<br>Áp suất không khí trong ống p phụ thuộc vào độ sâu h theo công thức:  $p=p_0+\\rho gh$<br>d) sai<br>Đẳng nhiệt:  $pV=hs\\Rightarrow p_0.S.ℓ=\\left(p_0+\\rho gh\\right).S.\\left(ℓ−\\Delta ℓ\\right)$<br>$\\Rightarrow 1,013.10^5.6,5=\\left(1,013.10^5+1030.9,8.h\\right).\\left(6,5−1,5\\right)\\Rightarrow h\\approx 3m$","difficultySource":"ai"},"ex":[{"exam":146,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Quá trình đẳng nhiệt và định luật Boyle","question":"Vào thế kỷ XIX, Lord Kelvin đã đưa ra phương pháp \"ống đo độ sâu\" để đo độ sâu dưới mặt nước biển. Với phương pháp này, người ta sử dụng một ống chứa không khí có một đầu bịt kín, một đầu để hở. Thành trong của ống được phủ một lớp bột. Trong quá trình ống được đưa xuống nước tới độ sâu h (tính từ mặt nước), lượng không khí trong ống luôn không đổi. Khi ống được đưa ra lại trên mặt nước, bằng cách đo chiều dài đoạn ống đã bị rửa trôi bột, người ta có thể xác định được độ sâu h. Cho biết áp suất khí quyển trên mặt nước p0 =1,013.10<sup>5</sup> Pa , khối lượng riêng của nước  $\\rho =$ 1030 kg/m3 , gia tốc trọng trường g = 9,80 m/s2 . Coi không khí trong ống là khí lí tưởng và nhiệt độ của nó không đổi.","difficulty":"kho","statements":[{"text":"Quá trình biến đổi trạng thái của lượng khí trong ống tuân theo định luật Charles.","answer":false},{"text":"Càng xuống sâu, thể tích khối khí trong ống càng tăng lên.","answer":false},{"text":"Áp suất không khí trong ống p phụ thuộc vào độ sâu h theo công thức  $p=p_0+\\rho gh$ .","answer":true},{"text":"Một nhà khoa học sử dụng phương pháp \"ống đo độ sâu\" để nghiên cứu tập tính lặn của một loài chim biển. Nhà khoa học gắn các ống có chiều dài 6,5 cm vào các con chim. Khi chúng trở lại mặt nước, nhà khoa học thu hồi các ống và đo chiều dài đoạn ống đã bị rửa trôi bột. Kết quả cho thấy nước đã rửa trôi bột một đoạn dài lớn nhất 1,5 cm tính từ đầu hở của ống. Nhà khoa học tính toán và đưa ra kết luận độ sâu lớn nhất mà loài chim biển này lặn xuống là 5 m.","answer":false}],"explanation":"a) S  b) S  c) Đ  d) S<br>a) sai<br>Nhiệt độ không đổi ⇒ đẳng nhiệt.<br>b) sai<br>Đẳng nhiệt: pV = hs , càng xuống sâu thì áp suất p tăng theo h với  $p=p_0+\\rho gh$   $\\Rightarrow$ thể tích V giảm.<br>c) đúng<br>Áp suất không khí trong ống p phụ thuộc vào độ sâu h theo công thức:  $p=p_0+\\rho gh$<br>d) sai<br>Đẳng nhiệt:  $pV=hs\\Rightarrow p_0.S.ℓ=\\left(p_0+\\rho gh\\right).S.\\left(ℓ−\\Delta ℓ\\right)$<br>$\\Rightarrow 1,013.10^5.6,5=\\left(1,013.10^5+1030.9,8.h\\right).\\left(6,5−1,5\\right)\\Rightarrow h\\approx 3m$","difficultySource":"ai"}}]},{"id":404539,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Đồng vị Iodine  ${}_{53}^{131}I$ là chất phóng xạ β− được sử dụng trong y học để điều trị các bệnh liên quan đến tuyến giáp. Chất này có chu kỳ bán rã là 8,04 ngày. Một bệnh nhân được chỉ định sử dụng liều Iodine-131 với độ phóng xạ ban đầu là 50 mCi (1 Ci = 3,7.10<sup>10</sup> Bq ).","difficulty":"kho","statements":[{"text":"Hạt nhân  ${}_{53}^{131}I$ phát ra hạt electron để biến đổi thành hạt nhân ${}_{54}^{131}{Xe}$ .","answer":true},{"text":"Hằng số phóng xạ của  ${}_{53}^{131}I$ là 0,086 s-1.","answer":false},{"text":"Khối lượng của  ${}_{53}^{131}I$ ban đầu có trong liều mà bệnh nhân đã sử dụng xấp xỉ 0,4 µg.","answer":true},{"text":"Bệnh nhân đó được chỉ định ngừng sử dụng trong thời gian 6 tuần mới kiểm tra lại. Khi kiểm tra kết quả cho thấy độ phóng xạ còn lại không vượt quá 5% liều dùng.","answer":true}],"explanation":"a) Đ  b) S  c) Đ  d) Đ<br>a) đúng<br>Phân rã β- là quá trình hạt nhân phát ra hạt electron, làm số hiệu nguyên tử Z tăng 1 đơn vị thành 54 tạo ra Xenon, trong khi số khối A giữ nguyên là 131 .<br>b) sai<br>$\\lambda =\\frac{ln2}{T}=\\frac{ln2}{8,04.24.60.60}=9,978.10^{−7}(s^{−1})$<br>c) đúng<br>$H_0=\\lambda N_0=\\lambda .\\frac{m_0}{M}.N_A$<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259822407-hinh-8.png\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>$\\Rightarrow m_0\\approx 0,4\\left(\\mu g\\right)$<br>d) đúng<br>Thời gian 6 tuần tương đương 42 ngày. Tỉ lệ độ phóng xạ còn lại là:<br>$\\frac{H}{H_0}=2^{−\\frac{t}{T}}=2^{−\\frac{42}{8,04}}\\approx$  2,68%, giá trị này hoàn toàn không vượt quá 5% liều dùng ban đầu. H0","difficultySource":"ai"},"ex":[{"exam":148,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Đồng vị Iodine  ${}_{53}^{131}I$ là chất phóng xạ β− được sử dụng trong y học để điều trị các bệnh liên quan đến tuyến giáp. Chất này có chu kỳ bán rã là 8,04 ngày. Một bệnh nhân được chỉ định sử dụng liều Iodine-131 với độ phóng xạ ban đầu là 50 mCi (1 Ci = 3,7.10<sup>10</sup> Bq ).","difficulty":"kho","statements":[{"text":"Hạt nhân  ${}_{53}^{131}I$ phát ra hạt electron để biến đổi thành hạt nhân ${}_{54}^{131}{Xe}$ .","answer":true},{"text":"Hằng số phóng xạ của  ${}_{53}^{131}I$ là 0,086 s-1.","answer":false},{"text":"Khối lượng của  ${}_{53}^{131}I$ ban đầu có trong liều mà bệnh nhân đã sử dụng xấp xỉ 0,4 µg.","answer":true},{"text":"Bệnh nhân đó được chỉ định ngừng sử dụng trong thời gian 6 tuần mới kiểm tra lại. Khi kiểm tra kết quả cho thấy độ phóng xạ còn lại không vượt quá 5% liều dùng.","answer":true}],"explanation":"a) Đ  b) S  c) Đ  d) Đ<br>a) đúng<br>Phân rã β- là quá trình hạt nhân phát ra hạt electron, làm số hiệu nguyên tử Z tăng 1 đơn vị thành 54 tạo ra Xenon, trong khi số khối A giữ nguyên là 131 .<br>b) sai<br>$\\lambda =\\frac{ln2}{T}=\\frac{ln2}{8,04.24.60.60}=9,978.10^{−7}(s^{−1})$<br>c) đúng<br>$H_0=\\lambda N_0=\\lambda .\\frac{m_0}{M}.N_A$<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259822407-hinh-8.png\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>$\\Rightarrow m_0\\approx 0,4\\left(\\mu g\\right)$<br>d) đúng<br>Thời gian 6 tuần tương đương 42 ngày. Tỉ lệ độ phóng xạ còn lại là:<br>$\\frac{H}{H_0}=2^{−\\frac{t}{T}}=2^{−\\frac{42}{8,04}}\\approx$  2,68%, giá trị này hoàn toàn không vượt quá 5% liều dùng ban đầu. H0","difficultySource":"ai"}}]},{"id":407677,"nq":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"5","question":"Một quả bóng có dung tích không đổi là 2,5 lít. Người ta bơm không khí ở áp suất khí quyển 100kN/m2 vào bóng. Mỗi lần bơm được 125 cm3 không khí. Coi quả bóng trước khi bơm không có không khí và trong thời gian bơm nhiệt độ của không khí không đổi. Áp suất của không khí trong quả bóng sau 10 lần bơm bằng X.10<sup>4</sup> N/m2. Tìm giá trị X .","difficulty":"trung-binh","explanation":"Trạng thái 1 (khí bơm):  $\\left\\{\\begin{aligned}V_1=10.125=1250cm^3=1,25ℓ <br>p_1=10^5Pa\\end{aligned}\\right.$<br>Trạng thái 2 (trong bóng):  $\\left\\{\\begin{aligned}V_2=2,5ℓ <br>p_2\\end{aligned}\\right.$<br>Áp dụng công thức định luật Boyle, ta có:<br>$p_1V_1=p_2V_2\\Rightarrow p_2=\\frac{p_1V_1}{V_2}$<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259854497-hinh-5.png\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"},"ex":[{"exam":152,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"5","question":"Một quả bóng có dung tích không đổi là 2,5 lít. Người ta bơm không khí ở áp suất khí quyển 100kN/m2 vào bóng. Mỗi lần bơm được 125 cm3 không khí. Coi quả bóng trước khi bơm không có không khí và trong thời gian bơm nhiệt độ của không khí không đổi. Áp suất của không khí trong quả bóng sau 10 lần bơm bằng X.10<sup>4</sup> N/m2. Tìm giá trị X .","difficulty":"trung-binh","explanation":"Trạng thái 1 (khí bơm):  $\\left\\{\\begin{aligned}V_1=10.125=1250cm^3=1,25ℓ <br>p_1=10^5Pa\\end{aligned}\\right.$<br>Trạng thái 2 (trong bóng):  $\\left\\{\\begin{aligned}V_2=2,5ℓ <br>p_2\\end{aligned}\\right.$<br>Áp dụng công thức định luật Boyle, ta có:<br>$p_1V_1=p_2V_2\\Rightarrow p_2=\\frac{p_1V_1}{V_2}$<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259854497-hinh-5.png\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"}}]},{"id":409538,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Liên hệ áp suất với động năng phân tử","answer":3,"options":["100 Pa.","500 Pa.","1.10<sup>3</sup> Pa.","5.10<sup>3</sup> Pa."],"question":"Khối lượng riêng của chất khí bằng 6.10<sup>−2</sup> kg/m3, tốc độ căn quân phương của chúng là 500 m/s. Áp suất mà khí đó tác dụng lên thành bình là","difficulty":"trung-binh","explanation":"Áp suất mà khối khí tác dụng lên thành bình:<br>$p=\\frac{1}{3}\\mu .m.\\overline{v^2}=\\frac{1}{3}.D.\\overline{v^2}=\\frac{1}{3}∙{6.10}^{-2}∙{\\left(500\\right)}^2\\approx {5.10}^3 Pa.$","difficultySource":"ai"},"ex":[{"exam":155,"idx":7,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Liên hệ áp suất với động năng phân tử","answer":3,"options":["100 Pa.","500 Pa.","1.10<sup>3</sup> Pa.","5.10<sup>3</sup> Pa."],"question":"Khối lượng riêng của chất khí bằng 6.10<sup>−2</sup> kg/m3, tốc độ căn quân phương của chúng là 500 m/s. Áp suất mà khí đó tác dụng lên thành bình là","difficulty":"trung-binh","explanation":"Áp suất mà khối khí tác dụng lên thành bình:<br>$p=\\frac{1}{3}\\mu .m.\\overline{v^2}=\\frac{1}{3}.D.\\overline{v^2}=\\frac{1}{3}∙{6.10}^{-2}∙{\\left(500\\right)}^2\\approx {5.10}^3 Pa.$","difficultySource":"ai"}}]},{"id":409886,"nq":{"form":"bai_tap","type":"true_false","topic":"Động năng trung bình phân tử và nhiệt độ","question":"Khi leo lên đỉnh Everest, các nhà leo núi phải đối mặt với sự thay đổi khắc nghiệt của áp suất và nhiệt độ, ảnh hưởng trực tiếp đến lượng khí oxygen cung cấp cho cơ thể. Giả sử coi thể tích không khí hít vào bằng dung tích phổi là V = 5,0 lít, không khí đi vào phổi sẽ nhanh chóng được cơ thể làm nóng để nhiệt độ 37oC. Coi không khí là khí lí tưởng có khối lượng mol là 29 g/mol và hằng số Boltzmann k = 1,38.10<sup>−23</sup> J/K. Xét tại hai vị trí: + Tại nơi cắm trại: áp suất p1 = 54 kPa, nhiệt độ t1 = – 3oC; + Tại đỉnh núi: áp suất p2 = 33 kPa, nhiệt độ t2 = –23oC.","difficulty":"kho","statements":[{"text":"Động năng tịnh tiến trung bình của các phân tử khí tại đỉnh núi nhỏ hơn tại nơi cắm trại khoảng 4,14.10<sup>−22</sup> J.","answer":true},{"text":"Tốc độ căn quân phương của các phân tử khí ngoài môi trường tại đỉnh núi xấp xỉ 464 m/s.","answer":true},{"text":"Khối lượng không khí hít vào phổi trong một lần hít tại nơi cắm trại xấp xỉ 3,48g.","answer":false},{"text":"Mật độ phân tử khí tại đỉnh núi giảm đi 30% so với tại nơi cắm trại.","answer":false}],"explanation":"a) đúng<br>Độ chênh lệch động năng tịnh tiến trung bình của phân tử tại hai vị trí:<br>$\\Delta \\overline{W_đ}={\\overline{W_đ}}_1-\\overline{W_{đ_2}}=\\frac{3}{2}.k.\\left(T_1-T_2\\right)=\\frac{3}{2}∙{1,38.10}^{-23}∙\\left[\\left(-3\\right)-\\left(-23\\right)\\right]={4,14.10}^{-22} J.$<br>b) đúng<br>Tốc độ căn quân phương của các phân tử khí ngoài môi trường tại đỉnh núi:<br>$\\overline{v_2^2}=\\sqrt{\\frac{3.R.T}{M}}=\\sqrt{\\frac{3∙8,31∙\\left(-23+273\\right)}{0,029}}\\approx 464 m/s.$<br>c) sai<br>Áp suất khí trong phổi sẽ bằng với áp suất khí bên ngoài. Phương trình trạng thái khí lí tưởng cho khối khí trong phổi:<br>$p.V=\\frac{m}{M}.R.T$<br>$⟹m=\\frac{p.V.M}{R.T}=\\frac{{54.10}^3∙{5.10}^{-3}∙29}{8,31∙\\left(37+273\\right)}\\approx 3,04 g.$<br>d) sai<br>Mật độ phân tử khí tại 2 vị trí:<br>$p=\\mu .k.T$<br>$⟹\\left\\{\\begin{aligned}\\mu_1=\\frac{p_1}{k.T_1} <br>\\mu_2=\\frac{p_2}{k.T_2}\\end{aligned}\\right.;$<br>Ta có:<br>$\\frac{\\mu_1}{\\mu_2}=\\frac{p_1.T_2}{p_2.T_1}=\\frac{54∙\\left(-23+273\\right)}{33∙\\left(-3+273\\right)}=\\frac{50}{33}⟹\\mu_2=66%\\mu_1;$<br>Vậy mật độ phân tử tại đỉnh núi giảm đi 34% so với tại nơi cắm trại.","difficultySource":"ai"},"ex":[{"exam":155,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Động năng trung bình phân tử và nhiệt độ","question":"Khi leo lên đỉnh Everest, các nhà leo núi phải đối mặt với sự thay đổi khắc nghiệt của áp suất và nhiệt độ, ảnh hưởng trực tiếp đến lượng khí oxygen cung cấp cho cơ thể. Giả sử coi thể tích không khí hít vào bằng dung tích phổi là V = 5,0 lít, không khí đi vào phổi sẽ nhanh chóng được cơ thể làm nóng để nhiệt độ 37oC. Coi không khí là khí lí tưởng có khối lượng mol là 29 g/mol và hằng số Boltzmann k = 1,38.10<sup>−23</sup> J/K. Xét tại hai vị trí: + Tại nơi cắm trại: áp suất p1 = 54 kPa, nhiệt độ t1 = – 3oC; + Tại đỉnh núi: áp suất p2 = 33 kPa, nhiệt độ t2 = –23oC.","difficulty":"kho","statements":[{"text":"Động năng tịnh tiến trung bình của các phân tử khí tại đỉnh núi nhỏ hơn tại nơi cắm trại khoảng 4,14.10<sup>−22</sup> J.","answer":true},{"text":"Tốc độ căn quân phương của các phân tử khí ngoài môi trường tại đỉnh núi xấp xỉ 464 m/s.","answer":true},{"text":"Khối lượng không khí hít vào phổi trong một lần hít tại nơi cắm trại xấp xỉ 3,48g.","answer":false},{"text":"Mật độ phân tử khí tại đỉnh núi giảm đi 30% so với tại nơi cắm trại.","answer":false}],"explanation":"a) đúng<br>Độ chênh lệch động năng tịnh tiến trung bình của phân tử tại hai vị trí:<br>$\\Delta \\overline{W_đ}={\\overline{W_đ}}_1-\\overline{W_{đ_2}}=\\frac{3}{2}.k.\\left(T_1-T_2\\right)=\\frac{3}{2}∙{1,38.10}^{-23}∙\\left[\\left(-3\\right)-\\left(-23\\right)\\right]={4,14.10}^{-22} J.$<br>b) đúng<br>Tốc độ căn quân phương của các phân tử khí ngoài môi trường tại đỉnh núi:<br>$\\overline{v_2^2}=\\sqrt{\\frac{3.R.T}{M}}=\\sqrt{\\frac{3∙8,31∙\\left(-23+273\\right)}{0,029}}\\approx 464 m/s.$<br>c) sai<br>Áp suất khí trong phổi sẽ bằng với áp suất khí bên ngoài. Phương trình trạng thái khí lí tưởng cho khối khí trong phổi:<br>$p.V=\\frac{m}{M}.R.T$<br>$⟹m=\\frac{p.V.M}{R.T}=\\frac{{54.10}^3∙{5.10}^{-3}∙29}{8,31∙\\left(37+273\\right)}\\approx 3,04 g.$<br>d) sai<br>Mật độ phân tử khí tại 2 vị trí:<br>$p=\\mu .k.T$<br>$⟹\\left\\{\\begin{aligned}\\mu_1=\\frac{p_1}{k.T_1} <br>\\mu_2=\\frac{p_2}{k.T_2}\\end{aligned}\\right.;$<br>Ta có:<br>$\\frac{\\mu_1}{\\mu_2}=\\frac{p_1.T_2}{p_2.T_1}=\\frac{54∙\\left(-23+273\\right)}{33∙\\left(-3+273\\right)}=\\frac{50}{33}⟹\\mu_2=66%\\mu_1;$<br>Vậy mật độ phân tử tại đỉnh núi giảm đi 34% so với tại nơi cắm trại.","difficultySource":"ai"}}]},{"id":409944,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Technetium ( ${}_{43}^{99}{Tc}$ ) là đồng vị phóng xạ nhân tạo được sử dụng rộng rãi nhất trong y học hạt nhân để chẩn đoán hình ảnh (xạ hình xương, tim, phổi...).  ${}_{43}^{99}{Tc}$  là chất phát xạ tia gamma () có chu kỳ bán rã ngắn T = 6,0 giờ. Sau khi tiêm vào cơ thể, nó sẽ tập trung tại các mô bệnh, phát ra tia gamma để camera chuyên dụng ghi lại hình ảnh, sau đó tự phân rã hoặc bị đào thải ra ngoài, giảm thiểu tác hại cho bệnh nhân. Giả sử một liều thuốc phóng xạ chứa  ${}_{43}^{99}{Tc}$  có độ phóng xạ ban đầu là H0 = 740 MBq được tiêm vào cơ thể bệnh nhân lúc 8 giờ sáng.","difficulty":"kho","statements":[{"text":"Tia gamma do  ${}_{43}^{99}{Tc}$  phát ra có bản chất là dòng hạt Helium chuyển động với tốc độ cao.","answer":false},{"text":"Người ta chọn  ${}_{43}^{99}{Tc}$  vì chu kỳ bán rã đủ dài để chụp ảnh nhưng đủ ngắn để bệnh nhân không bị phơi nhiễm phóng xạ quá lâu.","answer":true},{"text":"Đến 20 giờ cùng ngày, độ phóng xạ còn lại trong cơ thể bệnh nhân (giả sử chưa bị bài tiết qua đường tiêu hóa) chỉ còn 185 MBq.","answer":true},{"text":"Khối lượng  ${}_{43}^{99}{Tc}$  có trong liều thuốc tiêm ban đầu xấp xỉ 3,8.10<sup>−9</sup> gam.","answer":true}],"explanation":"a) sai<br>Tia gamma có bản chất là sóng điện từ.<br>b) đúng<br>Người ta chọn  ${}_{43}^{99}{Tc}$  vì chu kỳ bán rã đủ dài để chụp ảnh nhưng đủ ngắn để bệnh nhân không bị phơi nhiễm phóng xạ quá lâu.<br>c) đúng<br>Độ phóng xạ còn lại trong cơ thể người lúc 20 giờ cùng ngày:<br>$H=H_0.2^{-\\frac{t}{T}}=740∙2^{-\\frac{12}{6}}=185 MBq.$<br>d) đúng<br>Khối lượng  ${}_{43}^{99}{Tc}$  trong liều thuốc ban đầu:<br>$H_0=\\lambda .N_0=\\frac{\\ln\\left(2\\right)}{T}.\\frac{m}{M}.N_A$<br>$⟺\\frac{\\ln\\left(2\\right)}{\\left(6∙3600\\right)}∙\\frac{m}{99}∙{6,02.10}^{23}={740.10}^6$<br>$⟹m\\approx {3,8.10}^{-9} g.$","difficultySource":"ai"},"ex":[{"exam":155,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Technetium ( ${}_{43}^{99}{Tc}$ ) là đồng vị phóng xạ nhân tạo được sử dụng rộng rãi nhất trong y học hạt nhân để chẩn đoán hình ảnh (xạ hình xương, tim, phổi...).  ${}_{43}^{99}{Tc}$  là chất phát xạ tia gamma () có chu kỳ bán rã ngắn T = 6,0 giờ. Sau khi tiêm vào cơ thể, nó sẽ tập trung tại các mô bệnh, phát ra tia gamma để camera chuyên dụng ghi lại hình ảnh, sau đó tự phân rã hoặc bị đào thải ra ngoài, giảm thiểu tác hại cho bệnh nhân. Giả sử một liều thuốc phóng xạ chứa  ${}_{43}^{99}{Tc}$  có độ phóng xạ ban đầu là H0 = 740 MBq được tiêm vào cơ thể bệnh nhân lúc 8 giờ sáng.","difficulty":"kho","statements":[{"text":"Tia gamma do  ${}_{43}^{99}{Tc}$  phát ra có bản chất là dòng hạt Helium chuyển động với tốc độ cao.","answer":false},{"text":"Người ta chọn  ${}_{43}^{99}{Tc}$  vì chu kỳ bán rã đủ dài để chụp ảnh nhưng đủ ngắn để bệnh nhân không bị phơi nhiễm phóng xạ quá lâu.","answer":true},{"text":"Đến 20 giờ cùng ngày, độ phóng xạ còn lại trong cơ thể bệnh nhân (giả sử chưa bị bài tiết qua đường tiêu hóa) chỉ còn 185 MBq.","answer":true},{"text":"Khối lượng  ${}_{43}^{99}{Tc}$  có trong liều thuốc tiêm ban đầu xấp xỉ 3,8.10<sup>−9</sup> gam.","answer":true}],"explanation":"a) sai<br>Tia gamma có bản chất là sóng điện từ.<br>b) đúng<br>Người ta chọn  ${}_{43}^{99}{Tc}$  vì chu kỳ bán rã đủ dài để chụp ảnh nhưng đủ ngắn để bệnh nhân không bị phơi nhiễm phóng xạ quá lâu.<br>c) đúng<br>Độ phóng xạ còn lại trong cơ thể người lúc 20 giờ cùng ngày:<br>$H=H_0.2^{-\\frac{t}{T}}=740∙2^{-\\frac{12}{6}}=185 MBq.$<br>d) đúng<br>Khối lượng  ${}_{43}^{99}{Tc}$  trong liều thuốc ban đầu:<br>$H_0=\\lambda .N_0=\\frac{\\ln\\left(2\\right)}{T}.\\frac{m}{M}.N_A$<br>$⟺\\frac{\\ln\\left(2\\right)}{\\left(6∙3600\\right)}∙\\frac{m}{99}∙{6,02.10}^{23}={740.10}^6$<br>$⟹m\\approx {3,8.10}^{-9} g.$","difficultySource":"ai"}}]},{"id":411512,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Ban đầu, một mẫu chất phóng xạ chỉ chứa 0,248 mg đồng vị phóng xạ  ${}_{11}^{25}{Na}$ . Biết rằng, đồng vị phóng xạ̣  ${}_{11}^{25}{Na}$  có chu kì bán rã là 62 giây. Lấy khối lượng nguyên tử bằng số khối của nguyên tử đó tính theo đơn vị amu.","difficulty":"kho","statements":[{"text":"Cứ sau mỗi khoảng thời gian là 62 giây thì một nửa số hạt nhân  ${}_{11}^{25}{Na}$  còn lại trong mẫu bị phân rã.","answer":true},{"text":"Độ phóng xạ ban đầu của mẫu chất phóng xạ  ${}_{11}^{25}{Na}$  xấp xỉ bằng 6,68.10<sup>19</sup> Bq.","answer":false},{"text":"Sau 5 phút (kể từ thời điểm ban đầu), khối lượng đồng vị phóng xạ  ${}_{11}^{25}{Na}$  còn lại trong mẫu trên xấp xỉ bằng 8,67 mg.","answer":false},{"text":"Sau 186 giây (kể từ thời điểm ban đầu), độ phóng xạ của mẫu chất phóng xạ chỉ còn bằng 12,5% độ phóng xạ ban đầu.","answer":true}],"explanation":"a) đúng<br>Đồng vị phóng xạ̣  ${}_{11}^{25}{Na}$  có chu kì bán rã là 62 giây. Nên cứ sau mỗi khoảng thời gian là 62 giây thì một nửa số hạt nhân  ${}_{11}^{25}{Na}$  còn lại trong mẫu bị phân rã.<br>b) sai<br>Độ phóng xạ ban đầu của mẫu chất phóng xạ  ${}_{11}^{25}{Na}$  là:<br>$H_0=.N_0=\\frac{\\ln\\left(2\\right)}{T}.\\frac{m_0}{M}.N_A=\\frac{\\ln\\left(2\\right)}{62}.\\frac{0,248.{10}^{-3}}{25}.6,02.{10}^{23}\\approx 6,68.{10}^{16}$  Bq.<br>c) sai<br>Sau 5 phút (kể từ thời điểm ban đầu), khối lượng đồng vị phóng xạ  ${}_{11}^{25}{Na}$  còn lại trong mẫu trên là:<br>$m_t=m_0.2^{-\\frac{t}{T}}=0,248.2^{-\\frac{5.60}{62}}\\approx 8,67.{10}^{-3}$  mg.<br>d) đúng<br>Ta có:  $\\frac{H_t}{H_0}=2^{-\\frac{t'}{T}}=2^{-\\frac{186}{62}}=\\frac{1}{8}=12,5%$  hay  $H_t=12,5%.H_0$<br>Vậy, sau 186 giây (kể từ thời điểm ban đầu), độ phóng xạ của mẫu chất phóng xạ chỉ còn bằng 12,5% độ phóng xạ ban đầu.","difficultySource":"ai"},"ex":[{"exam":157,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Ban đầu, một mẫu chất phóng xạ chỉ chứa 0,248 mg đồng vị phóng xạ  ${}_{11}^{25}{Na}$ . Biết rằng, đồng vị phóng xạ̣  ${}_{11}^{25}{Na}$  có chu kì bán rã là 62 giây. Lấy khối lượng nguyên tử bằng số khối của nguyên tử đó tính theo đơn vị amu.","difficulty":"kho","statements":[{"text":"Cứ sau mỗi khoảng thời gian là 62 giây thì một nửa số hạt nhân  ${}_{11}^{25}{Na}$  còn lại trong mẫu bị phân rã.","answer":true},{"text":"Độ phóng xạ ban đầu của mẫu chất phóng xạ  ${}_{11}^{25}{Na}$  xấp xỉ bằng 6,68.10<sup>19</sup> Bq.","answer":false},{"text":"Sau 5 phút (kể từ thời điểm ban đầu), khối lượng đồng vị phóng xạ  ${}_{11}^{25}{Na}$  còn lại trong mẫu trên xấp xỉ bằng 8,67 mg.","answer":false},{"text":"Sau 186 giây (kể từ thời điểm ban đầu), độ phóng xạ của mẫu chất phóng xạ chỉ còn bằng 12,5% độ phóng xạ ban đầu.","answer":true}],"explanation":"a) đúng<br>Đồng vị phóng xạ̣  ${}_{11}^{25}{Na}$  có chu kì bán rã là 62 giây. Nên cứ sau mỗi khoảng thời gian là 62 giây thì một nửa số hạt nhân  ${}_{11}^{25}{Na}$  còn lại trong mẫu bị phân rã.<br>b) sai<br>Độ phóng xạ ban đầu của mẫu chất phóng xạ  ${}_{11}^{25}{Na}$  là:<br>$H_0=.N_0=\\frac{\\ln\\left(2\\right)}{T}.\\frac{m_0}{M}.N_A=\\frac{\\ln\\left(2\\right)}{62}.\\frac{0,248.{10}^{-3}}{25}.6,02.{10}^{23}\\approx 6,68.{10}^{16}$  Bq.<br>c) sai<br>Sau 5 phút (kể từ thời điểm ban đầu), khối lượng đồng vị phóng xạ  ${}_{11}^{25}{Na}$  còn lại trong mẫu trên là:<br>$m_t=m_0.2^{-\\frac{t}{T}}=0,248.2^{-\\frac{5.60}{62}}\\approx 8,67.{10}^{-3}$  mg.<br>d) đúng<br>Ta có:  $\\frac{H_t}{H_0}=2^{-\\frac{t'}{T}}=2^{-\\frac{186}{62}}=\\frac{1}{8}=12,5%$  hay  $H_t=12,5%.H_0$<br>Vậy, sau 186 giây (kể từ thời điểm ban đầu), độ phóng xạ của mẫu chất phóng xạ chỉ còn bằng 12,5% độ phóng xạ ban đầu.","difficultySource":"ai"}}]},{"id":411570,"nq":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"4","question":"Một bình thép kín chứa khí oxygen có thể tích 10 lít. Ban đầu, khí trong bình có nhiệt độ 27 °C và áp suất 16.105 Pa. Sau một thời gian sử dụng, ở cùng nhiệt độ 27 °C, áp suất của khí trong bình giảm xuống còn 6.10<sup>5</sup> Pa. Xem khí oxygen là khí lí tưởng, thể tích của bình không đổi. Số mol khí oxygen đã thoát ra khỏi bình do sử dụng là bao nhiêu? (Làm tròn kết quả đến chữ số hàng đơn vị)","difficulty":"de","explanation":"Số mol khí oxygen đã thoát ra khỏi bình là:<br>$\\Delta n=n_1-n_2=\\frac{p_1.V}{RT}-\\frac{p_2.V}{RT}=\\frac{V}{RT}.\\left(p_1-p_2\\right)=\\frac{10.{10}^{-3}}{8,31.\\left(27+273\\right)}.\\left(16.{10}^5-6.{10}^5\\right)\\approx 4$  mol.","difficultySource":"ai"},"ex":[{"exam":157,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"4","question":"Một bình thép kín chứa khí oxygen có thể tích 10 lít. Ban đầu, khí trong bình có nhiệt độ 27 °C và áp suất 16.105 Pa. Sau một thời gian sử dụng, ở cùng nhiệt độ 27 °C, áp suất của khí trong bình giảm xuống còn 6.10<sup>5</sup> Pa. Xem khí oxygen là khí lí tưởng, thể tích của bình không đổi. Số mol khí oxygen đã thoát ra khỏi bình do sử dụng là bao nhiêu? (Làm tròn kết quả đến chữ số hàng đơn vị)","difficulty":"de","explanation":"Số mol khí oxygen đã thoát ra khỏi bình là:<br>$\\Delta n=n_1-n_2=\\frac{p_1.V}{RT}-\\frac{p_2.V}{RT}=\\frac{V}{RT}.\\left(p_1-p_2\\right)=\\frac{10.{10}^{-3}}{8,31.\\left(27+273\\right)}.\\left(16.{10}^5-6.{10}^5\\right)\\approx 4$  mol.","difficultySource":"ai"}}]},{"id":412502,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":1,"options":["33,4 J.","33400 J.","3340 J.","334000 J."],"question":"Cần cung cấp một nhiệt lượng bao nhiêu để làm nóng chảy hoàn toàn 100 g nước đá ở 0°C ? Biết nhiệt nóng chảy riêng của nước đá là λ = 3,34.10<sup>5</sup> J/kg.","difficulty":"de","explanation":"Đổi khối lượng: m = 100 g = 0,1 kg .<br>Nhiệt lượng cần cung cấp để làm nóng chảy hoàn toàn khối lượng nước đá trên ở nhiệt độ nóng chảy là:<br>Q = λm = 3,34.105.0,1 = 33400 J","difficultySource":"ai"},"ex":[{"exam":159,"idx":3,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":1,"options":["33,4 J.","33400 J.","3340 J.","334000 J."],"question":"Cần cung cấp một nhiệt lượng bao nhiêu để làm nóng chảy hoàn toàn 100 g nước đá ở 0°C ? Biết nhiệt nóng chảy riêng của nước đá là λ = 3,34.10<sup>5</sup> J/kg.","difficulty":"de","explanation":"Đổi khối lượng: m = 100 g = 0,1 kg .<br>Nhiệt lượng cần cung cấp để làm nóng chảy hoàn toàn khối lượng nước đá trên ở nhiệt độ nóng chảy là:<br>Q = λm = 3,34.105.0,1 = 33400 J","difficultySource":"ai"}}]},{"id":412937,"nq":{"form":"bai_tap","type":"true_false","topic":"Phương trình Clapeyron – Mendeleev","question":"Một chiếc lốp xe ô tô được bơm căng không khí ở nhiệt độ 27°C. Áp kế đo áp suất không khí trong lốp lúc này chỉ 2,1 atm. Biết thể tích phần không khí bên trong lốp xe là 30 lít và coi như không đổi trong quá trình sử dụng. Giả thiết không khí là khí lí tưởng. Biết R = 8,31 J/(mol.K), 1 atm = 1,013.10<sup>5</sup> Pa.","difficulty":"trung-binh","statements":[{"text":"Số mol không khí có trong lốp xe xấp xỉ 2,56 mol.","answer":true},{"text":"Khi xe chạy trên đường dài, nhiệt độ không khí trong lốp tăng lên làm cho động năng chuyển động nhiệt trung bình của các phân tử khí tăng, dẫn đến áp suất khí trong lốp tăng.","answer":true},{"text":"Nếu nhiệt độ không khí trong lốp tăng lên đến 57°C thì áp suất khí trong lốp đạt 2,5 atm.","answer":false},{"text":"Để giữ cho áp suất trong lốp ở 57°C vẫn bằng 2,1 atm như ban đầu, người lái xe cần xả bớt một lượng khí chiếm khoảng 9,1% lượng khí ban đầu trong lốp.","answer":true}],"explanation":"a) đúng<br>Trạng thái ban đầu của khí trong lốp: p1 = 2,1 atm = 2,1.1,013.10<sup>5</sup> Pa = 212730 Pa ; V = 30 lít =  30.10<sup>−3</sup> m3; T1 = 27 + 273 = 300 K .<br>Áp dụng phương trình trạng thái khí lí tưởng p1V = nRT1, ta có số mol khí:<br>$n=\\frac{p_1V}{RT_1}=\\frac{212730.30.10^{−3}}{8,31.300}\\approx 2,56\\left(mol\\right)$<br>b) đúng<br>Theo thuyết động học phân tử, nhiệt độ tỉ lệ thuận với động năng tịnh tiến trung bình của phân tử. Khi nhiệt độ tăng, các phân tử khí chuyển động nhiệt nhanh hơn, động năng trung bình tăng, chúng va chạm vào thành lốp mạnh hơn và với tần suất dày đặc hơn, làm cho áp suất khí trong lốp tăng lên.<br>c) sai<br>Quá trình làm nóng lốp xe khi thể tích không đổi là quá trình đẳng tích.<br>Nhiệt độ lúc sau T2 =  57 +  273 = 330K .<br>Áp dụng định luật Charles:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259928610-hinh-3.png\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>d) đúng<br>Để áp suất ở 57°C (T2 = 330K) vẫn là p1 = 2,1 atm với thể tích V không đổi, gọi số mol khí lúc này là n'<br>Ta có phương trình trạng thái mới:  $p_1V=n^/RT_2\\Rightarrow n^/=\\frac{p_1V}{RT_2}$<br>$\\Rightarrow \\frac{n^/}{n}=\\frac{T_1}{T_2}=\\frac{300}{330}=\\frac{10}{11}$<br>Lượng khí cần xả bớt là:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259928950-hinh-4.png\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Tức là lượng khí cần xả chiếm khoảng 9,09%  $\\approx$   9,1% lượng khí ban đầu.","difficultySource":"ai"},"ex":[{"exam":159,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Phương trình Clapeyron – Mendeleev","question":"Một chiếc lốp xe ô tô được bơm căng không khí ở nhiệt độ 27°C. Áp kế đo áp suất không khí trong lốp lúc này chỉ 2,1 atm. Biết thể tích phần không khí bên trong lốp xe là 30 lít và coi như không đổi trong quá trình sử dụng. Giả thiết không khí là khí lí tưởng. Biết R = 8,31 J/(mol.K), 1 atm = 1,013.10<sup>5</sup> Pa.","difficulty":"trung-binh","statements":[{"text":"Số mol không khí có trong lốp xe xấp xỉ 2,56 mol.","answer":true},{"text":"Khi xe chạy trên đường dài, nhiệt độ không khí trong lốp tăng lên làm cho động năng chuyển động nhiệt trung bình của các phân tử khí tăng, dẫn đến áp suất khí trong lốp tăng.","answer":true},{"text":"Nếu nhiệt độ không khí trong lốp tăng lên đến 57°C thì áp suất khí trong lốp đạt 2,5 atm.","answer":false},{"text":"Để giữ cho áp suất trong lốp ở 57°C vẫn bằng 2,1 atm như ban đầu, người lái xe cần xả bớt một lượng khí chiếm khoảng 9,1% lượng khí ban đầu trong lốp.","answer":true}],"explanation":"a) đúng<br>Trạng thái ban đầu của khí trong lốp: p1 = 2,1 atm = 2,1.1,013.10<sup>5</sup> Pa = 212730 Pa ; V = 30 lít =  30.10<sup>−3</sup> m3; T1 = 27 + 273 = 300 K .<br>Áp dụng phương trình trạng thái khí lí tưởng p1V = nRT1, ta có số mol khí:<br>$n=\\frac{p_1V}{RT_1}=\\frac{212730.30.10^{−3}}{8,31.300}\\approx 2,56\\left(mol\\right)$<br>b) đúng<br>Theo thuyết động học phân tử, nhiệt độ tỉ lệ thuận với động năng tịnh tiến trung bình của phân tử. Khi nhiệt độ tăng, các phân tử khí chuyển động nhiệt nhanh hơn, động năng trung bình tăng, chúng va chạm vào thành lốp mạnh hơn và với tần suất dày đặc hơn, làm cho áp suất khí trong lốp tăng lên.<br>c) sai<br>Quá trình làm nóng lốp xe khi thể tích không đổi là quá trình đẳng tích.<br>Nhiệt độ lúc sau T2 =  57 +  273 = 330K .<br>Áp dụng định luật Charles:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259928610-hinh-3.png\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>d) đúng<br>Để áp suất ở 57°C (T2 = 330K) vẫn là p1 = 2,1 atm với thể tích V không đổi, gọi số mol khí lúc này là n'<br>Ta có phương trình trạng thái mới:  $p_1V=n^/RT_2\\Rightarrow n^/=\\frac{p_1V}{RT_2}$<br>$\\Rightarrow \\frac{n^/}{n}=\\frac{T_1}{T_2}=\\frac{300}{330}=\\frac{10}{11}$<br>Lượng khí cần xả bớt là:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259928950-hinh-4.png\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Tức là lượng khí cần xả chiếm khoảng 9,09%  $\\approx$   9,1% lượng khí ban đầu.","difficultySource":"ai"}}]},{"id":413953,"nq":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"98","question":"Một thợ hàn dùng bình có thể tích 75dm3 chứa khí oxygen (khối lượng mol 32 g/mol ) ở áp suất đo được là 4,01.10<sup>5</sup> Pa và nhiệt độ 37°C . Bình chứa có một kẽ hở nhỏ, theo thời gian một phần oxygen sẽ rò rỉ ra ngoài. Đến thời điểm khi nhiệt độ là 22°C và áp suất của oxygen trong bình là 2,81.10<sup>5</sup> Pa thì khối lượng khí oxygen đã thoát ra ngoài là bao nhiêu gam? (Kết quà làm tròn đến chữ số hàng đơn vị)","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Khí oxygen coi là khí lí tưởng, tuân theo phương trình trạng thái $pV = nRT$ với $T = t + 273$ K. Thể tích bình không đổi nên số mol khí giảm chính là lượng khí thoát ra.</p><p class=\"text-base leading-relaxed my-2\">Dữ kiện: $V = 75\\ \\text{dm}^3 = 0{,}075\\ \\text{m}^3$; $R = 8{,}314\\ \\text{J/(mol·K)}$; $M = 32\\ \\text{g/mol}$.</p><p class=\"text-base leading-relaxed my-2\">Trạng thái đầu: $p_1 = 4{,}01\\cdot10^5\\ \\text{Pa}$, $T_1 = 37 + 273 = 310\\ \\text{K}$.</p><p class=\"text-base leading-relaxed my-2\">Số mol ban đầu: $n_1 = \\dfrac{p_1 V}{R T_1} = \\dfrac{4{,}01\\cdot10^5 \\cdot 0{,}075}{8{,}314 \\cdot 310} \\approx 11{,}67\\ \\text{mol}$.</p><p class=\"text-base leading-relaxed my-2\">Trạng thái sau: $p_2 = 2{,}81\\cdot10^5\\ \\text{Pa}$, $T_2 = 22 + 273 = 295\\ \\text{K}$.</p><p class=\"text-base leading-relaxed my-2\">Số mol còn lại: $n_2 = \\dfrac{p_2 V}{R T_2} = \\dfrac{2{,}81\\cdot10^5 \\cdot 0{,}075}{8{,}314 \\cdot 295} \\approx 8{,}59\\ \\text{mol}$.</p><p class=\"text-base leading-relaxed my-2\">Số mol khí đã thoát ra: $\\Delta n = n_1 - n_2 \\approx 11{,}67 - 8{,}59 = 3{,}08\\ \\text{mol}$.</p><p class=\"text-base leading-relaxed my-2\">Khối lượng khí thoát ra: $\\Delta m = \\Delta n \\cdot M \\approx 3{,}08 \\cdot 32 \\approx 98{,}4\\ \\text{g}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: khối lượng oxygen đã thoát ra khoảng $98\\ \\text{g}$.</p>","difficultySource":"ai"},"ex":[{"exam":160,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"98","question":"Một thợ hàn dùng bình có thể tích 75dm3 chứa khí oxygen (khối lượng mol 32 g/mol ) ở áp suất đo được là 4,01.10<sup>5</sup> Pa và nhiệt độ 37°C . Bình chứa có một kẽ hở nhỏ, theo thời gian một phần oxygen sẽ rò rỉ ra ngoài. Đến thời điểm khi nhiệt độ là 22°C và áp suất của oxygen trong bình là 2,81.10<sup>5</sup> Pa thì khối lượng khí oxygen đã thoát ra ngoài là bao nhiêu gam? (Kết quà làm tròn đến chữ số hàng đơn vị)","difficulty":"trung-binh","explanation":"Khối lượng khí đá thoát ra ngoài:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259944351-hinh-20.png\" alt=\"Hình 20\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"}}]},{"id":414856,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":1,"options":["264 kJ.","132 kJ.","132 J.","264 J."],"question":"Nhiệt nóng chảy riêng ở nhiệt độ nóng chảy dưới áp suất tiêu chuẩn của nước đá là 3,3.10<sup>5</sup> J/kg. Ở điều kiện áp suất tiêu chuẩn, nhiệt lượng cần cung cấp cho 400g nước đá nóng chảy hoàn toàn ở nhiệt độ nóng chảy là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Nhiệt lượng làm một vật rắn ở nhiệt độ nóng chảy tan hoàn toàn: $Q = \\lambda m$ (nước đá đã ở $0^\\circ C$ nên không cần thêm nhiệt để nâng nhiệt độ).</p><p class=\"text-base leading-relaxed my-2\">Đổi $m = 400\\ \\text{g} = 0{,}4\\ \\text{kg}$.</p><p class=\"text-base leading-relaxed my-2\">$Q = 3{,}3\\cdot 10^{5}\\cdot 0{,}4 = 1{,}32\\cdot 10^{5}\\ \\text{J} = 132\\ \\text{kJ}$.</p><p class=\"text-base leading-relaxed my-2\">Sai vì: $132\\ \\text{J}$ là quên đổi $132\\,000\\ \\text{J}$ sang kJ rồi bỏ nhầm ba chữ số. $264\\ \\text{kJ}$ và $264\\ \\text{J}$ gấp đôi $Q$ tính được; $264$ ứng với khối lượng $0{,}8\\ \\text{kg}$, không phải $400\\ \\text{g}$.</p><p class=\"text-base leading-relaxed my-2\">Chọn B.</p>","difficultySource":"ai"},"ex":[{"exam":162,"idx":5,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":1,"options":["264 kJ.","132 kJ.","132 J.","264 J."],"question":"Nhiệt nóng chảy riêng ở nhiệt độ nóng chảy dưới áp suất tiêu chuẩn của nước đá là 3,3.10<sup>5</sup> J/kg. Ở điều kiện áp suất tiêu chuẩn, nhiệt lượng cần cung cấp cho 400g nước đá nóng chảy hoàn toàn ở nhiệt độ nóng chảy là","difficulty":"de","explanation":"Nhiệt lượng cần cung cấp cho 400g nước đá nóng chảy hoàn toàn ở nhiệt độ nóng chảy:<br>$Q=m.\\lambda =0,4∙{3,3.10}^5=132000 J=132 kJ.$","difficultySource":"ai"}}]},{"id":417268,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":1,"options":["365 g.","686 g.","748 g.","246 g."],"question":"Dẫn 100 g hơi nước ở 100°C vào một bình cách nhiệt đựng nước đá ở -4°C. Khi cân bằng nhiệt thu được nước ở 10°C. Biết nhiệt nóng chảy riêng của nước đá là 3,4.10<sup>5</sup> J/kg , nhiệt hoá hơi riêng của nước ở 100°C là 2,3.10<sup>6</sup> J/kg, nhiệt dung riêng của nước và nước đá lần lượt là 4200 J / kg.K và 2100 J/kg.K . Khối lượng nước đá có trong bình lúc đầu gần giá trị nào nhất sau đây?","difficulty":"kho","explanation":"Chọn đáp án B<br>Khối lượng hơi nước: m1 =100 g = 0,1 kg .<br>Gọi khối lượng nước đá ban đầu là m2 (kg).<br>Nhiệt độ cân bằng là  $t=10^\\circ C$<br>Nhiệt lượng do 0,1 kg hơi nước toả ra để ngưng tụ hoàn toàn ở 100°C và nguội xuống 10°C là:<br>$Q_{toa}=m_1.L+m_1.c_n.\\left(100−t\\right)=0,1.2,3.10^6+0,1.4200.\\left(100−10\\right)=267800\\left(J\\right)$<br>Nhiệt lượng do m2 (kg) nước đá thu vào để tăng nhiệt độ từ −4°C lên 0°C, nóng chảy hoàn toàn ở 0°C và phần nước tạo thành tiếp tục tăng nhiệt độ từ 0°C lên 10°C là:<br>$Q_{thu}=m_2.c_d\\left[0−\\left(−4\\right)+m_2\\lambda +m_2.c_n\\right].\\left(10−0\\right)$<br>$Q_{thu}=m_2.\\left(2100.4+3,4.10^5+4200.10\\right)=390400.m_2\\left(J\\right)$<br>Áp dụng phương trình cân bằng nhiệt:<br>Qtoa = Qthu ⇔ 267800 = 390400.m2 ⇒ m2 ≈ 0,68596(kg) ≈ 686(g)<br>Giá trị này gần nhất với 686 g.","difficultySource":"ai"},"ex":[{"exam":165,"idx":9,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":1,"options":["365 g.","686 g.","748 g.","246 g."],"question":"Dẫn 100 g hơi nước ở 100°C vào một bình cách nhiệt đựng nước đá ở -4°C. Khi cân bằng nhiệt thu được nước ở 10°C. Biết nhiệt nóng chảy riêng của nước đá là 3,4.10<sup>5</sup> J/kg , nhiệt hoá hơi riêng của nước ở 100°C là 2,3.10<sup>6</sup> J/kg, nhiệt dung riêng của nước và nước đá lần lượt là 4200 J / kg.K và 2100 J/kg.K . Khối lượng nước đá có trong bình lúc đầu gần giá trị nào nhất sau đây?","difficulty":"kho","explanation":"Chọn đáp án B<br>Khối lượng hơi nước: m1 =100 g = 0,1 kg .<br>Gọi khối lượng nước đá ban đầu là m2 (kg).<br>Nhiệt độ cân bằng là  $t=10^0C$<br>Nhiệt lượng do 0,1 kg hơi nước toả ra để ngưng tụ hoàn toàn ở 100°C và nguội xuống 10°C là:<br>$Q_{toa}=m_1.L+m_1.c_n.\\left(100−t\\right)=0,1.2,3.10^6+0,1.4200.\\left(100−10\\right)=267800\\left(J\\right)$<br>Nhiệt lượng do m2 (kg) nước đá thu vào để tăng nhiệt độ từ −4°C lên 0°C, nóng chảy hoàn toàn ở 0°C và phần nước tạo thành tiếp tục tăng nhiệt độ từ 0°C lên 10°C là:<br>$Q_{thu}=m_2.c_d\\left[0−\\left(−4\\right)+m_2\\lambda +m_2.c_n\\right].\\left(10−0\\right)$<br>$Q_{thu}=m_2.\\left(2100.4+3,4.10^5+4200.10\\right)=390400.m_2\\left(J\\right)$<br>Áp dụng phương trình cân bằng nhiệt:<br>Qtoa = Qthu ⇔ 267800 = 390400.m2 ⇒ m2 ≈ 0,68596(kg) ≈ 686(g)<br>Giá trị này gần nhất với 686 g.","difficultySource":"ai"}}]},{"id":417732,"nq":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng ΔU = A + Q","answer":"340","question":"Khi truyền nhiệt lượng 400J cho khối khí trong một xilanh hình trụ được nắp kín bằng pittông thì khối khí dãn nở đẩy pit-tông lên, làm thể tích của khối khí tăng thêm 0,3 lít. Biết áp suất của khối khí là 2.10<sup>5</sup> Pa và không đổi trong quá trình khối khí dãn nở. Nội năng của khối khí đã biến thiên bao nhiêu jun (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"trung-binh","explanation":"Đáp số 340<br>Khối khí nhận nhiệt lượng: Q = 400 J .<br>Khối khí dãn nở đẩy pit-tông nên nó thực hiện công.<br>Độ lớn công do khí thực hiện:  $A^/=p.\\Delta V=2.10^5.\\left(0,3.10^{−3}\\right)=60(J)$<br>Vì khí thực hiện công nên công mà khối khí nhận được là A = −A′ = −60 J.<br>Độ biến thiên nội năng của khối khí là:<br>ΔU = Q + A = 400 + (−60) = 340(J)","difficultySource":"ai"},"ex":[{"exam":165,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng ΔU = A + Q","answer":"340","question":"Khi truyền nhiệt lượng 400J cho khối khí trong một xilanh hình trụ được nắp kín bằng pittông thì khối khí dãn nở đẩy pit-tông lên, làm thể tích của khối khí tăng thêm 0,3 lít. Biết áp suất của khối khí là 2.10<sup>5</sup> Pa và không đổi trong quá trình khối khí dãn nở. Nội năng của khối khí đã biến thiên bao nhiêu jun (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"trung-binh","explanation":"Đáp số 340<br>Khối khí nhận nhiệt lượng: Q = 400 J .<br>Khối khí dãn nở đẩy pit-tông nên nó thực hiện công.<br>Độ lớn công do khí thực hiện:  $A^/=p.\\Delta V=2.10^5.\\left(0,3.10^{−3}\\right)=60(J)$<br>Vì khí thực hiện công nên công mà khối khí nhận được là A = −A′ = −60 J.<br>Độ biến thiên nội năng của khối khí là:<br>ΔU = Q + A = 400 + (−60) = 340(J)","difficultySource":"ai"}}]},{"id":417995,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Liên hệ áp suất với động năng phân tử","answer":0,"options":["379,5 m/s.","219,1 m/s.","435,3 m/s.","424,3 m/s."],"question":"Chất khí có áp suất 1,2.10<sup>5</sup> Pa và khối lượng riêng là 2,5 kg/m3 thì có tốc độ căn quân phương của phân tử là","difficulty":"de","explanation":"Chọn đáp án A<br>Tốc độ căn quân phương của phân tử:<br>$p=\\frac{1}{3}\\mu .m.\\overline{v^2}=\\frac{1}{3}.D.\\overline{v^2}⟹\\sqrt{\\overline{v^2}}=\\sqrt{\\frac{3.p}{D}}=\\sqrt{\\frac{3∙{1,2.10}^5}{2,5}}\\approx 379,5 m/s.$","difficultySource":"ai"},"ex":[{"exam":166,"idx":8,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Liên hệ áp suất với động năng phân tử","answer":0,"options":["379,5 m/s.","219,1 m/s.","435,3 m/s.","424,3 m/s."],"question":"Chất khí có áp suất 1,2.10<sup>5</sup> Pa và khối lượng riêng là 2,5 kg/m3 thì có tốc độ căn quân phương của phân tử là","difficulty":"de","explanation":"Chọn đáp án A<br>Tốc độ căn quân phương của phân tử:<br>$p=\\frac{1}{3}\\mu .m.\\overline{v^2}=\\frac{1}{3}.D.\\overline{v^2}⟹\\sqrt{\\overline{v^2}}=\\sqrt{\\frac{3.p}{D}}=\\sqrt{\\frac{3∙{1,2.10}^5}{2,5}}\\approx 379,5 m/s.$","difficultySource":"ai"}}]},{"id":418140,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Từ thông qua khung dây","answer":1,"options":["1,2.10<sup>−6</sup> Wb.","1,2.10<sup>−4</sup> Wb.","2,1.10<sup>−6</sup> Wb.","2,1.10<sup>−4</sup> Wb."],"question":"Một khung dây có tiết diện 20 cm2 đặt trong từ trường đều có vector cảm ứng từ hợp với mặt phẳng khung dây một góc  $30^{\\circ}$  và có độ lớn 0,12 T. Từ thông qua khung dây này bằng","difficulty":"de","explanation":"Chọn đáp án B<br>Từ thông qua khung dây:<br>$\\Phi =B.S.\\cos\\left(\\alpha \\right)=0,12∙{20.10}^{-4}∙\\cos\\left(\\left(90^{\\circ}-30^{\\circ}\\right)\\right)={1,2.10}^{-4} Wb.$","distractorNotes":{"A":"Quên đổi 20 cm² sang m² đúng cách (nhân $10^{-4}$) và dùng sai góc.","C":"Nhầm hàm lượng giác và cách đổi diện tích, hoán đổi các chữ số của kết quả.","D":"Dùng $\\sin 60^{\\circ}$ thay vì $\\cos 60^{\\circ}$ do nhầm góc, đồng thời đổi sai đơn vị diện tích."},"difficultySource":"ai"},"ex":[{"exam":166,"idx":13,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Từ thông qua khung dây","answer":1,"options":["1,2.10<sup>−6</sup> Wb.","1,2.10<sup>−4</sup> Wb.","2,1.10<sup>−6</sup> Wb.","2,1.10<sup>−4</sup> Wb."],"question":"Một khung dây có tiết diện 20 cm2 đặt trong từ trường đều có vector cảm ứng từ hợp với mặt phẳng khung dây một góc  $30^{\\circ}$  và có độ lớn 0,12 T. Từ thông qua khung dây này bằng","difficulty":"de","explanation":"Chọn đáp án B<br>Từ thông qua khung dây:<br>$\\Phi =B.S.\\cos\\left(\\alpha \\right)=0,12∙{20.10}^{-4}∙\\cos\\left(\\left(90^{\\circ}-30^{\\circ}\\right)\\right)={1,2.10}^{-4} Wb.$","distractorNotes":{"A":"Quên đổi 20 cm² sang m² đúng cách (nhân $10^{-4}$) và dùng sai góc.","C":"Nhầm hàm lượng giác và cách đổi diện tích, hoán đổi các chữ số của kết quả.","D":"Dùng $\\sin 60^{\\circ}$ thay vì $\\cos 60^{\\circ}$ do nhầm góc, đồng thời đổi sai đơn vị diện tích."},"difficultySource":"ai"}}]},{"id":418924,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Tính lực từ F = BIl·sinθ","answer":3,"options":["0,5 T.","0,9 T.","1,5 T.","2,0 T."],"question":"Một đoạn dây dẫn dài 10 cm đặt trong từ trường đều và vuông góc với vector cảm ứng từ. Dòng điện chạy qua dây có cường độ 0,20 A. Lực từ tác dụng lên đoạn dây đó là 4.10<sup>−2</sup> N. Cảm ứng từ của từ trường có độ lớn là","difficulty":"de","explanation":"Chọn đáp án D<br>Độ lớn cảm ứng từ trong trường hợp này:<br>$F=BIl\\sin\\left(\\alpha \\right)⟹B=\\frac{F}{Il\\sin\\left(\\alpha \\right)}=\\frac{{4.10}^{-2}}{0,20∙0,10∙\\sin\\left(90^{\\circ}\\right)}=2,0 T.$","difficultySource":"ai"},"ex":[{"exam":167,"idx":13,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Tính lực từ F = BIl·sinθ","answer":3,"options":["0,5 T.","0,9 T.","1,5 T.","2,0 T."],"question":"Một đoạn dây dẫn dài 10 cm đặt trong từ trường đều và vuông góc với vector cảm ứng từ. Dòng điện chạy qua dây có cường độ 0,20 A. Lực từ tác dụng lên đoạn dây đó là 4.10<sup>−2</sup> N. Cảm ứng từ của từ trường có độ lớn là","difficulty":"de","explanation":"Chọn đáp án D<br>Độ lớn cảm ứng từ trong trường hợp này:<br>$F=BIl\\sin\\left(\\alpha \\right)⟹B=\\frac{F}{Il\\sin\\left(\\alpha \\right)}=\\frac{{4.10}^{-2}}{0,20∙0,10∙\\sin\\left(90^{\\circ}\\right)}=2,0 T.$","difficultySource":"ai"}}]},{"id":419796,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":0,"options":["0,12.","0,07.","0,16.","0,84."],"question":"Một bình đựng nước ở 0°C. Người ta làm nước trong bình đông đặc lại bằng cách hút không khí và hơi nước trong bình ra ngoài. Lấy nhiệt nóng chảy riêng của nước là 3,3.10<sup>5</sup> J/kg và nhiệt hoá hơi riêng của nước là 2,48.10<sup>6</sup> J/kg. Bỏ qua sự trao đổi nhiệt với bình và môi trường bên ngoài. Tỉ số giữa khối lượng nước bị hoá hơi và khối lượng nước ở trong bình lúc đầu là","difficulty":"kho","explanation":"<p class=\"text-base leading-relaxed my-2\">Bỏ qua trao đổi nhiệt với bên ngoài: nhiệt toả ra khi một phần nước đông đặc bằng nhiệt thu vào khi phần còn lại hoá hơi.</p><p class=\"text-base leading-relaxed my-2\">Gọi $m$ là khối lượng nước ban đầu, $m_h$ là khối lượng nước hoá hơi, $m - m_h$ đông đặc: $m_hL = (m - m_h)\\lambda$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$m_h\\cdot 2{,}48\\cdot 10^{6} = (m - m_h)\\cdot 3{,}3\\cdot 10^{5}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$\\dfrac{m_h}{m} = \\dfrac{\\lambda}{L + \\lambda} = \\dfrac{3{,}3\\cdot 10^{5}}{2{,}81\\cdot 10^{6}} \\approx 0{,}12$.</p><p class=\"text-base leading-relaxed my-2\">Sai vì: $0{,}84$ và $0{,}16$ không đúng vì không bằng $\\dfrac{\\lambda}{L+\\lambda} \\approx 0{,}117$. $0{,}07$ cũng không đúng vì tỉ số này lớn hơn $0{,}1$. Nếu viết nhầm $m_h L = m\\lambda$ thì ra $\\dfrac{\\lambda}{L} \\approx 0{,}133$, vẫn khác các phương án.</p><p class=\"text-base leading-relaxed my-2\">Chọn A.</p>","difficultySource":"ai"},"ex":[{"exam":168,"idx":17,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":0,"options":["0,12.","0,07.","0,16.","0,84."],"question":"Một bình đựng nước ở 0°C. Người ta làm nước trong bình đông đặc lại bằng cách hút không khí và hơi nước trong bình ra ngoài. Lấy nhiệt nóng chảy riêng của nước là 3,3.10<sup>5</sup> J/kg và nhiệt hoá hơi riêng của nước là 2,48.10<sup>6</sup> J/kg. Bỏ qua sự trao đổi nhiệt với bình và môi trường bên ngoài. Tỉ số giữa khối lượng nước bị hoá hơi và khối lượng nước ở trong bình lúc đầu là","difficulty":"kho","explanation":"Chọn đáp án A<br>$m_hL=\\left(m−m_h\\right)\\lambda \\Rightarrow m_h.2,48.10^6=\\left(m−m_h\\right).3,3.10^5\\Rightarrow \\frac{m_h}{m}\\approx 0,12$","difficultySource":"ai"}}]},{"id":420813,"nq":{"form":"bai_tap","type":"short_answer","topic":"Quá trình đẳng nhiệt và định luật Boyle","answer":"1,8","question":"Một bọt khí nổi từ đáy giếng sâu 8 m lên mặt nước. Coi áp suất khí quyển là 1,013.10<sup>5</sup> Pa; khối lượng riêng của nước giếng là 1000 kg/m3 và nhiệt độ của nước giếng không thay đổi theo độ sâu. Lấy g = 10 $m/s^2$. Khi lên tới mặt nước, thể tích của bọt khí tăng bao nhiêu lần (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"$pV=const\\Rightarrow p_0V_0=\\left(p_0+Dgh\\right)V\\Rightarrow \\frac{V_0}{V}=\\frac{p_0+Dhg}{p_0}=\\frac{1,013.10^5+1000.10.8}{1,013.10^5}\\approx 1,8$","difficultySource":"ai"},"ex":[{"exam":169,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Quá trình đẳng nhiệt và định luật Boyle","answer":"1,8","question":"Một bọt khí nổi từ đáy giếng sâu 8 m lên mặt nước. Coi áp suất khí quyển là 1,013.10<sup>5</sup> Pa; khối lượng riêng của nước giếng là 1000 kg/m3 và nhiệt độ của nước giếng không thay đổi theo độ sâu. Lấy g = 10 m/s2. Khi lên tới mặt nước, thể tích của bọt khí tăng bao nhiêu lần (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"$pV=const\\Rightarrow p_0V_0=\\left(p_0+Dgh\\right)V\\Rightarrow \\frac{V_0}{V}=\\frac{p_0+Dhg}{p_0}=\\frac{1,013.10^5+1000.10.8}{1,013.10^5}\\approx 1,8$","difficultySource":"ai"}}]},{"id":421597,"nq":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"2,55","question":"Uranium-235 (235U) là một nguồn năng lượng khổng lồ. Mỗi phân hạch của hạt nhân  235U tỏa ra năng lượng trung bình 200 MeV. Biết năng suất tỏa nhiệt của xăng là 46.106 J/kg, khối lượng riêng của xăng là 0,7 kg/L; khối lượng mol của  235U là 235 g/mol;1MeV = 1,6.10<sup>−13</sup> J. Cần phải đốt cháy bao nhiêu m3 xăng để tỏa ra năng lượng tương đương với năng lượng tỏa ra khi phân hạch hoàn toàn 1 gam  235U (làm tròn kết quả đến chữ số hàng phần trăm)?","difficulty":"trung-binh","explanation":"Đáp số 2,55<br>$n=\\frac{m}{M}=\\frac{1}{235}mol$<br>$N=nN_A=\\frac{1}{235}.6,02.10^{23}\\approx 2,562.10^{21}$<br>Khối lượng xăng  $m_x=\\frac{Q}{q}=\\frac{N\\Delta E}{q}=\\frac{2,562.10^{21}.200.1,6.10^{−13}}{46.10^6}\\approx 1782kg$<br>Thể tích xăng cần dùng:  $V=\\frac{m_x}{D}=\\frac{1782}{0,7}\\approx 2,55.10^3ℓ=2,55m^3$","difficultySource":"ai"},"ex":[{"exam":170,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"2,55","question":"Uranium-235 (235U) là một nguồn năng lượng khổng lồ. Mỗi phân hạch của hạt nhân  235U tỏa ra năng lượng trung bình 200 MeV. Biết năng suất tỏa nhiệt của xăng là 46.106 J/kg, khối lượng riêng của xăng là 0,7 kg/L; khối lượng mol của  235U là 235 g/mol;1MeV = 1,6.10<sup>−13</sup> J. Cần phải đốt cháy bao nhiêu m3 xăng để tỏa ra năng lượng tương đương với năng lượng tỏa ra khi phân hạch hoàn toàn 1 gam  235U (làm tròn kết quả đến chữ số hàng phần trăm)?","difficulty":"trung-binh","explanation":"Đáp số 2,55<br>$n=\\frac{m}{M}=\\frac{1}{235}mol$<br>$N=nN_A=\\frac{1}{235}.6,02.10^{23}\\approx 2,562.10^{21}$<br>Khối lượng xăng  $m_x=\\frac{Q}{q}=\\frac{N\\Delta E}{q}=\\frac{2,562.10^{21}.200.1,6.10^{−13}}{46.10^6}\\approx 1782kg$<br>Thể tích xăng cần dùng:  $V=\\frac{m_x}{D}=\\frac{1782}{0,7}\\approx 2,55.10^3ℓ=2,55m^3$","difficultySource":"ai"}}]},{"id":421743,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Vận dụng phương trình trạng thái","answer":0,"options":["167 cm3.","16,7 cm3 .","1,67 cm3 .","167.10<sup>−3</sup> cm3 ."],"question":"Một quả bóng thám không chứa 100 cm3 khí helium ở áp suất 105 Pa và nhiệt độ 27°C. Khi quả bóng bay lên đến độ cao mà áp suất khí quyển chỉ còn 0,5.105 Pa và nhiệt độ giảm xuống còn -23°C, thể tích của quả bóng lúc này là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Lượng khí He trong bóng xác định mà $p$, $V$, $T$ đều đổi nên dùng $\\dfrac{p_1V_1}{T_1}=\\dfrac{p_2V_2}{T_2}$, với $T_1=300$ K, $T_2=250$ K.</p><p class=\"text-base leading-relaxed my-2\">Đề hiểu là $p_1=10^5$ Pa và $p_2=0{,}5\\cdot10^5$ Pa (mất dấu mũ).</p><p class=\"text-base leading-relaxed my-2\">$V_2=V_1\\cdot\\dfrac{p_1}{p_2}\\cdot\\dfrac{T_2}{T_1}=100\\cdot2\\cdot\\dfrac{250}{300}\\approx167\\ \\text{cm}^3$.</p><p class=\"text-base leading-relaxed my-2\">Sai vì: B, C, D lệch $10$, $100$, $1000$ lần so với $167$. Áp suất giảm một nửa còn nhiệt độ chỉ giảm nhẹ nên thể tích phải tăng lên hơn $100\\ \\text{cm}^3$, không thể giảm còn $16{,}7$; $1{,}67$ hay $0{,}167\\ \\text{cm}^3$.</p><p class=\"text-base leading-relaxed my-2\">Chọn A.</p>","difficultySource":"ai"},"ex":[{"exam":171,"idx":4,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Vận dụng phương trình trạng thái","answer":0,"options":["167 cm3.","16,7 cm3 .","1,67 cm3 .","167.10<sup>−3</sup> cm3 ."],"question":"Một quả bóng thám không chứa 100 cm3 khí helium ở áp suất 105 Pa và nhiệt độ 27°C. Khi quả bóng bay lên đến độ cao mà áp suất khí quyển chỉ còn 0,5.105 Pa và nhiệt độ giảm xuống còn -23°C, thể tích của quả bóng lúc này là","difficulty":"de","explanation":"Chọn đáp án A<br>$\\frac{p_1V_1}{T_1}=\\frac{p_2V_2}{T_2}\\Rightarrow \\frac{10^5.100}{27+273}=\\frac{0,5.10^5V}{−23+273}\\Rightarrow V\\approx 167cm^3$","difficultySource":"ai"}}]},{"id":422033,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Từ thông qua khung dây","answer":0,"options":["5.10<sup>−5</sup> Wb","5.10<sup>6</sup> Wb","5.10<sup>5</sup> Wb","5.10<sup>−6</sup> Wb"],"question":"Một khung dây phẳng diện tích 20 cm2 đặt trong từ trường đều có cảm ứng từ B = 0,05 T . Vectơ cảm ứng từ hợp với mặt phẳng khung dây một góc 30°. Từ thông qua khung dây là","difficulty":"de","explanation":"Chọn đáp án A<br>$\\Phi =BScos\\alpha =0,05.20.10^{−4}.cos\\left(90^0−30^0\\right)=5.10^{−5}Wb$","distractorNotes":{"B":"Đổi cm² sang m² sai, lại sai lũy thừa: thiếu dấu trừ nên được số mũ dương.","C":"Đổi cm² sang m² sai, lại sai lũy thừa: thiếu dấu trừ nên được số mũ dương.","D":"Lấy góc 30° giữa $\\vec B$ và mặt phẳng làm góc với pháp tuyến, dùng $\\cos 30°$ thay vì $\\sin 30°$ hoặc đổi đơn vị sai bậc."},"difficultySource":"ai"},"ex":[{"exam":171,"idx":14,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Từ thông qua khung dây","answer":0,"options":["5.10<sup>−5</sup> Wb","5.10<sup>6</sup> Wb","5.10<sup>5</sup> Wb","5.10<sup>−6</sup> Wb"],"question":"Một khung dây phẳng diện tích 20 cm2 đặt trong từ trường đều có cảm ứng từ B = 0,05 T . Vectơ cảm ứng từ hợp với mặt phẳng khung dây một góc 30°. Từ thông qua khung dây là","difficulty":"de","explanation":"Chọn đáp án A<br>$\\Phi =BScos\\alpha =0,05.20.10^{−4}.cos\\left(90^0−30^0\\right)=5.10^{−5}Wb$","distractorNotes":{"B":"Đổi cm² sang m² sai, lại sai lũy thừa: thiếu dấu trừ nên được số mũ dương.","C":"Đổi cm² sang m² sai, lại sai lũy thừa: thiếu dấu trừ nên được số mũ dương.","D":"Lấy góc 30° giữa $\\vec B$ và mặt phẳng làm góc với pháp tuyến, dùng $\\cos 30°$ thay vì $\\sin 30°$ hoặc đổi đơn vị sai bậc."},"difficultySource":"ai"}}]},{"id":422149,"nq":{"form":"bai_tap","type":"true_false","topic":"Quá trình đẳng nhiệt và định luật Boyle","question":"Một trong những bệnh nghề nghiệp của thợ lặn có tỉ lệ gây tử vong và mất sức lao động cao là bệnh giảm áp. Nếu một thợ lặn từ độ sâu 30 m nổi lên mặt nước quá nhanh, nitrogen (N2) không vận chuyển kịp đến phổi giải phóng ra ngoài sẽ tích lại trong cơ thể hình thành các bọt khí gây nguy hiểm. Giả sử sự chênh lệch nhiệt độ là không đáng kể. Cho biết khối lượng riêng của nước là 1000 kg/m3 , áp suất khí quyển là 1,013.10<sup>5</sup> Pa . Lấy g = 9,8 $m/s^2$.","difficulty":"trung-binh","statements":[{"text":"Khi thợ lặn nổi lên mặt nước quá nhanh, áp suất giảm đột ngột làm các bọt khí nitrogen nở ra, to dần gây tắc mạch chèn ép các tế bào thần kinh gây liệt, tổn thương các cơ quan.","answer":true},{"text":"Khi nổi lên mặt nước áp suất tại mặt nước khi đó bằng áp suất khí quyển 1,013.10<sup>5</sup> Pa .","answer":true},{"text":"Áp suất người thợ lặn phải chịu khi ở độ sâu 30 m là 294 kPa .","answer":false},{"text":"Thể tích của bọt khí nitrogen (coi là khí lí tưởng) khi lên đến mặt nước lớn gấp 2,9 lần thể tích của bọt khí này ở độ sâu 30 m .","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\"><strong>Áp suất tuyệt đối tại độ sâu 30 m:</strong> Áp suất tại một điểm dưới mặt nước gồm áp suất khí quyển và áp suất thủy tĩnh: $p = p_0 + \\rho g h$.</p><p class=\"text-base leading-relaxed my-2\">$p = 1{,}013.10^5 + 1000.9{,}8.30 = 1{,}013.10^5 + 2{,}94.10^5 = 3{,}953.10^5\\ \\text{Pa} \\approx 395{,}3\\ \\text{kPa}$</p><p class=\"text-base leading-relaxed my-2\">a) <strong>Đúng.</strong> Khi nổi lên quá nhanh, áp suất giảm đột ngột khiến bọt khí nitrogen nở ra, gây tắc mạch và chèn ép tế bào thần kinh, dẫn đến liệt và tổn thương cơ quan (đúng bản chất bệnh giảm áp).</p><p class=\"text-base leading-relaxed my-2\">b) <strong>Đúng.</strong> Tại mặt nước, thợ lặn chịu áp suất khí quyển: $p_{\\text{mặt}} = 1{,}013.10^5\\ \\text{Pa}$.</p><p class=\"text-base leading-relaxed my-2\">c) <strong>Sai.</strong> Số 294 kPa chỉ là áp suất thủy tĩnh của nước $\\rho g h$. Áp suất tổng cộng người thợ chịu là $395{,}3$ kPa.</p><p class=\"text-base leading-relaxed my-2\">d) <strong>Sai.</strong> Coi nhiệt độ không đổi, áp dụng định luật Boyle cho khí lí tưởng: $p_1V_1 = p_2V_2$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\dfrac{V_2}{V_1} = \\dfrac{p_1}{p_2} = \\dfrac{395{,}3.10^3}{1{,}013.10^5} \\approx 3{,}9$</p><p class=\"text-base leading-relaxed my-2\">Thể tích bọt khí khi lên mặt nước lớn gấp khoảng 3,9 lần, không phải 2,9 lần.</p>","difficultySource":"ai"},"ex":[{"exam":171,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Quá trình đẳng nhiệt và định luật Boyle","question":"Một trong những bệnh nghề nghiệp của thợ lặn có tỉ lệ gây tử vong và mất sức lao động cao là bệnh giảm áp. Nếu một thợ lặn từ độ sâu 30 m nổi lên mặt nước quá nhanh, nitrogen (N2) không vận chuyển kịp đến phổi giải phóng ra ngoài sẽ tích lại trong cơ thể hình thành các bọt khí gây nguy hiểm. Giả sử sự chênh lệch nhiệt độ là không đáng kể. Cho biết khối lượng riêng của nước là 1000 kg/m3 , áp suất khí quyển là 1,013.10<sup>5</sup> Pa . Lấy g = 9,8 m/s2.","difficulty":"trung-binh","statements":[{"text":"Khi thợ lặn nổi lên mặt nước quá nhanh, áp suất giảm đột ngột làm các bọt khí nitrogen nở ra, to dần gây tắc mạch chèn ép các tế bào thần kinh gây liệt, tổn thương các cơ quan.","answer":true},{"text":"Khi nổi lên mặt nước áp suất tại mặt nước khi đó bằng áp suất khí quyển 1,013.10<sup>5</sup> Pa .","answer":true},{"text":"Áp suất người thợ lặn phải chịu khi ở độ sâu 30 m là 294 kPa .","answer":false},{"text":"Thể tích của bọt khí nitrogen (coi là khí lí tưởng) khi lên đến mặt nước lớn gấp 2,9 lần thể tích của bọt khí này ở độ sâu 30 m .","answer":false}],"explanation":"","difficultySource":"ai"}}]},{"id":422265,"nq":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"843","question":"Chạy bộ vào mỗi buổi sáng là hoạt động luyện tập rất tốt cho sức khỏe. Trung bình, một người khi chạy bộ sẽ cần hít vào một lượng khí xác định trong mỗi nhịp thở. Giả sử ở điều kiện tiêu chuẩn (áp suất 1,013.10<sup>5</sup> Pa và nhiệt độ 0°C ), khối lượng không khí hít vào mỗi nhịp thở là 1g. Biết khối lượng riêng của không khí ở điều kiện tiêu chuẩn là 1,29 kg/m3 và coi khối lượng không khí hít vào trong mỗi nhịp thở là bằng nhau. Tính thể tích không khí cần hít vào trong mỗi nhịp thở khi người đó chạy bộ ở nơi có áp suất 100 kPa và nhiệt độ 20°C theo đơn vị ml (Kết quả làm tròn đến hàng đơn vị).","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Khối lượng không khí mỗi nhịp thở không đổi: $m = 1\\ \\text{g} = 1{,}0\\cdot10^{-3}\\ \\text{kg}$.</p><p class=\"text-base leading-relaxed my-2\">Thể tích không khí ở điều kiện tiêu chuẩn ($p_0 = 1{,}013\\cdot10^5\\ \\text{Pa}$, $T_0 = 273\\ \\text{K}$):</p><p class=\"text-base leading-relaxed my-2\">$V_0 = \\dfrac{m}{\\rho_0} = \\dfrac{1{,}0\\cdot10^{-3}}{1{,}29}\\ \\text{m}^3 \\approx 7{,}752\\cdot10^{-4}\\ \\text{m}^3 = 775{,}2\\ \\text{ml}$</p><p class=\"text-base leading-relaxed my-2\">Khi chạy bộ, không khí ở trạng thái $p_1 = 100\\ \\text{kPa}$, $T_1 = 20 + 273 = 293\\ \\text{K}$. Khối lượng không đổi nên áp dụng phương trình trạng thái khí lí tưởng cho khối khí:</p><p class=\"text-base leading-relaxed my-2\">$\\dfrac{p_0V_0}{T_0} = \\dfrac{p_1V_1}{T_1}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow V_1 = V_0\\cdot\\dfrac{p_0}{p_1}\\cdot\\dfrac{T_1}{T_0}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow V_1 = 775{,}2\\cdot\\dfrac{101{,}3}{100}\\cdot\\dfrac{293}{273} \\approx 775{,}2\\cdot1{,}013\\cdot1{,}0733 \\approx 842{,}9\\ \\text{ml}$</p><p class=\"text-base leading-relaxed my-2\">Làm tròn đến hàng đơn vị: $V_1 \\approx 843\\ \\text{ml}$.</p><p class=\"text-base leading-relaxed my-2\">Vậy thể tích không khí cần hít vào mỗi nhịp thở là khoảng <strong>843 ml</strong>.</p>","difficultySource":"ai"},"ex":[{"exam":171,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"843","question":"Chạy bộ vào mỗi buổi sáng là hoạt động luyện tập rất tốt cho sức khỏe. Trung bình, một người khi chạy bộ sẽ cần hít vào một lượng khí xác định trong mỗi nhịp thở. Giả sử ở điều kiện tiêu chuẩn (áp suất 1,013.10<sup>5</sup> Pa và nhiệt độ 0°C ), khối lượng không khí hít vào mỗi nhịp thở là 1g. Biết khối lượng riêng của không khí ở điều kiện tiêu chuẩn là 1,29 kg/m3 và coi khối lượng không khí hít vào trong mỗi nhịp thở là bằng nhau. Tính thể tích không khí cần hít vào trong mỗi nhịp thở khi người đó chạy bộ ở nơi có áp suất 100 kPa và nhiệt độ 20°C theo đơn vị ml (Kết quả làm tròn đến hàng đơn vị).","difficulty":"trung-binh","explanation":"Đáp số 843<br>$V_1=\\frac{m}{D_1}=\\frac{10^{−3}}{1,29}m^3=\\frac{10^3}{1,29}mℓ$<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260015832-hinh-3.png\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"}}]},{"id":422352,"nq":{"form":"bai_tap","type":"short_answer","topic":"Điện từ trường và sóng điện từ","answer":"3,3","question":"Một sóng điện từ có tần số 90 MHz truyền trong không khí với tốc độ 3.10<sup>8</sup> m/s. Bước sóng của sóng điện từ này bằng bao nhiêu mét (m) (Kết quả làm tròn đến chữ số hàng phần mười)?","difficulty":"de","explanation":"Đáp số 3,3<br>$\\lambda =\\frac{c}{f}=\\frac{3.10^8}{90.10^6}=\\frac{10}{3}\\approx 3,3m$","difficultySource":"ai"},"ex":[{"exam":171,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Điện từ trường và sóng điện từ","answer":"3,3","question":"Một sóng điện từ có tần số 90 MHz truyền trong không khí với tốc độ 3.10<sup>8</sup> m/s. Bước sóng của sóng điện từ này bằng bao nhiêu mét (m) (Kết quả làm tròn đến chữ số hàng phần mười)?","difficulty":"de","explanation":"Đáp số 3,3<br>$\\lambda =\\frac{c}{f}=\\frac{3.10^8}{90.10^6}=\\frac{10}{3}\\approx 3,3m$","difficultySource":"ai"}}]},{"id":422934,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Sau một vụ thử hạt nhân, người ta phát hiện đồng vị phóng xạ  ${}_{53}^{131}I$  phát tán vào khí quyển. Chất này có thể lắng đọng xuống đất, nhiễm vào cỏ và nguồn nước. Một nông trại nuôi bò sữa có những con bò không may ăn phải cỏ bị nhiễm đồng vị phóng xạ này nên sữa bò bị nhiễm phóng xạ và người ta đo được độ phóng xạ của  ${}_{53}^{131}I$  trong sữa bò tại trang trại là 12500 Bq/lít. Biết rằng chu kì bán rã của  ${}_{53}^{131}I$  là 8 ngày, giới hạn an toàn cho mức phóng xạ trong sữa theo tiêu chuẩn quốc tế (World Health Organization – WHO) là 100 Bq/lít.","difficulty":"kho","statements":[{"text":"Nếu một người uống sữa chứa  ${}_{53}^{131}I$  có mức phóng xạ vượt ngưỡng an toàn, đồng vị này có thể tích tụ trong tuyến giáp làm tổn hại sức khỏe và gây nguy cơ ung thư.","answer":true},{"text":"Hằng số phóng xạ của  ${}_{53}^{131}I$  là λ = 1,0.10<sup>−6</sup> s-1 (làm tròn và viết kết quả đến hai chữ số có nghĩa).","answer":true},{"text":"Thời gian tối thiểu tính từ khi người ta đo độ phóng xạ đến khi sữa bò tại trang trại đạt mức an toàn cho phép là 31,6 ngày (làm tròn kết quả đến chữ số hàng phần mười).","answer":false},{"text":"Số nucleon trong hạt nhân của đồng vị phóng xạ  ${}_{53}^{131}I$  là 78.","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\"><b>Ý a) Đúng.</b> Iodine-131 đi vào cơ thể qua sữa và tập trung chủ yếu ở tuyến giáp. Bức xạ β⁻ và γ của nó phá hủy tế bào tuyến giáp và làm tăng nguy cơ ung thư.</p><p class=\"text-base leading-relaxed my-2\"><b>Ý b) Đúng.</b> Hằng số phóng xạ: $\\lambda = \\dfrac{\\ln 2}{T}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi $T = 8$ ngày $= 8 \\cdot 86400 = 691200$ s.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\lambda = \\dfrac{0{,}693}{691200} \\approx 1{,}0 \\cdot 10^{-6}\\ \\text{s}^{-1}$.</p><p class=\"text-base leading-relaxed my-2\"><b>Ý c) Sai.</b> Độ phóng xạ giảm theo quy luật $H = H_0 \\cdot 2^{-t/T}$.</p><p class=\"text-base leading-relaxed my-2\">Điều kiện an toàn: $H = 100$ Bq/lít, với $H_0 = 12500$ Bq/lít.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow 2^{-t/T} = \\dfrac{100}{12500} = 0{,}008$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\dfrac{t}{T} = \\log_2 125 \\approx 6{,}966$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow t \\approx 6{,}966 \\cdot 8 \\approx 55{,}7$ ngày.</p><p class=\"text-base leading-relaxed my-2\">Thời gian tối thiểu là khoảng 55,7 ngày, không phải 31,6 ngày.</p><p class=\"text-base leading-relaxed my-2\"><b>Ý d) Sai.</b> Số khối (số nucleon) của hạt nhân ${}_{53}^{131}I$ là $A = 131$, trong đó có 53 proton và 78 neutron. Số 78 là số neutron, không phải số nucleon.</p>","difficultySource":"ai"},"ex":[{"exam":172,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Sau một vụ thử hạt nhân, người ta phát hiện đồng vị phóng xạ  ${}_{53}^{131}I$  phát tán vào khí quyển. Chất này có thể lắng đọng xuống đất, nhiễm vào cỏ và nguồn nước. Một nông trại nuôi bò sữa có những con bò không may ăn phải cỏ bị nhiễm đồng vị phóng xạ này nên sữa bò bị nhiễm phóng xạ và người ta đo được độ phóng xạ của  ${}_{53}^{131}I$  trong sữa bò tại trang trại là 12500 Bq/lít. Biết rằng chu kì bán rã của  ${}_{53}^{131}I$  là 8 ngày, giới hạn an toàn cho mức phóng xạ trong sữa theo tiêu chuẩn quốc tế (World Health Organization – WHO) là 100 Bq/lít.","difficulty":"kho","statements":[{"text":"Nếu một người uống sữa chứa  ${}_{53}^{131}I$  có mức phóng xạ vượt ngưỡng an toàn, đồng vị này có thể tích tụ trong tuyến giáp làm tổn hại sức khỏe và gây nguy cơ ung thư.","answer":true},{"text":"Hằng số phóng xạ của  ${}_{53}^{131}I$  là λ = 1,0.10<sup>−6</sup> s-1 (làm tròn và viết kết quả đến hai chữ số có nghĩa).","answer":true},{"text":"Thời gian tối thiểu tính từ khi người ta đo độ phóng xạ đến khi sữa bò tại trang trại đạt mức an toàn cho phép là 31,6 ngày (làm tròn kết quả đến chữ số hàng phần mười).","answer":false},{"text":"Số nucleon trong hạt nhân của đồng vị phóng xạ  ${}_{53}^{131}I$  là 78.","answer":false}],"explanation":"","difficultySource":"ai"}}]},{"id":423079,"nq":{"form":"bai_tap","type":"short_answer","topic":"Định luật phóng xạ và chu kì bán rã","answer":"4,7","question":"Để xác định thể tích máu trong cơ thể bệnh nhân, bác sĩ đã cho vào 1 (ml) một dung dịch chứa  ${}_{53}^{131}I$  (Đồng vị  ${}_{53}^{131}I$ là chất phóng xạ có chu kì bán rã 8,06 ngày) có độ phóng xạ 14,8.10<sup>4</sup> Bq. Sau 1 ngày người ta lấy 1 (ml) máu của bệnh nhân thì độ phóng xạ của lượng máu này là 28,86 Bq. Giả thiết chất phóng xạ được phân bố đều vào máu. Thể tích máu của bệnh nhân trong cơ thể bằng bao nhiêu lít (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"Đáp số 4,7<br>$H=H_0.2^{−\\frac{t}{T}}=14,8.10^4.2^{\\frac{−1}{8,06}}\\approx 135804Bq$<br>$\\Rightarrow V\\approx \\frac{135804}{28,86}\\approx 4,7.10^3ml=7,4ℓ$","difficultySource":"ai"},"ex":[{"exam":172,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Định luật phóng xạ và chu kì bán rã","answer":"4,7","question":"Để xác định thể tích máu trong cơ thể bệnh nhân, bác sĩ đã cho vào 1 (ml) một dung dịch chứa  ${}_{53}^{131}I$  (Đồng vị  ${}_{53}^{131}I$ là chất phóng xạ có chu kì bán rã 8,06 ngày) có độ phóng xạ 14,8.10<sup>4</sup> Bq. Sau 1 ngày người ta lấy 1 (ml) máu của bệnh nhân thì độ phóng xạ của lượng máu này là 28,86 Bq. Giả thiết chất phóng xạ được phân bố đều vào máu. Thể tích máu của bệnh nhân trong cơ thể bằng bao nhiêu lít (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"Đáp số 4,7<br>$H=H_0.2^{−\\frac{t}{T}}=14,8.10^4.2^{\\frac{−1}{8,06}}\\approx 135804Bq$<br>$\\Rightarrow V\\approx \\frac{135804}{28,86}\\approx 4,7.10^3ml=7,4ℓ$","difficultySource":"ai"}}]},{"id":424186,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Liên hệ áp suất với động năng phân tử","answer":2,"options":["12420 N/m2.","13027,3 N/m2.","23722,2 N/m2.","20436,6N/m2."],"question":"Bình thể tích 10 lít chứa khí lý tưởng có mật độ μ = 3.10<sup>24</sup> m-3, ở nhiệt độ 300°C. Cho hằng số Boltzmann là k = 1,38.10<sup>−23</sup> J/K. Áp suất của khối khí lý tưởng trong bình là","difficulty":"de","explanation":"Chọn đáp án C<br>$P=\\mu kT=3.10^{24}.1,38.10^{−23}.\\left(300+273\\right)=23722,2N/m^2$","difficultySource":"ai"},"ex":[{"exam":174,"idx":11,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Liên hệ áp suất với động năng phân tử","answer":2,"options":["12420 N/m2.","13027,3 N/m2.","23722,2 N/m2.","20436,6N/m2."],"question":"Bình thể tích 10 lít chứa khí lý tưởng có mật độ μ = 3.10<sup>24</sup> m-3, ở nhiệt độ 300°C. Cho hằng số Boltzmann là k = 1,38.10<sup>−23</sup> J/K. Áp suất của khối khí lý tưởng trong bình là","difficulty":"de","explanation":"Chọn đáp án C<br>$P=\\mu kT=3.10^{24}.1,38.10^{−23}.\\left(300+273\\right)=23722,2N/m^2$","difficultySource":"ai"}}]},{"id":424563,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"4,87","question":"Biết nước có nhiệt dung riêng là c = 4,19 kJ/kg.K và nhiệt hóa hơi riêng là 2,26.10<sup>6</sup> J/kg. Nhiệt lượng cần cung cấp cho 200 g ở nhiệt độ 58°C để nó hóa hơi hoàn toàn ở nhiệt độ 100°C là X.10<sup>5</sup> J. Giá trị của X là bao nhiêu? (Lấy kết quả làm tròn đến hàng phần trăm)","difficulty":"trung-binh","explanation":"Đáp số 4,87<br>$Q=mc\\Delta t+mL=0,2.4190.\\left(100−58\\right)+0,2.2,26.10^6=487196\\approx 4,87.10^5J$","difficultySource":"ai"},"ex":[{"exam":174,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"4,87","question":"Biết nước có nhiệt dung riêng là c = 4,19 kJ/kg.K và nhiệt hóa hơi riêng là 2,26.10<sup>6</sup> J/kg. Nhiệt lượng cần cung cấp cho 200 g ở nhiệt độ 58°C để nó hóa hơi hoàn toàn ở nhiệt độ 100°C là X.10<sup>5</sup> J. Giá trị của X là bao nhiêu? (Lấy kết quả làm tròn đến hàng phần trăm)","difficulty":"trung-binh","explanation":"Đáp số 4,87<br>$Q=mc\\Delta t+mL=0,2.4190.\\left(100−58\\right)+0,2.2,26.10^6=487196\\approx 4,87.10^5J$","difficultySource":"ai"}}]},{"id":424825,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":1,"options":["18.107J.","18.1010J.","18.108J.","18.109J."],"question":"Biết vận tốc ánh sáng trong chân khôngc= 3.10<sup>8</sup> m/s . Theo hệ thức Anhxtanh giữa năng lượng và khối lượng thì vật khối lượng 0,002 gam có năng lượng nghỉ bằng","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Hệ thức Anhxtanh giữa năng lượng nghỉ và khối lượng: $E_0 = m c^2$, trong đó $m$ là khối lượng (kg), $c$ là vận tốc ánh sáng trong chân không (m/s).</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị khối lượng: $m = 0{,}002\\ \\text{g} = 2\\cdot 10^{-6}\\ \\text{kg}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $E_0 = 2\\cdot 10^{-6}\\cdot (3\\cdot 10^{8})^2 = 2\\cdot 10^{-6}\\cdot 9\\cdot 10^{16}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow E_0 = 18\\cdot 10^{10}\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: năng lượng nghỉ của vật là $18\\cdot 10^{10}\\ \\text{J}$, chọn đáp án B.</p>","difficultySource":"ai"},"ex":[{"exam":175,"idx":6,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":1,"options":["18.107J.","18.1010J.","18.108J.","18.109J."],"question":"Biết vận tốc ánh sáng trong chân khôngc= 3.10<sup>8</sup> m/s . Theo hệ thức Anhxtanh giữa năng lượng và khối lượng thì vật khối lượng 0,002 gam có năng lượng nghỉ bằng","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Hệ thức Anhxtanh giữa năng lượng nghỉ và khối lượng: $E_0 = m c^2$, trong đó $m$ là khối lượng (kg), $c$ là vận tốc ánh sáng trong chân không (m/s).</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị khối lượng: $m = 0{,}002\\ \\text{g} = 2\\cdot 10^{-6}\\ \\text{kg}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $E_0 = 2\\cdot 10^{-6}\\cdot (3\\cdot 10^{8})^2 = 2\\cdot 10^{-6}\\cdot 9\\cdot 10^{16}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow E_0 = 18\\cdot 10^{10}\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: năng lượng nghỉ của vật là $18\\cdot 10^{10}\\ \\text{J}$, chọn đáp án B.</p>","difficultySource":"ai"}}]},{"id":424941,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":1,"options":["0,625 A .","1,25 A .","0,85 A .","0,50 A ."],"question":"Một sợi dây dẫn có tiết diện ngang S0 =1 mm2, điện trở suất  $\\rho$ = 2.10<sup>−8</sup> Ωm , được uốn thành một vòng tròn kín, bán kính r = 25 cm. Đặt vòng dây dẫn vào một từ trường đều sao cho các đường sức từ vuông góc với mặt phẳng vòng dây dẫn. Cảm ứng từ của từ trường biến thiên theo thời gian với quy luật B = kt , với t tính bằng đơn vị giây (s) và k = 0,2 T/s. Cường độ dòng điện cảm ứng trong vòng dây có độ lớn là","difficulty":"kho","explanation":"Chọn đáp án B<br>Diện tích vòng dây là:  $S=\\pi r^2=\\pi .0,25^2=0,0625\\pi (m^2)$<br>Suất điện động cảm ứng  $\\left|e\\right|=\\left|\\frac{\\Delta \\Phi }{\\Delta t}\\right|=\\frac{\\Delta B.S}{\\Delta t}=kS=0,2.0,0625\\pi =0,0125\\pi \\left(V\\right)$<br>Chiều dài dây dẫn:  $ℓ=2\\pi r=2\\pi .0,25=0,5\\pi \\left(m\\right)$<br>Điện trở vòng dây:  $R=\\frac{\\rho ℓ}{S_0}=\\frac{2.10^{−8}.0,5\\pi }{10^{−6}}=0,01\\pi \\left(\\Omega \\right)$<br>Dòng điện cảm ứng:  $i=\\frac{\\left|e\\right|}{R}=\\frac{0,0125\\pi }{0,01\\pi }=1,25A$","distractorNotes":{"A":"Thừa hệ số 2 ở một bước, như lấy chu vi dây gấp đôi $2\\pi r$ khi tính điện trở.","C":"Sai ở bước thay số, không rút gọn đúng $\\pi$ giữa suất điện động và điện trở.","D":"Nhầm diện tích vòng dây với tiết diện dây hoặc dùng sai $r$, làm lệch tỉ số $e/R$."},"difficultySource":"ai"},"ex":[{"exam":175,"idx":10,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":1,"options":["0,625 A .","1,25 A .","0,85 A .","0,50 A ."],"question":"Một sợi dây dẫn có tiết diện ngang S0 =1 mm2, điện trở suất  $\\rho$ = 2.10<sup>−8</sup> Ωm , được uốn thành một vòng tròn kín, bán kính r = 25 cm. Đặt vòng dây dẫn vào một từ trường đều sao cho các đường sức từ vuông góc với mặt phẳng vòng dây dẫn. Cảm ứng từ của từ trường biến thiên theo thời gian với quy luật B = kt , với t tính bằng đơn vị giây (s) và k = 0,2 T/s. Cường độ dòng điện cảm ứng trong vòng dây có độ lớn là","difficulty":"kho","explanation":"Chọn đáp án B<br>Diện tích vòng dây là:  $S=\\pi r^2=\\pi .0,25^2=0,0625\\pi (m^2)$<br>Suất điện động cảm ứng  $\\left|e\\right|=\\left|\\frac{\\Delta \\Phi }{\\Delta t}\\right|=\\frac{\\Delta B.S}{\\Delta t}=kS=0,2.0,0625\\pi =0,0125\\pi \\left(V\\right)$<br>Chiều dài dây dẫn:  $ℓ=2\\pi r=2\\pi .0,25=0,5\\pi \\left(m\\right)$<br>Điện trở vòng dây:  $R=\\frac{\\rho ℓ}{S_0}=\\frac{2.10^{−8}.0,5\\pi }{10^{−6}}=0,01\\pi \\left(\\Omega \\right)$<br>Dòng điện cảm ứng:  $i=\\frac{\\left|e\\right|}{R}=\\frac{0,0125\\pi }{0,01\\pi }=1,25A$","distractorNotes":{"A":"Thừa hệ số 2 ở một bước, như lấy chu vi dây gấp đôi $2\\pi r$ khi tính điện trở.","C":"Sai ở bước thay số, không rút gọn đúng $\\pi$ giữa suất điện động và điện trở.","D":"Nhầm diện tích vòng dây với tiết diện dây hoặc dùng sai $r$, làm lệch tỉ số $e/R$."},"difficultySource":"ai"}}]},{"id":425173,"nq":{"form":"bai_tap","type":"true_false","topic":"Động năng trung bình phân tử và nhiệt độ","question":"Một bình chứa khí có thể tích khoang chứa là V (ban đầu trong bình là chân không). Người ta nén khí Helium (coi là khí lí tưởng) vào bình đến áp suất p thì nhiệt độ khí trong bình lúc này là t =127°C , khối lượng tổng cộng của bình và khí lúc đó là M = 5 kg . Biết nhiệt dung riêng của vỏ bình là c = 850 J/Kg.K , nhiệt độ của vỏ bình luôn bằng nhiệt độ của khí trong bình tương ứng với mỗi thời điểm.","difficulty":"kho","statements":[{"text":"Nhiệt độ tuyệt đối của khí He trong bình lúc đầu là 400 K.","answer":true},{"text":"Động năng chuyển động nhiệt tịnh tiến trung bình của các phân tử khí He lúc đầu có giá trị xấp xỉ bằng 8,3.10<sup>−21</sup> J.","answer":true},{"text":"Hằng số Boltzmann có giá trị xấp xỉ bằng 1,38.10<sup>−23</sup> K/J.","answer":false},{"text":"Người ta mở van để xả khí He trong bình ra, ở thời điểm áp suất khí trong bình giảm đi một nửa thì nhiệt độ khí trong bình là t/ = 27°C , khối lượng tổng cộng của bình và khí lúc này là M/ = 4 kg. Tính từ lúc bắt đầu mở van xả khí đến thời điểm nhiệt độ khí trong bình là t/ = 27°C thì vỏ bình đã tỏa ra môi trường xung quanh một nhiệt lượng là 1,7.10<sup>5</sup> J.","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\"><b>a)</b> Đổi nhiệt độ sang nhiệt độ tuyệt đối: $T = t + 273 = 127 + 273 = 400\\ \\text{K}$. Ý a) <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>b)</b> Động năng chuyển động nhiệt tịnh tiến trung bình của một phân tử khí lí tưởng: $\\overline{W_d} = \\dfrac{3}{2}kT$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $k = 1{,}38\\cdot10^{-23}\\ \\text{J/K}$ và $T = 400\\ \\text{K}$: $\\overline{W_d} = \\dfrac{3}{2}\\cdot 1{,}38\\cdot10^{-23}\\cdot 400 = 8{,}28\\cdot10^{-21}\\ \\text{J} \\approx 8{,}3\\cdot10^{-21}\\ \\text{J}$. Ý b) <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>c)</b> Hằng số Boltzmann có giá trị $k = 1{,}38\\cdot10^{-23}\\ \\text{J/K}$. Giá trị số đúng nhưng đơn vị ghi là K/J là sai. Ý c) <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>d)</b> Thể tích bình $V$ không đổi. Theo phương trình trạng thái khí lí tưởng $pV = \\dfrac{m}{\\mu}RT$, khối lượng khí tỉ lệ với $\\dfrac{p}{T}$.</p><p class=\"text-base leading-relaxed my-2\">Tỉ số khối lượng khí còn lại so với lúc đầu:</p><p class=\"text-base leading-relaxed my-2\">$\\dfrac{m_2}{m_1} = \\dfrac{p_2}{p_1}\\cdot\\dfrac{T_1}{T_2} = \\dfrac{1}{2}\\cdot\\dfrac{400}{300} = \\dfrac{2}{3}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Khối lượng khí đã thoát ra là $\\Delta m_{\\text{khí}} = \\dfrac{m_1}{3}$.</p><p class=\"text-base leading-relaxed my-2\">Khối lượng tổng giảm từ 5 kg xuống 4 kg, nên khối lượng khí đã thoát là $1\\ \\text{kg}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\dfrac{m_1}{3} = 1\\ \\text{kg}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow m_1 = 3\\ \\text{kg}$ (khí lúc đầu), và khối lượng vỏ bình $m_b = 5 - 3 = 2\\ \\text{kg}$.</p><p class=\"text-base leading-relaxed my-2\">Kiểm tra: khí còn lại $2\\ \\text{kg}$, cộng vỏ $2\\ \\text{kg}$ bằng $4\\ \\text{kg}$, khớp với đề.</p><p class=\"text-base leading-relaxed my-2\">Nhiệt độ vỏ bình giảm từ $400\\ \\text{K}$ xuống $300\\ \\text{K}$, nên độ giảm nhiệt độ là $\\Delta T = 100\\ \\text{K}$.</p><p class=\"text-base leading-relaxed my-2\">Nhiệt lượng vỏ bình tỏa ra: $Q = m_b\\,c\\,|\\Delta T| = 2\\cdot 850\\cdot 100 = 1{,}7\\cdot10^{5}\\ \\text{J}$. Ý d) <b>Đúng</b>.</p>","difficultySource":"ai"},"ex":[{"exam":175,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Động năng trung bình phân tử và nhiệt độ","question":"Một bình chứa khí có thể tích khoang chứa là V (ban đầu trong bình là chân không). Người ta nén khí Helium (coi là khí lí tưởng) vào bình đến áp suất p thì nhiệt độ khí trong bình lúc này là t =127°C , khối lượng tổng cộng của bình và khí lúc đó là M = 5 kg . Biết nhiệt dung riêng của vỏ bình là c = 850 J/Kg.K , nhiệt độ của vỏ bình luôn bằng nhiệt độ của khí trong bình tương ứng với mỗi thời điểm.","difficulty":"kho","statements":[{"text":"Nhiệt độ tuyệt đối của khí He trong bình lúc đầu là 400 K.","answer":true},{"text":"Động năng chuyển động nhiệt tịnh tiến trung bình của các phân tử khí He lúc đầu có giá trị xấp xỉ bằng 8,3.10<sup>−21</sup> J.","answer":true},{"text":"Hằng số Boltzmann có giá trị xấp xỉ bằng 1,38.10<sup>−23</sup> K/J.","answer":false},{"text":"Người ta mở van để xả khí He trong bình ra, ở thời điểm áp suất khí trong bình giảm đi một nửa thì nhiệt độ khí trong bình là t/ = 27°C , khối lượng tổng cộng của bình và khí lúc này là M/ = 4 kg. Tính từ lúc bắt đầu mở van xả khí đến thời điểm nhiệt độ khí trong bình là t/ = 27°C thì vỏ bình đã tỏa ra môi trường xung quanh một nhiệt lượng là 1,7.10<sup>5</sup> J.","answer":true}],"explanation":"","difficultySource":"ai"}}]},{"id":425988,"nq":{"form":"bai_tap","type":"true_false","topic":"Tính nhiệt lượng theo nhiệt dung riêng","question":"Tại một quán cà phê, một nhân viên pha chế muốn điều chỉnh nhiệt độ cà phê nóng để phục vụ khách dễ uống. Ban đầu, người này rót 200 g cà phê nóng ở 80°C vào một cốc sứ khối lượng 150 g đang ở 25°C. Sau đó, nhân viên dùng một thìa bạc (đã được làm lạnh cùng nhiệt độ với kem) khối lượng 50 g để lấy một viên kem từ tủ lạnh ở -10°C và cho vào cốc cà phê, rồi khuấy đều. Khi cân bằng nhiệt, hệ đạt 40°C. Cho biết nhiệt dung riêng của cà phê (nước) và kem (đã tan - lỏng) là 4200 J/(kg.K); kem ở trạng thái rắn là 2000 J/(kg.K); bạc là 230 J/(kg.K) và cốc là 840 J/(kg.K); nhiệt nóng chảy riêng của kem là 3,4.10<sup>5</sup> J/kg. Bỏ qua thất thoát nhiệt ra môi trường.","difficulty":"kho","statements":[{"text":"Khi rót cà phê vào cốc, cà phê chỉ trao đổi nhiệt với không khí nên có thể bỏ qua nhiệt lượng truyền cho cốc sứ.","answer":false},{"text":"Khi cho kem vào, cả kem và thìa bạc đều bắt đầu nhận nhiệt từ cà phê.","answer":true},{"text":"Sau khi tan hết, phần nước từ kem tiếp tục nhận nhiệt cho đến khi đạt nhiệt độ cân bằng 40°C","answer":true},{"text":"Khối lượng kem cần thêm vào để hệ đạt 40°C (kết quả làm tròn đến hàng đơn vị, tính theo g) là 47 g.","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\"><b>Nguyên lí truyền nhiệt:</b> nhiệt lượng do vật tỏa ra bằng nhiệt lượng do vật thu vào (hệ cô lập, bỏ qua thất thoát ra môi trường).</p><p class=\"text-base leading-relaxed my-2\"><b>Ý a) Sai.</b> Cốc sứ ban đầu ở 25°C, nằm trong hệ trao đổi nhiệt với cà phê nên cà phê truyền nhiệt cho cốc. Không thể bỏ qua nhiệt lượng này.</p><p class=\"text-base leading-relaxed my-2\"><b>Ý b) Đúng.</b> Kem (−10°C) và thìa bạc (−10°C) đều có nhiệt độ thấp hơn cà phê nên cả hai đều nhận nhiệt từ cà phê.</p><p class=\"text-base leading-relaxed my-2\"><b>Ý c) Đúng.</b> Sau khi kem tan hết, nước từ kem có nhiệt độ 0°C và tiếp tục nhận nhiệt từ hệ cho đến khi cân bằng ở 40°C.</p><p class=\"text-base leading-relaxed my-2\"><b>Ý d) Sai.</b> Gọi $m$ là khối lượng kem (kg). Nhiệt lượng tỏa ra của cà phê:</p><p class=\"text-base leading-relaxed my-2\">$Q_{tỏa} = m_{cf} c_{cf}(t_1 - t) = 0,2 \\cdot 4200 \\cdot (80 - 40) = 33600 \\text{ J}$</p><p class=\"text-base leading-relaxed my-2\">Nhiệt lượng cốc sứ thu vào:</p><p class=\"text-base leading-relaxed my-2\">$Q_{cốc} = m_c c_c (t - t_2) = 0,15 \\cdot 840 \\cdot (40 - 25) = 1890 \\text{ J}$</p><p class=\"text-base leading-relaxed my-2\">Nhiệt lượng thìa bạc thu vào (từ −10°C lên 40°C):</p><p class=\"text-base leading-relaxed my-2\">$Q_{thìa} = m_{b} c_{b} (t - t_3) = 0,05 \\cdot 230 \\cdot 50 = 575 \\text{ J}$</p><p class=\"text-base leading-relaxed my-2\">Nhiệt lượng kem thu vào gồm ba giai đoạn: làm nóng từ −10°C đến 0°C, nóng chảy hoàn toàn, rồi nóng từ 0°C đến 40°C:</p><p class=\"text-base leading-relaxed my-2\">$Q_{kem} = m\\left(c_r \\cdot 10 + \\lambda + c_l \\cdot 40\\right) = m(2000 \\cdot 10 + 3{,}4\\cdot10^5 + 4200 \\cdot 40) = 528000\\,m$</p><p class=\"text-base leading-relaxed my-2\">Phương trình cân bằng nhiệt:</p><p class=\"text-base leading-relaxed my-2\">$Q_{tỏa} = Q_{cốc} + Q_{thìa} + Q_{kem}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow 33600 = 1890 + 575 + 528000\\,m$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow m = \\dfrac{31135}{528000} \\approx 0{,}059 \\text{ kg} = 59 \\text{ g}$</p><p class=\"text-base leading-relaxed my-2\">Khối lượng kem cần thêm là khoảng 59 g, không phải 47 g. Ý d) sai.</p>","difficultySource":"ai"},"ex":[{"exam":176,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Tính nhiệt lượng theo nhiệt dung riêng","question":"Tại một quán cà phê, một nhân viên pha chế muốn điều chỉnh nhiệt độ cà phê nóng để phục vụ khách dễ uống. Ban đầu, người này rót 200 g cà phê nóng ở 80°C vào một cốc sứ khối lượng 150 g đang ở 25°C. Sau đó, nhân viên dùng một thìa bạc (đã được làm lạnh cùng nhiệt độ với kem) khối lượng 50 g để lấy một viên kem từ tủ lạnh ở -10°C và cho vào cốc cà phê, rồi khuấy đều. Khi cân bằng nhiệt, hệ đạt 40°C. Cho biết nhiệt dung riêng của cà phê (nước) và kem (đã tan - lỏng) là 4200 J/(kg.K); kem ở trạng thái rắn là 2000 J/(kg.K); bạc là 230 J/(kg.K) và cốc là 840 J/(kg.K); nhiệt nóng chảy riêng của kem là 3,4.10<sup>5</sup> J/kg. Bỏ qua thất thoát nhiệt ra môi trường.","difficulty":"kho","statements":[{"text":"Khi rót cà phê vào cốc, cà phê chỉ trao đổi nhiệt với không khí nên có thể bỏ qua nhiệt lượng truyền cho cốc sứ.","answer":false},{"text":"Khi cho kem vào, cả kem và thìa bạc đều bắt đầu nhận nhiệt từ cà phê.","answer":true},{"text":"Sau khi tan hết, phần nước từ kem tiếp tục nhận nhiệt cho đến khi đạt nhiệt độ cân bằng 40°C","answer":true},{"text":"Khối lượng kem cần thêm vào để hệ đạt 40°C (kết quả làm tròn đến hàng đơn vị, tính theo g) là 47 g.","answer":false}],"explanation":"","difficultySource":"ai"}}]},{"id":428166,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Mol, số Avogadro và lượng chất khí","answer":0,"options":["7,826.10<sup>22</sup> .","9,826.10<sup>22</sup> .","6,825.10<sup>22</sup> .","8,825.10<sup>22</sup> ."],"question":"Coi khối lượng mol của hạt nhân   ${}_{13}^{27}{Al}$  bằng số khối của nó. Số proton có trong 0,27 g  ${}_{13}^{27}{Al}$  là","difficulty":"trung-binh","explanation":"Mỗi hạt nhân nhôm có Z = 13 proton<br>⇒ Tổng số proton trong 0,27 g nhôm là:<br>$N_P=ZN=Z.\\frac{m}{A}.N_A=13.\\frac{0,27}{27}.6,02.10^{23}=7,826.10^{22}$","difficultySource":"ai"},"ex":[{"exam":179,"idx":15,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Mol, số Avogadro và lượng chất khí","answer":0,"options":["7,826.10<sup>22</sup> .","9,826.10<sup>22</sup> .","6,825.10<sup>22</sup> .","8,825.10<sup>22</sup> ."],"question":"Coi khối lượng mol của hạt nhân   ${}_{13}^{27}{Al}$  bằng số khối của nó. Số proton có trong 0,27 g  ${}_{13}^{27}{Al}$  là","difficulty":"trung-binh","explanation":"Mỗi hạt nhân nhôm có Z = 13 proton<br>⇒ Tổng số proton trong 0,27 g nhôm là:<br>$N_P=ZN=Z.\\frac{m}{A}.N_A=13.\\frac{0,27}{27}.6,02.10^{23}=7,826.10^{22}$","difficultySource":"ai"}}]},{"id":428254,"nq":{"form":"bai_tap","type":"true_false","topic":"Kích thước, khối lượng hạt nhân và đơn vị u","question":"Đối với hạt nhân của nguyên tử ${}_{26}^{56}X$ .","difficulty":"trung-binh","statements":[{"text":"Hạt nhân nguyên tử  ${}_{26}^{56}X$ có 30 neutron.","answer":true},{"text":"Số proton và số neutron trong hạt nhân  ${}_{26}^{56}X$ bằng nhau.","answer":false},{"text":"Khối lượng của hạt nhân  ${}_{26}^{56}X$ xấp xỉ 56 amu.","answer":true},{"text":"Bán kính hạt nhân  ${}_{26}^{56}X$  xấp xỉ 3,55.10<sup>−15</sup> m.","answer":false}],"explanation":"a) đúng<br>Số neutron:  $N=A−Z=56−26=30$<br>b) sai<br>Số proton là 26, số neutron là 30 nên không bằng nhau.<br>c) đúng<br>Khối lượng hạt nhân xấp xỉ bằng số khối A = 56amu<br>d) sai<br>Bán kính hạt nhân xấp xỉ:  $R=1,2.10^{−15}.56^{\\frac{1}{3}}\\approx 4,59.10^{−15}m$","difficultySource":"ai"},"ex":[{"exam":179,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Kích thước, khối lượng hạt nhân và đơn vị u","question":"Đối với hạt nhân của nguyên tử ${}_{26}^{56}X$ .","difficulty":"trung-binh","statements":[{"text":"Hạt nhân nguyên tử  ${}_{26}^{56}X$ có 30 neutron.","answer":true},{"text":"Số proton và số neutron trong hạt nhân  ${}_{26}^{56}X$ bằng nhau.","answer":false},{"text":"Khối lượng của hạt nhân  ${}_{26}^{56}X$ xấp xỉ 56 amu.","answer":true},{"text":"Bán kính hạt nhân  ${}_{26}^{56}X$  xấp xỉ 3,55.10<sup>−15</sup> m.","answer":false}],"explanation":"a) đúng<br>Số neutron:  $N=A−Z=56−26=30$<br>b) sai<br>Số proton là 26, số neutron là 30 nên không bằng nhau.<br>c) đúng<br>Khối lượng hạt nhân xấp xỉ bằng số khối A = 56amu<br>d) sai<br>Bán kính hạt nhân xấp xỉ:  $R=1,2.10^{−15}.56^{\\frac{1}{3}}\\approx 4,59.10^{−15}m$","difficultySource":"ai"}}]},{"id":428312,"nq":{"form":"bai_tap","type":"true_false","topic":"Phương trình Clapeyron – Mendeleev","question":"Một căn phòng có thể tích phần không gian bên trong là 50 m3. Vào một ngày mùa hè, nhiệt độ trong ngôi nhà vào buổi sáng sớm là 25°C và đến giữa trưa là 37°C. Cho biết áp suất khí quyển không đổi trong ngày là 1 atm = 1,013.10<sup>5</sup> Pa và khối lượng mol của không khí là 29 g / mol.","difficulty":"kho","statements":[{"text":"Từ buổi sáng sớm đến giữa trưa, nhiệt độ trong ngôi nhà tăng 285 K.","answer":false},{"text":"Ở buổi trưa các phân tử khí trong ngôi nhà chuyển động nhanh hơn so với buổi sáng.","answer":true},{"text":"Số phân tử khí có trong ngôi nhà vào buổi sáng sớm là 1,23.10<sup>27</sup> phân tử.","answer":true},{"text":"Khối lượng không khí thoát ra khỏi căn phòng từ buổi sáng sớm đến giữa trưa là 2,2 kg .","answer":false}],"explanation":"a) sai<br>a)\tĐộ tăng nhiệt độ từ buổi sáng sớm đến giữa trưa là $\\Delta T=\\Delta t=37−25=12K$  .<br>b) đúng<br>Nhiệt độ tỉ lệ thuận với động năng tịnh tiến trung bình của phân tử. Do nhiệt độ buổi trưa (310 K) lớn hơn buổi sáng (298 K) nên các phân tử khí ở buổi trưa sẽ chuyển động nhiệt nhanh hơn.<br>c) đúng<br>Nhiệt độ buổi sáng là T1 = 25 + 273 = 298K . Hằng số khí lí tưởng R  $\\approx$  8,31J / (mol.K) và hằng số Avogadro NA = 6,02.10<sup>23</sup> mol-1.<br>Áp dụng phương trình Clapeyron: pV = n1RT1<br>Số mol không khí trong phòng vào buổi sáng là:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260078648-hinh-3.png\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Số phân tử khí có trong ngôi nhà vào buổi sáng sớm là:<br>N1 = n1.NA = 2045,3.6,02.10<sup>23</sup> = 1,23.10<sup>27</sup> phân tử.<br>d) sai<br>Nhiệt độ buổi trưa là T2 = 37 + 273 = 310K .<br>Khối lượng không khí trong phòng vào buổi sáng là:<br>$m_1=n_1\\mu =2045,3.29.10^{−3}\\approx 59,31kg$<br>Số mol không khí trong phòng vào buổi trưa là:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260078950-hinh-4.png\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Khối lượng không khí trong phòng vào buổi trưa là:<br>$m_2=n_2\\mu =1966,2.29.10^{−3}\\approx 57,02kg$<br>Khối lượng không khí đã thoát ra khỏi phòng là:<br>$\\Delta m=m_1−m_2=59,31−57,02=2,29kg$","difficultySource":"ai"},"ex":[{"exam":179,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Phương trình Clapeyron – Mendeleev","question":"Một căn phòng có thể tích phần không gian bên trong là 50 m3. Vào một ngày mùa hè, nhiệt độ trong ngôi nhà vào buổi sáng sớm là 25°C và đến giữa trưa là 37°C. Cho biết áp suất khí quyển không đổi trong ngày là 1 atm = 1,013.10<sup>5</sup> Pa và khối lượng mol của không khí là 29 g / mol.","difficulty":"kho","statements":[{"text":"Từ buổi sáng sớm đến giữa trưa, nhiệt độ trong ngôi nhà tăng 285 K.","answer":false},{"text":"Ở buổi trưa các phân tử khí trong ngôi nhà chuyển động nhanh hơn so với buổi sáng.","answer":true},{"text":"Số phân tử khí có trong ngôi nhà vào buổi sáng sớm là 1,23.10<sup>27</sup> phân tử.","answer":true},{"text":"Khối lượng không khí thoát ra khỏi căn phòng từ buổi sáng sớm đến giữa trưa là 2,2 kg .","answer":false}],"explanation":"a) sai<br>a)\tĐộ tăng nhiệt độ từ buổi sáng sớm đến giữa trưa là $\\Delta T=\\Delta t=37−25=12K$  .<br>b) đúng<br>Nhiệt độ tỉ lệ thuận với động năng tịnh tiến trung bình của phân tử. Do nhiệt độ buổi trưa (310 K) lớn hơn buổi sáng (298 K) nên các phân tử khí ở buổi trưa sẽ chuyển động nhiệt nhanh hơn.<br>c) đúng<br>Nhiệt độ buổi sáng là T1 = 25 + 273 = 298K . Hằng số khí lí tưởng R  $\\approx$  8,31J / (mol.K) và hằng số Avogadro NA = 6,02.10<sup>23</sup> mol-1.<br>Áp dụng phương trình Clapeyron: pV = n1RT1<br>Số mol không khí trong phòng vào buổi sáng là:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260078648-hinh-3.png\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Số phân tử khí có trong ngôi nhà vào buổi sáng sớm là:<br>N1 = n1.NA = 2045,3.6,02.10<sup>23</sup> = 1,23.10<sup>27</sup> phân tử.<br>d) sai<br>Nhiệt độ buổi trưa là T2 = 37 + 273 = 310K .<br>Khối lượng không khí trong phòng vào buổi sáng là:<br>$m_1=n_1\\mu =2045,3.29.10^{−3}\\approx 59,31kg$<br>Số mol không khí trong phòng vào buổi trưa là:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260078950-hinh-4.png\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Khối lượng không khí trong phòng vào buổi trưa là:<br>$m_2=n_2\\mu =1966,2.29.10^{−3}\\approx 57,02kg$<br>Khối lượng không khí đã thoát ra khỏi phòng là:<br>$\\Delta m=m_1−m_2=59,31−57,02=2,29kg$","difficultySource":"ai"}}]},{"id":428604,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":2,"options":["76,4%.","63,5%.","53,7%.","56,4%."],"question":"Một người thợ sửa xe phát hiện trên một số bộ phận bằng kim loại nhôm của chiếc xe bị hỏng. Để hàn một thanh nhôm bị gãy, người đó dùng một mỏ hàn công suất 1,7 kW. Muốn hàn kín, cần làm nóng chảy 20 g nhôm ở chỗ gãy. Biết nhiệt độ ban đầu của thanh nhôm là 25°C; nhiệt độ nóng chảy, nhiệt dung riêng và nhiệt nóng chảy riêng của nhôm lần lượt là 660°C, 880 J/kg.K và 4.10<sup>5</sup> J/kg. Thời gian từ lúc bắt đầu hàn đến lúc thanh nhôm nóng chảy hoàn toàn là 21 s. Hiệu suất của quá trình hàn này là","difficulty":"trung-binh","explanation":"$Q_{toa}=P.\\tau =1700.21=35700\\left(J\\right)$<br>$Q_{thu}=mc\\Delta t+m\\lambda =0,02.880.\\left(660−25\\right)+0,02.4.10^5=19176\\left(J\\right)$<br>$\\Rightarrow H=\\frac{Q_{thu}}{Q_{toa}}=\\frac{19176}{35700}=53,7%$","difficultySource":"ai"},"ex":[{"exam":180,"idx":5,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":2,"options":["76,4%.","63,5%.","53,7%.","56,4%."],"question":"Một người thợ sửa xe phát hiện trên một số bộ phận bằng kim loại nhôm của chiếc xe bị hỏng. Để hàn một thanh nhôm bị gãy, người đó dùng một mỏ hàn công suất 1,7 kW. Muốn hàn kín, cần làm nóng chảy 20 g nhôm ở chỗ gãy. Biết nhiệt độ ban đầu của thanh nhôm là 25°C; nhiệt độ nóng chảy, nhiệt dung riêng và nhiệt nóng chảy riêng của nhôm lần lượt là 660°C, 880 J/kg.K và 4.10<sup>5</sup> J/kg. Thời gian từ lúc bắt đầu hàn đến lúc thanh nhôm nóng chảy hoàn toàn là 21 s. Hiệu suất của quá trình hàn này là","difficulty":"trung-binh","explanation":"$Q_{toa}=P.\\tau =1700.21=35700\\left(J\\right)$<br>$Q_{thu}=mc\\Delta t+m\\lambda =0,02.880.\\left(660−25\\right)+0,02.4.10^5=19176\\left(J\\right)$<br>$\\Rightarrow H=\\frac{Q_{thu}}{Q_{toa}}=\\frac{19176}{35700}=53,7%$","difficultySource":"ai"}}]},{"id":429011,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Dùng một ấm điện có công suất 1000 W, hiệu suất 90% để đun 1 kg nước ở nhiệt độ 25°C. Biết nhiệt dung riêng của nước c = 4200 J/(kg.K), nhiệt hóa hơi của nước L = 2,26.10<sup>6</sup> J/kg nhiệt độ sôi của nước là 100°C.","difficulty":"trung-binh","statements":[{"text":"Sau khi nhiệt độ của nước tăng đến nhiệt độ sôi, người ta để ấm tiếp tục đun nước sôi trong 5 phút, khối lượng nước còn lại trong ấm là 830 g.","answer":false},{"text":"Nhiệt lượng cần cung cấp để làm 300 g nước hóa hơi hoàn toàn ở 100°C là 678000 kJ.","answer":false},{"text":"Nhiệt lượng cần cung cấp để làm nhiệt độ nước trong ấm tăng thêm 1°C là 4200 J.","answer":false},{"text":"Thời gian cần thiết để đun nước trong ấm đạt đến nhiệt độ sôi là 350 s.","answer":true}],"explanation":"a) sai<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260085764-hinh-8.png\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>$\\Rightarrow m_{nuoc con lai}=1−\\Delta m=0,881\\left(kg\\right)$<br>b) sai<br>$Q=mL=0,3.2,26.10^6=678000\\left(J\\right)$<br>c) sai<br>Nhiệt lượng cần cung cấp để làm nhiệt độ nước trong ấm tăng thêm 1°C lớn hơn 4200 J (Để nhiệt độ của ấm tăng thêm 1°C thì cả ấm phải nóng lên nữa → chứ không phải nước tăng nhiệt độ mà ấm không tăng nhiệt độ)<br>Nhiệt lượng để 1kg nước tăng thêm 1°C là 4200(J) mới đúng<br>d) đúng<br>$90%.1000.\\tau =1.4200.\\left(100−25\\right)\\Rightarrow \\tau =350s$","difficultySource":"ai"},"ex":[{"exam":180,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Dùng một ấm điện có công suất 1000 W, hiệu suất 90% để đun 1 kg nước ở nhiệt độ 25°C. Biết nhiệt dung riêng của nước c = 4200 J/(kg.K), nhiệt hóa hơi của nước L = 2,26.10<sup>6</sup> J/kg nhiệt độ sôi của nước là 100°C.","difficulty":"trung-binh","statements":[{"text":"Sau khi nhiệt độ của nước tăng đến nhiệt độ sôi, người ta để ấm tiếp tục đun nước sôi trong 5 phút, khối lượng nước còn lại trong ấm là 830 g.","answer":false},{"text":"Nhiệt lượng cần cung cấp để làm 300 g nước hóa hơi hoàn toàn ở 100°C là 678000 kJ.","answer":false},{"text":"Nhiệt lượng cần cung cấp để làm nhiệt độ nước trong ấm tăng thêm 1°C là 4200 J.","answer":false},{"text":"Thời gian cần thiết để đun nước trong ấm đạt đến nhiệt độ sôi là 350 s.","answer":true}],"explanation":"a) sai<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260085764-hinh-8.png\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>$\\Rightarrow m_{nuoc con lai}=1−\\Delta m=0,881\\left(kg\\right)$<br>b) sai<br>$Q=mL=0,3.2,26.10^6=678000\\left(J\\right)$<br>c) sai<br>Nhiệt lượng cần cung cấp để làm nhiệt độ nước trong ấm tăng thêm 1°C lớn hơn 4200 J (Để nhiệt độ của ấm tăng thêm 1°C thì cả ấm phải nóng lên nữa → chứ không phải nước tăng nhiệt độ mà ấm không tăng nhiệt độ)<br>Nhiệt lượng để 1kg nước tăng thêm 1°C là 4200(J) mới đúng<br>d) đúng<br>$90%.1000.\\tau =1.4200.\\left(100−25\\right)\\Rightarrow \\tau =350s$","difficultySource":"ai"}}]},{"id":430917,"nq":{"form":"bai_tap","type":"short_answer","topic":"Mol, số Avogadro và lượng chất khí","answer":"1,67","question":"Biết khối lượng mol của nước tinh khiết là 18 g/mol và số Avogadro NA = 6, 02.1023 mol−1. Số phân tử có trong 50 g nước tinh khiết là x. 10<sup>24</sup> phân tử. Tìm x (làm tròn kết quả đến chữ số hàng phần trăm).","difficulty":"de","explanation":"$n=\\frac{m}{M}=\\frac{50}{18}=\\frac{25}{9}\\left(mol\\right)$<br>$N=nN_A=\\frac{25}{9}.6,02.10^{23}\\approx 1,67.10^{24}$","difficultySource":"ai"},"ex":[{"exam":186,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Mol, số Avogadro và lượng chất khí","answer":"1,67","question":"Biết khối lượng mol của nước tinh khiết là 18 g/mol và số Avogadro NA = 6, 02.1023 mol−1. Số phân tử có trong 50 g nước tinh khiết là x. 10<sup>24</sup> phân tử. Tìm x (làm tròn kết quả đến chữ số hàng phần trăm).","difficulty":"de","explanation":"$n=\\frac{m}{M}=\\frac{50}{18}=\\frac{25}{9}\\left(mol\\right)$<br>$N=nN_A=\\frac{25}{9}.6,02.10^{23}\\approx 1,67.10^{24}$","difficultySource":"ai"}}]},{"id":431355,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Động năng trung bình phân tử và nhiệt độ","answer":0,"options":["6,21.10<sup>−21</sup> J.","2,76.10<sup>−21</sup> J .","5,59.10<sup>−22</sup> J.","6,12.10<sup>−21</sup> J."],"question":"Động năng tịnh tiến trung bình của mỗi phân tử khí là","difficulty":"de","explanation":"$E_d=\\frac{3}{2}kT=\\frac{3}{2}.1,38.10^{−23}.\\left(27+273\\right)=6,21.10^{−21}J$","difficultySource":"ai"},"ex":[{"exam":189,"idx":12,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Động năng trung bình phân tử và nhiệt độ","answer":0,"options":["6,21.10<sup>−21</sup> J.","2,76.10<sup>−21</sup> J .","5,59.10<sup>−22</sup> J.","6,12.10<sup>−21</sup> J."],"question":"Động năng tịnh tiến trung bình của mỗi phân tử khí là","difficulty":"de","explanation":"$E_d=\\frac{3}{2}kT=\\frac{3}{2}.1,38.10^{−23}.\\left(27+273\\right)=6,21.10^{−21}J$","difficultySource":"ai"}}]},{"id":431645,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"121","question":"Biết nhiệt dung riêng của nước là c = 4190 J/(kg.K) và nhiệt hóa hơi riêng của nước là L = 2,26.10<sup>6</sup> J/kg. Để làm cho m = 200 g nước lấy ở t1 = 10°C sôi ở t2 = 100°C và 10% khối lượng của nó đã hóa hơi khi sôi thì cần cung cấp một nhiệt lượng bằng bao nhiêu kJ (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"de","explanation":"$Q=mc\\Delta T+10%mL=m\\left(c\\Delta T+10%L\\right)=0,2.\\left[4190.\\left(100−10\\right)+10%.2,26.10^6\\right]=120620J\\approx 121kJ$","difficultySource":"ai"},"ex":[{"exam":189,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"121","question":"Biết nhiệt dung riêng của nước là c = 4190 J/(kg.K) và nhiệt hóa hơi riêng của nước là L = 2,26.10<sup>6</sup> J/kg. Để làm cho m = 200 g nước lấy ở t1 = 10°C sôi ở t2 = 100°C và 10% khối lượng của nó đã hóa hơi khi sôi thì cần cung cấp một nhiệt lượng bằng bao nhiêu kJ (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"de","explanation":"$Q=mc\\Delta T+10%mL=m\\left(c\\Delta T+10%L\\right)=0,2.\\left[4190.\\left(100−10\\right)+10%.2,26.10^6\\right]=120620J\\approx 121kJ$","difficultySource":"ai"}}]},{"id":431703,"nq":{"form":"bai_tap","type":"short_answer","topic":"Liên hệ áp suất với động năng phân tử","answer":"46,7","question":"Xét khối khí chứa trong một bình kín, biết tổng động năng tịnh tiến trung bình của các phân tử khí trong 1 m3 thể tích khí có giá trị 70 μJ/m3. Áp suất khí trong bình là x.10<sup>−6</sup> N/m2. Tìm x (làm tròn kết quả đến chữ số hàng phần mười)","difficulty":"trung-binh","explanation":"Tổng động năng tịnh tiến trung bình của các phân tử khí trong  $1m^3=\\frac{NE_d}{V}=70\\mu J/m^3$<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260147497-hinh-23.png\" alt=\"Hình 23\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"},"ex":[{"exam":189,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Liên hệ áp suất với động năng phân tử","answer":"46,7","question":"Xét khối khí chứa trong một bình kín, biết tổng động năng tịnh tiến trung bình của các phân tử khí trong 1 m3 thể tích khí có giá trị 70 μJ/m3. Áp suất khí trong bình là x.10<sup>−6</sup> N/m2. Tìm x (làm tròn kết quả đến chữ số hàng phần mười)","difficulty":"trung-binh","explanation":"Tổng động năng tịnh tiến trung bình của các phân tử khí trong  $1m^3=\\frac{NE_d}{V}=70\\mu J/m^3$<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260147497-hinh-23.png\" alt=\"Hình 23\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"}}]},{"id":433390,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":2,"options":["3,6.10<sup>3</sup> J.","7,2.10<sup>3</sup> J.","3,6.10<sup>6</sup> J.","7,2.10<sup>5</sup> J."],"question":"Cho biết rượu ethylic có nhiệt hóa hơi riêng là 0,9.106 J/kg và khối lượng riêng là 0,8 kg/ lít. Nhiệt lượng cần thiết để làm hóa hơi hoàn toàn 5 lít rượu ethylic ở nhiệt độ sôi là","difficulty":"de","explanation":"Chọn đáp án C<br>Nhiệt lượng cần thiết để làm hóa hơi hoàn toàn 5 lít rượu ethylic ở nhiệt độ sôi là:<br>$Q=L.m=L.D.V=0,9.{10}^6.0,8.5=3,6.{10}^6$  J.","difficultySource":"ai"},"ex":[{"exam":200,"idx":3,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":2,"options":["3,6.10<sup>3</sup> J.","7,2.10<sup>3</sup> J.","3,6.10<sup>6</sup> J.","7,2.10<sup>5</sup> J."],"question":"Cho biết rượu ethylic có nhiệt hóa hơi riêng là 0,9.106 J/kg và khối lượng riêng là 0,8 kg/ lít. Nhiệt lượng cần thiết để làm hóa hơi hoàn toàn 5 lít rượu ethylic ở nhiệt độ sôi là","difficulty":"de","explanation":"Chọn đáp án C<br>Nhiệt lượng cần thiết để làm hóa hơi hoàn toàn 5 lít rượu ethylic ở nhiệt độ sôi là:<br>$Q=L.m=L.D.V=0,9.{10}^6.0,8.5=3,6.{10}^6$  J.","difficultySource":"ai"}}]},{"id":433419,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Vận dụng phương trình trạng thái","answer":1,"options":["671 °C.","398 °C.","86 °C.","857 °C."],"question":"Trong cylinder của một động cơ đốt trong, hỗn hợp khí (xem là khí lí tưởng) ở áp suất 1 atm, nhiệt độ 40 °C và thể tích 2,8 dm3. Nén hỗn hợp khí đến thể tích 0,3 dm3, áp suất 20 atm thì nhiệt độ của khối khí khi đó xấp xỉ bằng Sử dụng các thông tin sau cho câu 6 và câu 7: Một mol khí oxygen được chứa trong một bình kín có thể tích không đổi. Người ta đun nóng khối khí làm nhiệt độ khối khí tăng từ 27 °C lên đến 127 °C. Khi đó, áp suất của khối khí thay đổi một lượng là 1,0.10<sup>5</sup> Pa.","difficulty":"trung-binh","explanation":"Chọn đáp án B<br>Nhiệt độ của khối khí khi đó là:<br>Ta có:  $\\frac{p_1.V_1}{T_1}=\\frac{p_2.V_2}{T_2}$    $\\frac{1.2,8}{40+273}=\\frac{20.0,3}{t_2+273}$    $t_2\\approx 398$  C.","difficultySource":"ai"},"ex":[{"exam":200,"idx":4,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Vận dụng phương trình trạng thái","answer":1,"options":["671 °C.","398 °C.","86 °C.","857 °C."],"question":"Trong cylinder của một động cơ đốt trong, hỗn hợp khí (xem là khí lí tưởng) ở áp suất 1 atm, nhiệt độ 40 °C và thể tích 2,8 dm3. Nén hỗn hợp khí đến thể tích 0,3 dm3, áp suất 20 atm thì nhiệt độ của khối khí khi đó xấp xỉ bằng Sử dụng các thông tin sau cho câu 6 và câu 7: Một mol khí oxygen được chứa trong một bình kín có thể tích không đổi. Người ta đun nóng khối khí làm nhiệt độ khối khí tăng từ 27 °C lên đến 127 °C. Khi đó, áp suất của khối khí thay đổi một lượng là 1,0.10<sup>5</sup> Pa.","difficulty":"trung-binh","explanation":"Chọn đáp án B<br>Nhiệt độ của khối khí khi đó là:<br>Ta có:  $\\frac{p_1.V_1}{T_1}=\\frac{p_2.V_2}{T_2}$    $\\frac{1.2,8}{40+273}=\\frac{20.0,3}{t_2+273}$    $t_2\\approx 398$  C.","difficultySource":"ai"}}]},{"id":433651,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Đại cương về dòng điện xoay chiều","answer":0,"options":["1,07 mA.","1,07 A.","107 mA.","10,7 mA."],"question":"Trong mô hình Bohr của nguyên tử hydrogen, electron chuyển động tròn đều quanh hạt nhân với chu kì là 1,5.10<sup>16</sup> s. Biết điện tích của electron có độ lớn là e = 1,6.1019 C. Cường độ dòng điện tương ứng với chuyển động này có độ lớn xấp xỉ bằng","difficulty":"de","explanation":"Chọn đáp án A<br>Electron chuyển động tròn đều có thể coi như tạo thành một dòng điện có độ lớn cường độ dòng điện là:<br>$I=\\frac{e}{T}=\\frac{1,6.{10}^{-19}}{1,5.{10}^{-16}}\\approx 1,07$  mA.","distractorNotes":{"B":"Sai bậc lũy thừa khi chia: $10^{-19}/10^{-16}$ cho $10^{-3}$, rồi đổi đơn vị mA sang A sai.","C":"Sai lũy thừa mười: tính ra $10^{-3}$ A nhưng đọc thành hàng trăm mA.","D":"Lệch một bậc lũy thừa mười khi chia $10^{-19}$ cho $10^{-16}$ rồi đổi sang mA."},"difficultySource":"ai"},"ex":[{"exam":200,"idx":12,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Đại cương về dòng điện xoay chiều","answer":0,"options":["1,07 mA.","1,07 A.","107 mA.","10,7 mA."],"question":"Trong mô hình Bohr của nguyên tử hydrogen, electron chuyển động tròn đều quanh hạt nhân với chu kì là 1,5.10<sup>16</sup> s. Biết điện tích của electron có độ lớn là e = 1,6.1019 C. Cường độ dòng điện tương ứng với chuyển động này có độ lớn xấp xỉ bằng","difficulty":"de","explanation":"Chọn đáp án A<br>Electron chuyển động tròn đều có thể coi như tạo thành một dòng điện có độ lớn cường độ dòng điện là:<br>$I=\\frac{e}{T}=\\frac{1,6.{10}^{-19}}{1,5.{10}^{-16}}\\approx 1,07$  mA.","distractorNotes":{"B":"Sai bậc lũy thừa khi chia: $10^{-19}/10^{-16}$ cho $10^{-3}$, rồi đổi đơn vị mA sang A sai.","C":"Sai lũy thừa mười: tính ra $10^{-3}$ A nhưng đọc thành hàng trăm mA.","D":"Lệch một bậc lũy thừa mười khi chia $10^{-19}$ cho $10^{-16}$ rồi đổi sang mA."},"difficultySource":"ai"}}]},{"id":433738,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật phóng xạ và chu kì bán rã","answer":1,"options":["3,87.10<sup>13</sup> Bq.","4,65.10<sup>13</sup> Bq.","l,61.10<sup>12</sup> Bq.","1,61.10<sup>19</sup> Bq."],"question":"Chất phóng xạ chứa đồng vị  ${}_{11}^{24}{Na}$  được sử dụng làm chất đánh dấu điện giải có chu kì bán rã là 15 giờ. Một bệnh nhân được tiêm 6 mℓ dược chất chứa  ${}_{11}^{24}{Na}$  với nồng độ 1,002.10<sup>3</sup> moℓ/ℓ. Độ phóng xạ của liều dược chất tại thời điểm tiêm xấp xỉ bằng","difficulty":"trung-binh","explanation":"Chọn đáp án B<br>Độ phóng xạ của liều dược chất tại thời điểm tiêm:<br>$H=.N=.n.N_A=\\frac{\\ln\\left(2\\right)}{T}.C_M.V.N_A=\\frac{\\ln\\left(2\\right)}{15.3600}.1,002.{10}^{-3}.6.{10}^{-3}.6,02.{10}^{23}\\approx 4,65.{10}^{13}$  Bq.","difficultySource":"ai"},"ex":[{"exam":200,"idx":15,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật phóng xạ và chu kì bán rã","answer":1,"options":["3,87.10<sup>13</sup> Bq.","4,65.10<sup>13</sup> Bq.","l,61.10<sup>12</sup> Bq.","1,61.10<sup>19</sup> Bq."],"question":"Chất phóng xạ chứa đồng vị  ${}_{11}^{24}{Na}$  được sử dụng làm chất đánh dấu điện giải có chu kì bán rã là 15 giờ. Một bệnh nhân được tiêm 6 mℓ dược chất chứa  ${}_{11}^{24}{Na}$  với nồng độ 1,002.10<sup>3</sup> moℓ/ℓ. Độ phóng xạ của liều dược chất tại thời điểm tiêm xấp xỉ bằng","difficulty":"trung-binh","explanation":"Chọn đáp án B<br>Độ phóng xạ của liều dược chất tại thời điểm tiêm:<br>$H=.N=.n.N_A=\\frac{\\ln\\left(2\\right)}{T}.C_M.V.N_A=\\frac{\\ln\\left(2\\right)}{15.3600}.1,002.{10}^{-3}.6.{10}^{-3}.6,02.{10}^{23}\\approx 4,65.{10}^{13}$  Bq.","difficultySource":"ai"}}]},{"id":433767,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":0,"options":["2,1.10<sup>25</sup> MeV.","1,1.10<sup>25</sup> MeV.","3,4.10<sup>12</sup> MeV.","1,7.10<sup>12</sup> J."],"question":"Cho phản ứng tổng hợp hạt nhân tạo thành hạt nhân helium như sau: Năng lượng tỏa ra khi tổng hợp được 2 mol khí helium xấp xỉ bằng ${}_1^2D+{}_1^3T\\rightarrow {}_2^4{He}+{}_0^1n+17,5MeV$","difficulty":"de","explanation":"Chọn đáp án A<br>Số hạt nhân helium có trong 2 mol:  $N=n.N_A$<br>Tổng năng lượng tỏa ra khi tổng hợp được 2 mol khí helium:<br>$E=N.E_1=n.N_A.E_1=2.6,02.{10}^{23}.17,5\\approx 2,1.{10}^{25}$  MeV.","difficultySource":"ai"},"ex":[{"exam":200,"idx":16,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":0,"options":["2,1.10<sup>25</sup> MeV.","1,1.10<sup>25</sup> MeV.","3,4.10<sup>12</sup> MeV.","1,7.10<sup>12</sup> J."],"question":"Cho phản ứng tổng hợp hạt nhân tạo thành hạt nhân helium như sau: Năng lượng tỏa ra khi tổng hợp được 2 mol khí helium xấp xỉ bằng ${}_1^2D+{}_1^3T\\rightarrow {}_2^4{He}+{}_0^1n+17,5MeV$","difficulty":"de","explanation":"Chọn đáp án A<br>Số hạt nhân helium có trong 2 mol:  $N=n.N_A$<br>Tổng năng lượng tỏa ra khi tổng hợp được 2 mol khí helium:<br>$E=N.E_1=n.N_A.E_1=2.6,02.{10}^{23}.17,5\\approx 2,1.{10}^{25}$  MeV.","difficultySource":"ai"}}]},{"id":433912,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Trong một phòng thí nghiệm hạt nhân, người ta tổng hợp được một 105 g đồng vị mendelevium  ${}_{101}^{258}{Md}$  tinh khiết để nghiên cứu tính chất phóng xạ. Đồng vị này là chất phóng xạ  có chu kì bán rã là 51,5 ngày. Khối lượng của hạt nhân mẹ  ${}_{101}^{258}{Md}$ , hạt  và hạt nhân sản phẩm X lần lượt là 258,0984 u, 4,0026 u và 254,0880 u. Biết năng lượng tỏa ra của phản ứng được xác định bởi biểu thức  $E=\\left(m_{tt}-m_{sp}\\right).c^2$  với  $m_{tt}$  là tổng khối lượng của các hạt trước phản ứng,  $m_{sp}$  là tổng khối lượng của các hạt sau phản ứng. Lấy 1 uc2 = 931,5 MeV.","difficulty":"kho","statements":[{"text":"Hạt nhân sản phẩm X của phản ứng phân rã hạt nhân  ${}_{101}^{258}{Md}$  có 155 hạt neutron.","answer":true},{"text":"Năng lượng tỏa ra trong mỗi lần phân rã  của hạt nhân  ${}_{101}^{258}{Md}$  là 7,2657 MeV.","answer":true},{"text":"Độ phóng xạ của mẫu  ${}_{101}^{258}{Md}$  tại thời điểm ban đầu xấp xỉ bằng 3,82.10<sup>16</sup> Bq.","answer":true},{"text":"Trong 60 ngày đầu, số hạt  được phát ra từ mẫu  ${}_{101}^{258}{Md}$  tinh khiết xấp xỉ bằng 1,09.10<sup>23</sup> hạt.","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\"><b>Phương trình phân rã:</b> Hạt nhân mẹ phóng xạ $\\alpha$: ${}_{101}^{258}\\text{Md}$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow {}_{2}^{4}\\text{He} + {}_{Z}^{A}X$.</p><p class=\"text-base leading-relaxed my-2\">Bảo toàn số khối: $A = 258 - 4 = 254$. Bảo toàn điện tích: $Z = 101 - 2 = 99$. Vậy X là ${}_{99}^{254}\\text{Es}$.</p><p class=\"text-base leading-relaxed my-2\"><b>a)</b> Số neutron của X: $N = A - Z = 254 - 99 = 155$. Ý a) <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>b)</b> Độ hụt khối của phản ứng: $\\Delta m = m_{tt} - m_{sp} = 258{,}0984 - (4{,}0026 + 254{,}0880) = 0{,}0078$ u.</p><p class=\"text-base leading-relaxed my-2\">Năng lượng tỏa ra: $E = \\Delta m \\cdot c^2 = 0{,}0078 \\cdot 931{,}5 \\approx 7{,}2657$ MeV. Ý b) <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>c)</b> Số hạt nhân ban đầu: $N_0 = \\dfrac{m}{M}N_A = \\dfrac{105}{258}\\cdot 6{,}022\\cdot 10^{23} \\approx 2{,}451\\cdot 10^{23}$ hạt.</p><p class=\"text-base leading-relaxed my-2\">Hằng số phóng xạ: $\\lambda = \\dfrac{\\ln 2}{T} = \\dfrac{0{,}693}{51{,}5\\cdot 86400\\ \\text{s}} \\approx 1{,}558\\cdot 10^{-7}\\ \\text{s}^{-1}$.</p><p class=\"text-base leading-relaxed my-2\">Độ phóng xạ ban đầu: $H_0 = \\lambda N_0 \\approx 1{,}558\\cdot 10^{-7}\\cdot 2{,}451\\cdot 10^{23} \\approx 3{,}82\\cdot 10^{16}$ Bq. Ý c) <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>d)</b> Số hạt nhân đã phân rã trong $t = 60$ ngày:</p><p class=\"text-base leading-relaxed my-2\">$\\Delta N = N_0\\left(1 - 2^{-t/T}\\right) = 2{,}451\\cdot 10^{23}\\left(1 - 2^{-60/51{,}5}\\right)$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$2^{-60/51{,}5} \\approx 0{,}446$, nên $\\Delta N \\approx 2{,}451\\cdot 10^{23}\\cdot 0{,}554 \\approx 1{,}36\\cdot 10^{23}$ hạt.</p><p class=\"text-base leading-relaxed my-2\">Mỗi lần phân rã phát ra 1 hạt $\\alpha$, nên số hạt $\\alpha$ trong 60 ngày đầu xấp xỉ $1{,}36\\cdot 10^{23}$, không phải $1{,}09\\cdot 10^{23}$. Ý d) <b>Sai</b>.</p>","difficultySource":"ai"},"ex":[{"exam":200,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Trong một phòng thí nghiệm hạt nhân, người ta tổng hợp được một 105 g đồng vị mendelevium  ${}_{101}^{258}{Md}$  tinh khiết để nghiên cứu tính chất phóng xạ. Đồng vị này là chất phóng xạ  có chu kì bán rã là 51,5 ngày. Khối lượng của hạt nhân mẹ  ${}_{101}^{258}{Md}$ , hạt  và hạt nhân sản phẩm X lần lượt là 258,0984 u, 4,0026 u và 254,0880 u. Biết năng lượng tỏa ra của phản ứng được xác định bởi biểu thức  $E=\\left(m_{tt}-m_{sp}\\right).c^2$  với  $m_{tt}$  là tổng khối lượng của các hạt trước phản ứng,  $m_{sp}$  là tổng khối lượng của các hạt sau phản ứng. Lấy 1 uc2 = 931,5 MeV.","difficulty":"kho","statements":[{"text":"Hạt nhân sản phẩm X của phản ứng phân rã hạt nhân  ${}_{101}^{258}{Md}$  có 155 hạt neutron.","answer":true},{"text":"Năng lượng tỏa ra trong mỗi lần phân rã  của hạt nhân  ${}_{101}^{258}{Md}$  là 7,2657 MeV.","answer":true},{"text":"Độ phóng xạ của mẫu  ${}_{101}^{258}{Md}$  tại thời điểm ban đầu xấp xỉ bằng 3,82.10<sup>16</sup> Bq.","answer":true},{"text":"Trong 60 ngày đầu, số hạt  được phát ra từ mẫu  ${}_{101}^{258}{Md}$  tinh khiết xấp xỉ bằng 1,09.10<sup>23</sup> hạt.","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\"><b>Phương trình phân rã:</b> Hạt nhân mẹ phóng xạ $\\alpha$: ${}_{101}^{258}\\text{Md}$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow {}_{2}^{4}\\text{He} + {}_{Z}^{A}X$.</p><p class=\"text-base leading-relaxed my-2\">Bảo toàn số khối: $A = 258 - 4 = 254$. Bảo toàn điện tích: $Z = 101 - 2 = 99$. Vậy X là ${}_{99}^{254}\\text{Es}$.</p><p class=\"text-base leading-relaxed my-2\"><b>a)</b> Số neutron của X: $N = A - Z = 254 - 99 = 155$. Ý a) <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>b)</b> Độ hụt khối của phản ứng: $\\Delta m = m_{tt} - m_{sp} = 258{,}0984 - (4{,}0026 + 254{,}0880) = 0{,}0078$ u.</p><p class=\"text-base leading-relaxed my-2\">Năng lượng tỏa ra: $E = \\Delta m \\cdot c^2 = 0{,}0078 \\cdot 931{,}5 \\approx 7{,}2657$ MeV. Ý b) <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>c)</b> Số hạt nhân ban đầu: $N_0 = \\dfrac{m}{M}N_A = \\dfrac{105}{258}\\cdot 6{,}022\\cdot 10^{23} \\approx 2{,}451\\cdot 10^{23}$ hạt.</p><p class=\"text-base leading-relaxed my-2\">Hằng số phóng xạ: $\\lambda = \\dfrac{\\ln 2}{T} = \\dfrac{0{,}693}{51{,}5\\cdot 86400\\ \\text{s}} \\approx 1{,}558\\cdot 10^{-7}\\ \\text{s}^{-1}$.</p><p class=\"text-base leading-relaxed my-2\">Độ phóng xạ ban đầu: $H_0 = \\lambda N_0 \\approx 1{,}558\\cdot 10^{-7}\\cdot 2{,}451\\cdot 10^{23} \\approx 3{,}82\\cdot 10^{16}$ Bq. Ý c) <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>d)</b> Số hạt nhân đã phân rã trong $t = 60$ ngày:</p><p class=\"text-base leading-relaxed my-2\">$\\Delta N = N_0\\left(1 - 2^{-t/T}\\right) = 2{,}451\\cdot 10^{23}\\left(1 - 2^{-60/51{,}5}\\right)$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$2^{-60/51{,}5} \\approx 0{,}446$, nên $\\Delta N \\approx 2{,}451\\cdot 10^{23}\\cdot 0{,}554 \\approx 1{,}36\\cdot 10^{23}$ hạt.</p><p class=\"text-base leading-relaxed my-2\">Mỗi lần phân rã phát ra 1 hạt $\\alpha$, nên số hạt $\\alpha$ trong 60 ngày đầu xấp xỉ $1{,}36\\cdot 10^{23}$, không phải $1{,}09\\cdot 10^{23}$. Ý d) <b>Sai</b>.</p>","difficultySource":"ai"}}]},{"id":440002,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Đồng vị xenon ( ${}_{54}^{133}Xe$ ) là chất phóng xạ  $\\beta^−$  có chu kì bán rã là 5,24 ngày. Trong y học, hỗn hợp khí chứa xenon được sử dụng để đánh giá độ thông khí của phổi người bệnh. Một người bệnh được chỉ định sử dụng liều xenon có độ phóng xạ 3,18.10<sup>8</sup> Bq. Coi rằng 85,0% lượng xenon trong liều đó lắng đọng tại phổi. Người bệnh được chụp ảnh phổi lần thứ nhất ngay sau khi hít khí và lần thứ hai sau đó 24,0 giờ. Biết khối lượng mol nguyên tử của xenon là 133 g/mol.","difficulty":"kho","statements":[{"text":"Hạt nhân  ${}_{54}^{133}Xe$  phóng ra hạt electron để biến đổi thành hạt nhân  ${}_{54}^{133}CS$ .","answer":true},{"text":"Hằng số phóng xạ của  ${}_{54}^{133}Xe$  là 0,132 s-1.","answer":false},{"text":"Khối lượng  ${}_{54}^{133}Xe$  có trong liều mà người bệnh đã hít vào là 0,0459 µg.","answer":true},{"text":"Sau khi dùng thuốc 24,0 giờ, lượng  ${}_{54}^{133}Xe$  đã lắng đọng tại phổi có độ phóng xạ là 2,79.10<sup>8</sup> Bq.","answer":false}],"explanation":"Phương pháp: Áp dụng công thức phóng xạ N = N0.2^(-t/T), H = λN, và phản ứng phóng xạ β⁻.<br>a) đúng<br>+ Hạt nhân Xe-133 (Z=54) phóng xạ β⁻ nên số proton tăng 1, số khối giữ nguyên: 133/54 Xe → 133/55 Cs + 0/-1 e.<br>b) sai<br>+ Hằng số phóng xạ λ = ln2/T = ln2/(5,24×24×3600) ≈ 1,53×10⁻⁶ s⁻¹, không phải 0,132 s⁻¹.<br>c) đúng<br>+ Số hạt N0 = H0/λ = 3,18×10⁸/1,53×10⁻⁶ ≈ 2,08×10¹⁴ hạt. Số mol n0 = N0/NA ≈ 3,45×10⁻¹⁰ mol. Khối lượng m0 = n0×M = 3,45×10⁻¹⁰×133 ≈ 0,0459×10⁻⁶ g = 0,0459 µg.<br>d) sai<br>+ Độ phóng xạ của lượng lắng đọng tại phổi sau 24 giờ: H = 0,85×H0×2^(-t/T) = 0,85×3,18×10⁸×2^(-24/(5,24×24)) ≈ 2,37×10⁸ Bq, không phải 2,79×10⁸ Bq.","difficultySource":"ai"},"ex":[{"exam":214,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Đồng vị xenon ( ${}_{54}^{133}Xe$ ) là chất phóng xạ  $\\beta^−$  có chu kì bán rã là 5,24 ngày. Trong y học, hỗn hợp khí chứa xenon được sử dụng để đánh giá độ thông khí của phổi người bệnh. Một người bệnh được chỉ định sử dụng liều xenon có độ phóng xạ 3,18.10<sup>8</sup> Bq. Coi rằng 85,0% lượng xenon trong liều đó lắng đọng tại phổi. Người bệnh được chụp ảnh phổi lần thứ nhất ngay sau khi hít khí và lần thứ hai sau đó 24,0 giờ. Biết khối lượng mol nguyên tử của xenon là 133 g/mol.","difficulty":"kho","statements":[{"text":"Hạt nhân  ${}_{54}^{133}Xe$  phóng ra hạt electron để biến đổi thành hạt nhân  ${}_{54}^{133}CS$ .","answer":true},{"text":"Hằng số phóng xạ của  ${}_{54}^{133}Xe$  là 0,132 s-1.","answer":false},{"text":"Khối lượng  ${}_{54}^{133}Xe$  có trong liều mà người bệnh đã hít vào là 0,0459 µg.","answer":true},{"text":"Sau khi dùng thuốc 24,0 giờ, lượng  ${}_{54}^{133}Xe$  đã lắng đọng tại phổi có độ phóng xạ là 2,79.10<sup>8</sup> Bq.","answer":false}],"explanation":"Phương pháp: Áp dụng công thức phóng xạ N = N0.2^(-t/T), H = λN, và phản ứng phóng xạ β⁻.<br>a) đúng<br>+ Hạt nhân Xe-133 (Z=54) phóng xạ β⁻ nên số proton tăng 1, số khối giữ nguyên: 133/54 Xe → 133/55 Cs + 0/-1 e.<br>b) sai<br>+ Hằng số phóng xạ λ = ln2/T = ln2/(5,24×24×3600) ≈ 1,53×10⁻⁶ s⁻¹, không phải 0,132 s⁻¹.<br>c) đúng<br>+ Số hạt N0 = H0/λ = 3,18×10⁸/1,53×10⁻⁶ ≈ 2,08×10¹⁴ hạt. Số mol n0 = N0/NA ≈ 3,45×10⁻¹⁰ mol. Khối lượng m0 = n0×M = 3,45×10⁻¹⁰×133 ≈ 0,0459×10⁻⁶ g = 0,0459 µg.<br>d) sai<br>+ Độ phóng xạ của lượng lắng đọng tại phổi sau 24 giờ: H = 0,85×H0×2^(-t/T) = 0,85×3,18×10⁸×2^(-24/(5,24×24)) ≈ 2,37×10⁸ Bq, không phải 2,79×10⁸ Bq.","difficultySource":"ai"}}]},{"id":440778,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","answer":0,"options":["4,4.10<sup>25</sup> hạt.","8,8.10<sup>25</sup> hạt.","2,2.10<sup>25</sup> hạt .","1,2.10<sup>25</sup> hạt."],"question":"Biết số Avôgađrô là 6,02.10<sup>23</sup> mol‒1, khối lượng mol của hạt nhân urani  ${}_{92}^{238}U$  là 238 gam/mol. Số neutron trong 119 gam urani  ${}_{92}^{238}U$  gần đúng là","difficulty":"trung-binh","explanation":"$N_U=\\frac{m_U}{M_U}.N_A$<br>1  ${}_{92}^{238}U$  có  $\\left(238−92\\right)=146$  neutron<br>$\\Rightarrow N_m=146N_U=146.\\frac{119}{238}.N_A=4,4.10^{25}$  hạt","difficultySource":"ai"},"ex":[{"exam":215,"idx":13,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","answer":0,"options":["4,4.10<sup>25</sup> hạt.","8,8.10<sup>25</sup> hạt.","2,2.10<sup>25</sup> hạt .","1,2.10<sup>25</sup> hạt."],"question":"Biết số Avôgađrô là 6,02.10<sup>23</sup> mol‒1, khối lượng mol của hạt nhân urani  ${}_{92}^{238}U$  là 238 gam/mol. Số neutron trong 119 gam urani  ${}_{92}^{238}U$  gần đúng là","difficulty":"trung-binh","explanation":"$N_U=\\frac{m_U}{M_U}.N_A$<br>1  ${}_{92}^{238}U$  có  $\\left(238−92\\right)=146$  neutron<br>$\\Rightarrow N_m=146N_U=146.\\frac{119}{238}.N_A=4,4.10^{25}$  hạt","difficultySource":"ai"}}]},{"id":441152,"nq":{"form":"bai_tap","type":"short_answer","topic":"Mol, số Avogadro và lượng chất khí","answer":"1,7","question":"Một quả bóng được bơm đầy khí nitrogen tinh khiết. Quả bóng được xác định có thể tích 0,75 lít vào một ngày có nhiệt 35°C và áp suất không khí là 0,95atm. Số Avogadro là NA = 6,02.10<sup>23</sup> mol-1, T(K) = t0C + 273, R = 0,082 (atm.l/mol.K). Số phân tử khí nitrogen trong bóng là X.10<sup>22</sup> phân tử. X bằng bao nhiêu? (Kết quả làm tròn đến chữ số hàng phần mười).","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Khí nitrogen được coi là khí lí tưởng, áp dụng phương trình trạng thái $PV = nRT$, với $n$ là số mol khí.</p><p class=\"text-base leading-relaxed my-2\">Đổi nhiệt độ: $T = 35 + 273 = 308\\ \\text{K}$.</p><p class=\"text-base leading-relaxed my-2\">Số mol khí nitrogen trong bóng:</p><p class=\"text-base leading-relaxed my-2\">$n = \\dfrac{PV}{RT} = \\dfrac{0{,}95 \\cdot 0{,}75}{0{,}082 \\cdot 308} \\approx 0{,}0282\\ \\text{mol}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Số phân tử khí:</p><p class=\"text-base leading-relaxed my-2\">$N = n \\cdot N_A = 0{,}0282 \\cdot 6{,}02 \\cdot 10^{23} \\approx 1{,}70 \\cdot 10^{22}\\ \\text{phân tử}$</p><p class=\"text-base leading-relaxed my-2\">Vậy $X = 1{,}7$.</p>","difficultySource":"ai"},"ex":[{"exam":215,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Mol, số Avogadro và lượng chất khí","answer":"1,7","question":"Một quả bóng được bơm đầy khí nitrogen tinh khiết. Quả bóng được xác định có thể tích 0,75 lít vào một ngày có nhiệt 350C và áp suất không khí là 0,95atm. Số Avogadro là NA = 6,02.10<sup>23</sup> mol-1, T(K) = t0C + 273, R = 0,082 (atm.l/mol.K). Số phân tử khí nitrogen trong bóng là X.10<sup>22</sup> phân tử. X bằng bao nhiêu? (Kết quả làm tròn đến chữ số hàng phần mười).","difficulty":"trung-binh","explanation":"<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790401126324-hinh-29.jpg\" alt=\"Hình 29\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"}}]},{"id":446924,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Động năng trung bình phân tử và nhiệt độ","answer":2,"options":["414.10<sup>−23</sup> J.","37,3.10<sup>−23</sup>J.","621.10<sup>−23</sup>J.","55,9.10<sup>−23</sup>J."],"question":"Động năng chuyển động tịnh tiến trung bình của phân tử khí lí tưởng ở 270C là","difficulty":"de","explanation":"$\\overline{E}_d=\\frac{3}{2}kT=\\frac{3}{2}.1,38.10^{−23}.\\left(27+273\\right)=6,21.10^{−21}\\left(J\\right)$","difficultySource":"ai"},"ex":[{"exam":223,"idx":10,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Động năng trung bình phân tử và nhiệt độ","answer":2,"options":["414.10<sup>−23</sup> J.","37,3.10<sup>−23</sup>J.","621.10<sup>−23</sup>J.","55,9.10<sup>−23</sup>J."],"question":"Động năng chuyển động tịnh tiến trung bình của phân tử khí lí tưởng ở 270C là","difficulty":"de","explanation":"$\\overline{E}_d=\\frac{3}{2}kT=\\frac{3}{2}.1,38.10^{−23}.\\left(27+273\\right)=6,21.10^{−21}\\left(J\\right)$","difficultySource":"ai"}}]},{"id":448837,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Tính nhiệt lượng theo nhiệt dung riêng","answer":0,"options":["775 kJ.","460 kJ.","315 kJ.","556 kJ."],"question":"Bạn Mạnh đun sôi 1kg nước từ 250C bằng một ấm điện. Sau khi nước sôi một thời gian, bạn Mạnh mới ngắt điện và rót hết lượng nước sôi còn lại trong ấm vào một phích nước. Biết rằng trong phích nước đã có sẵn 200g nước ở 600C và nhiệt độ nước trong phích khi cân bằng nhiệt là 920C. Bỏ qua sự trao đổi nhiệt của nước với môi trường và ruột phích. Cho nhiệt dung riêng của nước c = 4200 J/(kg.K), nhiệt hoá hơi của nước L = 2,3.10<sup>6</sup> J/kg ; nước sôi ở 1000C; phích nước có dung tích đủ lớn. Nhiệt lượng mà ấm đã cung cấp cho nước trong quá trình đun nói trên là","difficulty":"kho","explanation":"- Phương trình cân bằng nhiệt trong phích:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790496926320-hinh-6.jpg\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>- Nhiệt lượng âm cung cấp cho <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790496926757-hinh-7.jpg\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" /> nước từ <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790496927155-hinh-8.png\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" /> đến khi sôi <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790496927904-hinh-9.jpg\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" /> là:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790496928381-hinh-10.jpg\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>- Sau khi nước sôi một thời gian bạn Mạnh mới ngắt điện, khối lượng nước sôi còn lại trong ấm là m' <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790496928851-hinh-11.jpg\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>=> Khối lượng nước bị hoá hơi là: <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790496929509-hinh-12.jpg\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>-  Nhiệt lượng cung cấp cho <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790496929939-hinh-13.jpg\" alt=\"Hình 13\" class=\"mx-auto my-2 max-w-full rounded-lg\" /> nước hoá hơi là: <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790496930458-hinh-14.jpg\" alt=\"Hình 14\" class=\"mx-auto my-2 max-w-full rounded-lg\" />.<br>=> Nhiệt lượng mà ấm đã cung cấp cho nước trong quá trình đun nói trên là:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790496930872-hinh-15.jpg\" alt=\"Hình 15\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"},"ex":[{"exam":226,"idx":7,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Tính nhiệt lượng theo nhiệt dung riêng","answer":0,"options":["775 kJ.","460 kJ.","315 kJ.","556 kJ."],"question":"Bạn Mạnh đun sôi 1kg nước từ 250C bằng một ấm điện. Sau khi nước sôi một thời gian, bạn Mạnh mới ngắt điện và rót hết lượng nước sôi còn lại trong ấm vào một phích nước. Biết rằng trong phích nước đã có sẵn 200g nước ở 600C và nhiệt độ nước trong phích khi cân bằng nhiệt là 920C. Bỏ qua sự trao đổi nhiệt của nước với môi trường và ruột phích. Cho nhiệt dung riêng của nước c = 4200 J/(kg.K), nhiệt hoá hơi của nước L = 2,3.10<sup>6</sup> J/kg ; nước sôi ở 1000C; phích nước có dung tích đủ lớn. Nhiệt lượng mà ấm đã cung cấp cho nước trong quá trình đun nói trên là","difficulty":"kho","explanation":"- Phương trình cân bằng nhiệt trong phích:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790496926320-hinh-6.jpg\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>- Nhiệt lượng âm cung cấp cho <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790496926757-hinh-7.jpg\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" /> nước từ <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790496927155-hinh-8.png\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" /> đến khi sôi <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790496927904-hinh-9.jpg\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" /> là:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790496928381-hinh-10.jpg\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>- Sau khi nước sôi một thời gian bạn Mạnh mới ngắt điện, khối lượng nước sôi còn lại trong ấm là m' <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790496928851-hinh-11.jpg\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>=> Khối lượng nước bị hoá hơi là: <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790496929509-hinh-12.jpg\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>-  Nhiệt lượng cung cấp cho <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790496929939-hinh-13.jpg\" alt=\"Hình 13\" class=\"mx-auto my-2 max-w-full rounded-lg\" /> nước hoá hơi là: <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790496930458-hinh-14.jpg\" alt=\"Hình 14\" class=\"mx-auto my-2 max-w-full rounded-lg\" />.<br>=> Nhiệt lượng mà ấm đã cung cấp cho nước trong quá trình đun nói trên là:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790496930872-hinh-15.jpg\" alt=\"Hình 15\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"}}]},{"id":452241,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"5,1","question":"Một viên nước có khối lượng 15 g ở nhiệt độ ‒3°C. Biết nhiệt dung riêng và nhiệt nóng chảy riêng của nước đá lần lượt là 2100 J/(kg.K) và 3,34.10<sup>5</sup> J/kg. Nhiệt lượng tối thiểu cần cung cấp để viên nước đá nóng chảy hoàn toàn ở 0°C là bao nhiêu kJ (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"Khối lượng viên đá: m = 15 g = 0,015 kg .<br>Nhiệt lượng cần cung cấp để đá tăng từ -3°C đến 0°C :<br>Q1 = mcΔt = 0,015.2100.[0 – (-3)] = 94,5J<br>Nhiệt lượng cần cung cấp để đá nóng chảy hoàn toàn ở 0°C:<br>Q2 = λm = 3,34.105.0,015 = 5010J<br>Tổng nhiệt lượng tối thiểu cần cung cấp:<br>Q = Q1 + Q2 = 94,5 + 5010 = 5104,5J = 5,1045kJ<br>Làm tròn đến chữ số hàng phần mười, ta được 5,1.","difficultySource":"ai"},"ex":[{"exam":229,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"5,1","question":"Một viên nước có khối lượng 15 g ở nhiệt độ ‒30C. Biết nhiệt dung riêng và nhiệt nóng chảy riêng của nước đá lần lượt là 2100 J/(kg.K) và 3,34.10<sup>5</sup> J/kg. Nhiệt lượng tối thiểu cần cung cấp để viên nước đá nóng chảy hoàn toàn ở 00C là bao nhiêu kJ (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"Khối lượng viên đá: m = 15 g = 0,015 kg .<br>Nhiệt lượng cần cung cấp để đá tăng từ -30C đến 00C :<br>Q1 = mcΔt = 0,015.2100.[0 – (-3)] = 94,5J<br>Nhiệt lượng cần cung cấp để đá nóng chảy hoàn toàn ở 00C:<br>Q2 = λm = 3,34.105.0,015 = 5010J<br>Tổng nhiệt lượng tối thiểu cần cung cấp:<br>Q = Q1 + Q2 = 94,5 + 5010 = 5104,5J = 5,1045kJ<br>Làm tròn đến chữ số hàng phần mười, ta được 5,1.","difficultySource":"ai"}}]},{"id":453359,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Trong thí nghiệm nghiên cứu về tác hại của thuốc lá, các nhà khoa học thấy rằng trong mẫu thuốc lá có chứa hạt nhân Polonium  ${}_{84}^{210}{Po}$ . Hạt nhân  ${}_{84}^{210}{Po}$  phóng xạ  với chu kì bán rã là 140 ngày và biến đổi thành hạt nhân con X bền vững. Ban đầu, các nhà nghiên cứu nhận 20g một mẫu phóng xạ  ${}_{84}^{210}{Po}$  nguyên chất. Biết khối lượng của  ${}_{84}^{210}{Po}$ , hạt  và hạt X lần lượt là 209,9829 amu; 4,0015 amu và 205,9745 amu. Lấy 1 amu = 931,5 MeV/c2. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259994162-hinh-3.jpg\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Số neutron của hạt nhân X là 126.","answer":false},{"text":"Hằng số phóng xạ của hạt nhân  ${}_{84}^{210}{Po}$  xấp xỉ 5,73.10<sup>−8</sup> s–1.","answer":true},{"text":"Năng lượng tỏa ra của một phản ứng phân rã  ${}_{84}^{210}{Po}$  xấp xỉ 6,43 MeV.","answer":true},{"text":"Sau một khoảng thời gian 180 ngày kể từ thời điểm ban đầu, khối lượng hạt nhân X trong mẫu là 11,80g (Làm tròn kết quả đến chữ số hàng phần trăm).","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Phóng xạ $\\alpha$: ${}_{84}^{210}\\mathrm{Po}\\to{}_2^4\\mathrm{He}+{}_{82}^{206}\\mathrm{X}$, X là chì ${}^{206}\\mathrm{Pb}$.</p><p class=\"text-base leading-relaxed my-2\">a) Sai. Số neutron của X là $206-82=124$.</p><p class=\"text-base leading-relaxed my-2\">b) Đúng. $\\lambda=\\dfrac{\\ln2}{T}=\\dfrac{0{,}693}{140\\cdot86400}\\approx5{,}73\\cdot10^{-8}$ s$^{-1}$.</p><p class=\"text-base leading-relaxed my-2\">c) Đúng. $\\Delta E=(209{,}9829-4{,}0015-205{,}9745)\\cdot931{,}5=0{,}0069\\cdot931{,}5\\approx6{,}43$ MeV.</p><p class=\"text-base leading-relaxed my-2\">d) Sai. Po còn lại sau 180 ngày: $20\\cdot2^{-180/140}\\approx8{,}20$ g; Po đã phân rã $\\approx11{,}80$ g.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Khối lượng X tạo thành $\\approx11{,}80\\cdot\\dfrac{206}{210}\\approx11{,}57$ g, không phải $11{,}80$ g (đó là khối lượng Po đã phân rã).</p>","difficultySource":"ai"},"ex":[{"exam":167,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Trong thí nghiệm nghiên cứu về tác hại của thuốc lá, các nhà khoa học thấy rằng trong mẫu thuốc lá có chứa hạt nhân Polonium  ${}_{84}^{210}{Po}$ . Hạt nhân  ${}_{84}^{210}{Po}$  phóng xạ  với chu kì bán rã là 140 ngày và biến đổi thành hạt nhân con X bền vững. Ban đầu, các nhà nghiên cứu nhận 20g một mẫu phóng xạ  ${}_{84}^{210}{Po}$  nguyên chất. Biết khối lượng của  ${}_{84}^{210}{Po}$ , hạt  và hạt X lần lượt là 209,9829 amu; 4,0015 amu và 205,9745 amu. Lấy 1 amu = 931,5 MeV/c2. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259994162-hinh-3.jpg\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Số neutron của hạt nhân X là 126.","answer":false},{"text":"Hằng số phóng xạ của hạt nhân  ${}_{84}^{210}{Po}$  xấp xỉ 5,73.10<sup>−8</sup> s–1.","answer":true},{"text":"Năng lượng tỏa ra của một phản ứng phân rã  ${}_{84}^{210}{Po}$  xấp xỉ 6,43 MeV.","answer":true},{"text":"Sau một khoảng thời gian 180 ngày kể từ thời điểm ban đầu, khối lượng hạt nhân X trong mẫu là 11,80g (Làm tròn kết quả đến chữ số hàng phần trăm).","answer":false}],"explanation":"","difficultySource":"ai"}}]},{"id":453387,"nq":{"form":"bai_tap","type":"true_false","topic":"Độ phóng xạ và bài toán xác định tuổi","question":"Tuổi của một chiếc thuyền cổ có thể được xác định bằng cách so sánh sự phân rã phóng xạ của  ${}_6^{14}C$  từ gỗ sống với gỗ lấy từ chiếc thuyền cổ. Một mẫu gỗ tươi gồm 3.10<sup>23</sup> nguyên tử carbon được lấy ra từ một khối gỗ sống để nghiên cứu. Trong gỗ, có một trong mỗi 1012 nguyên tử carbon là đồng vị phóng xạ  ${}_6^{14}C$  có hằng số phóng xạ là 3,84.1012 s1. Lấy 1 năm có 365 ngày. Người ta lấy từ chiếc thuyền cổ này một mẫu gỗ cổ (bằng khối lượng của mẫu gỗ tươi) và xác định được độ phóng xạ của các đồng vị phóng xạ  ${}_6^{14}C$  trong mẫu này là 0,65 Bq. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259698513-hinh-10.jpg\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Chu kì bán rã của  ${}_6^{14}C$  xấp xỉ bằng 5 724 năm.","answer":true},{"text":"Số nguyên tử  ${}_6^{14}C$  có trong mẫu gỗ tươi trên là 3.10<sup>11</sup>.","answer":true},{"text":"Độ phóng xạ của  ${}_6^{14}C$  có trong mẫu gỗ tươi trên xấp xỉ bằng 2 Bq.","answer":false},{"text":"Tuổi của chiếc thuyền này xấp xỉ bằng 2 700 năm.","answer":false}],"explanation":"a) đúng<br>Chu kì bán rã của  ${}_6^{14}C$  bằng:<br>$T=\\frac{\\ln\\left(2\\right)}{}=\\frac{\\ln\\left(2\\right)}{3,84.{10}^{-12}}\\approx 5724$  năm.<br>b) đúng<br>Số nguyên tử  ${}_6^{14}C$  có trong mẫu gỗ tươi trên là:  $\\frac{3.{10}^{23}}{{10}^{12}}=3.{10}^{11}$ .<br>c) sai<br>Độ phóng xạ của  ${}_6^{14}C$  có trong mẫu gỗ tươi trên xấp xỉ bằng:<br>$H_0=.N_0=3,84.{10}^{-12}.3.{10}^{11}=1,152$  Bq.<br>d) sai<br>Tuổi của chiếc thuyền này xấp xỉ bằng:<br>$H_t=H_0.2^{-\\frac{t}{T}}$    $0,65=1,152.2^{-\\frac{t}{5724}}$    $t\\approx 4726$  năm","difficultySource":"ai"},"ex":[{"exam":134,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Độ phóng xạ và bài toán xác định tuổi","question":"Tuổi của một chiếc thuyền cổ có thể được xác định bằng cách so sánh sự phân rã phóng xạ của  ${}_6^{14}C$  từ gỗ sống với gỗ lấy từ chiếc thuyền cổ. Một mẫu gỗ tươi gồm 3.10<sup>23</sup> nguyên tử carbon được lấy ra từ một khối gỗ sống để nghiên cứu. Trong gỗ, có một trong mỗi 1012 nguyên tử carbon là đồng vị phóng xạ  ${}_6^{14}C$  có hằng số phóng xạ là 3,84.1012 s1. Lấy 1 năm có 365 ngày. Người ta lấy từ chiếc thuyền cổ này một mẫu gỗ cổ (bằng khối lượng của mẫu gỗ tươi) và xác định được độ phóng xạ của các đồng vị phóng xạ  ${}_6^{14}C$  trong mẫu này là 0,65 Bq. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259698513-hinh-10.jpg\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Chu kì bán rã của  ${}_6^{14}C$  xấp xỉ bằng 5 724 năm.","answer":true},{"text":"Số nguyên tử  ${}_6^{14}C$  có trong mẫu gỗ tươi trên là 3.10<sup>11</sup>.","answer":true},{"text":"Độ phóng xạ của  ${}_6^{14}C$  có trong mẫu gỗ tươi trên xấp xỉ bằng 2 Bq.","answer":false},{"text":"Tuổi của chiếc thuyền này xấp xỉ bằng 2 700 năm.","answer":false}],"explanation":"a) đúng<br>Chu kì bán rã của  ${}_6^{14}C$  bằng:<br>$T=\\frac{\\ln\\left(2\\right)}{}=\\frac{\\ln\\left(2\\right)}{3,84.{10}^{-12}}\\approx 5724$  năm.<br>b) đúng<br>Số nguyên tử  ${}_6^{14}C$  có trong mẫu gỗ tươi trên là:  $\\frac{3.{10}^{23}}{{10}^{12}}=3.{10}^{11}$ .<br>c) sai<br>Độ phóng xạ của  ${}_6^{14}C$  có trong mẫu gỗ tươi trên xấp xỉ bằng:<br>$H_0=.N_0=3,84.{10}^{-12}.3.{10}^{11}=1,152$  Bq.<br>d) sai<br>Tuổi của chiếc thuyền này xấp xỉ bằng:<br>$H_t=H_0.2^{-\\frac{t}{T}}$    $0,65=1,152.2^{-\\frac{t}{5724}}$    $t\\approx 4726$  năm","difficultySource":"ai"}}]},{"id":453513,"nq":{"form":"bai_tap","type":"true_false","topic":"Nóng chảy, đông đặc, hoá hơi, ngưng tụ","question":"Quạt hơi nước là thiết bị hoạt động dựa vào hiện tượng bay hơi nước để làm mát không khí. Bơm nước tuần hoàn liên tục qua tấm làm mát. Luồng gió bên ngoài phòng được quạt hút vào máy, đi qua tấm làm mát. Nước trên tấm làm mát sẽ hấp thụ nhiệt của khí nóng làm nước bay hơi và làm giảm nhiệt độ không khí. Giả sử toàn bộ nhiệt lượng lấy từ không khí chỉ để làm bay hơi nước. Biết lưu lượng nước bay hơi từ quạt là 0,15 g/s; Ở nhiệt độ và áp suất phòng khi đó thì nhiệt hóa hơi riêng của nước là 2,26.10<sup>6</sup> J/kg, khối lượng riêng của không khí trong phòng là 1,2 kg/m3 và nhiệt dung riêng đẳng áp của không khí là 1005 J/kg.K. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259602042-hinh-4.jpg\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Khối lượng nước bay hơi trong thời gian 20 phút là 0,18 kg.","answer":true},{"text":"Nhiệt lượng cần thiết lấy từ không khí để làm bay hơi nước ở nhiệt độ và áp suất phòng trong thời gian 20 phút là 4068 J.","answer":false},{"text":"Khối lượng không khí trong phòng đó (kích thước: 4 m x 4 m x 3 m) là 57,6 kg.","answer":true},{"text":"Sau 20 phút mở quạt, không khí mát từ quạt khuếch tán đều trong phòng làm nhiệt độ của phòng giảm đi khoảng 9,7°C.","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Nhiệt lượng cần để làm bay hơi nước: $Q=m L$. Nhiệt lượng này lấy từ không khí, làm không khí lạnh đi.</p><p class=\"text-base leading-relaxed my-2\">a) Đúng. $m=0{,}15\\cdot1200=180$ g $=0{,}18$ kg (20 phút = 1200 s).</p><p class=\"text-base leading-relaxed my-2\">b) Sai. $Q=0{,}18\\cdot2{,}26\\cdot10^6=406800$ J, không phải 4068 J.</p><p class=\"text-base leading-relaxed my-2\">c) Đúng. $V=4\\cdot4\\cdot3=48$ m$^3$, $m=1{,}2\\cdot48=57{,}6$ kg.</p><p class=\"text-base leading-relaxed my-2\">d) Sai. $\\Delta t=\\dfrac{Q}{m c}=\\dfrac{406800}{57{,}6\\cdot1005}\\approx7{,}0^\\circ$C, không phải $9{,}7^\\circ$C.</p>","difficultySource":"ai"},"ex":[{"exam":121,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Nóng chảy, đông đặc, hoá hơi, ngưng tụ","question":"Quạt hơi nước là thiết bị hoạt động dựa vào hiện tượng bay hơi nước để làm mát không khí. Bơm nước tuần hoàn liên tục qua tấm làm mát. Luồng gió bên ngoài phòng được quạt hút vào máy, đi qua tấm làm mát. Nước trên tấm làm mát sẽ hấp thụ nhiệt của khí nóng làm nước bay hơi và làm giảm nhiệt độ không khí. Giả sử toàn bộ nhiệt lượng lấy từ không khí chỉ để làm bay hơi nước. Biết lưu lượng nước bay hơi từ quạt là 0,15 g/s; Ở nhiệt độ và áp suất phòng khi đó thì nhiệt hóa hơi riêng của nước là 2,26.10<sup>6</sup> J/kg, khối lượng riêng của không khí trong phòng là 1,2 kg/m3 và nhiệt dung riêng đẳng áp của không khí là 1005 J/kg.K. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259602042-hinh-4.jpg\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Khối lượng nước bay hơi trong thời gian 20 phút là 0,18 kg.","answer":true},{"text":"Nhiệt lượng cần thiết lấy từ không khí để làm bay hơi nước ở nhiệt độ và áp suất phòng trong thời gian 20 phút là 4068 J.","answer":false},{"text":"Khối lượng không khí trong phòng đó (kích thước: 4 m x 4 m x 3 m) là 57,6 kg.","answer":true},{"text":"Sau 20 phút mở quạt, không khí mát từ quạt khuếch tán đều trong phòng làm nhiệt độ của phòng giảm đi khoảng 9,7°C.","answer":false}],"explanation":"","difficultySource":"ai"}}]},{"id":453514,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật Faraday và định luật Lenz","question":"Một nhóm học sinh tìm hiểu về mối liên hệ giữa độ lớn của suất điện động cảm ứng và tốc độ biến thiên của từ thông qua một mạch kín. Họ đã thực hiện các nội dung sau: (I) Chuẩn bị các dụng cụ gồm cuộn dây dẫn nối với điện kế G tạo thành mạch kín và có tổng điện trở bằng 1 Ω, nam châm thẳng đặt dọc theo trục của cuộn dây như hình vẽ; (II) Họ cho rằng độ lớn của suất điện động cảm ứng trong mạch kín tỉ lệ thuận với tốc độ biến thiên của từ thông qua mạch kín đó; (III)\tHọ đã làm thí nghiệm cho nam châm và cuộn dây chuyển động tịnh tiến lại gần nhau thì kim của điện kế lệch khỏi vạch số 0 và khi cho tốc độ dịch chuyển tương đối giữa nam châm và cuộn dây càng lớn thì góc lệch của kim điện kế so với vạch số 0 cũng càng lớn; (IV)\tHọ kết luận rằng thí nghiệm này đã chứng minh được nội dung ở (II). <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259602780-hinh-5.jpg\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Nội dung (II) là giả thuyết của nhóm học sinh trong quá trình nghiên cứu.","answer":true},{"text":"Khi cuộn dây và nam châm dịch chuyển lại gần nhau thì dòng điện cảm ứng trong mạch có chiều từ M đến N.","answer":false},{"text":"Nội dung (III) là đủ để đưa ra kết luận (IV).","answer":false},{"text":"Khi dịch chuyển nam châm so với cuộn dây trong nội dung (III), nếu số chỉ của điện kế G là 4 mA thì tốc độ biến thiên của từ thông qua cuộn dây bằng 4.10<sup>−3</sup> Wb/s.","answer":true}],"explanation":"","difficultySource":"ai"},"ex":[{"exam":121,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật Faraday và định luật Lenz","question":"Một nhóm học sinh tìm hiểu về mối liên hệ giữa độ lớn của suất điện động cảm ứng và tốc độ biến thiên của từ thông qua một mạch kín. Họ đã thực hiện các nội dung sau: (I) Chuẩn bị các dụng cụ gồm cuộn dây dẫn nối với điện kế G tạo thành mạch kín và có tổng điện trở bằng 1 Ω, nam châm thẳng đặt dọc theo trục của cuộn dây như hình vẽ; (II) Họ cho rằng độ lớn của suất điện động cảm ứng trong mạch kín tỉ lệ thuận với tốc độ biến thiên của từ thông qua mạch kín đó; (III)\tHọ đã làm thí nghiệm cho nam châm và cuộn dây chuyển động tịnh tiến lại gần nhau thì kim của điện kế lệch khỏi vạch số 0 và khi cho tốc độ dịch chuyển tương đối giữa nam châm và cuộn dây càng lớn thì góc lệch của kim điện kế so với vạch số 0 cũng càng lớn; (IV)\tHọ kết luận rằng thí nghiệm này đã chứng minh được nội dung ở (II). <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259602780-hinh-5.jpg\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Nội dung (II) là giả thuyết của nhóm học sinh trong quá trình nghiên cứu.","answer":true},{"text":"Khi cuộn dây và nam châm dịch chuyển lại gần nhau thì dòng điện cảm ứng trong mạch có chiều từ M đến N.","answer":false},{"text":"Nội dung (III) là đủ để đưa ra kết luận (IV).","answer":false},{"text":"Khi dịch chuyển nam châm so với cuộn dây trong nội dung (III), nếu số chỉ của điện kế G là 4 mA thì tốc độ biến thiên của từ thông qua cuộn dây bằng 4.10<sup>−3</sup> Wb/s.","answer":true}],"explanation":"","difficultySource":"ai"}}]},{"id":455066,"nq":{"form":"bai_tap","type":"true_false","topic":"Tính lực từ F = BIl·sinθ","question":"Một nhóm học sinh tiến hành thí nghiệm đo độ lớn cảm ứng từ B của từ trường đều của nam châm chữ U với bộ thí nghiệm cân lực từ như hình. Chiều dài dây dẫn PQ mang dòng điện đặt trong từ trường đều bằng 15 cm và thu được kết quả sự phụ thuộc của lực từ tác dụng lên đoạn dây theo cường độ dòng điện đi qua dây như đồ thị bên dưới. Biết dây dẫn vuông góc với các đường sức từ của nam châm và cùng nằm trên mặt phẳng nằm ngang. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259958769-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" /> <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259959762-hinh-8.png\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Độ lớn của lực từ tác dụng lên đoạn dây theo kết quả trong thí nghiệm tỉ lệ thuận với cường độ dòng điện qua dây dẫn.","answer":true},{"text":"Khi dòng điện có chiều từ P đến Q thì lực từ tác dụng lên đoạn dây có chiều thẳng đứng hướng lên.","answer":true},{"text":"Đoạn dây dẫn PQ được giữ cố định, khi dòng điện có chiều từ P đến Q thì số chỉ của cân sẽ giảm đi so với khi chưa có dòng điện.","answer":false},{"text":"Từ kết quả của đồ thị, độ lớn trung bình của cảm ứng từ B có thể tính được là 20.10<sup>−3</sup> T.","answer":false}],"explanation":"a) đúng<br>Quan sát đồ thị, ta thấy đường biểu diễn sự phụ thuộc của lực từ F và cường độ dòng điện I là một đường thẳng đi qua gốc tọa độ: F = k.I. Vì vậy, ta có thể kết luận lực từ tác dụng lên đoạn dây tỉ lệ thuận với cường độ dòng điện qua dây dẫn.<br>b) đúng<br>Áp dụng quy tắc bàn tay trái, ta xác định được lực từ tác dụng lên đoạn dây trong trường hợp này hướng lên.<br>c) sai<br>Do lực từ (tức lực do từ trường tác dụng lên đoạn dây mang dòng điện) thẳng đứng hướng lên, áp dụng định luật III Newton, ta xác định lực do đoạn dây tác dụng ngược lại từ trường có chiều thẳng đứng hướng xuống. Lực này tác dụng lên nam châm và khiến cho số chỉ cân tăng lên so với lúc chưa có dòng điện đi qua.<br>d) sai<br>Cảm ứng từ trung bình trong trường hợp này:<br>$\\overline{B}=\\frac{B_1+B_2+B_3+B_4}{4}=\\frac{\\frac{F_1}{I_1.l}+\\frac{F_2}{I_2.l}+\\frac{F_3}{I_3.l}+\\frac{F_4}{I_4.l}}{4}=\\frac{\\frac{{2.10}^{-3}}{1∙0,15}+\\frac{{4.10}^{-3}}{2∙0,15}+\\frac{{6.10}^{-3}}{3∙0,15}+\\frac{{8.10}^{-3}}{4∙0,15}}{4}$<br>$⟹\\overline{B}\\approx {13,3.10}^{-3} T.$","difficultySource":"ai"},"ex":[{"exam":162,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Tính lực từ F = BIl·sinθ","question":"Một nhóm học sinh tiến hành thí nghiệm đo độ lớn cảm ứng từ B của từ trường đều của nam châm chữ U với bộ thí nghiệm cân lực từ như hình. Chiều dài dây dẫn PQ mang dòng điện đặt trong từ trường đều bằng 15 cm và thu được kết quả sự phụ thuộc của lực từ tác dụng lên đoạn dây theo cường độ dòng điện đi qua dây như đồ thị bên dưới. Biết dây dẫn vuông góc với các đường sức từ của nam châm và cùng nằm trên mặt phẳng nằm ngang. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259958769-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" /> <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259959762-hinh-8.png\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Độ lớn của lực từ tác dụng lên đoạn dây theo kết quả trong thí nghiệm tỉ lệ thuận với cường độ dòng điện qua dây dẫn.","answer":true},{"text":"Khi dòng điện có chiều từ P đến Q thì lực từ tác dụng lên đoạn dây có chiều thẳng đứng hướng lên.","answer":true},{"text":"Đoạn dây dẫn PQ được giữ cố định, khi dòng điện có chiều từ P đến Q thì số chỉ của cân sẽ giảm đi so với khi chưa có dòng điện.","answer":false},{"text":"Từ kết quả của đồ thị, độ lớn trung bình của cảm ứng từ B có thể tính được là 20.10<sup>−3</sup> T.","answer":false}],"explanation":"a) đúng<br>Quan sát đồ thị, ta thấy đường biểu diễn sự phụ thuộc của lực từ F và cường độ dòng điện I là một đường thẳng đi qua gốc tọa độ: F = k.I. Vì vậy, ta có thể kết luận lực từ tác dụng lên đoạn dây tỉ lệ thuận với cường độ dòng điện qua dây dẫn.<br>b) đúng<br>Áp dụng quy tắc bàn tay trái, ta xác định được lực từ tác dụng lên đoạn dây trong trường hợp này hướng lên.<br>c) sai<br>Do lực từ (tức lực do từ trường tác dụng lên đoạn dây mang dòng điện) thẳng đứng hướng lên, áp dụng định luật III Newton, ta xác định lực do đoạn dây tác dụng ngược lại từ trường có chiều thẳng đứng hướng xuống. Lực này tác dụng lên nam châm và khiến cho số chỉ cân tăng lên so với lúc chưa có dòng điện đi qua.<br>d) sai<br>Cảm ứng từ trung bình trong trường hợp này:<br>$\\overline{B}=\\frac{B_1+B_2+B_3+B_4}{4}=\\frac{\\frac{F_1}{I_1.l}+\\frac{F_2}{I_2.l}+\\frac{F_3}{I_3.l}+\\frac{F_4}{I_4.l}}{4}=\\frac{\\frac{{2.10}^{-3}}{1∙0,15}+\\frac{{4.10}^{-3}}{2∙0,15}+\\frac{{6.10}^{-3}}{3∙0,15}+\\frac{{8.10}^{-3}}{4∙0,15}}{4}$<br>$⟹\\overline{B}\\approx {13,3.10}^{-3} T.$","difficultySource":"ai"}}]},{"id":455415,"nq":{"form":"bai_tap","type":"true_false","topic":"Nóng chảy, đông đặc, hoá hơi, ngưng tụ","question":"Vào mùa nồm ẩm (cuối đông – đầu xuân ở miền Bắc), độ ẩm không khí rất cao, hơi nước dễ ngưng tụ trên các bề mặt lạnh như nền nhà, tường, bàn ghế, gây ẩm ướt và trơn trượt. Hình vẽ bên dưới mô tả sơ đồ cấu tạo của máy hút ẩm kiểu ngưng tụ. Không khí ẩm được quạt hút vào máy, khi đi qua dàn lạnh thì bị làm lạnh, một phần hơi nước ngưng tụ thành nước lỏng và chảy vào khay hứng. Sau đó, không khí đi qua dàn nóng, được làm nóng trở lại gần bằng nhiệt độ môi trường rồi được thổi ra ngoài. Xét một khối không khí có khối lượng 20 g, trong đó hơi nước chiếm 80% khối lượng khối không khí. Ban đầu, khối không khí có nhiệt độ  $t_1=30^{\\circ}C.$  Khi đi qua dàn lạnh, khối không khí được làm lạnh, nhiệt độ giảm xuống còn  $t_2=10^{\\circ}C$  trong khoảng thời gian 5 s. Công suất hấp thụ nhiệt của dàn lạnh xem như không đổi và bằng 400 W. Cho biết, nhiệt dung riêng của không khí khô là  $c_k=900$  J/(kg.K), nhiệt dung riêng của hơi nước là  $c_{hn}=1860$  J/(kg.K). Trong điều kiện hoạt động của máy, để 1 kg nước chuyển từ thể hơi sang thể lỏng cần trao đổi nhiệt lượng 2,4.10<sup>6</sup> J. Bỏ qua sự trao đổi nhiệt với môi trường xung quanh. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259891616-hinh-5.png\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Khi đi qua dàn lạnh, khối không khí sẽ tỏa nhiệt.","answer":true},{"text":"Trước khi đi qua dàn lạnh, khối lượng không khí khô là 4 g.","answer":true},{"text":"Nhiệt lượng mà không khí khô trao đổi ở dàn lạnh là 160 J.","answer":false},{"text":"Khối lượng hơi nước ngưng tụ ở dàn lạnh xấp xỉ 0,6 g.","answer":true}],"explanation":"a) đúng<br>Khi đi qua dàn lạnh, khối không khí được làm lạnh và một phần hơi nước trong không khí ngưng tụ. Do đó, khối không khí đã tỏa nhiệt ra dàn lạnh.<br>b) đúng<br>Trước khi đi qua dàn lạnh, khối lượng không khí khô là:<br>$m_k=20%m_{kk}=20%.20=4$  g.<br>c) sai<br>Nhiệt lượng mà không khí khô trao đổi ở dàn lạnh là:<br>$Q_k=m_k.c_k.\\left(t_1-t_2\\right)=4.{10}^{-3}.900.\\left(30-10\\right)=72$  J.<br>d) đúng<br>Khối lượng hơi nước ngưng tụ ở dàn lạnh là:<br>$P.\\tau =Q_k+Q_{hn}+Q_{nt}=\\left(m_k.c_k+m_{hn}.c_{hn}\\right).\\left(t_1-t_2\\right)+m_{nt}.L$<br>$m_{nt}=\\frac{P.\\tau -\\left(m_k.c_k+m_{hn}.c_{hn}\\right).\\left(t_1-t_2\\right)}{L}=\\frac{400.5-\\left[4.{10}^{-3}.900+\\left(20-4\\right).{10}^{-3}.1860\\right].\\left(30-10\\right)}{2,4.{10}^6}$   0,6 g.","difficultySource":"ai"},"ex":[{"exam":156,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Nóng chảy, đông đặc, hoá hơi, ngưng tụ","question":"Vào mùa nồm ẩm (cuối đông – đầu xuân ở miền Bắc), độ ẩm không khí rất cao, hơi nước dễ ngưng tụ trên các bề mặt lạnh như nền nhà, tường, bàn ghế, gây ẩm ướt và trơn trượt. Hình vẽ bên dưới mô tả sơ đồ cấu tạo của máy hút ẩm kiểu ngưng tụ. Không khí ẩm được quạt hút vào máy, khi đi qua dàn lạnh thì bị làm lạnh, một phần hơi nước ngưng tụ thành nước lỏng và chảy vào khay hứng. Sau đó, không khí đi qua dàn nóng, được làm nóng trở lại gần bằng nhiệt độ môi trường rồi được thổi ra ngoài. Xét một khối không khí có khối lượng 20 g, trong đó hơi nước chiếm 80% khối lượng khối không khí. Ban đầu, khối không khí có nhiệt độ  $t_1=30^{\\circ}C.$  Khi đi qua dàn lạnh, khối không khí được làm lạnh, nhiệt độ giảm xuống còn  $t_2=10^{\\circ}C$  trong khoảng thời gian 5 s. Công suất hấp thụ nhiệt của dàn lạnh xem như không đổi và bằng 400 W. Cho biết, nhiệt dung riêng của không khí khô là  $c_k=900$  J/(kg.K), nhiệt dung riêng của hơi nước là  $c_{hn}=1860$  J/(kg.K). Trong điều kiện hoạt động của máy, để 1 kg nước chuyển từ thể hơi sang thể lỏng cần trao đổi nhiệt lượng 2,4.10<sup>6</sup> J. Bỏ qua sự trao đổi nhiệt với môi trường xung quanh. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259891616-hinh-5.png\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Khi đi qua dàn lạnh, khối không khí sẽ tỏa nhiệt.","answer":true},{"text":"Trước khi đi qua dàn lạnh, khối lượng không khí khô là 4 g.","answer":true},{"text":"Nhiệt lượng mà không khí khô trao đổi ở dàn lạnh là 160 J.","answer":false},{"text":"Khối lượng hơi nước ngưng tụ ở dàn lạnh xấp xỉ 0,6 g.","answer":true}],"explanation":"a) đúng<br>Khi đi qua dàn lạnh, khối không khí được làm lạnh và một phần hơi nước trong không khí ngưng tụ. Do đó, khối không khí đã tỏa nhiệt ra dàn lạnh.<br>b) đúng<br>Trước khi đi qua dàn lạnh, khối lượng không khí khô là:<br>$m_k=20%m_{kk}=20%.20=4$  g.<br>c) sai<br>Nhiệt lượng mà không khí khô trao đổi ở dàn lạnh là:<br>$Q_k=m_k.c_k.\\left(t_1-t_2\\right)=4.{10}^{-3}.900.\\left(30-10\\right)=72$  J.<br>d) đúng<br>Khối lượng hơi nước ngưng tụ ở dàn lạnh là:<br>$P.\\tau =Q_k+Q_{hn}+Q_{nt}=\\left(m_k.c_k+m_{hn}.c_{hn}\\right).\\left(t_1-t_2\\right)+m_{nt}.L$<br>$m_{nt}=\\frac{P.\\tau -\\left(m_k.c_k+m_{hn}.c_{hn}\\right).\\left(t_1-t_2\\right)}{L}=\\frac{400.5-\\left[4.{10}^{-3}.900+\\left(20-4\\right).{10}^{-3}.1860\\right].\\left(30-10\\right)}{2,4.{10}^6}$   0,6 g.","difficultySource":"ai"}}]},{"id":455470,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":3,"options":["25750 kJ.","3150 kJ.","169500 kJ.","25960 kJ."],"question":"Một bệnh viện cần khử trùng dụng cụ y tế bằng hơi nước. Họ đã sử dụng nồi hơi để làm nóng nước từ nhiệt độ phòng 20°C đến khi nước chuyển hoàn toàn thành hơi ở 100°C. Biết rằng mỗi lần khử trùng, bệnh viện cần đun sôi 10 kg nước. Nhiệt hóa hơi riêng của nước ở 100°C là 2,26.10<sup>6</sup> J/kg và nhiệt dung riêng của nước là 4200 J/kg.K. Nhiệt lượng cần thiết để làm cho 10 kg nước ở 20°C chuyển hoàn toàn thành hơi nước ở 100°C <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260083575-hinh-4.jpg\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"$Q=mc\\Delta t+mL=10.42000.\\left(100−20\\right)+10.2,26.10^6=25960000\\left(J\\right)$","difficultySource":"ai"},"ex":[{"exam":180,"idx":17,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":3,"options":["25750 kJ.","3150 kJ.","169500 kJ.","25960 kJ."],"question":"Một bệnh viện cần khử trùng dụng cụ y tế bằng hơi nước. Họ đã sử dụng nồi hơi để làm nóng nước từ nhiệt độ phòng 20°C đến khi nước chuyển hoàn toàn thành hơi ở 100°C. Biết rằng mỗi lần khử trùng, bệnh viện cần đun sôi 10 kg nước. Nhiệt hóa hơi riêng của nước ở 100°C là 2,26.10<sup>6</sup> J/kg và nhiệt dung riêng của nước là 4200 J/kg.K. Nhiệt lượng cần thiết để làm cho 10 kg nước ở 20°C chuyển hoàn toàn thành hơi nước ở 100°C <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260083575-hinh-4.jpg\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"$Q=mc\\Delta t+mL=10.42000.\\left(100−20\\right)+10.2,26.10^6=25960000\\left(J\\right)$","difficultySource":"ai"}}]},{"id":455471,"nq":{"form":"bai_tap","type":"true_false","topic":"Xử lí số liệu thí nghiệm đo nhiệt","question":"Một học sinh làm thí nghiệm xác định nhiệt nóng chảy riêng của nước đá với bộ dụng cụ gồm: Biến áp nguồn; nhiệt lượng kế có dây nung công suất P = 10 W, cân điện tử, cốc hứng nước có khối lượng 50 g; giá đỡ. Bố trí thí nghiệm như hình bên, tiến hành và quan sát thí nghiệm qua hai giai đoạn liên tiếp: Giai đoạn 1: Cho khối nước đá đang tan vào nhiệt lượng kế, bật nguồn điện để dây nung nóng lên làm nước đá nóng chảy, cốc hứng nước đặt trên cân điện tử hứng nước chảy ra từ nhiệt lượng kế và quan sát số chỉ của cân. Sau một thời gian kể từ khi cấp điện cho dây nung, tại thời điểm t1, thấy số chỉ của cân là 60 g. Giai đoạn 2: Tiếp tục quan sát thì nhận thấy, sau thời gian 15 phút kế tiếp kể từ thời điểm t1, số chỉ của cân tăng đến 87 g. Cho rằng toàn bộ nhiệt lượng tỏa ra từ dây nung đều truyền cho nước đá trong nhiệt lượng kế và toàn bộ nước đá tan ra đều chảy vào cốc, bỏ qua sự trao đổi nhiệt với môi trường. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260083937-hinh-5.jpg\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Quá trình nước đá đang tan là quá trình thu nhiệt.","answer":true},{"text":"Số chỉ của cân là khối lượng của nước chảy xuống từ bình nhiệt lượng kế.","answer":false},{"text":"Ở điều kiện tiêu chuẩn, nước đá tan ở nhiệt độ 0 K.","answer":false},{"text":"Nhiệt nóng chảy riêng của nước đá đo được trong thí nghiệm này là 3,3.10<sup>4</sup> J/kg.","answer":false}],"explanation":"Giai đoạn 1: 60 g gồm 50g khối lượng cốc  $\\Rightarrow \\Delta m_{nc}=10g$ (khối lượng nước bị tan ra)<br>Giai đoạn 2: Trong 15 phút ở giao đoạn 2 → khối lượng nước bị tan  $\\Rightarrow \\Delta m_2=87−60=27\\left(g\\right)$<br>a) đúng<br>Nước đá thu nhiệt để nóng chảy<br>b) sai<br>Số chỉ của cân bao gồm cốc đựng nước nữa.<br>Còn muốn đo khối lượng của nước thôi thì cần hiệu chỉnh cân. Cân điện tử có chức năng hiệu chỉnh. Khi đặt lên cân một cái cốc ấn nút zezo nó sẽ hiệu chỉnh về số 0. Coi như khối lượng của nước là 0 gam và thêm bao nhiêu nước thì thêm bấy nhiêu gam. Đề bài không nói giai đoạn đó. Đề bài nói khối lượng cốc là 50g nên hiểu là nước của mình chảy vào nó sẽ hiện lên số chỉ của cân sẽ bằng tổng khối lượng của nước và khối lượng của cốc<br>c) sai<br>Ở điều kiện tiêu chuẩn, nước đá tan ở nhiệt độ 0°C<br>d) sai<br>Dựa vào giao đoạn 2: 15 phút và  $\\Delta m_2=27g$<br>Ta có:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260084531-hinh-6.png\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"},"ex":[{"exam":180,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Xử lí số liệu thí nghiệm đo nhiệt","question":"Một học sinh làm thí nghiệm xác định nhiệt nóng chảy riêng của nước đá với bộ dụng cụ gồm: Biến áp nguồn; nhiệt lượng kế có dây nung công suất P = 10 W, cân điện tử, cốc hứng nước có khối lượng 50 g; giá đỡ. Bố trí thí nghiệm như hình bên, tiến hành và quan sát thí nghiệm qua hai giai đoạn liên tiếp: Giai đoạn 1: Cho khối nước đá đang tan vào nhiệt lượng kế, bật nguồn điện để dây nung nóng lên làm nước đá nóng chảy, cốc hứng nước đặt trên cân điện tử hứng nước chảy ra từ nhiệt lượng kế và quan sát số chỉ của cân. Sau một thời gian kể từ khi cấp điện cho dây nung, tại thời điểm t1, thấy số chỉ của cân là 60 g. Giai đoạn 2: Tiếp tục quan sát thì nhận thấy, sau thời gian 15 phút kế tiếp kể từ thời điểm t1, số chỉ của cân tăng đến 87 g. Cho rằng toàn bộ nhiệt lượng tỏa ra từ dây nung đều truyền cho nước đá trong nhiệt lượng kế và toàn bộ nước đá tan ra đều chảy vào cốc, bỏ qua sự trao đổi nhiệt với môi trường. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260083937-hinh-5.jpg\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Quá trình nước đá đang tan là quá trình thu nhiệt.","answer":true},{"text":"Số chỉ của cân là khối lượng của nước chảy xuống từ bình nhiệt lượng kế.","answer":false},{"text":"Ở điều kiện tiêu chuẩn, nước đá tan ở nhiệt độ 0 K.","answer":false},{"text":"Nhiệt nóng chảy riêng của nước đá đo được trong thí nghiệm này là 3,3.10<sup>4</sup> J/kg.","answer":false}],"explanation":"Giai đoạn 1: 60 g gồm 50g khối lượng cốc  $\\Rightarrow \\Delta m_{nc}=10g$ (khối lượng nước bị tan ra)<br>Giai đoạn 2: Trong 15 phút ở giao đoạn 2 → khối lượng nước bị tan  $\\Rightarrow \\Delta m_2=87−60=27\\left(g\\right)$<br>a) đúng<br>Nước đá thu nhiệt để nóng chảy<br>b) sai<br>Số chỉ của cân bao gồm cốc đựng nước nữa.<br>Còn muốn đo khối lượng của nước thôi thì cần hiệu chỉnh cân. Cân điện tử có chức năng hiệu chỉnh. Khi đặt lên cân một cái cốc ấn nút zezo nó sẽ hiệu chỉnh về số 0. Coi như khối lượng của nước là 0 gam và thêm bao nhiêu nước thì thêm bấy nhiêu gam. Đề bài không nói giai đoạn đó. Đề bài nói khối lượng cốc là 50g nên hiểu là nước của mình chảy vào nó sẽ hiện lên số chỉ của cân sẽ bằng tổng khối lượng của nước và khối lượng của cốc<br>c) sai<br>Ở điều kiện tiêu chuẩn, nước đá tan ở nhiệt độ 0°C<br>d) sai<br>Dựa vào giao đoạn 2: 15 phút và  $\\Delta m_2=27g$<br>Ta có:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260084531-hinh-6.png\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"}}]},{"id":455500,"nq":{"form":"bai_tap","type":"true_false","topic":"Đọc đồ thị các đẳng quá trình","question":"Một mol khí lí tưởng thực hiện chu trình biến đổi được biểu diễn bằng đồ thị như hình vẽ bên dưới. Biết p1 = 8,31.10<sup>5</sup> Pa; T1 = 300 K; p2 = 13,85.10<sup>5</sup> Pa. - Giai đoạn (1) sang (2): đồ thị là một phần của nhánh Parabol có đỉnh tại gốc tọa độ O (phương trình Parabol này có dạng T = aV2 với a là hằng số tính theo đơn vị K/m6); - Giai đoạn (2) sang (3): Đồ thị là một đoạn thẳng có đường kéo dài vuông góc với trục OV; - Giai đoạn (3) về (1): Đồ thị là một đoạn thẳng kéo dài đi qua gốc tọa độ O. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259843179-hinh-3.png\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Đường 2 – 3 biểu diễn quá trình đẳng nhiệt.","answer":false},{"text":"Đường 3 – 1 biểu diễn quá trình đẳng áp.","answer":true},{"text":"Giá trị của a là 108.","answer":false},{"text":"Nhiệt độ T2 xấp xỉ bằng 833,3 K.","answer":true}],"explanation":"a) S  b) Đ  c) S  d) Đ<br>a) sai<br>Trong hệ tọa độ V – T, đồ thị từ (2) sang (3) là đoạn thẳng có đường kéo dài vuông góc với trục OV nên quá trình này là quá trình đẳng tích.<br>b) đúng<br>Trong hệ tọa độ V – T, đồ thị từ (3) về (1) là đoạn thẳng có đường kéo dài đi qua gốc tọa độ O nên quá trình này là quá trình đẳng áp<br>c) sai<br>Phương trình clapeyron của khối khí tại trạng thái (1):<br>$p_1.V_1=n.R.T_1$<br>$⟹V_1=\\frac{n.R.T_1}{p_1}=\\frac{1∙8,31∙300}{{8,31.10}^5}={3.10}^{-3} m^3=3 lít;$<br>Giá trị của a:<br>$T_1=a.V_1^2⟹a=\\frac{T_1}{V_1^2}=\\frac{300}{{\\left({3.10}^{-3}\\right)}^2}\\approx {33,3.10}^6 K/m^6.$<br>d) đúng<br>Từ trạng thái (1) đến (2):  $\\frac{T}{V^2}=a=hằng số$ . Vì vậy:<br>$\\frac{T_1}{V_1^2}=\\frac{T_2}{V_2^2}⟹V_2=V_1.\\sqrt{\\frac{T_2}{T_1}}={3.10}^{-3}∙\\sqrt{\\frac{T_2}{300}};$<br>Nhiệt độ tại trạng thái (2):<br>$p_2.V_2=n.R.T_2$<br>$⟺{13,85.10}^5∙{3.10}^{-3}∙\\sqrt{\\frac{T_2}{300}}=1∙8,31∙T_2$<br>$⟹T_2\\approx 833,33 K.$","difficultySource":"ai"},"ex":[{"exam":150,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Đọc đồ thị các đẳng quá trình","question":"Một mol khí lí tưởng thực hiện chu trình biến đổi được biểu diễn bằng đồ thị như hình vẽ bên dưới. Biết p1 = 8,31.10<sup>5</sup> Pa; T1 = 300 K; p2 = 13,85.10<sup>5</sup> Pa. - Giai đoạn (1) sang (2): đồ thị là một phần của nhánh Parabol có đỉnh tại gốc tọa độ O (phương trình Parabol này có dạng T = aV2 với a là hằng số tính theo đơn vị K/m6); - Giai đoạn (2) sang (3): Đồ thị là một đoạn thẳng có đường kéo dài vuông góc với trục OV; - Giai đoạn (3) về (1): Đồ thị là một đoạn thẳng kéo dài đi qua gốc tọa độ O. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259843179-hinh-3.png\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Đường 2 – 3 biểu diễn quá trình đẳng nhiệt.","answer":false},{"text":"Đường 3 – 1 biểu diễn quá trình đẳng áp.","answer":true},{"text":"Giá trị của a là 108.","answer":false},{"text":"Nhiệt độ T2 xấp xỉ bằng 833,3 K.","answer":true}],"explanation":"a) S  b) Đ  c) S  d) Đ<br>a) sai<br>Trong hệ tọa độ V – T, đồ thị từ (2) sang (3) là đoạn thẳng có đường kéo dài vuông góc với trục OV nên quá trình này là quá trình đẳng tích.<br>b) đúng<br>Trong hệ tọa độ V – T, đồ thị từ (3) về (1) là đoạn thẳng có đường kéo dài đi qua gốc tọa độ O nên quá trình này là quá trình đẳng áp<br>c) sai<br>Phương trình clapeyron của khối khí tại trạng thái (1):<br>$p_1.V_1=n.R.T_1$<br>$⟹V_1=\\frac{n.R.T_1}{p_1}=\\frac{1∙8,31∙300}{{8,31.10}^5}={3.10}^{-3} m^3=3 lít;$<br>Giá trị của a:<br>$T_1=a.V_1^2⟹a=\\frac{T_1}{V_1^2}=\\frac{300}{{\\left({3.10}^{-3}\\right)}^2}\\approx {33,3.10}^6 K/m^6.$<br>d) đúng<br>Từ trạng thái (1) đến (2):  $\\frac{T}{V^2}=a=hằng số$ . Vì vậy:<br>$\\frac{T_1}{V_1^2}=\\frac{T_2}{V_2^2}⟹V_2=V_1.\\sqrt{\\frac{T_2}{T_1}}={3.10}^{-3}∙\\sqrt{\\frac{T_2}{300}};$<br>Nhiệt độ tại trạng thái (2):<br>$p_2.V_2=n.R.T_2$<br>$⟺{13,85.10}^5∙{3.10}^{-3}∙\\sqrt{\\frac{T_2}{300}}=1∙8,31∙T_2$<br>$⟹T_2\\approx 833,33 K.$","difficultySource":"ai"}}]},{"id":455552,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Xử lí số liệu thí nghiệm đo nhiệt","answer":2,"options":["0,756 kg.","1,260 kg.","0,504 kg.","6,044 kg."],"question":"Một chậu có chứa M = 6,8 kg hỗn hợp nước và nước đá ở trong phòng. Sự thay đổi của nhiệt độ của hỗn hợp theo thời gian được biểu diễn bằng đồ thị hình bên. Lấy gần đúng nhiệt dung riêng của nước là 4200 J/(kgK); nhiệt nóng chảy riêng của nước đá là 3,4.10<sup>5</sup> J/kg. Cho rằng sự hấp thụ nhiệt từ môi trường là đều. Khối lượng nước đá còn lại ở thời điểm phút 30 bằng bao nhiêu? <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259997810-hinh-3.png\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"Chọn đáp án C<br>Khối lượng nước đá còn lại ở thời điểm phút 30 bằng khối lượng nước đá tan trong thời gian  $t_1=50−30=20$  phút<br>$\\left\\{\\begin{aligned}Pt_1=m_d\\lambda <br>Pt_2=Mc\\Delta t\\end{aligned}\\right.\\Rightarrow \\frac{t_1}{t_2}=\\frac{m_d\\lambda }{Mc\\Delta t}\\Rightarrow \\frac{20}{60−50}=\\frac{m_d.3,4.10^5}{6,8.4200.3}\\Rightarrow m_d=0,504kg$","difficultySource":"ai"},"ex":[{"exam":168,"idx":15,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Xử lí số liệu thí nghiệm đo nhiệt","answer":2,"options":["0,756 kg.","1,260 kg.","0,504 kg.","6,044 kg."],"question":"Một chậu có chứa M = 6,8 kg hỗn hợp nước và nước đá ở trong phòng. Sự thay đổi của nhiệt độ của hỗn hợp theo thời gian được biểu diễn bằng đồ thị hình bên. Lấy gần đúng nhiệt dung riêng của nước là 4200 J/(kgK); nhiệt nóng chảy riêng của nước đá là 3,4.10<sup>5</sup> J/kg. Cho rằng sự hấp thụ nhiệt từ môi trường là đều. Khối lượng nước đá còn lại ở thời điểm phút 30 bằng bao nhiêu? <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259997810-hinh-3.png\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"Chọn đáp án C<br>Khối lượng nước đá còn lại ở thời điểm phút 30 bằng khối lượng nước đá tan trong thời gian  $t_1=50−30=20$  phút<br>$\\left\\{\\begin{aligned}Pt_1=m_d\\lambda <br>Pt_2=Mc\\Delta t\\end{aligned}\\right.\\Rightarrow \\frac{t_1}{t_2}=\\frac{m_d\\lambda }{Mc\\Delta t}\\Rightarrow \\frac{20}{60−50}=\\frac{m_d.3,4.10^5}{6,8.4200.3}\\Rightarrow m_d=0,504kg$","difficultySource":"ai"}}]},{"id":455557,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt độ và cân bằng nhiệt","question":"Vào mùa hè để giải khát người ta thường uống nước mát, đề có một ly nước mát người ta làm như sau: Lấy một ly thuỷ tinh chứa 150 g nước ở nhiệt độ 3°C sau đó cho nước đá vào trong ly nước như hình bên. Biết mỗi viên nước đá trước khi bỏ vào ly nước có khối lượng 8 g, ở nhiệt độ −2,5°C. Nhiệt dung riêng của nước là 4200 J/(kgK) của nước đá là 1800 J/(kgK), nhiệt nóng chảy riêng của nước đá là 3,3.10<sup>5</sup> J/kg. Bỏ qua sự trao đổi nhiệt với ly và môi trường. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259999191-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Các viên đá nổi lên trong ly nước chứng tỏ nước ở thể rắn có khối lượng riêng nhỏ hơn nước ở thể lỏng.","answer":true},{"text":"Khi sờ vào ly nước đá ta thấy có nước bám vào thành ly. Đây là do hơi nước trong không khí gặp lạnh rồi ngưng tụ bám vào thành ngoài của ly.","answer":true},{"text":"Để mỗi viên nước đá tan chảy hoàn toàn cần cung cấp cho nó một nhiệt lượng 2676 J","answer":true},{"text":"Một người pha một ly nước mát để uống, người này thêm vào ly nước trên 5 viên nước đá để làm lạnh. Nhiệt độ cuối cùng của ly nước sau khi đá tan hết là 6,92°C (làm tròn kết quả đến chữ số hàng phần trăm).","answer":true}],"explanation":"a) đúng<br>$F_A=D_nV_g>P=mg=D_dV_g$<br>b) đúng<br>Khi sờ vào ly nước đá ta thấy có nước bám vào thành ly. Đây là do hơi nước trong không khí gặp lạnh rồi ngưng tụ bám vào thành ngoài của ly.<br>c) đúng<br>$Q=m_d\\left(c_d\\Delta t+\\lambda \\right)=8.10^{−3}.\\left(1800.2,5+3,3.10^5\\right)=2676J$<br>d) đúng<br>$5Q+5m_dc_nt=m_nc_n\\left(t_n−t\\right)\\Rightarrow 5.2676+5.8.10^{−3}.4200.t=0,15.4200.\\left(30−t\\right)\\Rightarrow t\\approx 6,92^0C$","difficultySource":"ai"},"ex":[{"exam":168,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt độ và cân bằng nhiệt","question":"Vào mùa hè để giải khát người ta thường uống nước mát, đề có một ly nước mát người ta làm như sau: Lấy một ly thuỷ tinh chứa 150 g nước ở nhiệt độ 3°C sau đó cho nước đá vào trong ly nước như hình bên. Biết mỗi viên nước đá trước khi bỏ vào ly nước có khối lượng 8 g, ở nhiệt độ −2,5°C. Nhiệt dung riêng của nước là 4200 J/(kgK) của nước đá là 1800 J/(kgK), nhiệt nóng chảy riêng của nước đá là 3,3.10<sup>5</sup> J/kg. Bỏ qua sự trao đổi nhiệt với ly và môi trường. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259999191-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Các viên đá nổi lên trong ly nước chứng tỏ nước ở thể rắn có khối lượng riêng nhỏ hơn nước ở thể lỏng.","answer":true},{"text":"Khi sờ vào ly nước đá ta thấy có nước bám vào thành ly. Đây là do hơi nước trong không khí gặp lạnh rồi ngưng tụ bám vào thành ngoài của ly.","answer":true},{"text":"Để mỗi viên nước đá tan chảy hoàn toàn cần cung cấp cho nó một nhiệt lượng 2676 J","answer":true},{"text":"Một người pha một ly nước mát để uống, người này thêm vào ly nước trên 5 viên nước đá để làm lạnh. Nhiệt độ cuối cùng của ly nước sau khi đá tan hết là 6,92°C (làm tròn kết quả đến chữ số hàng phần trăm).","answer":true}],"explanation":"a) đúng<br>$F_A=D_nV_g>P=mg=D_dV_g$<br>b) đúng<br>Khi sờ vào ly nước đá ta thấy có nước bám vào thành ly. Đây là do hơi nước trong không khí gặp lạnh rồi ngưng tụ bám vào thành ngoài của ly.<br>c) đúng<br>$Q=m_d\\left(c_d\\Delta t+\\lambda \\right)=8.10^{−3}.\\left(1800.2,5+3,3.10^5\\right)=2676J$<br>d) đúng<br>$5Q+5m_dc_nt=m_nc_n\\left(t_n−t\\right)\\Rightarrow 5.2676+5.8.10^{−3}.4200.t=0,15.4200.\\left(30−t\\right)\\Rightarrow t\\approx 6,92^0C$","difficultySource":"ai"}}]},{"id":455558,"nq":{"form":"bai_tap","type":"true_false","topic":"Xử lí số liệu thí nghiệm đo nhiệt","question":"Để xác định nhiệt nóng chảy riêng của nước đá, nhóm học sinh tiến hành thí nghiệm theo sơ đồ nguyên lí như hình bên.  Dòng điện làm nóng dây nung trong một nhiệt lượng kế và làm nước đá nóng chảy. Lượng nước thu được sau khi toàn bộ nước đá nóng chảy được đem đi cân thì thấy nó có khối lượng 20 g. Công suất điện tiêu thụ được xác định bằng oát kế là 44 W. Thời gian đun được xác định bằng đồng hồ là 2,5 phút. Bỏ qua sự trao đồi nhiệt với môi trường xung quanh, bỏ qua nhiệt dung của bình nhiệt lượng kế, bỏ qua toả nhiệt trên các dây dẫn. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259999730-hinh-8.jpg\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Ở áp suất tiêu chuẩn, nước đá tinh khiết nóng chảy ở nhiệt độ 0°C.","answer":true},{"text":"Trong quá trình nóng chảy của nước đá, nhiệt độ của nước đá không đồi.","answer":true},{"text":"Nhiệt lượng nước đá nhận được từ dây nung trong thời gian đun là 110 J.","answer":false},{"text":"Nhiệt nóng chảy riêng của nước đá đo được là 3,3.10<sup>5</sup> J/kg.","answer":true}],"explanation":"a) đúng<br>Ở áp suất tiêu chuẩn, nước đá tinh khiết nóng chảy ở nhiệt độ 0°C.<br>b) đúng<br>Trong quá trình nóng chảy của nước đá, nhiệt độ của nước đá không đồi.<br>c) sai<br>$Q=Pt=44.2,5.60=6600J$<br>d) đúng<br>$\\lambda =\\frac{Q}{m}=\\frac{6600}{20.10^{−3}}=3,3.10^5\\left(J/kg\\right)$","difficultySource":"ai"},"ex":[{"exam":168,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Xử lí số liệu thí nghiệm đo nhiệt","question":"Để xác định nhiệt nóng chảy riêng của nước đá, nhóm học sinh tiến hành thí nghiệm theo sơ đồ nguyên lí như hình bên.  Dòng điện làm nóng dây nung trong một nhiệt lượng kế và làm nước đá nóng chảy. Lượng nước thu được sau khi toàn bộ nước đá nóng chảy được đem đi cân thì thấy nó có khối lượng 20 g. Công suất điện tiêu thụ được xác định bằng oát kế là 44 W. Thời gian đun được xác định bằng đồng hồ là 2,5 phút. Bỏ qua sự trao đồi nhiệt với môi trường xung quanh, bỏ qua nhiệt dung của bình nhiệt lượng kế, bỏ qua toả nhiệt trên các dây dẫn. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259999730-hinh-8.jpg\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Ở áp suất tiêu chuẩn, nước đá tinh khiết nóng chảy ở nhiệt độ 0°C.","answer":true},{"text":"Trong quá trình nóng chảy của nước đá, nhiệt độ của nước đá không đồi.","answer":true},{"text":"Nhiệt lượng nước đá nhận được từ dây nung trong thời gian đun là 110 J.","answer":false},{"text":"Nhiệt nóng chảy riêng của nước đá đo được là 3,3.10<sup>5</sup> J/kg.","answer":true}],"explanation":"a) đúng<br>Ở áp suất tiêu chuẩn, nước đá tinh khiết nóng chảy ở nhiệt độ 0°C.<br>b) đúng<br>Trong quá trình nóng chảy của nước đá, nhiệt độ của nước đá không đồi.<br>c) sai<br>$Q=Pt=44.2,5.60=6600J$<br>d) đúng<br>$\\lambda =\\frac{Q}{m}=\\frac{6600}{20.10^{−3}}=3,3.10^5\\left(J/kg\\right)$","difficultySource":"ai"}}]},{"id":455608,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Vào những ngày hè nóng bức, các gia đình thường sử dụng loại quạt điều hòa để làm mát không khí. Khi quạt vận hành, không khí nóng từ môi trường xung quanh sẽ được hút vào bên trong quạt, đi qua các tấm làm mát (cooling pad). Nước được bơm liên tục từ khoang chứa nước lên tấm làm mát. Tấm làm mát này được thiết kế với rất nhiều đường ống dẫn với mặt cắt như tổ ong có thể dẫn và thấm đẫm nước. Khi không khí nóng bên ngoài luồn qua tấm làm mát đã có nước sẽ tạo ra hiện tượng bay hơi nước tự nhiên ở trong các ống dẫn. Khi nước bay hơi, nhiệt lượng được lấy từ không khí xung quanh, làm giảm nhiệt độ không khí. Giả sử toàn bộ nhiệt lượng lấy từ không khí để làm nước bay hơi. Biết lưu lượng nước bay hơi từ quạt là 0,7 g/s; nhiệt hóa hơi của nước ở 35°C là 2,26.10<sup>6</sup> J/kg; khối lượng riêng không khí trong phòng là 1,2 kg/m3 và nhiệt dung riêng của không khí là 1005 J/kgK. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259754587-hinh-2.jpg\" alt=\"Hình 2\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Quạt điều hòa làm mát không khí bằng cách thu nhiệt của không khí xung quanh để làm nước bay hơi.","answer":true},{"text":"Tốc độ bay hơi của nước trong quạt điều hòa không phụ thuộc vào nhiệt độ không khí xung quanh.","answer":false},{"text":"Nhiệt lượng cần thiết lấy từ không khí xung quanh để làm bay hơi 0,42kg nước ở 35°C là 949,2kJ.","answer":true},{"text":"Trong một căn phòng kín kích thước 4m x 5m x 4m, nhiệt độ không khí trong phòng ở 35°C . Sau 10 phút mở quạt, nhiệt độ phòng giảm đi khoảng 8,9°C","answer":true}],"explanation":"a) đúng<br>Khí nóng đi vào → Đi qua tấm làm mát → Thu khí nóng → Cho khí lạnh<br>Khí nóng (toả nhiệt); khí lạnh (thu nhiệt)<br>Nước thu nhiệt của không khí để làm bay hơi nước; và không khí toả nhiệt ra. Từ nóng thành lạnh<br>b) sai<br>Tốc độ bay hơi của nước có phụ thuộc vào nhiệt độ không khí ở xung quanh. Nếu như nhiệt độ càng lớn thì tốc độ bay hơi càng nhanh.<br>c) đúng<br>$Q=m\\lambda =0,42.2,26.10^6=949,2\\left(kJ\\right)$<br>d) đúng<br>$V=4.5.4=80m^3\\Rightarrow m=D.V=1,2.80=96kg$<br>Sau 10 phút (600s)  $\\Rightarrow 600\\left(s\\right).0,9\\left(g/s\\right)=420g=0,42kg$<br>$Q=mc\\Delta t\\Rightarrow Q=96.1005.\\Delta t$<br>$\\Rightarrow 949,2=96.1005.\\Delta t$<br>$\\Rightarrow \\Delta t=9,838^0C$","difficultySource":"ai"},"ex":[{"exam":141,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Vào những ngày hè nóng bức, các gia đình thường sử dụng loại quạt điều hòa để làm mát không khí. Khi quạt vận hành, không khí nóng từ môi trường xung quanh sẽ được hút vào bên trong quạt, đi qua các tấm làm mát (cooling pad). Nước được bơm liên tục từ khoang chứa nước lên tấm làm mát. Tấm làm mát này được thiết kế với rất nhiều đường ống dẫn với mặt cắt như tổ ong có thể dẫn và thấm đẫm nước. Khi không khí nóng bên ngoài luồn qua tấm làm mát đã có nước sẽ tạo ra hiện tượng bay hơi nước tự nhiên ở trong các ống dẫn. Khi nước bay hơi, nhiệt lượng được lấy từ không khí xung quanh, làm giảm nhiệt độ không khí. Giả sử toàn bộ nhiệt lượng lấy từ không khí để làm nước bay hơi. Biết lưu lượng nước bay hơi từ quạt là 0,7 g/s; nhiệt hóa hơi của nước ở 35°C là 2,26.10<sup>6</sup> J/kg; khối lượng riêng không khí trong phòng là 1,2 kg/m3 và nhiệt dung riêng của không khí là 1005 J/kgK. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259754587-hinh-2.jpg\" alt=\"Hình 2\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Quạt điều hòa làm mát không khí bằng cách thu nhiệt của không khí xung quanh để làm nước bay hơi.","answer":true},{"text":"Tốc độ bay hơi của nước trong quạt điều hòa không phụ thuộc vào nhiệt độ không khí xung quanh.","answer":false},{"text":"Nhiệt lượng cần thiết lấy từ không khí xung quanh để làm bay hơi 0,42kg nước ở 35°C là 949,2kJ.","answer":true},{"text":"Trong một căn phòng kín kích thước 4m x 5m x 4m, nhiệt độ không khí trong phòng ở 35°C . Sau 10 phút mở quạt, nhiệt độ phòng giảm đi khoảng 8,9°C","answer":true}],"explanation":"a) đúng<br>Khí nóng đi vào → Đi qua tấm làm mát → Thu khí nóng → Cho khí lạnh<br>Khí nóng (toả nhiệt); khí lạnh (thu nhiệt)<br>Nước thu nhiệt của không khí để làm bay hơi nước; và không khí toả nhiệt ra. Từ nóng thành lạnh<br>b) sai<br>Tốc độ bay hơi của nước có phụ thuộc vào nhiệt độ không khí ở xung quanh. Nếu như nhiệt độ càng lớn thì tốc độ bay hơi càng nhanh.<br>c) đúng<br>$Q=m\\lambda =0,42.2,26.10^6=949,2\\left(kJ\\right)$<br>d) đúng<br>$V=4.5.4=80m^3\\Rightarrow m=D.V=1,2.80=96kg$<br>Sau 10 phút (600s)  $\\Rightarrow 600\\left(s\\right).0,9\\left(g/s\\right)=420g=0,42kg$<br>$Q=mc\\Delta t\\Rightarrow Q=96.1005.\\Delta t$<br>$\\Rightarrow 949,2=96.1005.\\Delta t$<br>$\\Rightarrow \\Delta t=9,838^0C$","difficultySource":"ai"}}]},{"id":455951,"nq":{"form":"bai_tap","type":"true_false","topic":"Vận dụng phương trình trạng thái","question":"Một chiếc khinh khí cầu gồm khoang chứa hàng nặng 300 kg và phần khí cầu hình cầu chứa thể tích V = 3000 m3 không khí. Trên khí cầu có một lỗ thông hơi và không khí ở trong khí cầu được làm nóng bằng một ngọn lửa (hình vẽ). Coi thể tích phần vỏ khí cầu luôn không đổi và không khí lí tưởng có khối lượng mol là M = 29g/mol. Để khinh khí cầu bay lên, người ta làm không khí bên trong khinh khí cầu nóng lên, một phần khí thoát ra ngoài qua lỗ thông hơi, khi đó khí cầu nhẹ hơn. Biết ở mặt đất, áp suất và khối lượng riêng của không khí lần lượt là p0 = 1,013.10<sup>5</sup> Pa và D0 =1,23kg/m3. Lấy g = 9,8 $m/s^2$ . Bỏ qua khối lượng vỏ khí cầu và thể tích của khoang hàng. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259774070-hinh-17.jpg\" alt=\"Hình 17\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Áp suất của khí bên trong khí cầu do bị đốt nóng nên luôn cao hơn áp suất khí quyển.","answer":false},{"text":"Trong quá trình được đốt nóng, khối lượng riêng của khí luôn tỉ lệ nghịch với nhiệt độ tuyệt đối.","answer":false},{"text":"Ở sát mặt đất, khi chưa được đốt nóng, nhiệt độ của khí trong khinh khí cầu gần đúng bằng 287,4 K","answer":false},{"text":"Để khinh khí cầu nhấc khỏi mặt đất thì nhiệt độ của khí trong khí cầu phải tăng thêm một lượng tối thiểu là 45,4 K.","answer":false}],"explanation":"a) S  b) S  c) S  d) S<br>a) sai<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259774501-hinh-18.png\" alt=\"Hình 18\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Khí cấu có 1 cái lỗ. Đo áp suất tại điểm A và B. Bên trên có p0.<br>Hai áp suất tai điểm A và B đều nằm trong không khí → nên áp suất tại B bằng áp suất tại A. Tức là áp suất trong khí cầu cũng phải là  $p_0$<br>$\\Rightarrow$  Áp suất của khí bên trong khí cầu do bị đốt nóng nên luôn bằng nhau áp suất khí quyển.<br>b) đúng<br>$pV=nRTV=\\frac{m}{D}\\rightarrow p.\\frac{m}{D}=\\frac{m}{M}.RT\\Rightarrow D=\\frac{p.M}{R.T}\\Rightarrow D\\sim \\frac{1}{T}$<br>$\\Rightarrow D↓\\sim \\frac{1}{T↑}$<br>c) đúng<br>$D=\\frac{pM}{RT}\\Rightarrow 1,23=\\frac{1,013.10^5.29.10^{−3}}{8,31.T_0}\\Rightarrow T_0\\approx 287,41K$<br>d) sai<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259774904-hinh-19.png\" alt=\"Hình 19\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>$\\Delta =t_{sau}−t_{truoc}$<br>$F_A=P\\Rightarrow D_{khong khi}.V_{khong khi}.g=m_{hang}.g+m_{khi nong}.g$<br>$m=D.V;D=\\frac{pM}{kT}\\rightarrow 1,23.300.9,8=300.9,8+D_{khi nong}.3000.9,8$<br>$\\Rightarrow 1,23.3000=\\frac{300.1,013.10^5.29.10^{−3}}{8,31.T_{nong}}$<br>$\\Rightarrow T_{nong}\\approx 312,84K$<br>$\\Rightarrow \\Delta T=T_{nong}−T_0=312,84−287,41=25,44\\left(K\\right)$","difficultySource":"ai"},"ex":[{"exam":143,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Vận dụng phương trình trạng thái","question":"Một chiếc khinh khí cầu gồm khoang chứa hàng nặng 300 kg và phần khí cầu hình cầu chứa thể tích V = 3000 m3 không khí. Trên khí cầu có một lỗ thông hơi và không khí ở trong khí cầu được làm nóng bằng một ngọn lửa (hình vẽ). Coi thể tích phần vỏ khí cầu luôn không đổi và không khí lí tưởng có khối lượng mol là M = 29g/mol. Để khinh khí cầu bay lên, người ta làm không khí bên trong khinh khí cầu nóng lên, một phần khí thoát ra ngoài qua lỗ thông hơi, khi đó khí cầu nhẹ hơn. Biết ở mặt đất, áp suất và khối lượng riêng của không khí lần lượt là p0 = 1,013.10<sup>5</sup> Pa và D0 =1,23kg/m3. Lấy g = 9,8 m/s2 . Bỏ qua khối lượng vỏ khí cầu và thể tích của khoang hàng. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259774070-hinh-17.jpg\" alt=\"Hình 17\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Áp suất của khí bên trong khí cầu do bị đốt nóng nên luôn cao hơn áp suất khí quyển.","answer":false},{"text":"Trong quá trình được đốt nóng, khối lượng riêng của khí luôn tỉ lệ nghịch với nhiệt độ tuyệt đối.","answer":false},{"text":"Ở sát mặt đất, khi chưa được đốt nóng, nhiệt độ của khí trong khinh khí cầu gần đúng bằng 287,4 K","answer":false},{"text":"Để khinh khí cầu nhấc khỏi mặt đất thì nhiệt độ của khí trong khí cầu phải tăng thêm một lượng tối thiểu là 45,4 K.","answer":false}],"explanation":"a) S  b) S  c) S  d) S<br>a) sai<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259774501-hinh-18.png\" alt=\"Hình 18\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Khí cấu có 1 cái lỗ. Đo áp suất tại điểm A và B. Bên trên có p0.<br>Hai áp suất tai điểm A và B đều nằm trong không khí → nên áp suất tại B bằng áp suất tại A. Tức là áp suất trong khí cầu cũng phải là  $p_0$<br>$\\Rightarrow$  Áp suất của khí bên trong khí cầu do bị đốt nóng nên luôn bằng nhau áp suất khí quyển.<br>b) đúng<br>$pV=nRTV=\\frac{m}{D}\\rightarrow p.\\frac{m}{D}=\\frac{m}{M}.RT\\Rightarrow D=\\frac{p.M}{R.T}\\Rightarrow D\\sim \\frac{1}{T}$<br>$\\Rightarrow D↓\\sim \\frac{1}{T↑}$<br>c) đúng<br>$D=\\frac{pM}{RT}\\Rightarrow 1,23=\\frac{1,013.10^5.29.10^{−3}}{8,31.T_0}\\Rightarrow T_0\\approx 287,41K$<br>d) sai<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259774904-hinh-19.png\" alt=\"Hình 19\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>$\\Delta =t_{sau}−t_{truoc}$<br>$F_A=P\\Rightarrow D_{khong khi}.V_{khong khi}.g=m_{hang}.g+m_{khi nong}.g$<br>$m=D.V;D=\\frac{pM}{kT}\\rightarrow 1,23.300.9,8=300.9,8+D_{khi nong}.3000.9,8$<br>$\\Rightarrow 1,23.3000=\\frac{300.1,013.10^5.29.10^{−3}}{8,31.T_{nong}}$<br>$\\Rightarrow T_{nong}\\approx 312,84K$<br>$\\Rightarrow \\Delta T=T_{nong}−T_0=312,84−287,41=25,44\\left(K\\right)$","difficultySource":"ai"}}]},{"id":456460,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Liên hệ áp suất với động năng phân tử","answer":0,"options":["9,66.10<sup>9</sup> phân tử.","9,66.10<sup>15</sup> phân tử.","1,07.10<sup>17</sup> phân tử.","1,07.10<sup>11</sup> phân tử."],"question":"Trong một buồng chân không dùng để bảo quản linh kiện điện tử, người ta đo được áp suất của lượng khí còn sót lại là 4.10<sup>5</sup> Pa ở nhiệt độ 27 °C. Biết hằng số Boltzmann là k = 1,38.1023 J/K. Số phân tử khí trung bình có trong mỗi cm3 của buồng chân không này xấp xỉ bằng <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260239424-hinh-3.png\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Chọn đáp án A<br>Ta có:  $p=\\frac{1}{3}\\mu m\\overline{v^2}$  và  $\\overline{E_đ}=\\frac{1}{2}m\\overline{v^2}=\\frac{3}{2}Kt$<br>Suy ra:  $p=\\mu kT$    $\\mu =\\frac{p}{kT}=\\frac{4.{10}^{-5}}{1,38.{10}^{-23}.\\left(27+273\\right)}\\approx 9,66.{10}^{15}$  phân tử/m3  9,66.10<sup>9</sup> phân tử/cm3.","difficultySource":"ai"},"ex":[{"exam":200,"idx":7,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Liên hệ áp suất với động năng phân tử","answer":0,"options":["9,66.10<sup>9</sup> phân tử.","9,66.10<sup>15</sup> phân tử.","1,07.10<sup>17</sup> phân tử.","1,07.10<sup>11</sup> phân tử."],"question":"Trong một buồng chân không dùng để bảo quản linh kiện điện tử, người ta đo được áp suất của lượng khí còn sót lại là 4.10<sup>5</sup> Pa ở nhiệt độ 27 °C. Biết hằng số Boltzmann là k = 1,38.1023 J/K. Số phân tử khí trung bình có trong mỗi cm3 của buồng chân không này xấp xỉ bằng <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260239424-hinh-3.png\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Chọn đáp án A<br>Ta có:  $p=\\frac{1}{3}\\mu m\\overline{v^2}$  và  $\\overline{E_đ}=\\frac{1}{2}m\\overline{v^2}=\\frac{3}{2}Kt$<br>Suy ra:  $p=\\mu kT$    $\\mu =\\frac{p}{kT}=\\frac{4.{10}^{-5}}{1,38.{10}^{-23}.\\left(27+273\\right)}\\approx 9,66.{10}^{15}$  phân tử/m3  9,66.10<sup>9</sup> phân tử/cm3.","difficultySource":"ai"}}]},{"id":456480,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","answer":"1946","question":"Một nhà máy điện hạt nhân sử dụng nhiên liệu là đồng vị phóng xạ 235U. Biết rằng mỗi phản ứng phân hạch của một hạt nhân 235U tỏa ra năng lượng 200 MeV. Hiệu suất chuyển hóa năng lượng hạt nhân thành điện năng của nhà máy là 36%. Công suất phát điện của nhà máy là 1400 MW. Khối lượng 235U mà nhà máy tiêu thụ trong 1 năm (coi nhà máy hoạt động liên tục với công suất không đổi) bằng bao nhiêu kilogam (kg)? (Làm tròn kết quả đến chữ số hàng đơn vị) Lấy 1 năm = 365 ngày; 1 MeV = 1,6.10<sup>13</sup> J. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260242546-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"Đáp số 1946<br>Điện năng do nhà máy tạo ra trong 1 năm là:  $A=P.\\tau =36%.Q$    $Q=\\frac{P.\\tau }{0,36}$<br>Số phản ứng phân hạch hạt nhân 235U trong 1 năm:  $N=\\frac{Q}{E}=\\frac{P.\\tau }{0,36.E}$<br>Khối lượng 235U mà nhà máy đã tiêu thụ trong 1 năm:<br>$m=n.M=\\frac{N}{N_A}.M=\\frac{P.\\tau .M}{0,36.E.N_A}=\\frac{1400.{10}^6.365.24.3600.235}{0,36.200.1,6.{10}^{-13}.6,02.{10}^{23}}\\approx 1496$  kg.","difficultySource":"ai"},"ex":[{"exam":200,"idx":27,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","answer":"1946","question":"Một nhà máy điện hạt nhân sử dụng nhiên liệu là đồng vị phóng xạ 235U. Biết rằng mỗi phản ứng phân hạch của một hạt nhân 235U tỏa ra năng lượng 200 MeV. Hiệu suất chuyển hóa năng lượng hạt nhân thành điện năng của nhà máy là 36%. Công suất phát điện của nhà máy là 1400 MW. Khối lượng 235U mà nhà máy tiêu thụ trong 1 năm (coi nhà máy hoạt động liên tục với công suất không đổi) bằng bao nhiêu kilogam (kg)? (Làm tròn kết quả đến chữ số hàng đơn vị) Lấy 1 năm = 365 ngày; 1 MeV = 1,6.10<sup>13</sup> J. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260242546-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"Đáp số 1946<br>Điện năng do nhà máy tạo ra trong 1 năm là:  $A=P.\\tau =36%.Q$    $Q=\\frac{P.\\tau }{0,36}$<br>Số phản ứng phân hạch hạt nhân 235U trong 1 năm:  $N=\\frac{Q}{E}=\\frac{P.\\tau }{0,36.E}$<br>Khối lượng 235U mà nhà máy đã tiêu thụ trong 1 năm:<br>$m=n.M=\\frac{N}{N_A}.M=\\frac{P.\\tau .M}{0,36.E.N_A}=\\frac{1400.{10}^6.365.24.3600.235}{0,36.200.1,6.{10}^{-13}.6,02.{10}^{23}}\\approx 1496$  kg.","difficultySource":"ai"}}]},{"id":456502,"nq":{"form":"bai_tap","type":"true_false","topic":"Quá trình đẳng nhiệt và định luật Boyle","question":"Hình vẽ bên mô tả sơ đồ một chiếc ghế nâng hạ bằng khí thông qua chuyển động lên xuống của xi lanh nối với mặt ghế. Thanh nén khí cố định trên đế bịt kín một lượng khí lí tưởng trong xi lanh. Bỏ qua ma sát giữa thanh nén và xi lanh. Tổng khối lượng của mặt ghế và xi lanh là 6 kg , tiết diện của thanh nén là 30 cm2. Một học sinh nặng 54 kg ngồi lên ghế (hai chân để lơ lửng không chạm mặt sàn) thì ghế hạ xuống 12 cm khi ổn định. Coi nhiệt độ của khí trong xi lanh không đổi, áp suất khí quyển là 105 Pa và lấy g = 10 $m/s^2$. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259655411-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Khi ghế để trống, áp suất của khí trong xi lanh bằng áp suất khí quyển.","answer":false},{"text":"Khi ghế để trống, cột khí trong xi lanh dài 20 cm.","answer":true},{"text":"Khi học sinh ngồi trên ghế, áp suất của khí trong xi lanh là 2.10<sup>5</sup> Pa.","answer":false},{"text":"Quá trình ghế hạ xuống, khí trong xi lanh sinh công.","answer":false}],"explanation":"a) sai<br>$p_k=p_{KQ}+\\frac{6.10}{30.10^{−4}}=120000Pa=1,2.10^5Pa$<br>b) đúng<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259655705-hinh-8.png\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>$\\Rightarrow V_s=2.10^{−4}=S.h_s\\Rightarrow h_s=8cm$<br>c) sai<br>$p_s=p_d+\\frac{54.10}{30.10^{−4}}=3.10^5Pa$<br>$V↓$  nhận công<br>d) sai<br>Quá trình ghế hạ xuống, khí trong xi lanh nhận công","difficultySource":"ai"},"ex":[{"exam":130,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Quá trình đẳng nhiệt và định luật Boyle","question":"Hình vẽ bên mô tả sơ đồ một chiếc ghế nâng hạ bằng khí thông qua chuyển động lên xuống của xi lanh nối với mặt ghế. Thanh nén khí cố định trên đế bịt kín một lượng khí lí tưởng trong xi lanh. Bỏ qua ma sát giữa thanh nén và xi lanh. Tổng khối lượng của mặt ghế và xi lanh là 6 kg , tiết diện của thanh nén là 30 cm2. Một học sinh nặng 54 kg ngồi lên ghế (hai chân để lơ lửng không chạm mặt sàn) thì ghế hạ xuống 12 cm khi ổn định. Coi nhiệt độ của khí trong xi lanh không đổi, áp suất khí quyển là 105 Pa và lấy g = 10 m/s2. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259655411-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Khi ghế để trống, áp suất của khí trong xi lanh bằng áp suất khí quyển.","answer":false},{"text":"Khi ghế để trống, cột khí trong xi lanh dài 20 cm.","answer":true},{"text":"Khi học sinh ngồi trên ghế, áp suất của khí trong xi lanh là 2.10<sup>5</sup> Pa.","answer":false},{"text":"Quá trình ghế hạ xuống, khí trong xi lanh sinh công.","answer":false}],"explanation":"a) sai<br>$p_k=p_{KQ}+\\frac{6.10}{30.10^{−4}}=120000Pa=1,2.10^5Pa$<br>b) đúng<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259655705-hinh-8.png\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>$\\Rightarrow V_s=2.10^{−4}=S.h_s\\Rightarrow h_s=8cm$<br>c) sai<br>$p_s=p_d+\\frac{54.10}{30.10^{−4}}=3.10^5Pa$<br>$V↓$  nhận công<br>d) sai<br>Quá trình ghế hạ xuống, khí trong xi lanh nhận công","difficultySource":"ai"}}]},{"id":456564,"nq":{"form":"bai_tap","type":"short_answer","topic":"Xử lí số liệu thí nghiệm đo nhiệt","answer":"408","question":"Một nhóm học sinh thực hiện thí nghiệm xác định nhiệt nóng chảy riêng của nước đá. Các bạn bố trí thí nghiệm như hình bên và tiến hành thí nghiệm qua các bước sau:<br>Bước 1: − Cho nước đá vào nhiệt lượng kế và hứng nước chảy ra bằng một chiếc cốc đặt trên cân, cho đến khi nước chảy ổn định đọc số chỉ của cân được giá trị m0.<br>− Bật đồng hồ đo thời gian, sau thời gian t (giây), đọc số chỉ của cân được giá trị m1.<br>Bước 2: − Bật biến áp nguồn.<br>− Đọc số chỉ P của oát kế.<br>− Cho nước chảy thêm vào cốc khi đồng hồ chỉ 2t (giây), đọc số chỉ của cân được giá trị m2. Kết quả thí nghiệm được nhóm ghi lại ở bảng sau: Đại lượng\tm0 (kg)\tm1 (kg)\tm2 (kg)\tt (s)\tP (W) Kết quả đo\t5,00.10<sup>−3</sup>\t8,00.10<sup>−3</sup>\t25,0.10<sup>−3</sup>\t168\t34,0 Xem điều kiện môi trường (nhiệt độ, áp suất, …) không đổi trong suốt thời gian làm thí nghiệm và điện năng tiêu thụ chuyển hóa hoàn toàn thành nhiệt lượng cung cấp cho nước đá. Bỏ qua sự bay hơi của nước. Giá trị nhiệt nóng chảy riêng của nước đá dùng trong thí nghiệm này là bao nhiêu kJ/kg? (Kết quả làm tròn đến hàng đơn vị). <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259823953-hinh-11.jpg\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"Đáp số 408<br>Khối lượng nước đá tan do môi trường truyền nhiệt trong khoảng thời gian t (từ lúc bật đồng hồ đến t = 168s) là:  $\\Delta m_{mt}=m_1−m_0=8.10^{−3}−5.10^{−3}=3.10^{−3}kg$  .<br>Khối lượng nước đá tan tổng cộng trong khoảng thời gian t tiếp theo (từ thời điểm t đến 2t ) khi bật biến áp nguồn là:  $\\Delta m_{tong}=m_2−m_1=25.10^{−3}−8.10^{−3}=17.10^{−3}kg$<br>Vì môi trường vẫn tiếp tục truyền nhiệt một cách ổn định như cũ, phần khối lượng nước đá tan chỉ do dây nung cung cấp nhiệt lượng trong thời gian t là:  $\\Delta m=\\Delta m_{tong}−\\Delta m_{mt}=14.10^{−3}kg$<br>Nhiệt lượng do dây nung cung cấp trong khoảng thời gian t = 168 s là: Q =  P.t  = 34.168 = 5712 J .<br>Nhiệt nóng chảy riêng của nước đá là:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259824297-hinh-12.png\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"},"ex":[{"exam":148,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Xử lí số liệu thí nghiệm đo nhiệt","answer":"408","question":"Một nhóm học sinh thực hiện thí nghiệm xác định nhiệt nóng chảy riêng của nước đá. Các bạn bố trí thí nghiệm như hình bên và tiến hành thí nghiệm qua các bước sau:<br>Bước 1: − Cho nước đá vào nhiệt lượng kế và hứng nước chảy ra bằng một chiếc cốc đặt trên cân, cho đến khi nước chảy ổn định đọc số chỉ của cân được giá trị m0.<br>− Bật đồng hồ đo thời gian, sau thời gian t (giây), đọc số chỉ của cân được giá trị m1.<br>Bước 2: − Bật biến áp nguồn.<br>− Đọc số chỉ P của oát kế.<br>− Cho nước chảy thêm vào cốc khi đồng hồ chỉ 2t (giây), đọc số chỉ của cân được giá trị m2. Kết quả thí nghiệm được nhóm ghi lại ở bảng sau: Đại lượng\tm0 (kg)\tm1 (kg)\tm2 (kg)\tt (s)\tP (W) Kết quả đo\t5,00.10<sup>−3</sup>\t8,00.10<sup>−3</sup>\t25,0.10<sup>−3</sup>\t168\t34,0 Xem điều kiện môi trường (nhiệt độ, áp suất, …) không đổi trong suốt thời gian làm thí nghiệm và điện năng tiêu thụ chuyển hóa hoàn toàn thành nhiệt lượng cung cấp cho nước đá. Bỏ qua sự bay hơi của nước. Giá trị nhiệt nóng chảy riêng của nước đá dùng trong thí nghiệm này là bao nhiêu kJ/kg? (Kết quả làm tròn đến hàng đơn vị). <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259823953-hinh-11.jpg\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"Đáp số 408<br>Khối lượng nước đá tan do môi trường truyền nhiệt trong khoảng thời gian t (từ lúc bật đồng hồ đến t = 168s) là:  $\\Delta m_{mt}=m_1−m_0=8.10^{−3}−5.10^{−3}=3.10^{−3}kg$  .<br>Khối lượng nước đá tan tổng cộng trong khoảng thời gian t tiếp theo (từ thời điểm t đến 2t ) khi bật biến áp nguồn là:  $\\Delta m_{tong}=m_2−m_1=25.10^{−3}−8.10^{−3}=17.10^{−3}kg$<br>Vì môi trường vẫn tiếp tục truyền nhiệt một cách ổn định như cũ, phần khối lượng nước đá tan chỉ do dây nung cung cấp nhiệt lượng trong thời gian t là:  $\\Delta m=\\Delta m_{tong}−\\Delta m_{mt}=14.10^{−3}kg$<br>Nhiệt lượng do dây nung cung cấp trong khoảng thời gian t = 168 s là: Q =  P.t  = 34.168 = 5712 J .<br>Nhiệt nóng chảy riêng của nước đá là:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259824297-hinh-12.png\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"}}]},{"id":456645,"nq":{"form":"bai_tap","type":"true_false","topic":"Tính lực từ F = BIl·sinθ","question":"Một nhóm học sinh làm thí nghiệm đo độ lớn cảm ứng từ B của từ trường đều giữa hai nhánh nam châm hình chữ U với bộ dụng cụ cân lực từ như ở hình vẽ. Chiều dài đoạn dây dẫn mang dòng điện đặt trong từ trường đều bằng 10 cm và thu được kết quả phụ thuộc của lực từ tác dụng lên đoạn dây theo cường độ dòng điện đi qua dây như ở đồ thị dưới đây. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259785055-hinh-8.jpg\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" /> <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259785364-hinh-9.png\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Độ lớn của lực từ tác dụng lên đoạn dây theo kết quả trong thí nghiệm tỉ lệ thuận với cường độ dòng điện qua dây dẫn.","answer":true},{"text":"Khi dòng điện có chiều từ P đến Q thì lực từ tác dụng lên đoạn dây có chiều thẳng đứng hướng lên.","answer":true},{"text":"Đoạn dây dẫn PQ được giữ cố định, khi dòng điện có chiều từ P đến Q thì số chỉ của cân sẽ giảm đi so với lúc chưa có dòng điện.","answer":false},{"text":"Từ kết quả của đồ thị, nhóm học sinh đã tính được độ lớn trung bình của cảm ứng từ B = 0,2.10<sup>−3</sup>T.","answer":false}],"explanation":"a) Đ  b) Đ  c) S  d) S<br>a) đúng<br>$F_t=BIℓ.sin\\alpha$<br>Đồ thị là một hàm bậc nhất  đi qua gốc toạ độ<br>b) đúng<br>Cảm ứng từ B có chiều từ S sang N. Dòng điện có chiều từ P sang Q.<br>Dùng quy tắc bàn tay trái → Lực từ hướng lên<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259785798-hinh-10.png\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>c) sai<br>Nam châm đẩy 1 lực từ  $\\vec{F}_t$  hướng lên. Thì sợi dây sẽ đẩy 1 lực từ hướng xuống → sẽ làm số chỉ của cân tăng lên<br>d) sai<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259786175-hinh-11.png\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>$F_t=BIℓ.sin\\alpha sin\\alpha =1\\rightarrow BIℓ$<br>Chọn 1 điểm đẹp trên đồ thị<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259786760-hinh-12.png\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>$\\Rightarrow F_t=BIℓ\\Rightarrow 4.10^{−3}=B.2.0,1\\Rightarrow B=0,02T=20.10^{−3}T$","difficultySource":"ai"},"ex":[{"exam":144,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Tính lực từ F = BIl·sinθ","question":"Một nhóm học sinh làm thí nghiệm đo độ lớn cảm ứng từ B của từ trường đều giữa hai nhánh nam châm hình chữ U với bộ dụng cụ cân lực từ như ở hình vẽ. Chiều dài đoạn dây dẫn mang dòng điện đặt trong từ trường đều bằng 10 cm và thu được kết quả phụ thuộc của lực từ tác dụng lên đoạn dây theo cường độ dòng điện đi qua dây như ở đồ thị dưới đây. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259785055-hinh-8.jpg\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" /> <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259785364-hinh-9.png\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Độ lớn của lực từ tác dụng lên đoạn dây theo kết quả trong thí nghiệm tỉ lệ thuận với cường độ dòng điện qua dây dẫn.","answer":true},{"text":"Khi dòng điện có chiều từ P đến Q thì lực từ tác dụng lên đoạn dây có chiều thẳng đứng hướng lên.","answer":true},{"text":"Đoạn dây dẫn PQ được giữ cố định, khi dòng điện có chiều từ P đến Q thì số chỉ của cân sẽ giảm đi so với lúc chưa có dòng điện.","answer":false},{"text":"Từ kết quả của đồ thị, nhóm học sinh đã tính được độ lớn trung bình của cảm ứng từ B = 0,2.10<sup>−3</sup>T.","answer":false}],"explanation":"a) Đ  b) Đ  c) S  d) S<br>a) đúng<br>$F_t=BIℓ.sin\\alpha$<br>Đồ thị là một hàm bậc nhất  đi qua gốc toạ độ<br>b) đúng<br>Cảm ứng từ B có chiều từ S sang N. Dòng điện có chiều từ P sang Q.<br>Dùng quy tắc bàn tay trái → Lực từ hướng lên<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259785798-hinh-10.png\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>c) sai<br>Nam châm đẩy 1 lực từ  $\\vec{F}_t$  hướng lên. Thì sợi dây sẽ đẩy 1 lực từ hướng xuống → sẽ làm số chỉ của cân tăng lên<br>d) sai<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259786175-hinh-11.png\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>$F_t=BIℓ.sin\\alpha sin\\alpha =1\\rightarrow BIℓ$<br>Chọn 1 điểm đẹp trên đồ thị<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259786760-hinh-12.png\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>$\\Rightarrow F_t=BIℓ\\Rightarrow 4.10^{−3}=B.2.0,1\\Rightarrow B=0,02T=20.10^{−3}T$","difficultySource":"ai"}}]},{"id":456761,"nq":{"form":"bai_tap","type":"short_answer","topic":"Từ thông qua khung dây","answer":"5","question":"Đồ thị dưới đây biểu diễn sự biến thiên của từ thông qua tiết diện của một cuộn dây dẫn phẳng theo thời gian. Biết từ thông qua tiết diện của cuộn dây dẫn biến đổi chỉ do độ lớn cảm ứng từ của từ trường thay đổi và từ trường này có các đường sức từ vuông góc với mặt phẳng cuộn dây. Biết tiết diện của cuộn dây là 50.10<sup>−4</sup> m2 và cuộn dây có 200 vòng dây. Độ lớn cực đại của cảm ứng từ bằng bao nhiêu tesla (làm tròn kết quả đến chữ số hàng đơn vị)? <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259979701-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Đáp số 5<br>Từ đồ thị, ta thấy giá trị cực đại của từ thông là $\\Phi_0$ = 5Wb.<br>Vì các đường sức từ vuông góc với mặt phẳng cuộn dây nên góc giữa vectơ cảm ứng từ  $\\vec{B}$ và vectơ pháp tuyến  $\\vec{n}$  của mặt phẳng cuộn dây là  $\\alpha =0^0\\Rightarrow cos\\left(0^0\\right)=1$<br>Ta có:  $\\Phi_0=N.B_0.S\\Rightarrow B_0=\\frac{\\Phi_0}{N.S}$<br>Thay số:  $B_0=\\frac{5}{200.50.10^{04}}=5\\left(T\\right)$","difficultySource":"ai"},"ex":[{"exam":165,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Từ thông qua khung dây","answer":"5","question":"Đồ thị dưới đây biểu diễn sự biến thiên của từ thông qua tiết diện của một cuộn dây dẫn phẳng theo thời gian. Biết từ thông qua tiết diện của cuộn dây dẫn biến đổi chỉ do độ lớn cảm ứng từ của từ trường thay đổi và từ trường này có các đường sức từ vuông góc với mặt phẳng cuộn dây. Biết tiết diện của cuộn dây là 50.10<sup>−4</sup> m2 và cuộn dây có 200 vòng dây. Độ lớn cực đại của cảm ứng từ bằng bao nhiêu tesla (làm tròn kết quả đến chữ số hàng đơn vị)? <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259979701-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Đáp số 5<br>Từ đồ thị, ta thấy giá trị cực đại của từ thông là $\\Phi_0$ = 5Wb.<br>Vì các đường sức từ vuông góc với mặt phẳng cuộn dây nên góc giữa vectơ cảm ứng từ  $\\vec{B}$ và vectơ pháp tuyến  $\\vec{n}$  của mặt phẳng cuộn dây là  $\\alpha =0^0\\Rightarrow cos\\left(0^0\\right)=1$<br>Ta có:  $\\Phi_0=N.B_0.S\\Rightarrow B_0=\\frac{\\Phi_0}{N.S}$<br>Thay số:  $B_0=\\frac{5}{200.50.10^{04}}=5\\left(T\\right)$","difficultySource":"ai"}}]},{"id":456897,"nq":{"form":"bai_tap","type":"true_false","topic":"Đọc đồ thị các đẳng quá trình","question":"Một mol khí helium (xem là khí lí tưởng) được chứa trong một xi lanh kín có pit-tông có thể chuyển động không ma sát. Khối khí thực hiện quá trình biến đổi trạng thái được biểu diễn trên đồ thị (V, T) như hình vẽ. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259908418-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Từ trạng thái (1) sang trạng thái (2), khối khí thực hiện quá trình nén đẳng nhiệt.","answer":true},{"text":"Áp suất của khối khí ở trạng thái (2) bằng 2.10<sup>5</sup> Pa.","answer":false},{"text":"Công do khối khí thực hiện trong quá trình biến đổi từ trạng thái (2) sang trạng thái (3) có độ lớn bằng 400 J.","answer":false},{"text":"Động năng tịnh tiến trung bình của các phân tử khí ở trạng thái (4) xấp xỉ bằng 1,86.1020 J.","answer":true}],"explanation":"a) đúng<br>Từ trạng thái (1) sang trạng thái (2), đồ thị biểu diễn sự phụ thuộc của V vào T là đoạn thẳng có đường kéo dài vuông góc với trục OT nên đây là quá trình đẳng nhiệt.<br>Mà thế tích của khối khí giảm.<br>Vậy, từ trạng thái (1) sang trạng thái (2), khối khí thực hiện quá trình nén đẳng nhiệt.<br>b) sai<br>Áp suất của khối khí ở trạng thái (2) bằng:<br>$p_2.V_2=nRT_2$    $p_2=\\frac{nRT_2}{V_2}=\\frac{1.8,31.300}{1.{10}^{-3}}=24,93.{10}^5$  Pa.<br>c) sai<br>Công do khối khí thực hiện trong quá trình biến đổi từ trạng thái (2) sang trạng thái (3) có độ lớn bằng:<br>$A=p_2.\\left(V_3-V_2\\right)=24,93.{10}^5.\\left(3-1\\right).{10}^{-3}=4986$  J.<br>d) đúng<br>Động năng tịnh tiến trung bình của mỗi phân tử khí ở trạng thái (4) là:<br>$\\overline{E_đ}=\\frac{3}{2}kT_4=\\frac{3}{2}.\\frac{R}{N_A}.T_4=\\frac{3}{2}.\\frac{8,31}{6,02.{10}^{23}}.900\\approx 1,86.{10}^{-20}$  J.","difficultySource":"ai"},"ex":[{"exam":157,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Đọc đồ thị các đẳng quá trình","question":"Một mol khí helium (xem là khí lí tưởng) được chứa trong một xi lanh kín có pit-tông có thể chuyển động không ma sát. Khối khí thực hiện quá trình biến đổi trạng thái được biểu diễn trên đồ thị (V, T) như hình vẽ. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259908418-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Từ trạng thái (1) sang trạng thái (2), khối khí thực hiện quá trình nén đẳng nhiệt.","answer":true},{"text":"Áp suất của khối khí ở trạng thái (2) bằng 2.10<sup>5</sup> Pa.","answer":false},{"text":"Công do khối khí thực hiện trong quá trình biến đổi từ trạng thái (2) sang trạng thái (3) có độ lớn bằng 400 J.","answer":false},{"text":"Động năng tịnh tiến trung bình của các phân tử khí ở trạng thái (4) xấp xỉ bằng 1,86.1020 J.","answer":true}],"explanation":"a) đúng<br>Từ trạng thái (1) sang trạng thái (2), đồ thị biểu diễn sự phụ thuộc của V vào T là đoạn thẳng có đường kéo dài vuông góc với trục OT nên đây là quá trình đẳng nhiệt.<br>Mà thế tích của khối khí giảm.<br>Vậy, từ trạng thái (1) sang trạng thái (2), khối khí thực hiện quá trình nén đẳng nhiệt.<br>b) sai<br>Áp suất của khối khí ở trạng thái (2) bằng:<br>$p_2.V_2=nRT_2$    $p_2=\\frac{nRT_2}{V_2}=\\frac{1.8,31.300}{1.{10}^{-3}}=24,93.{10}^5$  Pa.<br>c) sai<br>Công do khối khí thực hiện trong quá trình biến đổi từ trạng thái (2) sang trạng thái (3) có độ lớn bằng:<br>$A=p_2.\\left(V_3-V_2\\right)=24,93.{10}^5.\\left(3-1\\right).{10}^{-3}=4986$  J.<br>d) đúng<br>Động năng tịnh tiến trung bình của mỗi phân tử khí ở trạng thái (4) là:<br>$\\overline{E_đ}=\\frac{3}{2}kT_4=\\frac{3}{2}.\\frac{R}{N_A}.T_4=\\frac{3}{2}.\\frac{8,31}{6,02.{10}^{23}}.900\\approx 1,86.{10}^{-20}$  J.","difficultySource":"ai"}}]},{"id":456902,"nq":{"form":"bai_tap","type":"short_answer","topic":"Tính lực từ F = BIl·sinθ","answer":"66,6","question":"Một đoạn dây dẫn thẳng bằng đồng được đặt trong một từ trường đều sao cho đoạn dây vuông góc với các đường sức từ. Trong đoạn dây có dòng điện khổng đổi với cường độ 0,7 A và có phương và chiều như hình vẽ. Bỏ qua ảnh hưởng của từ trường Trái Đất lên đoạn dây dẫn. Biết khối lượng của một đơn vị chiều dài của đoạn dây đồng là 46,6.10<sup>3</sup> kg/m; lấy g = 10 $m/s^2$. Để lực từ do từ trường đều tác dụng lên đoạn dây dẫn cân bằng với trọng lực tác dụng lên đoạn dây, thì độ lớn cảm ứng từ của từ trường đều bằng bao nhiêu (đơn vị 102 T)? (Làm tròn kết quả đến chữ số hàng phần phần mười). <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259910480-hinh-10.png\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Ta có:  $\\vec{F}+\\vec{P}=\\vec{0}$    $F=P$    $BIl.\\sin\\left(\\alpha \\right)=mg$<br>$B=\\frac{m}{l}.\\frac{g}{I.\\sin\\left(\\alpha \\right)}=46,6.{10}^{-3}.\\frac{10}{0,7.\\sin\\left(90\\right)}\\approx 66,6.{10}^{-2}$  T.","difficultySource":"ai"},"ex":[{"exam":157,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Tính lực từ F = BIl·sinθ","answer":"66,6","question":"Một đoạn dây dẫn thẳng bằng đồng được đặt trong một từ trường đều sao cho đoạn dây vuông góc với các đường sức từ. Trong đoạn dây có dòng điện khổng đổi với cường độ 0,7 A và có phương và chiều như hình vẽ. Bỏ qua ảnh hưởng của từ trường Trái Đất lên đoạn dây dẫn. Biết khối lượng của một đơn vị chiều dài của đoạn dây đồng là 46,6.10<sup>3</sup> kg/m; lấy g = 10 m/s2. Để lực từ do từ trường đều tác dụng lên đoạn dây dẫn cân bằng với trọng lực tác dụng lên đoạn dây, thì độ lớn cảm ứng từ của từ trường đều bằng bao nhiêu (đơn vị 102 T)? (Làm tròn kết quả đến chữ số hàng phần phần mười). <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259910480-hinh-10.png\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Ta có:  $\\vec{F}+\\vec{P}=\\vec{0}$    $F=P$    $BIl.\\sin\\left(\\alpha \\right)=mg$<br>$B=\\frac{m}{l}.\\frac{g}{I.\\sin\\left(\\alpha \\right)}=46,6.{10}^{-3}.\\frac{10}{0,7.\\sin\\left(90\\right)}\\approx 66,6.{10}^{-2}$  T.","difficultySource":"ai"}}]},{"id":456980,"nq":{"form":"bai_tap","type":"true_false","topic":"Tính lực từ F = BIl·sinθ","question":"Một thiết bị bao gồm một sợi dây dẫn điện đồng chất, tiết diện đều, một nam châm, một chiếc cân, một bộ nguồn điện có suất điện động không đổi (có gắn sẵn các đầu và một công tắc điện K có điện trở không đáng kể). Sợi dây có tiết diện S = 3,5.10<sup>−9</sup> m2, chiều dài L = 72,0 cm và điện trở được  xác định bằng công thức $R=1,7.10^{−8}.\\frac{L}{S}$   (với S tính bằng m ;L tính bằng m và R tính bằng Ω ). Bộ nguồn có suất điện động E = 12,0 V và điện trở trong r = 0,5Ω . Uốn sợi dây dẫn điện thành khung dây và bố trí thí nghiệm như hình bên (khung dây được giữ bởi hai chốt A, B). Biết phần nằm ngang của sợi dây nằm giữa hai cực của nam châm có chiều dài 12,0 cm . Khi bật công tắc cho dòng điện chạy trong mạch điện thì thấy số chỉ của cân thay đổi 6,0 g. Lấy gia tốc trọng trường g = 9,8 $m/s^2$ <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259802953-hinh-3.png\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Điện trở của sợi dây là 3,5Ω .","answer":true},{"text":"Sau khi đóng khóa K, cường độ dòng điện chạy trong mạch điện có độ lớn 3,0 A.","answer":true},{"text":"Sau khi đóng khóa K, số chỉ của cân giảm đi.","answer":true},{"text":"Độ lớn cảm ứng từ giữa hai cực của nam châm là 0,13 T.","answer":false}],"explanation":"a) Đ  b) Đ  c) Đ  d) S<br>a) đúng<br>$R=1,7.10^{−8}.\\frac{L}{S}=1,7.10^{−8}.\\frac{0,72}{3,5.10^{−9}}=\\frac{612}{175}\\approx 3,5\\Omega$<br>b) đúng<br>$I=\\frac{E}{R+r}=\\frac{12}{3,5+0,5}=3A$<br>c) đúng<br>Khóa K đóng, dòng điện có chiều đi ra từ cực dương đi vào từ cực âm. Đường sức từ có chiều ra N vào S (ra Bắc vào Nam)<br>Áp dụng quy tắc bàn tay trái  $\\Rightarrow$  Lực từ  $\\vec{F}$  do nam châm tác dụng lên đoạn dây có chiều hướng xuống  $\\Rightarrow$  Theo định luật III Newton, lực từ  $\\vec{F}^/$  do đoạn dây tác dụng lên nam châm hướng lên  $\\Rightarrow$  Số chỉ của cân giảm<br>d) sai<br>$F=\\Delta P\\Rightarrow BIL=\\Delta m.g\\Rightarrow B=\\frac{\\Delta mg}{IL}=\\frac{6.10^{−3}.9,8}{3.0,12}\\approx 0,163T$","difficultySource":"ai"},"ex":[{"exam":146,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Tính lực từ F = BIl·sinθ","question":"Một thiết bị bao gồm một sợi dây dẫn điện đồng chất, tiết diện đều, một nam châm, một chiếc cân, một bộ nguồn điện có suất điện động không đổi (có gắn sẵn các đầu và một công tắc điện K có điện trở không đáng kể). Sợi dây có tiết diện S = 3,5.10<sup>−9</sup> m2, chiều dài L = 72,0 cm và điện trở được  xác định bằng công thức $R=1,7.10^{−8}.\\frac{L}{S}$   (với S tính bằng m ;L tính bằng m và R tính bằng Ω ). Bộ nguồn có suất điện động E = 12,0 V và điện trở trong r = 0,5Ω . Uốn sợi dây dẫn điện thành khung dây và bố trí thí nghiệm như hình bên (khung dây được giữ bởi hai chốt A, B). Biết phần nằm ngang của sợi dây nằm giữa hai cực của nam châm có chiều dài 12,0 cm . Khi bật công tắc cho dòng điện chạy trong mạch điện thì thấy số chỉ của cân thay đổi 6,0 g. Lấy gia tốc trọng trường g = 9,8 m/s2 <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259802953-hinh-3.png\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Điện trở của sợi dây là 3,5Ω .","answer":true},{"text":"Sau khi đóng khóa K, cường độ dòng điện chạy trong mạch điện có độ lớn 3,0 A.","answer":true},{"text":"Sau khi đóng khóa K, số chỉ của cân giảm đi.","answer":true},{"text":"Độ lớn cảm ứng từ giữa hai cực của nam châm là 0,13 T.","answer":false}],"explanation":"a) Đ  b) Đ  c) Đ  d) S<br>a) đúng<br>$R=1,7.10^{−8}.\\frac{L}{S}=1,7.10^{−8}.\\frac{0,72}{3,5.10^{−9}}=\\frac{612}{175}\\approx 3,5\\Omega$<br>b) đúng<br>$I=\\frac{E}{R+r}=\\frac{12}{3,5+0,5}=3A$<br>c) đúng<br>Khóa K đóng, dòng điện có chiều đi ra từ cực dương đi vào từ cực âm. Đường sức từ có chiều ra N vào S (ra Bắc vào Nam)<br>Áp dụng quy tắc bàn tay trái  $\\Rightarrow$  Lực từ  $\\vec{F}$  do nam châm tác dụng lên đoạn dây có chiều hướng xuống  $\\Rightarrow$  Theo định luật III Newton, lực từ  $\\vec{F}^/$  do đoạn dây tác dụng lên nam châm hướng lên  $\\Rightarrow$  Số chỉ của cân giảm<br>d) sai<br>$F=\\Delta P\\Rightarrow BIL=\\Delta m.g\\Rightarrow B=\\frac{\\Delta mg}{IL}=\\frac{6.10^{−3}.9,8}{3.0,12}\\approx 0,163T$","difficultySource":"ai"}}]},{"id":457011,"nq":{"form":"bai_tap","type":"true_false","topic":"Quá trình đẳng nhiệt và định luật Boyle","question":"Trong quá trình quang hợp, cây thủy sinh hấp thụ carbon dioxide và nhả ra oxygen. Oxygen này hòa tan vào nước, trở thành nguồn dưỡng khí thiết yếu cho cá và các sinh vật khác sống trong hồ. Một môi trường giàu oxygen giúp cá khỏe mạnh, giảm stress và tăng cường sức đề kháng. Một bong bóng chứa khí oxygen có thể tích 0,60 cm3 được giải phóng bởi một cây thủy sinh ở độ sâu 2,5 m. Áp suất khí quyển bằng 1, 00.105 Pa, tương đương với áp suất do một cột nước có độ cao 10 m. Coi khí là lí tưởng và có nhiệt độ không đổi bằng 20°C. Biết khối lượng mol của khí oxygen là 32 g/mol. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260123782-hinh-10.jpg\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Giữa đáy hồ có độ sâu 2,5 m và ở mặt nước, có độ chênh lệch áp suất là 0,5.105 Pa.","answer":false},{"text":"Áp suất của bong bóng lúc được giải phóng bằng 2,5.10<sup>5</sup> Pa.","answer":false},{"text":"Khối lượng khí oxygen có trong bong bóng đó xấp xỉ bằng 0,8 g.","answer":false},{"text":"Thể tích của bong bóng khi đến mặt nước bằng 0,75 cm3.","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Áp suất nước ở độ sâu $h$: $\\Delta p=\\frac{h}{10}\\cdot10^5$ Pa (vì cột nước $10$ m tương ứng $10^5$ Pa).</p><p class=\"text-base leading-relaxed my-2\">a) Sai. $\\Delta p=\\frac{2{,}5}{10}\\cdot10^5=0{,}25\\cdot10^5$ Pa, không phải $0{,}5\\cdot10^5$ Pa.</p><p class=\"text-base leading-relaxed my-2\">b) Sai. $p_1=p_0+\\Delta p=1{,}00\\cdot10^5+0{,}25\\cdot10^5=1{,}25\\cdot10^5$ Pa, không phải $2{,}5\\cdot10^5$ Pa.</p><p class=\"text-base leading-relaxed my-2\">c) Sai. $n=\\frac{pV}{RT}=\\frac{1{,}25\\cdot10^5\\cdot0{,}6\\cdot10^{-6}}{8{,}31\\cdot293}\\approx3{,}1\\cdot10^{-5}$ mol, khối lượng $m=nM\\approx9{,}9\\cdot10^{-4}$ g, không phải $0{,}8$ g.</p><p class=\"text-base leading-relaxed my-2\">d) Đúng. Đẳng nhiệt: $p_1V_1=p_0V_2$, nên $V_2=\\frac{1{,}25\\cdot10^5\\cdot0{,}6}{1{,}00\\cdot10^5}=0{,}75$ cm$^3$.</p>","difficultySource":"ai"},"ex":[{"exam":186,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Quá trình đẳng nhiệt và định luật Boyle","question":"Trong quá trình quang hợp, cây thủy sinh hấp thụ carbon dioxide và nhả ra oxygen. Oxygen này hòa tan vào nước, trở thành nguồn dưỡng khí thiết yếu cho cá và các sinh vật khác sống trong hồ. Một môi trường giàu oxygen giúp cá khỏe mạnh, giảm stress và tăng cường sức đề kháng. Một bong bóng chứa khí oxygen có thể tích 0,60 cm3 được giải phóng bởi một cây thủy sinh ở độ sâu 2,5 m. Áp suất khí quyển bằng 1, 00.105 Pa, tương đương với áp suất do một cột nước có độ cao 10 m. Coi khí là lí tưởng và có nhiệt độ không đổi bằng 20°C. Biết khối lượng mol của khí oxygen là 32 g/mol. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260123782-hinh-10.jpg\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Giữa đáy hồ có độ sâu 2,5 m và ở mặt nước, có độ chênh lệch áp suất là 0,5.105 Pa.","answer":false},{"text":"Áp suất của bong bóng lúc được giải phóng bằng 2,5.10<sup>5</sup> Pa.","answer":false},{"text":"Khối lượng khí oxygen có trong bong bóng đó xấp xỉ bằng 0,8 g.","answer":false},{"text":"Thể tích của bong bóng khi đến mặt nước bằng 0,75 cm3.","answer":true}],"explanation":"","difficultySource":"ai"}}]},{"id":457015,"nq":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"39","question":"Trong ô tô, người ta thường đặt ở hệ thống tay lái một thiết bị nhằm bảo vệ người lái xe khi gặp tai nạn, gọi là \" túi khí \" (như hình). Túi khí được chế tạo bằng vật liệu co dãn, chịu được áp suất lớn, trong túi khí chứa NaN3. Khi xe va chạm mạnh với vật cản hệ thống cảm biến sẽ kích thích để chất rắn NaN3 phân hủy toàn bộ thành Na và 64,6 g khí nitrogen (N2) được coi là khí lí tưởng. Khối lượng mol của khí nitrogen là 28 g/mol. Bỏ qua thể tích khí có trong túi trước khi phồng lên và thể tích của Na tạo thành trong túi do phân hủy. Sau khi túi được kích hoạt, khí trong túi có áp suất p = 1, 5.10<sup>5</sup> Pa, nhiệt độ 30°C thì thể tích túi khi đó là bao nhiêu lít (làm tròn kết quả đến chữ số hàng đơn vị)? <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260124089-hinh-11.jpg\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Số mol khí nitrogen: $n=\\frac{m}{M}=\\frac{64{,}6}{28}\\approx2{,}307$ mol.</p><p class=\"text-base leading-relaxed my-2\">Phương trình trạng thái khí lí tưởng: $pV=nRT$ với $T=30+273=303$ K.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$V=\\frac{nRT}{p}=\\frac{2{,}307\\cdot8{,}31\\cdot303}{1{,}5\\cdot10^5}\\approx0{,}0387$ m$^3$$\\approx38{,}7$ lít.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Làm tròn đến hàng đơn vị: $V\\approx39$ lít.</p>","difficultySource":"ai"},"ex":[{"exam":186,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"39","question":"Trong ô tô, người ta thường đặt ở hệ thống tay lái một thiết bị nhằm bảo vệ người lái xe khi gặp tai nạn, gọi là \" túi khí \" (như hình). Túi khí được chế tạo bằng vật liệu co dãn, chịu được áp suất lớn, trong túi khí chứa NaN3. Khi xe va chạm mạnh với vật cản hệ thống cảm biến sẽ kích thích để chất rắn NaN3 phân hủy toàn bộ thành Na và 64,6 g khí nitrogen (N2) được coi là khí lí tưởng. Khối lượng mol của khí nitrogen là 28 g/mol. Bỏ qua thể tích khí có trong túi trước khi phồng lên và thể tích của Na tạo thành trong túi do phân hủy. Sau khi túi được kích hoạt, khí trong túi có áp suất p = 1, 5.10<sup>5</sup> Pa, nhiệt độ 30°C thì thể tích túi khi đó là bao nhiêu lít (làm tròn kết quả đến chữ số hàng đơn vị)? <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260124089-hinh-11.jpg\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"","difficultySource":"ai"}}]},{"id":457016,"nq":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"42","question":"Có 4 bình có thể tích V1 = 33,24 lít, V2 = V3 = 2V1, V4 = 3V1 thông với nhau bằng các ống nối nhưng cách nhiệt với nhau bằng vách ngăn. Vách ngăn trong ống nối sẽ mở khi hai bình khí được nối với nhau có sự chênh lệch áp suất. Ban đầu các bình chứa khí nitrogen (được coi là khí lí tưởng) ở cùng nhiệt độ 27°C và áp suất p0 = 6.10<sup>4</sup> Pa. Bỏ qua thể tích của các đoạn ống nối, biết khối lượng mol của khí nitrogen là 28 g/mol. Ta đồng thời thực hiện thay đổi nhiệt độ của các bình để nhiệt độ bình (2) ở −23°C, bình (3) ở 127°C, bình (4) ở 327°C và giữ nguyên nhiệt độ bình (1). Khi ở trạng thái cân bằng, khối lượng khí trong bình (3) bằng bao nhiêu gam (làm tròn kết quả đến chữ số hàng đơn vị). <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260124410-hinh-12.png\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"<p class=\"text-base leading-relaxed my-2\">Tổng số mol khí không đổi (vách ngăn chỉ mở để cân bằng áp suất). Ban đầu: $n=\\frac{p_0(V_1+V_2+V_3+V_4)}{R\\cdot300}$ với $V_1+V_2+V_3+V_4=8V_1$.</p><p class=\"text-base leading-relaxed my-2\">Nhiệt độ cuối: $T_1=300$ K, $T_2=250$ K, $T_3=400$ K, $T_4=600$ K. Khi cân bằng áp suất chung $p$: $n=\\frac{p}{R}\\left(\\frac{V_1}{300}+\\frac{2V_1}{250}+\\frac{2V_1}{400}+\\frac{3V_1}{600}\\right)=\\frac{p V_1}{R}\\cdot0{,}021333$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$p=\\frac{p_0\\cdot8}{300\\cdot0{,}021333}=\\frac{6\\cdot10^4\\cdot8}{6{,}4}=7{,}5\\cdot10^4$ Pa.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Số mol trong bình 3: $n_3=\\frac{pV_3}{RT_3}=\\frac{7{,}5\\cdot10^4\\cdot66{,}48\\cdot10^{-3}}{8{,}31\\cdot400}=1{,}5$ mol.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Khối lượng: $m_3=n_3M=1{,}5\\cdot28=42$ g.</p>","difficultySource":"ai"},"ex":[{"exam":186,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"42","question":"Có 4 bình có thể tích V1 = 33,24 lít, V2 = V3 = 2V1, V4 = 3V1 thông với nhau bằng các ống nối nhưng cách nhiệt với nhau bằng vách ngăn. Vách ngăn trong ống nối sẽ mở khi hai bình khí được nối với nhau có sự chênh lệch áp suất. Ban đầu các bình chứa khí nitrogen (được coi là khí lí tưởng) ở cùng nhiệt độ 27°C và áp suất p0 = 6.10<sup>4</sup> Pa. Bỏ qua thể tích của các đoạn ống nối, biết khối lượng mol của khí nitrogen là 28 g/mol. Ta đồng thời thực hiện thay đổi nhiệt độ của các bình để nhiệt độ bình (2) ở −23°C, bình (3) ở 127°C, bình (4) ở 327°C và giữ nguyên nhiệt độ bình (1). Khi ở trạng thái cân bằng, khối lượng khí trong bình (3) bằng bao nhiêu gam (làm tròn kết quả đến chữ số hàng đơn vị). <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260124410-hinh-12.png\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"","difficultySource":"ai"}}]},{"id":457037,"nq":{"form":"bai_tap","type":"true_false","topic":"Đọc đồ thị các đẳng quá trình","question":"Hình bên là đồ thị biểu diễn chu trình biến đổi trạng thái của một lượng khí lí tưởng. Ở trạng thái (1) áp suất khí là p1 = 2.10<sup>5</sup> Pa . <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259853859-hinh-3.png\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Quá trình biến đổi từ trạng thái (1) sang trạng thái (2) là quá trình đẳng áp.","answer":true},{"text":"Quá trình biến đổi từ trạng thái (2) sang trạng thái (3) tuân theo định luật Boyle.","answer":true},{"text":"Ở trạng thái (2) nhiệt độ của khí là 1200°C .","answer":false},{"text":"Nếu trong quá trình chuyển từ trạng thái (2) sang trạng thái (3) có một nửa lượng khí thoát ra","answer":false}],"explanation":"a) đúng<br>Quá trình biến đổi từ trạng thái (1) sang trạng thái (2) có đồ thị đi qua gốc toạ độ, là quá trình đẳng áp.<br>b) đúng<br>Quá trình biến đổi từ trạng thái (2) sang trạng thái (3) có đồ thị có phương vuông góc với trục OT là quá trình đẳng nhiệt, tuân theo định luật Boyle<br>c) sai<br>Trạng thái 1:  $\\left\\{\\begin{aligned}V_1=2\\left(ℓ\\right) <br>T_1=400K\\end{aligned}\\right.$<br>Trạng thái 2:  $\\left\\{\\begin{aligned}V_2=6\\left(ℓ\\right) <br>T_2\\end{aligned}\\right.$<br>Áp dụng công thức định luật Charles cho quá trình đẳng áp biến đổi từ trạng thái (1) sang trạng thái (2), ta có:<br>$\\frac{V_1}{T_1}=\\frac{V_2}{T_2}\\Rightarrow \\frac{2}{400}=\\frac{6}{T_2}\\Rightarrow T_2=1200K$<br>$\\Rightarrow t_2=1200−273=927^0C$<br>d) sai<br>Trạng thái 2:  $\\left\\{\\begin{aligned}p_2=p_1=2.10^5Pa <br>V_2=6\\left(ℓ\\right)\\end{aligned}\\right.$<br>Trạng thái 3:  $\\left\\{\\begin{aligned}p_3 <br>V_2=2ℓ\\end{aligned}\\right.$<br>Áp dụng công thức định luật Boyle cho quá trình đẳng nhiệt từ trạng thái (2) sang trạng thái (3), ta có:<br>$p_2V_2=p_3V_3\\Rightarrow 2.10^5.6=p_3.2\\Rightarrow p_3=6.10^5(Pa)$<br>Tại trạng thái 3, ta có phương trình Clapeyron:<br>$p_3V_3=nRT_3\\Rightarrow p_3\\sim n$<br>Do một nửa lượng khí thoát ra ngoài nên áp suất khí ở trạng thái 3 là:<br>$p_3=\\frac{p_3}{2}=\\frac{6.10^5}{2}=3.10^5(Pa)$","difficultySource":"ai"},"ex":[{"exam":152,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Đọc đồ thị các đẳng quá trình","question":"Hình bên là đồ thị biểu diễn chu trình biến đổi trạng thái của một lượng khí lí tưởng. Ở trạng thái (1) áp suất khí là p1 = 2.10<sup>5</sup> Pa . <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259853859-hinh-3.png\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Quá trình biến đổi từ trạng thái (1) sang trạng thái (2) là quá trình đẳng áp.","answer":true},{"text":"Quá trình biến đổi từ trạng thái (2) sang trạng thái (3) tuân theo định luật Boyle.","answer":true},{"text":"Ở trạng thái (2) nhiệt độ của khí là 1200°C .","answer":false},{"text":"Nếu trong quá trình chuyển từ trạng thái (2) sang trạng thái (3) có một nửa lượng khí thoát ra","answer":false}],"explanation":"a) đúng<br>Quá trình biến đổi từ trạng thái (1) sang trạng thái (2) có đồ thị đi qua gốc toạ độ, là quá trình đẳng áp.<br>b) đúng<br>Quá trình biến đổi từ trạng thái (2) sang trạng thái (3) có đồ thị có phương vuông góc với trục OT là quá trình đẳng nhiệt, tuân theo định luật Boyle<br>c) sai<br>Trạng thái 1:  $\\left\\{\\begin{aligned}V_1=2\\left(ℓ\\right) <br>T_1=400K\\end{aligned}\\right.$<br>Trạng thái 2:  $\\left\\{\\begin{aligned}V_2=6\\left(ℓ\\right) <br>T_2\\end{aligned}\\right.$<br>Áp dụng công thức định luật Charles cho quá trình đẳng áp biến đổi từ trạng thái (1) sang trạng thái (2), ta có:<br>$\\frac{V_1}{T_1}=\\frac{V_2}{T_2}\\Rightarrow \\frac{2}{400}=\\frac{6}{T_2}\\Rightarrow T_2=1200K$<br>$\\Rightarrow t_2=1200−273=927^0C$<br>d) sai<br>Trạng thái 2:  $\\left\\{\\begin{aligned}p_2=p_1=2.10^5Pa <br>V_2=6\\left(ℓ\\right)\\end{aligned}\\right.$<br>Trạng thái 3:  $\\left\\{\\begin{aligned}p_3 <br>V_2=2ℓ\\end{aligned}\\right.$<br>Áp dụng công thức định luật Boyle cho quá trình đẳng nhiệt từ trạng thái (2) sang trạng thái (3), ta có:<br>$p_2V_2=p_3V_3\\Rightarrow 2.10^5.6=p_3.2\\Rightarrow p_3=6.10^5(Pa)$<br>Tại trạng thái 3, ta có phương trình Clapeyron:<br>$p_3V_3=nRT_3\\Rightarrow p_3\\sim n$<br>Do một nửa lượng khí thoát ra ngoài nên áp suất khí ở trạng thái 3 là:<br>$p_3=\\frac{p_3}{2}=\\frac{6.10^5}{2}=3.10^5(Pa)$","difficultySource":"ai"}}]},{"id":457096,"nq":{"form":"bai_tap","type":"short_answer","topic":"Xử lí số liệu thí nghiệm đo nhiệt","answer":"9,01","question":"Trong phòng thí nghiệm, người ta dùng một lò nấu chảy kim loại để nấu chảy một mẫu đồng. Hình bên là đồ thị biểu diễn sự phụ thuộc nhiệt độ của mẫu đồng theo thời gian. Biết lò cung cấp nhiệt cho mẫu đồng với tốc độ không đổi là 121kJ / phút, nhiệt nóng chảy riêng của đồng là 1,8.10<sup>5</sup> J /kg. Bỏ qua sự trao đổi nhiệt với môi trường. Khối lượng của mẫu đồng này là bao nhiêu kilôgam (làm tròn kết quả đến chữ số hàng phần trăm)? <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259764227-hinh-12.png\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Đáp số 9,01<br>Nóng chảy từ  $B\\rightarrow C\\Rightarrow 30\\rightarrow 43,4$<br>$Q=m\\lambda$<br>$\\Rightarrow P.t=m\\lambda$<br>$\\Rightarrow 121.10^3.\\left(43,4−30\\right)=m.1,8.10^5$<br>$\\Rightarrow m=9,01kg$","difficultySource":"ai"},"ex":[{"exam":142,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Xử lí số liệu thí nghiệm đo nhiệt","answer":"9,01","question":"Trong phòng thí nghiệm, người ta dùng một lò nấu chảy kim loại để nấu chảy một mẫu đồng. Hình bên là đồ thị biểu diễn sự phụ thuộc nhiệt độ của mẫu đồng theo thời gian. Biết lò cung cấp nhiệt cho mẫu đồng với tốc độ không đổi là 121kJ / phút, nhiệt nóng chảy riêng của đồng là 1,8.10<sup>5</sup> J /kg. Bỏ qua sự trao đổi nhiệt với môi trường. Khối lượng của mẫu đồng này là bao nhiêu kilôgam (làm tròn kết quả đến chữ số hàng phần trăm)? <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259764227-hinh-12.png\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Đáp số 9,01<br>Nóng chảy từ  $B\\rightarrow C\\Rightarrow 30\\rightarrow 43,4$<br>$Q=m\\lambda$<br>$\\Rightarrow P.t=m\\lambda$<br>$\\Rightarrow 121.10^3.\\left(43,4−30\\right)=m.1,8.10^5$<br>$\\Rightarrow m=9,01kg$","difficultySource":"ai"}}]},{"id":457123,"nq":{"form":"bai_tap","type":"true_false","topic":"Liều chiếu xạ và tác hại của phóng xạ","question":"Trong y học hạt nhân, ngoài đại lượng Liều hấp thụ (D, đơn vị Gray - Gy) dùng để đo năng lượng bức xạ truyền cho 1 kg vật chất (D = E/m), người ta còn dùng đại lượng Liều tương đương (H, đơn vị Sievert Sv) để đánh giá mức độ tổn thương sinh học. Công thức liên hệ là: H = DωR, trong đó ωR là hệ số phẩm chất (hay trọng số bức xạ), phụ thuộc vào loại tia. Với tia X, gamma, beta thì ωR = 1; với proton thì ωR = 2. Xạ trị proton là phương pháp tiên tiến sử dụng chùm hạt proton năng lượng cao thay vì tia X hay gamma. Điểm ưu việt của nó là \"đỉnh Bragg\": proton giải phóng phần lớn năng lượng tại đúng vị trí khối u rồi dừng lại, giảm tối đa tổn thương cho mô lành phía sau. Một máy gia tốc Cyclotron bắn chùm hạt proton có động năng K = 230MeV (1MeV = 1,6.10<sup>−13</sup> J) vào một khối u nặng m = 5 g. Trong một lần điều trị, người ta bắn vào 1010 hạt và khối u hấp thụ hoàn toàn năng lượng. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260010353-hinh-5.jpg\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Hạt proton được sử dụng trong phương pháp này thực chất là hạt nhân của nguyên tử Hydrogen thường (Hydrogen nhẹ).","answer":true},{"text":"Khác với tia X hay gamma thường gây tổn thương mô lành trên toàn bộ đường đi, chùm proton có ưu điểm là giải phóng phần lớn năng lượng tại đích đến (khối u) rồi dừng lại, giúp giảm thiểu tác dụng phụ.","answer":true},{"text":"Tổng năng lượng mà chùm proton truyền cho khối u trong một lần điều trị là 0,368 J.","answer":true},{"text":"Liều tương đương mà khối u phải chịu trong lần điều trị này là khoảng 147,2mSv (miliSievert).","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\">a) Đúng. Proton là hạt nhân của nguyên tử hydrogen thường ($^1_1$H, một proton và không có neutron).</p><p class=\"text-base leading-relaxed my-2\">b) Đúng. Đây chính là ưu điểm \"đỉnh Bragg\" của xạ trị proton: giải phóng phần lớn năng lượng ở khối u rồi dừng lại.</p><p class=\"text-base leading-relaxed my-2\">c) Đúng. Năng lượng một hạt: $230\\cdot1{,}6\\cdot10^{-13}=3{,}68\\cdot10^{-11}$ J. Tổng năng lượng với $10^{10}$ hạt: $E=10^{10}\\cdot3{,}68\\cdot10^{-11}=0{,}368$ J.</p><p class=\"text-base leading-relaxed my-2\">d) Sai. Liều hấp thụ: $D=\\frac{E}{m}=\\frac{0{,}368}{5\\cdot10^{-3}}=73{,}6$ Gy. Liều tương đương: $H=D\\omega_R=73{,}6\\cdot2=147{,}2$ Sv, tức $147200$ mSv, không phải $147{,}2$ mSv.</p>","difficultySource":"ai"},"ex":[{"exam":170,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Liều chiếu xạ và tác hại của phóng xạ","question":"Trong y học hạt nhân, ngoài đại lượng Liều hấp thụ (D, đơn vị Gray - Gy) dùng để đo năng lượng bức xạ truyền cho 1 kg vật chất (D = E/m), người ta còn dùng đại lượng Liều tương đương (H, đơn vị Sievert Sv) để đánh giá mức độ tổn thương sinh học. Công thức liên hệ là: H = DωR, trong đó ωR là hệ số phẩm chất (hay trọng số bức xạ), phụ thuộc vào loại tia. Với tia X, gamma, beta thì ωR = 1; với proton thì ωR = 2. Xạ trị proton là phương pháp tiên tiến sử dụng chùm hạt proton năng lượng cao thay vì tia X hay gamma. Điểm ưu việt của nó là \"đỉnh Bragg\": proton giải phóng phần lớn năng lượng tại đúng vị trí khối u rồi dừng lại, giảm tối đa tổn thương cho mô lành phía sau. Một máy gia tốc Cyclotron bắn chùm hạt proton có động năng K = 230MeV (1MeV = 1,6.10<sup>−13</sup> J) vào một khối u nặng m = 5 g. Trong một lần điều trị, người ta bắn vào 1010 hạt và khối u hấp thụ hoàn toàn năng lượng. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260010353-hinh-5.jpg\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Hạt proton được sử dụng trong phương pháp này thực chất là hạt nhân của nguyên tử Hydrogen thường (Hydrogen nhẹ).","answer":true},{"text":"Khác với tia X hay gamma thường gây tổn thương mô lành trên toàn bộ đường đi, chùm proton có ưu điểm là giải phóng phần lớn năng lượng tại đích đến (khối u) rồi dừng lại, giúp giảm thiểu tác dụng phụ.","answer":true},{"text":"Tổng năng lượng mà chùm proton truyền cho khối u trong một lần điều trị là 0,368 J.","answer":true},{"text":"Liều tương đương mà khối u phải chịu trong lần điều trị này là khoảng 147,2mSv (miliSievert).","answer":false}],"explanation":"","difficultySource":"ai"}}]},{"id":457232,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt độ và cân bằng nhiệt","question":"Quá trình nấu rượu gạo (dung dịch ethanol) thủ công được thực hiện như sau: Gạo được nấu chín, để nguội, rắc men, ủ kín từ 3 đến 5 ngày thu được hỗn hợp chủ yếu gồm nước, ethanol và bã rượu. Đun nóng hỗn hợp trên (trong nồi chưng cất) đến nhiệt độ sôi để ethanol và nước hóa hơi và đi vào đường ống dẫn. Hỗn hợp hơi (ethanol và nước) trong đường ống được làm lạnh khi đi qua thùng nước lạnh sẽ hóa lỏng và chảy vào bình hứng. Ta có bảng giá trị của ethanol và nước như sau: Chất\tNhiệt độ sôi (C)\tKhối lượng riêng (kg/m3)\tNhiệt dung riêng (J/(kg.K))\tNhiệt hóa hơi riêng (J/kg) Ethanol\t78\t789\t2 440\t0,9.106 Nước\t100\t997\t4 200\t2,3.10<sup>6</sup> Giả thuyết trong quá trình nấu rượu, hỗn hợp được cung cấp nhiệt một cách đều đặn. Ethanol sôi và hóa hơi trước ở 78 °C. Sau đó đến 100 °C thì nước bắt đầu sôi và hóa hơi. Bỏ qua lượng hơi nước ban đầu trong ống dẫn. Bỏ qua sự truyền nhiệt với môi trường, ống dẫn và bình hứng. Thùng nước lạnh chứa lượng nước có thể tích 250 lít ở nhiệt độ 20 °C. Khi thu được 20 lít rượu gạo 40 (thể tích ethanol chiếm 40%), người ta đo nhiệt độ của rượu khi có cân bằng nhiệt là 45 °C. Biết nhiệt độ của ethanol khi ra khỏi thùng nước lạnh là 35 °C. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259965670-hinh-6.jpg\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Khối lượng ethanol và nước có trong 20 lít rượu gạo 40 lần lượt là 11,964 kg và 6,312 kg.","answer":false},{"text":"Nhiệt độ của nước khi ra khỏi thùng nước lạnh là 48 °C.","answer":true},{"text":"Khi hơi nước và hơi ethanol đi qua thùng nước lạnh, chúng tỏa nhiệt và ngưng tụ.","answer":true},{"text":"Nếu trong quá trình nấu rượu không thay nước mới trong thùng nước lạnh thì nhiệt độ nước trong thùng sau khi thu được 20 lít rượu gạo 40 là 55 C.","answer":true}],"explanation":"a) sai<br>Khối lượng ethanol chứa trong 20 lít rượu gạo 40 là:  $m_e=D_e.V_e=789.40%.20.{10}^{-3}=6,312$  kg.<br>Khối lượng nước chứa trong 20 lít rượu gạo 40 là:  $m_n=D_n.V_n=997.60%.20.{10}^{-3}=11,964$  kg.<br>b) đúng<br>Xét sự trao đổi nhiệt giữa ethanol và nước, ta có:<br>$\\left|Q_{tỏa}\\right|=\\left|Q_{thu}\\right|$    $m_n.c_n.\\left(t_n-45\\right)=m_e.c_e.\\left(45-35\\right)$<br>$11,964.4200.\\left(t_n-45\\right)=6,312.2440.10$<br>$t_n=\\frac{1006337}{20937}\\approx 48 ℃$ .<br>c) đúng<br>Khi hơi nước và hơi ethanol đi qua thùng nước lạnh có nhiệt độ thấp hơn nên chúng truyền nhiệt cho nước lạnh, bị làm lạnh và ngưng tụ thành chất lỏng.<br>d) đúng<br>Khối lượng nước chứa trong thùng nước lạnh là:  $m=D_n.V=997.250.{10}^{-3}=249,25$  kg.<br>Xét sự trao đổi nhiệt giữa ethanol, nước (trong ống dẫn) với nước trong thùng nước lạnh, ta có:<br>$\\left|Q_{tỏa}\\right|=\\left|Q_{thu}\\right|$<br>$L_n.m_n+m_n.c_n.\\left(100-48\\right)+L_e.m_e+m_e.c_e.\\left(78-35\\right)=m.c_n.\\left(t-20\\right)$<br>$2,3.{10}^6.11,964+11,964.4200.52+0,9.{10}^6.6,312+6,312.2440.43=249,25.4200\\left(t-20\\right)$<br>$t\\approx 55 ℃$ .","difficultySource":"ai"},"ex":[{"exam":163,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt độ và cân bằng nhiệt","question":"Quá trình nấu rượu gạo (dung dịch ethanol) thủ công được thực hiện như sau: Gạo được nấu chín, để nguội, rắc men, ủ kín từ 3 đến 5 ngày thu được hỗn hợp chủ yếu gồm nước, ethanol và bã rượu. Đun nóng hỗn hợp trên (trong nồi chưng cất) đến nhiệt độ sôi để ethanol và nước hóa hơi và đi vào đường ống dẫn. Hỗn hợp hơi (ethanol và nước) trong đường ống được làm lạnh khi đi qua thùng nước lạnh sẽ hóa lỏng và chảy vào bình hứng. Ta có bảng giá trị của ethanol và nước như sau: Chất\tNhiệt độ sôi (C)\tKhối lượng riêng (kg/m3)\tNhiệt dung riêng (J/(kg.K))\tNhiệt hóa hơi riêng (J/kg) Ethanol\t78\t789\t2 440\t0,9.106 Nước\t100\t997\t4 200\t2,3.10<sup>6</sup> Giả thuyết trong quá trình nấu rượu, hỗn hợp được cung cấp nhiệt một cách đều đặn. Ethanol sôi và hóa hơi trước ở 78 °C. Sau đó đến 100 °C thì nước bắt đầu sôi và hóa hơi. Bỏ qua lượng hơi nước ban đầu trong ống dẫn. Bỏ qua sự truyền nhiệt với môi trường, ống dẫn và bình hứng. Thùng nước lạnh chứa lượng nước có thể tích 250 lít ở nhiệt độ 20 °C. Khi thu được 20 lít rượu gạo 40 (thể tích ethanol chiếm 40%), người ta đo nhiệt độ của rượu khi có cân bằng nhiệt là 45 °C. Biết nhiệt độ của ethanol khi ra khỏi thùng nước lạnh là 35 °C. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259965670-hinh-6.jpg\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Khối lượng ethanol và nước có trong 20 lít rượu gạo 40 lần lượt là 11,964 kg và 6,312 kg.","answer":false},{"text":"Nhiệt độ của nước khi ra khỏi thùng nước lạnh là 48 °C.","answer":true},{"text":"Khi hơi nước và hơi ethanol đi qua thùng nước lạnh, chúng tỏa nhiệt và ngưng tụ.","answer":true},{"text":"Nếu trong quá trình nấu rượu không thay nước mới trong thùng nước lạnh thì nhiệt độ nước trong thùng sau khi thu được 20 lít rượu gạo 40 là 55 C.","answer":true}],"explanation":"a) sai<br>Khối lượng ethanol chứa trong 20 lít rượu gạo 40 là:  $m_e=D_e.V_e=789.40%.20.{10}^{-3}=6,312$  kg.<br>Khối lượng nước chứa trong 20 lít rượu gạo 40 là:  $m_n=D_n.V_n=997.60%.20.{10}^{-3}=11,964$  kg.<br>b) đúng<br>Xét sự trao đổi nhiệt giữa ethanol và nước, ta có:<br>$\\left|Q_{tỏa}\\right|=\\left|Q_{thu}\\right|$    $m_n.c_n.\\left(t_n-45\\right)=m_e.c_e.\\left(45-35\\right)$<br>$11,964.4200.\\left(t_n-45\\right)=6,312.2440.10$<br>$t_n=\\frac{1006337}{20937}\\approx 48 ℃$ .<br>c) đúng<br>Khi hơi nước và hơi ethanol đi qua thùng nước lạnh có nhiệt độ thấp hơn nên chúng truyền nhiệt cho nước lạnh, bị làm lạnh và ngưng tụ thành chất lỏng.<br>d) đúng<br>Khối lượng nước chứa trong thùng nước lạnh là:  $m=D_n.V=997.250.{10}^{-3}=249,25$  kg.<br>Xét sự trao đổi nhiệt giữa ethanol, nước (trong ống dẫn) với nước trong thùng nước lạnh, ta có:<br>$\\left|Q_{tỏa}\\right|=\\left|Q_{thu}\\right|$<br>$L_n.m_n+m_n.c_n.\\left(100-48\\right)+L_e.m_e+m_e.c_e.\\left(78-35\\right)=m.c_n.\\left(t-20\\right)$<br>$2,3.{10}^6.11,964+11,964.4200.52+0,9.{10}^6.6,312+6,312.2440.43=249,25.4200\\left(t-20\\right)$<br>$t\\approx 55 ℃$ .","difficultySource":"ai"}}]},{"id":457262,"nq":{"form":"bai_tap","type":"true_false","topic":"Xử lí số liệu thí nghiệm đo nhiệt","question":"Thí nghiệm đo nhiệt nóng chảy riêng của nước đá được mô tả như hình vẽ. Dây đun (dây điện trở) có công suất 480 W dùng để làm nóng chảy nước đá trong thùng chứa. Sau 120 s, số chỉ của cân điện tử giảm đi 0,172 kg. Cho biết chỉ có sự trao đổi nhiệt giữa nước đá và dây đun. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260005555-hinh-4.jpg\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Nhiệt lượng cần thiết để làm tan nước đá ở thí nghiệm trên là 57600 J.","answer":true},{"text":"Việc đọc số liệu trên cân điện tử phải được thực hiện khi nguồn điện còn đang bật và ống thoát nước vẫn mở để tăng độ chính xác.","answer":false},{"text":"Khối lượng nước đá đã tan trong thời gian đun là 0,172 kg.","answer":true},{"text":"Nhiệt nóng chảy riêng của nước đá đo được ở thí nghiệm này lớn hơn 3,2.10<sup>5</sup> J/kg.","answer":true}],"explanation":"a) đúng<br>$Q=Pt=480.120=57600J$<br>b) sai<br>Như vậy sẽ bị nhiễu<br>c) đúng<br>$m_d=0,172kg$<br>d) đúng<br>$\\lambda =\\frac{Q}{m_d}=\\frac{57600}{0,172}\\approx 3,35.10^5\\left(J/kg\\right)$","difficultySource":"ai"},"ex":[{"exam":169,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Xử lí số liệu thí nghiệm đo nhiệt","question":"Thí nghiệm đo nhiệt nóng chảy riêng của nước đá được mô tả như hình vẽ. Dây đun (dây điện trở) có công suất 480 W dùng để làm nóng chảy nước đá trong thùng chứa. Sau 120 s, số chỉ của cân điện tử giảm đi 0,172 kg. Cho biết chỉ có sự trao đổi nhiệt giữa nước đá và dây đun. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260005555-hinh-4.jpg\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Nhiệt lượng cần thiết để làm tan nước đá ở thí nghiệm trên là 57600 J.","answer":true},{"text":"Việc đọc số liệu trên cân điện tử phải được thực hiện khi nguồn điện còn đang bật và ống thoát nước vẫn mở để tăng độ chính xác.","answer":false},{"text":"Khối lượng nước đá đã tan trong thời gian đun là 0,172 kg.","answer":true},{"text":"Nhiệt nóng chảy riêng của nước đá đo được ở thí nghiệm này lớn hơn 3,2.10<sup>5</sup> J/kg.","answer":true}],"explanation":"a) đúng<br>$Q=Pt=480.120=57600J$<br>b) sai<br>Như vậy sẽ bị nhiễu<br>c) đúng<br>$m_d=0,172kg$<br>d) đúng<br>$\\lambda =\\frac{Q}{m_d}=\\frac{57600}{0,172}\\approx 3,35.10^5\\left(J/kg\\right)$","difficultySource":"ai"}}]}]$j$::jsonb) loop
    h := public.question_content_hash(r->'nq');
    if exists (select 1 from public.question_bank where content_hash = h and id <> (r->>'id')::bigint) then raise notice 'TRUNG %', r->>'id'; continue; end if;
    update public.question_bank set question = r->'nq', content_hash = h, updated_at = now() where id = (r->>'id')::bigint;
    for e in select * from jsonb_array_elements(r->'ex') loop
      update public.exams set questions = jsonb_set(questions, array[e->>'idx'], e->'el') where id = (e->>'exam')::bigint;
    end loop;
  end loop;
end $do$;
alter table public.exams enable trigger trg_exams_sync_bank;
commit;
